INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(72, 'koKR', '', 'Mój ojciec był dozorcą tej posiadłości na długo przede mną. To on musiał zmywać krew po masakrze. Ale mniejsza z tym.$b$bOstatnie środki z funduszu powierniczego Flintridge\'ów się wyczerpały. Teraz resztki rodzinnego dobytku pójdą pod młotek. Podziękuj sępom od podatków. Jeśli naprawdę tak cię korci, żeby dowiedzieć się czegoś więcej, możesz przejrzeć te graty. Kto wie, co znajdziesz.', 'Przeszukaj spakowany dobytek w poszukiwaniu jakiejś wskazówki.', '', '', '', '', '', '', 0),
(120, 'koKR', 'Posłaniec do Wichrogrodu', 'Nastały ciężkie czasy, $N. Nasze miasteczko jest nieustannie oblegane. Bez posiłków z pewnością czeka nas klęska. Wiadomość, którą ci teraz powierzam, ma ogromną wagę. Natychmiast dostarcz ten raport generałowi Marcusowi Jonathanowi w Wichrogrodzie. Gdy tylko go przekażesz, od razu wracaj do mnie z wieściami, dobrymi czy złymi.$b$bA teraz pośpiesz się!', 'Sędzia Solomon dał ci raport, który musisz dostarczyć generałowi Marcusowi Jonathanowi w Wichrogrodzie. Sędzia chce, żebyś $gwrócił:wróciła; do niego, gdy tylko go dostarczysz.', '', '', '', '', '', '', 0),
(121, 'koKR', 'Posłaniec do Wichrogrodu', 'Czekając na odpowiedź króla, chcę, żebyś $gzaniósł:zaniosła; ten list sędziemu Solomonowi.$b$bOdmaszerować, $N!', 'Zanieś list z odpowiedzią generała Marcusa Jonathana sędziemu Solomonowi w Jeziernych Włościach.', '', '', '', '', '', '', 0),
(135, 'koKR', 'Bractwo Nieskornych', 'Zastanawiam się, co Wiley miał na myśli, kiedy wspomniał o kamieniarzach. Może mu się wymsknęło. Czy banda Nieskornych może mieć coś wspólnego z kamieniarzami? Tylko jeden człowiek wie to na pewno: Mathias Shaw, szef WW:7. Pokaż mu liścik Wileya i sprawdź, czy może coś dodać do tej coraz bardziej zawiłej zagadki. Jeśli będziesz mieć kłopot ze znalezieniem Shawa, zajrzyj do koszar na Starym Mieście.', 'Zanieś liścik Wileya Mathiasowi Shawowi w Wichrogrodzie.', '', '', '', '', '', '', 0),
(137, 'koKR', '<NYI> <TXT> Pochwała z Wichrogrodu', 'Jeśli zdobędziesz pochwałę od któregoś z naszych marszałków, przynieś mi ją. Można ją wymienić na parę naszych rękawic z godłem lwa.', 'Generał Marcus Jonathan w Wichrogrodzie przyjmie pochwałę z Kniei Elwynn. W zamian za taki dokument otrzymasz do wyboru element zbroi.', '', 'Wróć do generała Marcusa Jonathana w Dolinie Bohaterów w Wichrogrodzie.', '', '', '', '', 0),
(141, 'koKR', 'Bractwo Nieskornych', 'Gildią Kamieniarzy kierował człowiek o nazwisku Edwin VanCleef. VanCleef odpowiadał za odbudowę Wichrogrodu po tym, jak orkowie zrównali go z ziemią podczas Pierwszej Wojny. Najwyraźniej VanCleef i jego ludzie byli niezadowoleni z tego, jak potraktował ich król po zakończeniu odbudowy. To mogłoby co nieco wyjaśniać.$b$bSporządziłem dokładniejszy raport dla twojego zwierzchnika w Zachodnim Skraju. Zanieś mu go natychmiast!', 'Zanieś raport Shawa Gryanowi Mocnopłaszczowi w Zachodnim Skraju.', '', '', '', '', '', '', 0),
(167, 'koKR', 'Och, bracie...', 'Byliśmy głęboko w ogromnej kopalni w Zachodnim Skraju, ukrytej pod stodołą w Księżycowym Potoku. Nie mam pojęcia, skąd się wzięły te śmierdzące złodziejskie typy. W każdym razie tunel zawalił się nam na głowy. Ja się wydostałem, ale pozostali... cóż... o pozostałych nikt więcej nie słyszał.$b$bWyglądasz na kogoś, komu może tam lepiej pójść. Jeśli poszukasz mojego brata, będę ci wdzięczny. Zawsze nosił przy sobie odznakę Ligi Odkrywców. Jeśli go nie znajdziesz, ta odznaka przynajmniej da mi trochę spokoju.', 'Przynieś odznakę Ligi Odkrywców brygadzisty Ostopokrzywa Wilderowi Ostopokrzywowi w Wichrogrodzie.', '', 'Wróć do Wildera Ostopokrzywa w Wichrogrodzie.', '', '', '', '', 0),
(168, 'koKR', 'Zbieranie wspomnień', 'Wielu moich przyjaciół zginęło tego strasznego dnia, gdy zawalił się tunel. Jeśli przygody zaprowadzą cię do tamtego skrzydła kopalni w Księżycowym Potoku, wypatruj wszystkiego, co mogłoby pomóc ich zidentyfikować. Jeśli natkniesz się na ich legitymacje Związku Górników, przynieś mi je, a dopilnuję, żeby ich rodziny wreszcie poznały prawdę o tym strasznym wypadku.', 'Zdobądź 4 legitymacje Związku Górników i zanieś je Wilderowi Ostopokrzywowi w Wichrogrodzie.', '', 'Wróć do Wildera Ostopokrzywa w Wichrogrodzie.', '', '', '', '', 0),
(171, 'koKR', 'Opiekun z Przymierza', '$GByłeś:Byłaś; dla mnie $gtaki dobry:taka dobra;, $N. Nawet mi się nie śniło, że w Tygodniu Dziecka będzie tyle zabawy. Dziękuję. Nie chcę się smucić tym, co mnie spotkało i w ogóle – rodzice zawsze mi powtarzali, żeby nie dać się złym rzeczom, które się przytrafiają. Wiesz, jak dorosnę, chcę zostać bohaterem... takim jak ty.$B$BSmutno mi to mówić, ale czas już wracać do domu. Chodźmy, a ja opowiem opiekunce, jak super z ciebie osoba!', 'Odprowadź swojego podopiecznego do sierocińca w Wichrogrodzie, oddając gwizdek ludzkiej sieroty opiekunce sierocińca Nightingale w Dzielnicy Katedralnej.', '', 'Wróć do opiekunki sierocińca Nightingale w Wichrogrodzie.', '', '', '', '', 0),
(212, 'koKR', 'Danie na zimno', 'Jednym z moich najsłynniejszych dań jest schłodzony bazyliszek w winegrecie limonkowym. Kłopot w tym, że... tego mięsa nie da się utrzymać w świeżości, a dziś wieczorem muszę podać to danie na urodzinach pewnego szlachcica!$B$BJeśli więc szybko przyniesiesz mi schłodzony udziec bazyliszka ze świeżo zabitego zimnookiego bazyliszka, będę ci winien królewską ucztę!$B$BZimnookie bazyliszki podobno wędrują po nadmorskich wydmach w północno-zachodniej Dolinie Cierniodławów, więc czeka cię długa podróż. I pośpiesz się!', 'Zabij zimnookiego bazyliszka, zdobądź schłodzony udziec bazyliszka i zanieś go Angusowi Sternowi w „Błękitnym Samotniku”.', '', 'Wróć do Angusa Sterna nad Lustrzanym Jeziorem w Kniei Elwynn.', '', '', '', '', 0),
(269, 'koKR', 'W poszukiwaniu mądrości', 'Udaj się do Wichrogrodu i porozmawiaj z biskupem Farthingiem w Katedrze Światła. Daj mu dziennik Dygota i powiedz, że zamierzasz zmierzyć się z Morbentem Felem.$B$BChoć Wichrogród porzucił Mroczne Włości, Farthing to dobra dusza i bardzo mądry człowiek. Może pomóc ci w twojej misji ratowania nas.$B$BTwoje zadanie jest niebezpieczne, ale pośpiesz się, $N. Z każdą godziną cienie Kniei Zmierzchu gęstnieją coraz bardziej.', 'Daj ukończony dziennik Dygota biskupowi Farthingowi w Wichrogrodzie.', '', '', '', '', '', '', 0),
(270, 'koKR', 'Przeklęta flota', 'Przed laty Trzecia Flota Kul Tiras zatonęła u wybrzeży Bagnisk, rozległych moczarów na północ od krasnoludzkiego królestwa Żelaznej Kuźni. Na pokładzie jednego ze statków znajdował się ładunek żelaza z kuźni światła.$B$BTen metal jest dla nas cenny, bo wykuta z niego broń uderza świętą prawdą. Jeśli masz zmierzyć się z Morbentem Felem, będziesz potrzebować takiej broni.$B$BUdaj się do Przystani Menethilów i porozmawiaj z moim krasnoludzkim towarzyszem, Glorinem Stalobrwym. Jeśli ten zaginiony metal da się odnaleźć, on będzie wiedział, gdzie szukać.', 'Udaj się do Przystani Menethilów na Bagniskach i porozmawiaj z Glorinem Stalobrwym.', '', '', '', '', '', '', 0),
(293, 'koKR', 'Oczyszczenie oka', 'Nie potrafię zdjąć klątwy z Oka Paletha. Oczy Paletha wykonali ludzcy kapłani, więc musisz udać się do Wichrogrodu i tam poszukać pomocy. Porozmawiaj z arcybiskupem Benedyktem. Stoi na czele Katedry Światła w Wichrogrodzie. On może pomóc.$B$BMam taką nadzieję, przez wzgląd na ciebie.', 'Zanieś przeklęte oko Paletha arcybiskupowi Benedyktowi. Benedykt przebywa w Katedrze Światła w Wichrogrodzie.', '', '', '', '', '', '', 0),
(322, 'koKR', 'Błogosławiony oręż', 'W Dzielnicy Krasnoludów w Wichrogrodzie mieszka krasnoludzki kowal broni, który potrafi pracować z żelazem z kuźni światła. Nazywa się Grimand Elmore.$B$BZapakowałem znalezione przez ciebie żelazo do skrzynki. Zanieś ją Grimandowi i opowiedz mu swoją historię. Jestem pewien, że pomoże komuś, kto wypełnia taką misję jak twoja, i wykuje dla ciebie broń – broń, która zaniepokoi nawet Morbenta Fela!', 'Zanieś skrzynkę sztabek z kuźni światła Grimandowi Elmore\'owi w Wichrogrodzie.', '', '', '', '', '', '', 0),
(325, 'koKR', 'W pełnej gotowości', 'Oto broń przeciwko temu potworowi, o którym $gmówiłeś:mówiłaś;. Jesteś $ggotów:gotowa;, $N. Powodzenia! Nie mogę się doczekać opowieści o twojej chwale!', 'Zanieś Zgubę Morbenta Svenowi w Kniei Zmierzchu.', '', '', '', '', '', '', 0),
(332, 'koKR', 'Reklama winiarni', 'Jeśli rozmawiasz z kimkolwiek o winie, to wiesz, że my, Gallinowie, sprzedajemy najlepsze wino w Wichrogrodzie. A mamy niedaleko – wciąż w Dzielnicy Handlowej, nad uroczymi miejskimi kanałami.$B$BProszę, weź tę ulotkę. Zanieś ją mojej siostrze Suzetcie do naszego sklepu, a dostaniesz w prezencie butelkę naszego słynnego pinot noir. Nie pożałujesz!', 'Udaj się do Winiarni Gallinów i oddaj Suzetcie Gallinie talon na wino, by otrzymać darmową butelkę wina.', '', '', '', '', '', '', 0),
(333, 'koKR', 'Harlan potrzebuje dostawy', 'Ostatnio mamy mnóstwo klientów. Wygląda na to, że wszyscy kupują zbroje i mocne ubrania. Zupełnie jakby spodziewali się zimnej, ciężkiej pory roku...$B$BAle to zmartwienia na przyszłość. Dziś martwi mnie to, że kończy mi się dziana odzież na sprzedaż. Potrzebuję kolejnego transportu od naszego dostawcy.$B$BJeśli zaniesiesz to zamówienie Remie Schneider do pracowni „Krawiec i Przymiarki nad Kanałem”, będę ci bardzo wdzięczny.', 'Udaj się do pracowni krawieckiej nad kanałem i zanieś Remie Schneider zamówienie na tkaninę od Harlana Bagleya.', '', '', '', '', '', '', 0),
(334, 'koKR', 'Paczka dla Thurmana', 'Mój syn Thurman terminuje w „Odzieży Larsona” w Dzielnicy Magów. Dziś bardzo się śpieszył i zapomniał nożyc i igieł. Wiem, że ktoś tak wspaniały jak ty ma pewnie na głowie ważne sprawy, ale bez narzędzi Thurman nie może wykonywać swojej pracy ucznia!$B$BProszę, $N. Zaniesiesz mu jego przybornik krawiecki? „Odzież Larsona” to jeden z dwóch sklepów odzieżowych w Dzielnicy Magów – ten położony dalej w głębi, przy wieży magów.', 'Udaj się do „Odzieży Larsona” w Dzielnicy Magów w Wichrogrodzie i oddaj Thurmanowi Schneiderowi jego przybornik krawiecki.', '', '', '', '', '', '', 0),
(335, 'koKR', 'Szlachetny trunek', 'Lord Wishock robi niezłe zamieszanie w Izbie Szlachty. Dowiedział się o naszym małym „przybytku” tu, na dole, i zabiega o wszczęcie pełnego śledztwa. Mam plan, jak zapewnić Wishockowi „zajęcie”, ale będę potrzebował twojej pomocy.$b$bW Ogrodzie Stalvana na obrzeżach Mrocznych Włości rośnie pewien kwiat. Ten mały biały kwiat znany jest jako Łza Tilloi. Potrzebuję też korzenia piżmaka, który rośnie wyłącznie u samego podnóża wodospadu, daleko poniżej Kamiennej Tamy na Bagniskach.', 'Zardeth z Czarnego Szponu chce, żebyś $gprzyniósł:przyniosła; mu Łzę Tilloi z Mrocznych Włości i korzeń piżmaka z Bagnisk.', '', 'Wróć do Zardetha z Czarnego Szponu w Wichrogrodzie.', '', '', '', '', 0),
(336, 'koKR', 'Szlachetny trunek', 'Lord Wishock, jak każdy człowiek, ma swoje słabości. Jego słabością jest zamiłowanie do trunków. Ta hipokryzja jest zdumiewająca. Ten nadęty głupiec całe dnie próbuje zamknąć naszą małą „tawernę”, a noce spędza na górze, nabijając rachunek, którego nigdy nie płaci. Cóż, zobaczmy, jak Wishockowi zasmakuje specjalny trunek, który dla niego przygotowałem: mocne piwo Czarnego Szponu. Ma niezłego kopa, $n.$b$bZanieś mu je i zobacz, jak mu smakuje. Ten stary głupiec najpewniej kręci się po Sali Petentów.', 'Zanieś mocne piwo Czarnego Szponu lordowi Wishockowi w Sali Petentów.', '', '', '', '', '', '', 0),
(337, 'koKR', 'Stara księga historyczna', 'Choć okładka tej księgi jest porysowana i oblepiona błotem, na grzbiecie wciąż da się odczytać tytuł „Historia Wichrogrodu”. Po otwarciu księgi na pierwszej stronie wyraźnie widać pieczęć Biblioteki Wichrogrodu.$B$BWygląda na to, że ktoś ją wypożyczył i nigdy nie oddał...', 'Zwróć księgę „Historia Wichrogrodu” do Biblioteki Wichrogrodu.', '', '', '', '', '', '', 0),
(343, 'koKR', 'Mowa o harcie', 'Wygłaszam przemowę o harcie ducha i chciałbym przytoczyć fragmenty pewnej książki o metalurgii – „Naprężenia żelaza”. Egzemplarz tej książki powinien się znajdować w Bibliotece Królewskiej w Twierdzy Wichrogród. Możesz mi go przynieść? Jeśli tak, niech błogosławieństwo Światłości będzie z tobą!$B$BBiblioteka Królewska jest ogromna, ale główny bibliotekarz, Milton Sheaf, zna każdą półkę jak własnego syna. Porozmawiaj z nim, on znajdzie dla ciebie tę książkę.', 'Udaj się do Biblioteki Królewskiej w Twierdzy Wichrogród i porozmawiaj z Miltonem Sheafem. Znajdzie dla ciebie książkę o metalurgii, której brat Kristoff potrzebuje do swojej przemowy.', '', '', '', '', '', '', 0),
(350, 'koKR', 'Zwróć się do starego przyjaciela', 'Że Marzon kontaktuje się z kimś z Nieskornych i ma powiązania z Lescovarem...$B$BSkoro $gzabiłeś:zabiłaś; VanCleefa i Thredda, trudno będzie postawić Lescovara przed sądem, bo bez ich zeznań twoje dowody są nic niewarte. Nie mówiąc już o tym, że Lescovar jest szlachcicem i ma rozległe koneksje. W praktyce stawia go to ponad prawem.$B$BBędziesz potrzebować innej pomocy. Bardzo niechętnie to robię, ale znam kogoś, kto nam pomoże. Triasa znajdziesz w Dzielnicy Handlowej.', 'Porozmawiaj z Ellingiem Triasem w Wichrogrodzie.', '', '', '', '', '', '', 0),
(353, 'koKR', 'Przesyłka dla Gromdardy', 'Gromdardowie to szanowany krasnoludzki klan, słynący z wyrafinowanego i wybrednego gustu. Nic więc dziwnego, że Gringer Gromdarda, górski strażnik z Żelaznej Kuźni, zamówił u mnie broń.$B$BBroń jest gotowa, ale... górski strażnik Gromdarda jest daleko stąd, w odległym Loch Modan. Jeśli wybierasz się na północ, możesz dostarczyć mu tę paczkę?$B$BW ostatniej wiadomości górski strażnik Gromdarda pisał, że stacjonuje w północnej wieży strażniczej w Loch Modan.', 'Dostarcz paczkę dla Gromdardy górskiemu strażnikowi Gromdardzie w Loch Modan.', '', '', '', '', '', '', 0),
(373, 'koKR', 'Niewysłany list', 'Przeszukując ciało Edwina VanCleefa, znajdujesz między innymi niewysłany list. Jest zaadresowany do Barosa Alexstona, architekta miejskiego Wichrogrodu, Ratusz, Plac Katedralny.$B$BWygląda na to, że został niedawno napisany i zapieczętowany.', 'Dostarcz list do architekta miejskiego Barosowi Alexstonowi w Wichrogrodzie.', '', '', '', '', '', '', 0),
(387, 'koKR', 'Stłum bunt', 'Bunt trzeba stłumić! Potrzebuję twojej pomocy. Jeśli rozniesie się, że więźniowie opanowali więzienie, stracę posadę! Ktoś tu maczał palce, jestem tego pewien. Ale teraz najważniejsze jest zmuszenie więźniów do posłuszeństwa, dla bezpieczeństwa Wichrogrodu.$b$bKarą za bunt jest śmierć. Zabij kilku z tych wykolejeńców! To powinno opanować sytuację.', 'Strażnik Thelwater z Wichrogrodu chce, żebyś $gzabił:zabiła; w Kazamatach 10 więźniów z Nieskornych, 8 skazańców z Nieskornych i 8 buntowników z Nieskornych.', '', 'Wróć do strażnika Thelwatera w Wichrogrodzie.', '', '', '', '', 0),
(388, 'koKR', 'Kolor krwi', 'Gorycz płynie w moich żyłach jak zimna rzeka. Mój wnuk, Mac, był takim dobrym chłopcem. Miał zaledwie 14 lat. Kiedy armię wysłano na front, Mac chwycił za broń, by bronić miasta. Był strażnikiem w Kazamatach, gdzie trzymają bandę Nieskornych. Mac upomniał kilku więźniów, którzy darli wełniane koce, żeby robić z nich chusty – symbol ich bandy. Za to dostał nóż w plecy.$b$bPragnę zemsty. Przynieś mi 10 tych ich cennych wełnianych chust. Mają kolor krwi.', 'Nikova Raskol z Wichrogrodu chce, żebyś $gzebrał:zebrała; 10 czerwonych wełnianych chust.', '', 'Wróć do Nikovy Raskol na Starym Mieście w Wichrogrodzie.', '', '', '', '', 0),
(389, 'koKR', 'Bazil Thredd', 'VanCleef i ja byliśmy członkami Gildii Kamieniarzy. Naszym głównym zadaniem była odbudowa Wichrogrodu po wojnie.$B$BGdy wypełniliśmy swoje obowiązki, oszukano nas. Szlachta odmówiła zapłaty za naszą pracę. Kilku starszym kamieniarzom zaproponowano posady w administracji, ale VanCleef odmówił z lojalności wobec wszystkich kamieniarzy. Wszczął rozruchy i opuścił miasto, przysięgając zemstę.$b$bJego zastępca, Bazil Thredd, może wiedzieć więcej o planach VanCleefa. Jest przetrzymywany w Kazamatach.', 'Porozmawiaj ze strażnikiem Thelwaterem w Kazamatach.', '', '', '', '', '', '', 0),
(391, 'koKR', 'Bunt w Kazamatach', 'Postawmy sprawę jasno, $N: nie ufam ci. Ale w obecnej sytuacji i tak pewnie niczego nie zmienisz.$B$BWięc będzie tak: idź na dół i pogadaj sobie z Threddem. Jeśli naprawdę jesteś po naszej stronie, zabij go, a gdy skończysz, przynieś mi jego głowę. A jeśli okaże się, że jesteś po jego stronie, i nie wyjdziesz... kiedy cię znajdziemy, zginiesz razem z resztą tego robactwa.', 'Zabij Bazila Thredda i przynieś jego głowę strażnikowi Thelwaterowi w Kazamatach.', '', 'Wróć do strażnika Thelwatera w Wichrogrodzie.', '', '', '', '', 0),
(392, 'koKR', 'Osobliwy gość', 'Przez pierwsze lata odsiadki Thredda nikt go nie odwiedzał. Uznałem, że Bractwo nie ma już z niego pożytku i o nim zapomniało.$B$BW każdym razie kilka miesięcy temu to się zmieniło – zaczął mieć regularne wizyty... raz, może dwa razy w tygodniu. Odwiedzał go dziwny człowiek – z tych małomównych. Miałem swoje podejrzenia, ale wszystkie jego papiery były w porządku.$B$BWedług dokumentów nazywał się Maelik – oto jego rysopis. Nie sądzę, żeby jeszcze kiedyś odwiedził Thredda.', 'Zanieś zapieczętowany rysopis gościa Thredda Barosowi Alexstonowi w Wichrogrodzie.', '', '', '', '', '', '', 0),
(393, 'koKR', 'Cień przeszłości', 'Naprawdę nie mam pojęcia, $N. Jest ktoś jeszcze, kto może ci pomóc, i tak się składa, że jest mi winien przysługę za... zresztą nieważne. Mistrza Mathiasa Shawa z WW:7 znajdziesz w koszarach na Starym Mieście. Shaw trzyma rękę na pulsie większości podejrzanych i nieczystych interesów w mieście.$B$BJeśli ktoś wie, to właśnie on.', 'Zanieś zapieczętowany rysopis gościa Thredda mistrzowi Mathiasowi Shawowi w Wichrogrodzie.', '', '', '', '', '', '', 0),
(394, 'koKR', 'Głowa bestii', 'Znajdź Shawa na Starym Mieście. Powiedz mu, że zagrożenie ze strony Lescovara zostało zażegnane, i opowiedz o swoim udziale w sprawie spisków lorda przeciwko miastu. Na pewno będzie dumny, że wśród obywateli Wichrogrodu jest $gkolejny bohater:kolejna bohaterka;.$B$BNajpewniej wyśle cię na spotkanie z księciem albo jakimś innym szlachcicem. Tylko nie pozwól, żeby uderzyło ci to do głowy, $N. Szlachta może sobie myśleć, że rządzi miastem, ale niektóre sprawy pozostają poza jej zasięgiem.', 'Porozmawiaj z Mathiasem Shawem w Wichrogrodzie.', '', '', '', '', '', '', 0),
(395, 'koKR', 'Koniec Bractwa', 'Ach, prawie zapomniałem. Pod twoją nieobecność przyszedł Alexston, chciał z tobą porozmawiać. Bez wątpienia chce zdać szlachcie relację z poczynań Bractwa Nieskornych.$B$BMała rada, $N: gdyby ktoś pytał, podaj wszystkie szczegóły poza tym, że to twoja ręka zabiła Lescovara. Zaufaj mi. Jestem... obeznany... z takimi sprawami.$B$BA co do Triasa, cóż, nie mów o nim nikomu... nigdy... jeśli tylko możesz tego uniknąć.', 'Porozmawiaj z Barosem Alexstonem w Wichrogrodzie.', '', '', '', '', '', '', 0),
(396, 'koKR', 'Audiencja u króla', 'Przygotowałem raport dla króla. Uważam, że to ty $gpowinieneś:powinnaś; mu go dostarczyć wraz z relacją z tego, co $godkryłeś:odkryłaś;. Nie martw się, król z pewnością pochwali cię za wypełnienie obowiązku wobec mieszkańców Wichrogrodu.$B$BTwoja audiencja odbędzie się niebawem, więc lepiej się pośpiesz – do Twierdzy Wichrogród jest spory kawałek drogi.', 'Dostarcz raport Barosa Alexstona o Bractwie Nieskornych królowi Varianowi Wrynnowi w Twierdzy Wichrogród.', '', '', '', '', '', '', 0),
(397, 'koKR', 'Wierna służba', 'Słyszałem, że lordowi Wishockowi zasmakował jego trunek.$b$bDobrze nam $gsłużyłeś:służyłaś;, $N. Dzięki tobie my, czarnoksiężnicy Wichrogrodu, będziemy mogli bez przeszkód praktykować naszą sztukę. W nagrodę za twoje wysiłki przygotowałem dla ciebie specjalny dar. Porozmawiaj z moim sługą – nazywa się Zggi – i odbierz nagrodę.', 'Porozmawiaj ze sługą Zardetha z Czarnego Szponu, który nazywa się Zggi, i odbierz nagrodę.', '', '', '', '', '', '', 0),
(399, 'koKR', 'Skromne początki', 'Wydaje się, że minęła wieczność, odkąd jako chłopiec pracowałem na farmie w Zachodnim Skraju. Mówią, że do przeszłości nie ma powrotu, i to prawda. W moim przypadku podwójna – dom mojej rodziny spłonął i zajęli go złodzieje.$b$bRozmawiałem z ojcem o losie niektórych moich rzeczy, w tym mojego pierwszego kompasu. Nie zdołał ich uratować. Mówi jednak, że powinny być gdzieś ukryte w gospodarstwie.$b$bGospodarstwo Alexstona znajdziesz na zachód od Wzgórza Strażniczego. Może $gmógłbyś:mogłabyś; się tam wybrać i odzyskać dla mnie kompas?', 'Udaj się do domu Barosa Alexstona w Zachodnim Skraju, poszukaj jego kompasu, a potem zanieś mu go na Plac Katedralny w Wichrogrodzie.', '', 'Wróć do Barosa Alexstona w Wichrogrodzie.', '', '', '', '', 0),
(434, 'koKR', 'Atak!', 'Kiedy przebiorę szpiegobota, pójdzie porozmawiać z Lescovarem. Strażnicy powinni go bez problemu przepuścić.$B$BGdy $gzbierałeś:zbierałaś; dla mnie materiały, zająłem się powiadomieniem Marzona, że nadszedł czas na jego kolejne spotkanie z Lescovarem. Podrzuciłem nawet trochę fałszywych informacji.$B$BLescovar odprawi strażników i będzie czekał na Marzona tutaj, w ogrodzie. Gdy usłyszysz rozmowę o Nieskornych, do dzieła. Musisz zabić ich obu, zanim strażnicy wrócą! Kiedy skończysz, porozmawiaj z Triasem.', 'Zostań w ogrodzie, dopóki lord Gregor Lescovar i Marzon Ciche Ostrze nie odbędą rozmowy. Potem zabij ich obu i wróć do Ellinga Triasa w Wichrogrodzie.', 'Podsłuchaj rozmowę Lescovara z Marzonem', 'Wróć do Ellinga Triasa w Wichrogrodzie.', '', '', '', '', 0),
(538, 'koKR', 'Południowy Brzeg', '$N. Jeśli nie przeszkadza ci długa podróż, mam dla ciebie zadanie – znów pomożesz Wichrogrodowi uzupełnić bibliotekę.$B$BDawne królestwo Alterak upadło po wielkiej wojnie, a miało pokaźny księgozbiór. To tragedia, że miasto legło w gruzach, ale jeszcze większą tragedią jest utrata całej jego wiedzy! Musimy odzyskać, co się da.$B$BPołudniowy Brzeg to miasteczko położone najbliżej Ruin Alterak. Udaj się tam i porozmawiaj z mistrzem wiedzy Dibbsem. Wskaże ci drogę do ruin i powie, jakie księgi można tam znaleźć.', 'Porozmawiaj z mistrzem wiedzy Dibbsem w Południowym Brzegu.', '', '', '', '', '', '', 0),
(540, 'koKR', 'Ocalić wiedzę', 'Te bestialskie ogry zamieszkują teraz ruiny Alterak i drżę na myśl, co robią z cennymi księgami, które tam zostały. Musisz odzyskać, co się da!$B$BWejdź do Ruin Alterak i poszukaj ksiąg zrabowanych przez ogry. Zabierz wszystko, co znajdziesz, i przynieś mi, ale szukaj też jednej konkretnej księgi: „Ramię Gri\'leka”. Zawiera starożytną wiedzę trolli, którą muszę poznać, a Ruiny Alterak to ostatnie znane miejsce, gdzie znajdował się nienaruszony egzemplarz tej księgi.', 'Przynieś 5 odzyskanych ksiąg oraz zniszczoną skórzaną księgę zawierającą „Ramię Gri\'leka” mistrzowi wiedzy Dibbsowi w Południowym Brzegu.', '', 'Wróć do mistrza wiedzy Dibbsa w Południowym Brzegu w Międzygórzu.', '', '', '', '', 0),
(542, 'koKR', 'Powrót do Miltona', 'Muszę poświęcić trochę czasu na studiowanie „Ramienia Gri\'leka”, które mi $gprzyniosłeś:przyniosłaś;, choć jestem pewien, że Milton nie może się doczekać, aż pozostałe odzyskane księgi trafią do zbiorów Wichrogrodu.$B$BOto księgi, które $gzebrałeś:zebrałaś; w Ruinach Alterak – spakowane i skatalogowane. Zanieś je Miltonowi Sheafowi w Wichrogrodzie, na pewno będzie ci wdzięczny.', 'Zanieś księgi z Alterak Miltonowi Sheafowi w Wichrogrodzie.', '', '', '', '', '', '', 0),
(543, 'koKR', 'Tiara Perenolde\'ów', 'Tiara Perenolde\'ów to dawna pamiątka rodowa „szlachetnych” Perenolde\'ów – rodu, który panował w Alterak, zanim królestwo popadło w ruinę. Podobno wykonali ją mistrzowie jubilerscy z Żelaznej Kuźni i wysadzili najprzedniejszymi szmaragdami.$B$BGdy królestwo Alterak zostało zniszczone, tiara zaginęła, ale krążą plotki, że ogrzy mag, Grel\'borg Skąpiec, znalazł ją i teraz przemierza Ruiny Alterak w poszukiwaniu kolejnych skarbów.$B$BChcemy, żebyś $gzdobył:zdobyła; dla nas tę tiarę.', 'Przynieś tiarę Perenolde\'ów Remingtonowi Ridgewellowi w Wichrogrodzie.', '', 'Wróć do hrabiego Remingtona Ridgewella w Twierdzy Wichrogród w Wichrogrodzie', '', '', '', '', 0),
(563, 'koKR', 'Przeniesienie', 'Nie powinno być problemu z tym, żeby mój raport trafił do właściwych rąk. Nowy kapitan straży, major Samuelson, był moim mentorem, gdy stacjonowałem w Wichrogrodzie. To da mu aż nadto pretekstu, by przenieść mnie z powrotem do miasta. Musisz jednak zanieść mu mój raport... nie chciałbym, żeby stary Redpath się zorientował.', 'Dostarcz raport Farrena majorowi Samuelsonowi w Twierdzy Wichrogród.', '', '', '', '', '', '', 0),
(579, 'koKR', 'Biblioteka Wichrogrodu', '', '', '', 'Wróć do Donyala Tovalda w Kniei Elwynn.', '', '', '', '', 0),
(690, 'koKR', 'Prośba Malina', 'Witaj, $N. Wyglądasz na $gposzukiwacza:poszukiwaczkę; przygód, a ja mam zadanie, którym trzeba się zająć.$B$BArcymag Trelane, mój pierwszy mistrz, niedawno uciekł ze Stromgardu na Wyżynach Aratorskich i poprosił mnie o pomoc w odzyskaniu części rzeczy, które tam zostawił.$B$BMiasto zostało oblężone, a on próbował bronić Wieży Aratoru, lecz na próżno. Mam już na wyżynach swoich agentów, ale proszą o dodatkowe wsparcie. Jesteś $gzainteresowany:zainteresowana;?', 'Odnajdź Skuerta w Punkcie Schronienia na Wyżynach Aratorskich.', '', '', '', '', '', '', 0),
(697, 'koKR', 'Prośba Malina', 'Zanieś ten list do Wichrogrodu i daj znać Malinowi, że Kryten i ja niedługo wrócimy do domu. Sowicie cię wynagrodzi za pomoc, $N, co do tego nie mam wątpliwości.$B$BBezpiecznej drogi.', 'Zanieś zapieczętowany list arcymagowi Malinowi w Dzielnicy Magów w Wichrogrodzie.', '', '', '', '', '', '', 0),
(1015, 'koKR', 'Nowe rubieże', 'Uwaga, bohaterowie!$B$BKrąg Cenariona szuka sprawnych ochotników, którzy pomogą mu badać rozległe, nowe rubieże Kalimdoru! Daleko na zachód od Tanaris i Gadżetonu leży zakazane pustkowie pełne niewyobrażalnych niebezpieczeństw, a Krąg potrzebuje chętnych i honorowych wysłanników, którzy będą działać w jego imieniu.$B$BWszyscy zainteresowani powinni zgłosić się do Kręgu Cenariona. Po więcej informacji udajcie się do arcydruida Fandrala Jeleniorogiego w Darnassus!', 'Porozmawiaj z arcydruidem Fandralem Jeleniorogim w Enklawie Cenariona w Darnassus o wezwaniu Kręgu Cenariona do badania rubieży Kalimdoru.', '', '', '', '', '', '', 0),
(1075, 'koKR', 'Zwój od Maurena', 'Dobra, teraz część planu ze zdalną detonacją... och, jeszcze tego nie wyjaśniłem, prawda?$B$BNo więc w skrócie: z pomocą odrobiny magii mogę sprawić, że ładunki wybuchną, kiedy będziesz daleko. Składam urządzenie, dzięki któremu wystarczy wcisnąć jeden guzik, a NG-5 wybuchnie, kiedy tylko zechcesz.$B$BAle potrzebuję zaklęcia od przyjaciela z Wichrogrodu – nazywa się Collin Mauren. Znajdziesz go w tamtejszej Dzielnicy Magów. To człowiek, więc łatwo go wypatrzysz.', 'Odnajdź Collina Maurena w Wichrogrodzie.', '', '', '', '', '', '', 0),
(1076, 'koKR', 'Diabliki w Zachodnim Skraju', 'Ach, chyba już wiem. Zaklęcie przesyłania wiadomości... Myślę, że właśnie o taki efekt mu chodzi.$B$BBędę musiał sporządzić zwój z wpisanym w niego zaklęciem. Do tego potrzebuję szczątków pyłowego diablika.$B$BZanim zbiorę resztę składników, może udasz się do Zachodniego Skraju i odszukasz jedno z tych paskudnych stworzeń? Są niebezpieczne, ale skoro jesteś $ggotów:gotowa; poddać się jednemu z eksperymentów Gaxima, na pewno sobie z nimi poradzisz.$B$BBędę tu, kiedy wrócisz.', 'Przynieś szczątki pyłowego diablika Collinowi Maurenowi w Wichrogrodzie.', '', 'Wróć do Collina Maurena w Wichrogrodzie.', '', '', '', '', 0),
(1077, 'koKR', 'Przesyłka specjalna dla Gaxima', 'Proszę, $N. To powinno się sprawdzić.$B$BPozdrów ode mnie Gaxima, kiedy go zobaczysz. Chętnie posłucham o tej przygodzie, gdy dobiegnie końca.$B$BBywaj zdrów.', 'Zanieś zwój wiadomości Gaximowi Rdzawosykowi w Górach Szponogłazach.', '', '', '', '', '', '', 0),
(1078, 'koKR', 'Łuski dla Maurena', 'Podróżni ciągle wypytują mnie o Góry Szponogłazy. Wygląda na to, że to popularne miejsce dla poszukiwaczy przygód – nieważne, czy szuka się wywern, żywiołaków, czy ma się interesy ze spółką Gitgeszeft.$B$BW Zwęglonej Dolinie, w głębi Gór Szponogłazów, żył kiedyś gatunek bazyliszków, których łuski, starte na proch, były wspaniałym odczynnikiem do kilku opracowanych przeze mnie zaklęć.$B$BJeśli te bazyliszki wciąż tam żyją, bardzo chętnie zdobyłbym kilka ich łusek.$B$BNie spiesz się, to nic pilnego, ale dobrze zapłacę.', 'Przynieś 8 skrystalizowanych łusek Collinowi Maurenowi w Wichrogrodzie.', '', 'Wróć do Collina Maurena w Wichrogrodzie.', '', '', '', '', 0),
(1241, 'koKR', 'Zaginiony dyplomata', 'Niedawno wysłano do Theramore dyplomatę na spotkanie z Jainą Proudmoore. Ten dyplomata nigdy tam nie dotarł.$B$BPodejrzewam, że maczali w tym palce Nieskorni, ale nie wiem, w jaki sposób. Zniknięcie dyplomaty wciąż umyka uwadze opinii publicznej, ale to nie potrwa długo.$B$BAgenci króla już przeczesują miasto w poszukiwaniu tropów, ale chciałbym włączyć do sprawy także własne kontakty.$B$BW Dolinie Bohaterów przebywa mój stary przyjaciel, Jorgen. Znajdź go, daj mu ten liścik i postępuj zgodnie z jego wskazówkami.', 'Odnajdź Jorgena w Wichrogrodzie.', '', '', '', '', '', '', 0),
(1242, 'koKR', 'Zaginiony dyplomata', 'Zanieś ten tu liścik Ellingowi Triasowi. Nic więcej mu nie gadaj. Bądź $guprzejmy:uprzejma; i czekaj, aż odpowie. I nie martw się, odpowie.$B$BPowtórzę ci to już tylko raz, $N: traktuj tę sprawę poważnie i trzymaj język za zębami.$B$BTriasa znajdziesz w jego sklepie z serami, „Sery Triasa”, w Dzielnicy Handlowej. Powodzenia.', 'Dostarcz zapieczętowany liścik od Jorgena Ellingowi Triasowi w Wichrogrodzie.', '', '', '', '', '', '', 0),
(1243, 'koKR', 'Zaginiony dyplomata', 'Jorgen, ty stary sukin... A więc tak to ma wyglądać, co?$B$BDobra, jakoś to przełknę. Oby tym prędzej trafił do Wypaczonej Otchłani!$B$BPosłuchaj, jak to będzie, $N. Ja uruchomię tu swoje kontakty, ale większość bieganiny spadnie na ciebie, żebym zaoszczędził trochę grosza.$B$BUdaj się do Mrocznych Włości w Kniei Zmierzchu i odszukaj wartownika Backusa – zwykle patroluje północną drogę tuż za miastem. Powiedz mu po prostu, że na moją prośbę sprawdzasz, co porabiają Nieskorni, a przekaże ci wszystko, co wie.', 'Przekaż zapieczętowany liścik wartownikowi Backusowi w Kniei Zmierzchu.', '', '', '', '', '', '', 0),
(1244, 'koKR', 'Zaginiony dyplomata', 'Działalność Nieskornych? Cóż, zawsze coś się dzieje; nawet jeśli trzymają się na uboczu, uważamy ich za zagrożenie.$B$BAle skoro o tym mowa, niedawno doszło do dość dziwnego zdarzenia. To musiało być ze dwa tygodnie temu – kilku ich agentów zebrało się w okolicy Zagrody Addle\'a. Z raportu wnioskowałem, że wydarzyło się tam coś poważnego.$B$BMoże najpierw tam zajrzysz i przyniesiesz mi wszystko, co znajdziesz?$B$BZagroda leży na południe od drogi z Zachodniego Skraju, zaraz po wejściu do Kniei Zmierzchu.', 'Znajdź rejestr Nieskornych i zanieś go wartownikowi Backusowi w Kniei Zmierzchu.', '', 'Wróć do wartownika Backusa w Mrocznych Włościach w Kniei Zmierzchu.', '', '', '', '', 0),
(1245, 'koKR', 'Zaginiony dyplomata', 'Oho, to wygląda na zbyt skomplikowane, żeby miało tylko wyprowadzić cię w pole. Nie powinienem nawet na to patrzeć. Zanieś to Triasowi – on się w tym połapie. I NIE pozwól, żeby ktokolwiek wszedł ci w drogę. To mnie przerasta. Może nawet i jego, ale zobaczymy.$B$BI zrób mi przysługę, $N: nikomu nie mów, że ci pomogłem. Gdyby przełożeni się dowiedzieli, że o tym wiedziałem i nic im nie powiedziałem, pewnie by mnie powiesili.', 'Przynieś rejestr Nieskornych Ellingowi Triasowi w Wichrogrodzie.', '', '', '', '', '', '', 0),
(1246, 'koKR', 'Zaginiony dyplomata', 'No tak, skoro o tym mowa... Dashel... Dashel jakiśtam... Jak on się nazywał? PIĘŚĆ! Dashel Kamieniopięść. W pewnych kręgach mówią na niego Pięść – pewnie dlatego, że lubi się wdawać w bójki.$B$BZwykle znajdziesz go na Starym Mieście – w samym jego środku. Idź z nim pogadać. Jeśli będzie trzeba, użyj miecza albo czegoś ciężkiego i tępego, żeby go trochę rozgadać. I nie wahaj się. Jeśli siedzi w tym tak głęboko, jak wynika z tych papierów, z własnej woli nic ci nie powie.', 'Porozmawiaj z Dashelem Kamieniopięścią w Wichrogrodzie.', '', '', '', '', '', '', 0),
(1247, 'koKR', 'Zaginiony dyplomata', 'No więc tak... eee... może coś tam wiem o tym spotkaniu w Zagrodzie Addle\'a. Było chyba parę tygodni temu. Ja naprawdę nie miałem z tym nic wspólnego. Moja robota skończyła się, jak plan A nie wypalił... przeklęci poszukiwacze przygód.$B$BGość, którego mieli w środku do planu B, przyszedł z Przystani Menethilów; mówią na niego Chudy. Tyle wiem o ich planie awaryjnym.', 'Porozmawiaj z Ellingiem Triasem w Wichrogrodzie.', '', '', '', '', '', '', 0),
(1248, 'koKR', 'Zaginiony dyplomata', 'Jeden z moich dawnych kontaktów osiadł na emeryturze na Bagniskach, w portowym mieście Przystań Menethilów. Powinien ci pomóc na samo twoje słowo, jeśli powiesz mu, że pracujesz dla mnie. Nazywa się Mikhail. Kiedy kilka lat temu wyjeżdżał z Wichrogrodu, wspominał, że zostanie karczmarzem.$B$BPorozmawiaj z nim, znajdź tego Chudego i dowiedz się, czy jest coś jeszcze, co powinniśmy wiedzieć o tym porwanym dyplomacie. Musimy ustalić, dokąd go zabrali, albo przynajmniej kim jest. W rejestrze nie ma ani słowa o tym, co zamierzali zrobić po jego pojmaniu.', 'Porozmawiaj z Mikhailem na Bagniskach.', '', '', '', '', '', '', 0),
(1249, 'koKR', 'Zaginiony dyplomata', 'Mówisz, że przysłał cię Elling? W takim razie moja gościnność jest teraz dziesięciokrotnie większa. Czego tylko potrzebujesz, wystarczy poprosić. Zrobię, co w mojej mocy, żeby ci pomóc.$B$BHmm, Chudy, powiadasz? Nie wiem, czy to imię coś mi mówi, ale będę się za nim rozglądał.$B$BTylko się teraz nie odwracaj, $N, ale ten jegomość przy wyjściu patrzy w naszą stronę. Przysłuchuje się naszej rozmowie odrobinę zbyt uważnie, jeśli rozumiesz, co mam na myśli. Na twoim miejscu zrobiłbym wszystko, żeby go obezwładnić, zanim rzuci się do drzwi.', 'Obezwładnij Tapoke Jahna, zanim ucieknie, a potem wróć do Mikhaila w Przystani Menethilów.', 'Pokonaj Tapoke Jahna', 'Wróć do Mikhaila w tawernie „Głęboka Woda” w Przystani Menethilów.', '', '', '', '', 0),
(1250, 'koKR', 'Zaginiony dyplomata', 'Nieskorni nie płacili mi tyle, żebym miał za nich umierać. Porwali króla. Tak, króla Wichrogrodu, a nie jakiegoś podrzędnego dyplomatę. Płynął do Theramore na spotkanie z Jainą Proudmoore – podobno to była wielka sprawa i wielka tajemnica. Ale nie tylko Nieskorni są w to zamieszani. Współpracują z kimś. Chyba wiedzieli, że to ich przerasta.$B$BMoja rola polegała tylko na tym, żeby wprowadzić ich człowieka na pokład królewskiego statku, kiedy stał w porcie. Ten gość nazywał się Hendel. Tylko tyle wiem. Przysięgam!', 'Porozmawiaj z Mikhailem na Bagniskach.', '', '', '', '', '', '', 0),
(1260, 'koKR', 'Morgan Stern', 'Przygotowuję nowe menu dla restauracji. Będzie pełne wiejskich potraw w bagiennym stylu. Myślę, że moim gościom w „Błękitnym Samotniku” bardzo przypadną do gustu!$B$BWysłałem mojego bratanka Morgana do Theramore, miasta na skraju Pyłowego Bagniska. Zbiera tam przepisy od miejscowych, a ja muszę wiedzieć, co dotąd znalazł.$B$BPodróż do Theramore jest długa. Dla mnie za długa. Ale założę się, że ktoś tak młody jak ty chętnie skorzysta z okazji do podróży, prawda?', 'Porozmawiaj z Morganem Sternem w Theramore.', '', '', '', '', '', '', 0),
(1264, 'koKR', 'Zaginiony dyplomata', 'Na początku każdego miesiąca żołnierze piechoty morskiej z Kul Tiras dostają żołd i zwykle wyruszają z Theramore gdzie indziej. Wielu z nich przychodzi tutaj, żeby uganiać się za kobietami, hulać i po prostu dobrze się bawić. Jedną z tych grup zaliczam do stałych bywalców naszej tawerny i sądzę, że jest wśród nich ten Hendel.$B$BDowódca Samaul z Theramore pomoże ci go znaleźć, jeśli Hendel wciąż tam stacjonuje. Jest całkowicie lojalny wobec Proudmoore, ale jeśli rzucisz imieniem Ellinga, powinien ci pomóc... dyskretnie.', 'Odnajdź dowódcę Samaula na Pyłowym Bagnisku.', '', '', '', '', '', '', 0),
(1265, 'koKR', 'Zaginiony dyplomata', 'Hendel? Tak, znam go. Ale do czego ci jeden z moich żołnierzy?$B$BElling przysłał cię, żebyś go $godnalazł:odnalazła;? Hmm, nie podoba mi się to. Elling nie kazałby ci przychodzić najpierw do mnie, gdyby twoja sprawa nie była poważna. Rozumiem, jeśli nie możesz mi powiedzieć, o co chodzi, ale wiedz jedno: moim obowiązkiem jest chronić te ziemie. Jeśli zamierzasz wywołać zamieszanie, radzę ci powiedzieć mi tyle, ile możesz.$B$BO ile wiem, Hendel stacjonował w pierwszej wieży za Theramore. Bądź $gostrożny:ostrożna;.', 'Poszukaj w Posterunku Strażniczym jakichkolwiek śladów szeregowego Hendela.', 'Posterunek Strażniczy zbadany', 'Wróć do arcymaga Tervosha na Pyłowym Bagnisku.', '', '', '', '', 0),
(1266, 'koKR', 'Zaginiony dyplomata', 'Szeregowy Hendel jest na zachód stąd. Pełni wartę, pilnując odpoczywających infiltratorów z Theramore. Obserwują bazę Hordy w Paprotni i wypatrują wszystkiego, co mogłoby zagrozić naszym granicom.$B$BNie powinno być kłopotu z odnalezieniem go; wystarczy wypatrywać namiotów przy drodze.$B$BMuszę się zająć inną sprawą, ale wkrótce do ciebie dołączę. Gdybyś $gmiał:miała; jakiekolwiek kłopoty, zawsze znajdziesz mnie w wieży lady Proudmoore.', 'Odnajdź szeregowego Hendela na Pyłowym Bagnisku.', '', '', '', '', '', '', 0),
(1267, 'koKR', 'Zaginiony dyplomata', '', 'Porozmawiaj z Jainą Proudmoore na Pyłowym Bagnisku.', '', '', '', '', '', '', 0),
(1271, 'koKR', 'Uczta w „Błękitnym Samotniku”', '', '', '', '', '', '', '', '', 0),
(1274, 'koKR', 'Zaginiony dyplomata', 'Przepraszam, $gpanie:pani;. Biskup DeLavey poprosił mnie, żebym zagadywał poszukiwaczy przygód, którzy mogliby mu pomóc w pewnej delikatnej sprawie.$B$BJeśli po cichu udasz się do Twierdzy Wichrogród i porozmawiasz z nim przy najbliższej sposobności, z pewnością doceni twoją pomoc. Raz jeszcze proszę o dyskrecję. To sprawa niemałej wagi.', 'Odnajdź biskupa DeLaveya w Twierdzy Wichrogród.', '', '', '', '', '', '', 0),
(1301, 'koKR', 'James Hyal', 'Zanim zacząłem pracę tutaj, w „Błękitnym Samotniku”, szkolił mnie jeden z najlepszych kucharzy i karczmarzy, jakich w życiu spotkałem. Nazywał się James Hyal. Wszystko, co mam, i wszystko, co w życiu osiągnąłem, zawdzięczam jemu.$b$bCiekawe, jak mu się wiedzie. Razem z bratem, Vincentem, wyjechali do pracy w tawernie w Przystani Menethilów, ale ostatnio nie miałem od niego żadnych wieści.$b$bJeśli kiedyś będziesz w tamtych stronach, może pozdrowisz go ode mnie?', 'Porozmawiaj z Vincentem Hyalem w Przystani Menethilów.', '', '', '', '', '', '', 0),
(1324, 'koKR', 'Zaginiony dyplomata', 'Co?! Przychodzisz tu, oskarżasz mnie o konszachty z Nieskornymi i myślisz, że będę stał i słuchał, jak mnie obrażasz?! Coś mi mówi, że od dawna ci się to należało.', 'Pokonaj szeregowego Hendela na Pyłowym Bagnisku.', 'Obezwładnij szeregowego Hendela', 'Wróć do arcymaga Tervosha na Pyłowym Bagnisku.', '', '', '', '', 0),
(1338, 'koKR', 'Zamówienie Gromdardy', 'Jest pewien krasnoludzki płatnerz, którego prace bardzo podziwiam. Nazywa się Furen Długobrody i nie ma sobie równych. Potrzebuję nowej tarczy i muszę mieć tarczę jego roboty!$B$BKłopot w tym, że Furen jest daleko na południu, w Dzielnicy Krasnoludów w Wichrogrodzie. Na ziemiach ludzi! Nie mam pojęcia, czemu miałby tam mieszkać, tak daleko od Żelaznej Kuźni. Ludzie muszą mu płacić prawdziwą fortunę, żeby go tam zatrzymać!$B$BWięc jeśli masz ochotę na podróż i nie pogardzisz zarobkiem, zaniesiesz Furenowi moje zamówienie na tarczę?', 'Zanieś prośbę Gromdardy Furenowi Długobrodemu w Wichrogrodzie.', '', '', '', '', '', '', 0),
(1363, 'koKR', 'Polecenie Mazena', 'Jako opiekun zbiorów biblioteki Akademii Sztuk i Nauk Tajemnych odpowiadam za to, by wszystkie magiczne księgi i zwoje zawsze były na swoim miejscu. Kto wie, do jakich szaleństw by doszło, gdyby któreś z tych zaczarowanych pism wpadło w niepowołane ręce?$b$bCo mi przypomina... mój asystent, Dellis, popełnił w zeszłym tygodniu straszny błąd. W bibliotece radzi sobie świetnie, ale gdy tylko wyjdzie za bramy Wichrogrodu, jest zupełnie nieporadny. Bądź $gbohaterem:bohaterką; i pomóż staremu Dellisowi, dobrze?', 'Porozmawiaj z akolitą Dellisem w Wichrogrodzie.', '', '', '', '', '', '', 0),
(1364, 'koKR', 'Polecenie Mazena', 'Polecenia mistrza Mazena były zupełnie jasne: dostarczyć bardzo ważny esej wartownikowi Mahar Ba w Strażnicy Otchłani.$b$bAle ja nigdy wcześniej nie byłem na Jałowych Ziemiach! Podróż była przerażająca!$b$bKiedy dotarłem do Moczarów Smutków, skręciłem nie tam, gdzie trzeba, i otoczyły mnie okropne bagienne stwory podobne do roślin. Ruszyły na mnie chwiejnie, jakby chciały zaatakować, więc uciekłem. Ale w pośpiechu upuściłem esej. Jestem pewien, że zabrała go któraś z tych bestii.$b$bCzy możesz spróbować go odzyskać i dostarczyć wartownikowi Mahar Ba?', 'Odzyskaj Eseje Khadgara o zbieżności wymiarów i dostarcz je wartownikowi Mahar Ba w Strażnicy Otchłani.', '', 'Wróć do wartownika Mahar Ba w Strażnicy Otchłani na Jałowych Ziemiach.', '', '', '', '', 0),
(1447, 'koKR', 'Zaginiony dyplomata', 'No tak, $gnajbystrzejszym:najbystrzejszą; z tych, co przyłażą do Wichrogrodu, to ty nie jesteś, ale zaraz będziesz $gjednym:jedną; z najgłupszych, którzy już stąd nie wyjdą.$B$B$GPoznałeś:Poznałaś; moich kumpli?', 'Pokonaj Dashela Kamieniopięść w Wichrogrodzie.', 'Pokonaj Dashela Kamieniopięść', 'Porozmawiaj z Dashelem Kamieniopięścią w Wichrogrodzie.', '', '', '', '', 0),
(1448, 'koKR', 'W poszukiwaniu świątyni', 'Kiedyś i ja byłem młody i pełen wigoru, tak jak ty.$b$bAle teraz jestem stary i nie mogę już przemierzać świata jak dawniej. Ach, czego ja nie widziałem!$b$bByła jednak jedna zagadka, której nie zdołałem rozwiązać. W ramach mojej ostatniej wyprawy Liga Odkrywców wysłała mnie na poszukiwanie Świątyni Atal\'Hakkar. Podobno miała się znajdować w Moczarach Smutków.$b$bZe względu na wątłe zdrowie szukałem jej z powietrza, na grzbiecie gryfa, ale nigdy jej nie znalazłem.$b$bPomożesz staremu krasnoludowi? Może tobie, na piechotę, lepiej się poszczęści.', 'Brohann Beczkobrzuch z Wichrogrodu chce, żebyś $godszukał:odszukała; Świątynię Atal\'Hakkar.', 'Odszukaj Świątynię Atal\'Hakkar', 'Wróć do Brohanna Beczkobrzucha w Wichrogrodzie.', '', '', '', '', 0),
(1449, 'koKR', 'Do Zaziemia', 'Jak już wspominałem, próbowałem sam wypatrzyć świątynię z powietrza. Cóż, nie całkiem sam.$b$bUdałem się do słynnej gryfiej ptaszarni w Orlim Gnieździe w Zaziemiu. Tam poprosiłem o pomoc jednego z ich najlepszych lotników. Ten lotnik spadł z wierzchowca prosto w bagno...$b$bNa starość nie mogę sobie przypomnieć imienia biedaka. Ale mistrz ptaszarni na pewno je pamięta.$b$bUdaj się tam i odszukaj Falstada Dzikiego Młota.$b$bMusimy się dowiedzieć, co się stało z tym lotnikiem.', 'Porozmawiaj z wielkim thanem Falstadem Dzikim Młotem w Orlim Gnieździe w Zaziemiu.', '', '', '', '', '', '', 0),
(1469, 'koKR', 'Opowieść Rhapsody\'ego', 'Przed lotem wypiłem całą beczułkę stouta. Hep!$b$bI co to był za lot! Śmigałem w tę i we w tę, a Brohann za mną. Tylko żadnej świątyni nie widziałem. Hep!$b$bZnaczy, nie widziałem, póki się trochę za bardzo nie wstawiłem i nie spadłem z wierzchowca. Wpadłem prosto do wody i coś mnie wciągnęło na dno. Patrzę, a tu wokół banda upiornych trolli. Ale żem stamtąd zwiewał wpław, aż miło! Nawet zwinąłem tę trollową pamiątkę. Masz, zanieś ją Brohannowi i powiedz mu, że jego świątynia naprawdę tam jest, na dnie. Hep!', 'Zanieś fragment tabliczki Atal\'ai Brohannowi Beczkobrzuchowi w Wichrogrodzie.', '', '', '', '', '', '', 0),
(1475, 'koKR', 'W głąb Świątyni Atal\'Hakkar', 'Według legendy Świątynia Atal\'Hakkar to święty przybytek poświęcony pradawnemu bogu, Hakkarowi Duszożercy. Strzeże jej okrutne plemię trolli zwane Atal\'ai, a sama świątynia jest ponoć nie do zdobycia.$b$bTeraz, gdy spoczywa na dnie Sadzawki Łez, wydobycie z niej artefaktów jest jeszcze trudniejsze. Ale właśnie tego od ciebie potrzebuję, $n.$b$bPomóż mi, zbierając nienaruszone tabliczki Atal\'ai. Przynieś mi je, a wrócę do Ligi Odkrywców jako bohater. Razem podzielimy się chwałą.', 'Zbierz 10 tabliczek Atal\'ai dla Brohanna Beczkobrzucha z Wichrogrodu.', '', 'Wróć do Brohanna Beczkobrzucha w Wichrogrodzie.', '', '', '', '', 0),
(1477, 'koKR', 'Niezbędne zapasy', 'Nasi magowie prowadzą badania w Strażnicy Otchłani na Jałowych Ziemiach – badania kluczowe dla zrozumienia Mrocznych Portali. Potrzebują niemal nieustannych dostaw, ale nasz szlak zaopatrzenia do Strażnicy Otchłani jest niepewny.$B$BMusisz dopilnować, żeby zapasy dotarły na miejsce. Zgłoś się do komendanta warty Sorigala w Mrocznych Włościach i zrób, o co cię poprosi. To zadanie zaprowadzi cię na wrogie ziemie, $N. Przygotuj się.', 'Porozmawiaj z komendantem warty Sorigalem w Mrocznych Włościach w Kniei Zmierzchu.', '', '', '', '', '', '', 0),
(1639, 'koKR', 'Pijak Bartleby', 'Jasne, mogę cię uczyć. Ale najpierw chcę zobaczyć, co już potrafisz.$B$BWidzisz tamtego pijaka na końcu baru? Bartleby\'ego? Chcę, żebyś $gzdobył:zdobyła; jego kufel.$B$BHa, a jeśli znasz Bartleby\'ego, to wiesz, że tak po prostu ci go nie odda.', 'Porozmawiaj z Bartlebym.', '', '', '', '', '', '', 0),
(1640, 'koKR', 'Pokonaj Bartleby\'ego', 'Chcesz czego?! Chyba cię pogięło!$B$BTen kufel dostaniesz tylko wtedy, gdy wyrwiesz mi go z zimnych, martwych palców...', 'Pokonaj Bartleby\'ego, a potem z nim porozmawiaj.', 'Pokonaj Bartleby\'ego', 'Porozmawiaj z Bartlebym w Wichrogrodzie.', '', '', '', '', 0),
(1642, 'koKR', '', 'We wszystkim paladyn musi odzwierciedlać Światłość, która wspiera naszą siłę. Dążenie do boskości nie oznacza dla nas pragnienia, by stać się bogiem – dążymy do tego, by każdy nasz czyn był dobry.$B$BChoć w tych ciężkich czasach jesteśmy wzywani do gromienia zła, zawsze musisz pamiętać, że to pomoc innym naprawdę wyróżni cię spośród mieszkańców Azeroth. Współczucie, cierpliwość, odwaga – to wszystko znaczy dla paladyna tyle samo, co siła w bitwie.$B$BZapamiętaj to dobrze i nigdy nie zapominaj.', '', '', '', '', '', '', '', 0),
(1643, 'koKR', '', 'Twoim zadaniem, $N, jest więc znalezienie w Wichrogrodzie kogoś, kto potrzebuje pomocy. Kogoś o czystym sercu i czystych pobudkach. Może kogoś, kto sam pomaga innym. Może kogoś, kto potrzebuje przewodnika. Tak czy inaczej, ta osoba musi mieć szlachetne zamiary i liczyć na twoją życzliwość.$B$BZrób to i wróć do mnie, gdy skończysz. Wtedy porozmawiamy więcej o twojej ścieżce i o tym, co znaczy być paladynem Światłości.', 'Poszukaj Stephanie Turner w Dzielnicy Handlowej Wichrogrodu.', '', '', '', '', '', '', 0),
(1644, 'koKR', '', 'Biedactwa, większość z nich straciła rodziny w atakach Plagi w ostatnim dziesięcioleciu.$B$BMój mąż John zbiera dla mnie materiały, z których szyję dzieciom koszule i spodnie, ale nawet na to nie mam czasu. Skupiam się na tym, żeby miały co jeść i dach nad głową.$B$BCo takiego? Chcesz pomóc? Och, dzięki niech będą Światłości, i dziękuję ci, $N.$B$BGdybyś $gmógł:mogła; przynieść mi trochę lnianego płótna, żebym uszyła dzieciom ubrania, bardzo by mi to pomogło.', 'Przynieś 10 sztuk lnianego płótna Stephanie Turner w Wichrogrodzie.', '', 'Wróć do Stephanie Turner w Wichrogrodzie.', '', '', '', '', 0),
(1649, 'koKR', 'Księga Męstwa', 'Męstwo i wszystkie towarzyszące mu cnoty są jak rzadkie minerały: trzeba je cenić, gdy się je znajdzie, bo są wiele warte, ale trzeba też poświęcić czas, by je wydobyć... i oczyścić. Właściwie połączone tworzą mocny stop, którego czasem nie skruszą nawet najpotężniejsze ciosy.$B$BTa siła, twoja wiara, twoja odwaga muszą zostać wystawione na próbę. Musisz nauczyć się nigdy nie tracić wiary i zrozumieć, że dzięki mocy Światłości zdołasz pokonać to, czego większość innych nie potrafi.', '', '', '', '', '', '', '', 0),
(1650, 'koKR', 'Księga Męstwa', 'Dobrze! Brak wahania to pewny znak, że jesteś $ggotów:gotowa; i $gchętny:chętna;, by się sprawdzić. Niech więc tak będzie.$B$BNa samym krańcu Długiego Brzegu w Zachodnim Skraju stoi mały dom z widokiem na ocean. Mieszka tam para, Stilwellowie. Jordan to niezwykły kowal, a na jakiś czas wyjechał do Żelaznej Kuźni na spotkanie z krasnoludami. Przez to jego żona Daphne została sama, bez żadnej ochrony.$B$BZ raportów wynika, że Nieskorni praktycznie opanowali okolicę, więc Daphne może potrzebować ochrony przed tymi złoczyńcami. Udaj się tam.', 'Odnajdź Daphne Stilwell w Zachodnim Skraju.', '', '', '', '', '', '', 0),
(1652, 'koKR', 'Księga Męstwa', 'Proszę, wróć do Duthoriana i powiedz mu, że na razie jestem bezpieczna. Zawdzięczam to tobie i Kościołowi.$B$BOn przekaże wiadomość do Żelaznej Kuźni, żeby mój Jordan wiedział, że nie ma się czego obawiać.$B$BOch, jak ja tęsknię za mężem. Nie mogę się doczekać, aż wróci.', '', '', '', '', '', '', '', 0),
(1653, 'koKR', 'Próba prawości', 'Właściwie nie wątpię, że sam Jordan zechce ci podziękować, a skoro potrzebuję posłańca, który zaniesie mu wieść, że jego żona jest bezpieczna, myślę, że będziesz idealnym wyborem.$B$BJordan miał zostać paladynem Światłości, zanim oddanie rzemiosłu ojca poprowadziło go inną drogą – doskonale zna nasz sposób życia i uchodzi za jednego z najwierniejszych spośród nas.$B$BPowinien wciąż być w Żelaznej Kuźni – za dnia lubi pracować przed bramami, coś mówił o chłodnym górskim powietrzu.', 'Porozmawiaj z Jordanem Stilwellem w Żelaznej Kuźni.', '', '', '', '', '', '', 0),
(1665, 'koKR', 'Kufel Bartleby\'ego', 'No dobra, masz tu mój kufel. Czekaj! Najpierw dopiję, co w nim zostało... No, gotowe.', 'Zanieś kufel Bartleby\'ego Burlguardowi.', '', '', '', '', '', '', 0),
(1688, 'koKR', 'Surena Caledon', 'Miałem uczennicę imieniem Surena Caledon. Stała tam, gdzie ty teraz stoisz, spragniona wiedzy o magii czarnoksięskiej i obdarzona niemałym talentem. Co więcej, była młoda i miła dla oka. Gdybym tylko wtedy przejrzał tę zdradziecką ladacznicę!$b$bTa złodziejska dziewka uciekła z jednym z Nieskornych, Erlanem Drudgemoorem. Jej strata nie ma większego znaczenia, ale podarowałem jej obcisły naszyjnik z krwawnika, który muszę odzyskać.$b$bJej życie nic już dla mnie nie znaczy. Znajdziesz ją na dyniowym polu Brackwellów. Odzyskaj to, co moje.', 'Odzyskaj obcisły naszyjnik Sureny dla Gakina Mrokospętacza w Wichrogrodzie.', '', 'Wróć do Gakina Mrokospętacza w Wichrogrodzie.', '', '', '', '', 0),
(1689, 'koKR', 'Spętanie', 'Odzyskując mój naszyjnik i pokonując Surenę, $gudowodniłeś:udowodniłaś;, że jesteś co najmniej tak $gzdolny:zdolna; jak ona.$b$bMimo to widzę, że rozpaczliwie potrzebujesz szkolenia. Potrafisz kierować przepływami magii, owszem, ale bycie czarnoksiężnikiem to coś znacznie więcej.$b$bPokażę ci, jak rozkazywać wędrowcowi Pustki, ale najpierw musisz go przywołać w kręgu przywołań i ujarzmić wszelką bronią – fizyczną i magiczną – jaką masz do dyspozycji. Użyj magii tego naszyjnika w kręgu przywołań na dole.', 'Za pomocą obcisłego naszyjnika z krwawnika przywołaj i ujarzmij wędrowca Pustki, a potem zwróć naszyjnik Gakinowi Mrokospętaczowi w Wichrogrodzie.', '', 'Wróć do Gakina Mrokospętacza w Wichrogrodzie.', '', '', '', '', 0),
(1698, 'koKR', 'Yorus Jęczmieniowar', 'Yorus Jęczmieniowar rzucił wyzwanie wszystkim dzielnym wojownikom Przymierza. Czeka w karczmie w Jeziernych Włościach, w Rudej Grani, i obiecuje sowitą nagrodę każdemu, kto przejdzie jego próbę.', 'Porozmawiaj z Yorusem Jęczmieniowarem.', '', '', '', '', '', '', 0),
(1700, 'koKR', 'Grimand Elmore', 'Sporządziłem kopię notatek o technikach, których nauczyłem się przy robieniu twojej zbroi, i muszę je przesłać Grimandowi Elmore\'owi. Jest tu, w Dzielnicy Krasnoludów, w sklepie z bronią.$B$BI zrób unik, kiedy będziesz mu je wręczać. Jest diabelnie dumny ze swoich umiejętności i nie spodoba mu się myśl, że miałby się czegoś ode mnie uczyć...', 'Zanieś notatki Furena Grimandowi Elmore\'owi.', '', '', '', '', '', '', 0),
(1701, 'koKR', 'Hartowana w ogniu kolczuga', 'Dałem ci porządną tarczę, ale nie musimy na tym poprzestać. Znam sekret wykuwania niezwykle twardej kolczugi. To niełatwe i wymaga bardzo rzadkich surowców, ale jeśli zechcesz się nabiegać, zrobię ci taką.$B$BCo ty na to, $N? Jeśli podejmiesz wyzwanie, dam ci listę tego, co trzeba zdobyć, i gdzie tego szukać.', 'Zbierz surowce, których potrzebuje Furen Długobrody, i zanieś mu je do Wichrogrodu.', '', 'Wróć do Furena Długobrodego w Kniei Elwynn.', '', '', '', '', 0),
(1702, 'koKR', 'Kowal tarcz', 'Naprawdę $gpokazałeś:pokazałaś;, na co cię stać, kiedy $gprzeszedłeś:przeszłaś; ścieżkę zdrowia w Rethbanie, $N. A ja dotrzymuję słowa. Dostaniesz obiecaną nagrodę...$B$BTyle że jest w Wichrogrodzie.$B$BPorozmawiaj z moim przyjacielem, Furenem Długobrodym, w Dzielnicy Krasnoludów w Wichrogrodzie. To najlepszy kowal tarcz, jakiego spotkasz, a jest mi winien dużą przysługę.$B$BMasz, zanieś Furenowi tę beczkę Parzącego Jęczmiennego Browaru i poproś go o tarczę. Da ci porządną.', 'Zanieś beczkę Parzącego Furenowi Długobrodemu.', '', '', '', '', '', '', 0),
(1703, 'koKR', 'Mathiel', 'Sporządziłem kopię notatek o technikach, których nauczyłem się przy robieniu twojej zbroi, i trzeba je przesłać kowalowi Mathielowi. Mieszka w Darnassus, a to kawał drogi, ale jestem pewien, że będzie bardzo wdzięczny, gdy się dowie, czego się nauczyłem.', 'Zanieś notatki Furena Mathielowi.', '', '', '', '', '', '', 0),
(1704, 'koKR', 'Klockmort Kluczokręt', 'Sporządziłem kopię notatek o technikach, których nauczyłem się przy robieniu twojej zbroi, i potrzebuję kogoś, kto zaniesie je Klockmortowi Kluczokrętowi. To gnomi kowal z Żelaznej Kuźni, a kiedy się dowie, czego się nauczyłem... założę się, że z podniecenia wyrwie sobie brodę.', 'Zanieś notatki Furena Klockmortowi Kluczokrętowi.', '', '', '', '', '', '', 0),
(1705, 'koKR', 'Płonąca krew', 'Niechętnie to przyznaję, ale Furen chyba naprawdę coś odkrył. Żeby się jednak upewnić, muszę wypróbować jego techniki na nowej zbroi. Jeśli pomożesz mi zdobyć surowce, $N, zbroja będzie twoja.$B$BDo jej wykonania potrzebuję próbek płonącej krwi i płonącej skały.$B$BJedyne znane mi miejsce, gdzie można je zdobyć, to Knieja Zmierzchu. Worgeny Pożeracze Nocy, które zagnieździły się w kopalni w Zgubie Rolanda, mają płonącą krew, a skałę będzie miał ich przywódca, Flakowylew.$B$BOby szczęście dodało ci skrzydeł, $N.', 'Przynieś 20 fiolek płonącej krwi i 1 płonącą skałę Grimandowi Elmore\'owi w Wichrogrodzie.', '', 'Wróć do Grimanda Elmore\'a w Kniei Elwynn.', '', '', '', '', 0),
(1706, 'koKR', 'Zbroja Grimanda', '', '', '', '', '', '', '', '', 0),
(1715, 'koKR', '„Zarżnięte Jagnię”', 'Hmpf. Dawniej wszyscy czarnoksiężnicy w Khaz Modan szkolili się pod okiem mistrzów z Gnomoregan, ale teraz, kiedy musieliśmy się przenieść do tej szczurzej nory w Żelaznej Kuźni, a Magni postanowił pilnie nas obserwować, jesteśmy zmuszeni wysyłać nowicjuszy na szkolenie do Wichrogrodu.$b$bNa szczęście Gakin to nie byle kto, więc i tak nauczysz się tego, co trzeba, ale krew mnie zalewa!$b$bTak czy siak, Gakina znajdziesz w piwnicy tawerny „Zarżnięte Jagnię” w Wichrogrodzie.', '', '', '', '', '', '', '', 0),
(1716, 'koKR', 'Pożeracz dusz', 'Sukkub to pożeracz dusz, niszczyciel serc i władca umysłów. Nie zna niczego poza złem.$b$bTo właśnie tego demona nauczysz się przywoływać i kontrolować, ale nie da się go sprowadzić do naszego świata bez bodźca.$b$bZwabiony symbolem miłości z pewnością odpowie na twoje wezwanie. Wtedy możesz go pokonać i uczynić swoim narzędziem.$b$bTrudno jednak będzie znaleźć coś takiego. Porozmawiaj z Takarem Jasnowidzem. Znajdziesz go na Pustkowiach w Kalimdorze, niedaleko Obozu Taurajo.', 'Porozmawiaj z Takarem Jasnowidzem na Pustkowiach.', '', '', '', '', '', '', 0),
(1717, 'koKR', '', '$n! Nie spodziewałem się ciebie w tych stronach, ale kazano mi wypatrywać twojego przybycia.$b$bNajwyższy czas, żebyś $gprzeszedł:przeszła; dalsze szkolenie, więc następnym razem, gdy będziesz w Wichrogrodzie, zajrzyj do Gakina. Będzie na ciebie czekał.', '', '', '', '', '', '', '', 0),
(1718, 'koKR', 'Wyspiarz', 'Twoja sława jako $gwojownika:wojowniczki; rośnie, $N. Czas zmierzyć się z równymi sobie i przekonać się, ile jesteś $gwart:warta;.$B$BU wybrzeży Pustkowi, na południe od Zapadki, leży wyspa. Nazywa się Wyspa Jatki i spotykają się na niej wojownicy.$B$BSpotykają się i walczą.$B$BOdszukaj przywódcę wojowników Wyspy Jatki, Klannoca Macleoda. Jeśli uzna cię za $ggodnego:godną;, poprowadzi cię dalej ścieżką wojownika.$B$BAby dotrzeć na Wyspę Jatki, poszukaj płycizn przy mieliźnie wzdłuż Wybrzeża Kupców.', 'Odszukaj Klannoca Macleoda i porozmawiaj z nim.', '', '', '', '', '', '', 0),
(1738, 'koKR', 'Sercodrzew', 'Przygotowując się na twoje przybycie, użyłem swego wzroku, by spojrzeć na świat i przez mgły czasu. Znalazłem to, czego szukasz.$b$bW czasie Wojny Starożytnych dwoje kochanków poległo razem w bitwie. Tam, gdzie wydali ostatnie tchnienie, wyrosło drzewo zwane sercodrzewem – symbol ich nieśmiertelnej miłości.$b$bTo powinno wystarczyć, by skusić sukkuba. Znajdziesz je w Ruinach Ordil\'Aran, w północno-zachodniej części Jesionowej Kniei.', 'Zdobądź sercodrzew w Jesionowej Kniei i zanieś go Gakinowi Mrokospętaczowi w Dzielnicy Magów w Wichrogrodzie.', '', 'Wróć do Gakina Mrokospętacza w Wichrogrodzie.', '', '', '', '', 0),
(1739, 'koKR', 'Spętanie', 'Dzięki rdzeniowi sercodrzewu zdołasz rzucić w kręgu przywołań w krypcie na dole zaklęcie otwierające portal, przez który przejdzie sukkub.$b$bUważaj, $n, sukkuby zawładnęły już nawet najsilniejszymi umysłami.$b$bGdy go pokonasz i odeślesz z powrotem w pustkę, wróć do mnie, a pokażę ci, jak go przywoływać i nad nim panować.', 'Za pomocą rdzenia sercodrzewu przywołaj i ujarzmij sukkuba, a potem zwróć rdzeń Gakinowi Mrokospętaczowi w tawernie „Zarżnięte Jagnię”.', '', 'Wróć do Gakina Mrokospętacza w Wichrogrodzie.', '', '', '', '', 0),
(1780, 'koKR', '', 'Jeszcze dziś zaniosę to dzieciom. Proszę, uważaj na siebie, $N. Nieczęsto $gmężczyźni:kobiety; twojego pokroju pokazują się w mieście, ale $gudowodniłeś:udowodniłaś;, że paladyni z Wichrogrodu nigdy nie odwrócą się od potrzebujących.$B$BBywaj.', '', '', '', '', '', '', '', 0),
(1781, 'koKR', '', 'Weź to, $N. To Symbol Życia.$B$B$GOkazałeś:Okazałaś; się $gmiłosierny:miłosierna; i $gcierpliwy:cierpliwa;, a teraz nadszedł czas, by sprawdzić, czy masz dość mocy, by skupić jeden z największych darów Światłości.$B$BMój przyjaciel Gazin wrócił niedawno ze starcia z Nieskornymi w Elwynn, w pobliżu Czuwania Bohaterów – ledwo uszedł z życiem. Jest przy ołtarzu, gdzie nasi kapłani leczą jego rany.$B$BWeź Symbol i porozmawiaj z nim. Jeśli zdołasz mu pomóc, wkrótce znów porozmawiamy. Niech opromienia cię chwała Światłości.', 'Zanieś Symbol Życia Gazinowi Tenormowi w Wichrogrodzie.', '', '', '', '', '', '', 0),
(1782, 'koKR', 'Zbroja Furena', '', '', '', '', '', '', '', '', 0),
(1788, 'koKR', '', 'Zaniosę te pisma doradcom króla, kiedy Duthorian je przejrzy, ale tymczasem idź porozmawiać z Duthorianem. Na pewno zechce cię poklepać po plecach!$B$BJeszcze raz dziękuję, $N. Mam nadzieję, że jeszcze się spotkamy. Jesteś $gsojusznikiem:sojuszniczką;, $gktórego:którą; z dumą nazywam przyjacielem.', '', '', '', '', '', '', '', 0),
(1790, 'koKR', 'Symbol Życia', '', '', '', '', '', '', '', '', 0),
(1793, 'koKR', 'Księga Męstwa', '', '', '', '', '', '', '', '', 0),
(1798, 'koKR', 'W poszukiwaniu Strahada', 'Czas, żebyś $gnauczył:nauczyła; się przywoływać łowcę spaczenia, $n. Nie mam tu odczynników ani przedmiotów potrzebnych do tej nauki, więc musisz odszukać kogoś innego – Strahada Farsana, kolejnego członka naszego wewnętrznego kręgu.$b$bMieszka w Zapadce, goblińskim porcie. Wyślę mu wiadomość, żeby wiedział o twoim przybyciu.', 'Porozmawiaj ze Strahadem Farsanem na Pustkowiach.', '', '', '', '', '', '', 0),
(1861, 'koKR', 'Lustrzane Jezioro', 'Ten świat padł ofiarą potężnych zmagań mistycznych, które wyrwały prądy magii z niegdyś stabilnych kanałów. Próbujemy ustalić, jakie skutki wywołały te zmiany, a niektórzy z nas obawiają się najgorszego!$B$BAle więcej wyjawię ci później. Teraz musimy zebrać informacje.$B$BMasz, weź tę flaszkę. Idź do stóp wodospadu nad Lustrzanym Jeziorem, na południowy zachód od bram Wichrogrodu, i nabierz próbkę tamtejszej wody. Przynieś mi ją, żebym mogła zbadać, czy nie ma w niej magicznych skażeń.', 'Przynieś próbkę wody z Lustrzanego Jeziora Jennei Cannon w Wichrogrodzie.', '', 'Wróć do Jennei Cannon w Wichrogrodzie.', '', '', '', '', 0),
(1920, 'koKR', 'Zbadaj „Błękitnego Samotnika”', 'Zgłoszono zakłócenia w tawernie „Błękitny Samotnik” w Dzielnicy Magów. Po tawernie krążą teraz dziwne, niewidzialne stwory i obawiam się, że powstała tam szczelina many.$B$BChcę, żebyś $gzbadał:zbadała; tawernę i $gschwytał:schwytała; te stwory. Użyj w tawernie inkantacji manifestacji, żeby stwory stały się widoczne, obezwładnij je, a potem schwytaj za pomocą szkatuły izolującej. Gdy zbierzesz ich dość, wróć do mnie z napełnionymi szkatułami, pustymi szkatułami i inkantacją.', 'Weź inkantację manifestacji oraz szkatuły ze skrzyni szkatuł izolujących, która stoi za Jenneą Cannon. Przynieś 3 napełnione szkatuły izolujące Jennei do sanktuarium czarodziejów.', '', 'Wróć do Jennei Cannon w Wichrogrodzie.', '', '', '', '', 0),
(1921, 'koKR', 'Zbieranie materiałów', 'Dobrze $gsłużyłeś:służyłaś; innym magom i nadszedł czas, byś $gprzywdział:przywdziała; szatę czarodzieja. Wynne Larson może ją uszyć, ale musisz przynieść jej potrzebne materiały.$B$BSzata będzie z lnianego płótna, które łatwo znaleźć, ale musisz też zdobyć naładowane klejnoty szczeliny, a jedyne znane miejsce, gdzie można je znaleźć, to Kopalnia Srebrnego Strumienia w Loch Modan – zostawił je tam w skrzyniach krasnoludzki związek górników.$B$BZbierz płótno i klejnoty i zanieś je Wynne Larson do „Odzieży Larsona” w Dzielnicy Magów.', 'Przynieś 10 sztuk lnianego płótna i 6 naładowanych klejnotów szczeliny Wynne Larson w Wichrogrodzie.', '', 'Wróć do Wynne Larson w Wichrogrodzie.', '', '', '', '', 0),
(1938, 'koKR', 'Traktat Ura o magii cienia', 'Dawno temu w tej wieży studiowało trzech magów, aż jeden z nich uległ mrocznym sztukom. Nakłaniano go, by odwrócił się od tej złej magii, ale nie potrafił się jej oprzeć. Dlatego został wygnany.$B$BNową domeną upadłego maga jest Wieża Ilgalara w Rudej Grani, a zabrał ze sobą potężną księgę – Traktat Ura o magii cienia.$B$BMy, magowie Wichrogrodu, chcemy odzyskać tę księgę. Wejdź do Wieży Ilgalara, znajdź księgę w jego bibliotece i przynieś ją mnie.', 'Zanieś Traktat Ura o magii cienia arcyczarownikowi Andromathowi w Wichrogrodzie.', '', 'Wróć do arcyczarownika Andromatha w Wichrogrodzie.', '', '', '', '', 0),
(1939, 'koKR', 'Arcyczarownik Andromath', 'Arcyczarownik Andromath chce z tobą porozmawiać, $N. Przebywa na szczycie sanktuarium czarodziejów, w Dzielnicy Magów w Wichrogrodzie.$B$BRozsądnie byłoby z nim porozmawiać, bo Andromath to jeden z najpotężniejszych magów, których nie zamknięto w Dalaranie. Jego rada to rada najwyższej próby.', 'Porozmawiaj z arcyczarownikiem Andromathem.', '', '', '', '', '', '', 0),
(1940, 'koKR', 'Nieskazitelny pajęczy jedwab', 'Twoja służba była niezłomna, $N. Myślę, że może nadszedł czas, byś $gotrzymał:otrzymała; lepszy strój, bardziej odpowiedni dla twojej pozycji $gbiegłego maga:biegłej magini;. Jeśli zbierzesz potrzebne materiały, załatwimy uszycie szaty.$B$BMusisz udać się do Kniei Zmierzchu i zapolować na padlinowe samotniki. Wydobądź z nich jedwab, ale nada się tylko najlepszy, najbardziej nieskazitelny. Gdy zbierzesz go dość, zanieś go Wynne Larson tutaj, w Dzielnicy Magów, do „Odzieży Larsona”. Ona uszyje ci szatę.', 'Przynieś 8 sztuk nieskazitelnego pajęczego jedwabiu Wynne Larson w Wichrogrodzie.', '', 'Wróć do Wynne Larson w Wichrogrodzie.', '', '', '', '', 0),
(1941, 'koKR', 'Szata z tkaniny many', '', '', '', '', '', '', '', '', 0),
(1942, 'koKR', 'Odzienie astralnego węzła', '', '', '', '', '', '', '', '', 0),
(1947, 'koKR', 'Wyprawa na bagna', 'Teraz nadszedł czas, byś $gzasłużył:zasłużyła; na różdżkę maga. Aby rozpocząć to zadanie, porozmawiaj z Tabethą, ludzką pustelnicą z Pyłowego Bagniska. Jej chatę znajdziesz głęboko na bagnach, na zachód od Theramore.$B$BPorozmawiaj z nią, bo jej wiedza jest ogromna. Chatę Tabethy znajdziesz na zachód od Theramore, tuż na północ od Ruin Kamiennych Maczug.', 'Porozmawiaj z Tabethą.', '', '', '', '', '', '', 0),
(1953, 'koKR', 'Powrót na bagna', 'Nadszedł czas, $N, byś $gporozmawiał:porozmawiała; z Tabethą... pustelnicą z Pyłowego Bagniska. Nauczy cię, jak stworzyć potężne narzędzie maga.$B$BChata Tabethy stoi głęboko na Pyłowym Bagnisku, na zachód od Theramore.', 'Porozmawiaj z Tabethą.', '', '', '', '', '', '', 0),
(2040, 'koKR', 'Podziemny szturm', 'Gnomoregan wpadł w łapy tych podłych troggów! Sytuacja jest poważna, ale może ty zdołasz pomóc, $N.$B$BGłęboko w Martwej Kopalni stoi sprawny gobliński rozdrabniacz. Znajdź go i przynieś jego nienaruszone źródło zasilania. Dzięki niemu dostarczymy naszym żyrowiertomatycznym ekskawatorom mocy potrzebnej do przebicia się przez skaliste podziemne granice Gnomoregan i otworzymy drogę do gnomiego szturmu!', 'Zdobądź Gnoam Sprecklesprocket w Martwej Kopalni i zanieś go Shoni Szichej w Wichrogrodzie.', '', 'Wróć do Shoni Szichej w Dzielnicy Krasnoludów w Wichrogrodzie.$B', '', '', '', '', 0),
(2041, 'koKR', 'Porozmawiaj z Shoni', 'Może... Może ty pomożesz nam w bitwie o Gnomoregan.$B$BW Wichrogrodzie znajdziesz dowódczynię naszego podziemnego oddziału szturmowego, Shoni Szichą. Shoni potrzebuje pomocy przy swoich żyrowiertomatycznych ekskawatorach.$B$BPewnie znajdziesz ją wśród krasnoludów w Wichrogrodzie.$B$BPowodzenia, $N.', 'Porozmawiaj z Shoni Szichą w Dzielnicy Krasnoludów w Wichrogrodzie.$B', '', '', '', '', '', '', 0),
(2206, 'koKR', 'Capnij i zmykaj', 'Nasi agenci w terenie donoszą o wzmożonej aktywności Nieskornych na południe od Złotych Włości. Z raportów wynika, że Nieskorni przejęli Przystań Jeroda i przemycają przez nią duże ilości kontrabandy z Rudej Grani do Zachodniego Skraju.$B$BMusisz przeniknąć do budynku portowego i zdobyć dla mnie ten harmonogram wysyłek, $N. Pewnie znajdziesz go głęboko w kieszeniach bosmana portowego.$B$B...i, $N, jeśli cię nakryją, WW:7 wyprze się jakiejkolwiek wiedzy o twoim istnieniu.', 'Znajdź bosmana portowego Nieskornych i odzyskaj harmonogram wysyłek dla mistrza Mathiasa Shawa.$B', '', 'Wróć do mistrza Mathiasa Shawa w siedzibie WW:7 w Wichrogrodzie.', '', '', '', '', 0),
(2260, 'koKR', 'Polecenie Eriona', 'Wieści o twoich czynach rozeszły się szeroko, $N. Tak szeroko, że wywiad Wichrogrodu zapytał o ciebie z imienia.$B$BPodróż jest męcząca i nie bez niebezpieczeństw, ale okazji do szkolenia pod okiem WW:7 nie należy lekceważyć.$B$BCzeka na ciebie nowy świat, $N. Udaj się na Stare Miasto w Wichrogrodzie i porozmawiaj z Renzikiem „Kosa” w siedzibie WW:7.$B', 'Udaj się do Wichrogrodu i zgłoś się do Renzika „Kosa”.', '', '', '', '', '', '', 0),
(2281, 'koKR', 'Spotkanie w Rudej Grani', 'Wysłanie cię teraz w teren byłoby samobójstwem. Renzik nie potrzebuje kolejnego martwego łotra na sumieniu. Ale nie martw się, $N – Renzik cię podszkoli.$B$BUdaj się w Góry Rudej Grani i porozmawiaj ze współpracownikiem WW:7 imieniem Lucius. Znajdziesz go w dokach Jeziernych Włości, gdzie kręci się z innymi podejrzanymi nicponiami.', 'Wyrusz do Jeziernych Włości w Górach Rudej Grani i porozmawiaj z Luciusem.', '', '', '', '', '', '', 0),
(2298, 'koKR', 'Królewska obława', 'No więc siedzim tu, mamy właśnie rozpisywać fazę III, a tu wpada paru tych tępaków Magniego i gada coś o jakimś skoku, i aresztuje paru z Ukrytego Kręgu.$B$BA starego Czarnobrodego nikt w kajdany nie zakuje! Dyskutacja zrobiła się gęsta i ciężka, i jakosik wypsnęło się twoje imię!$B$BMoja rada? Łap pierwszego gryfa z Żelaznej Kuźni i leć do Wichrogrodu. Idź na Stare Miasto i tam pogadaj z moim starym kumplem, Renzikiem „Kosa”.', '', '', '', '', '', '', '', 0),
(2359, 'koKR', 'Wieża Klavena', 'Od tygodni obserwuję tę wieżę, $N. Niedawno przyszedł duży transport z Kniei Zmierzchu, a razem z nim ci strażnicy.$B$BCzym oni są? Wiem tyle, co ty. Jedno mogę ci powiedzieć – to nie są ludzie.$B$BTak czy inaczej, w transporcie była skrzynia – zakładam, że to jej pilnują te poczwary. Zombie z kolcami ma klucz, którego będziemy potrzebować.$B$BZdobądź ten klucz, dostań się do wieży i sprawdź, co jest w skrzyni. Ze swoimi odkryciami wróć do Mathiasa.', 'Wykradnij klucz do wieży Nieskornych, włam się do wieży i sprawdź zawartość skrzyni z Kniei Zmierzchu. Wszelkie znalezione informacje zanieś Mathiasowi Shawowi w Wichrogrodzie. Przeczytaj dziennik Kearnen, by dowiedzieć się więcej o wieży.$B', '', 'Wróć do mistrza Mathiasa Shawa w siedzibie WW:7 w Wichrogrodzie.', '', '', '', '', 0),
(2360, 'koKR', 'Mathias i Nieskorni', 'W samą porę, $N. Zwiad WW:7 donosi o niezwykle wzmożonej aktywności Nieskornych w Zachodnim Skraju.$B$BWygląda na to, że Nieskorni zajęli opuszczoną wieżę strażniczą Przymierza na południowy wschód od Wzgórza Strażniczego i wykorzystują ją jako bazę do przemytu towarów szlakiem zaopatrzeniowym z Rudej Grani.$B$BUdaj się do Zachodniego Skraju i skontaktuj się z agentką Kearnen, która przekaże ci szczegóły. Znajdziesz ją w ukryciu w pobliżu wieży.$B$B...i, $N, jeśli cię nakryją, WW:7 wyprze się jakiejkolwiek wiedzy o twoim istnieniu.', 'Udaj się do Zachodniego Skraju i odszukaj agentkę Kearnen, która przekaże ci szczegóły zadania.', '', '', '', '', '', '', 0),
(2745, 'koKR', 'Infiltracja zamku', 'Hmm, ciekawa historia i nie wolno jej lekceważyć. Tak, mogę ci pomóc, ale jeśli chcesz doprowadzić sprawę do końca, musisz wymierzyć sprawiedliwość w sposób niezupełnie... legalny.$B$BTrzeba się rozprawić z Lescovarem i Marzonem, i to szybko. Myślisz, że dasz radę?$B$BTwoja decyzja. Jeśli tak, pospiesz się do zamku i odszukaj mojego starego przyjaciela, gnoma imieniem Tyrion. Od paru tygodni obserwuje Lescovara. Powinien pomóc ci to zakończyć.', 'Porozmawiaj z Tyrionem w zamku Wichrogrodu.', '', '', '', '', '', '', 0),
(2746, 'koKR', 'Rzeczy niemałej wagi', 'Trias chce przyspieszyć harmonogram, co? Dobra, da się zrobić, ale nie jestem gotowy. I wiedz jedno: ja robię najtrudniejszą część, ale to ty ubrudzisz sobie ręce, jasne? Dobrze.$B$BDobra, zanim wprowadzę plan w życie, musisz mi zdobyć kilka rzeczy. Mam idealne przebranie, dzięki któremu szpiegobot prześlizgnie się obok strażników.$B$BPrzynieś mi trochę jedwabiu i parę jabłek. Jedwab zdobądź, jak chcesz, ale na małej farmie Clary tuż za miastem rosną jabłka idealnej wielkości.', 'Przynieś 3 sztuki jedwabnego płótna i 2 świeże jabłka Clary Tyrionowi w Wichrogrodzie.', '', 'Wróć do Tyriona w Wichrogrodzie.', '', '', '', '', 0),
(2758, 'koKR', 'Źródło kowalstwa', 'Kiedy byłem mniej więcej w twoim wieku, krasnolud imieniem Galvan wziął mnie pod swoje skrzydła i wyszkolił na płatnerza. Zanim wyjechał do Łupieżczej Zatoki, kazał mi obiecać, że będę uczyć każdego, kto ma chęć i determinację, by doskonalić się w sztuce kowalstwa – i oto jestem, po tylu latach.$B$BA teraz twoja kolej, żeby się czegoś nauczyć. Zrób mi sześć par karwaszy ze złotych łusek, a dowiesz się, skąd bierze się kowalstwo, $N.', 'Przynieś sześć par karwaszy ze złotych łusek Hankowi Młotowi w Wichrogrodzie.', '', 'Wróć do Hanka Młota w Dzielnicy Krasnoludów w Wichrogrodzie.', '', '', '', '', 0),
(2759, 'koKR', 'W poszukiwaniu Galvana', 'Choć Galvan opuścił Łupieżczą Zatokę wiele lat temu, członkowie zakonu wciąż mieszkają w mieście w nadziei, że pewnego dnia znajdą kogoś jeszcze godnego nauk Galvana.$B$BWeź tę odznakę i pokaż ją McGavanowi w Łupieżczej Zatoce.$B$BJeśli naprawdę tam dotrzesz, będzie wiedział, że jesteś $ggodzien:godna;. Wierzę w ciebie, $N!', 'Porozmawiaj z McGavanem w Łupieżczej Zatoce.', '', '', '', '', '', '', 0),
(2861, 'koKR', 'Zadanie Tabethy', 'Chodzą słuchy, że Tabetha, zaprzyjaźniona magini, która mieszka w głębi Pyłowego Bagniska, ma kość niezgody z pewną piaskową trollicą z Zul\'Farrak. Jeśli porozmawiasz z Tabethą, powie ci więcej.$B$BI weź ze sobą przyjaciół, $N. Jeśli Tabetha pośle cię do Zul\'Farrak, lepiej nie idź tam w pojedynkę.$B$BChatkę Tabethy znajdziesz na zachód od Theramore, tuż na północ od Ruin Kamiennych Maczug.', 'Porozmawiaj z Tabethą na Pyłowym Bagnisku.', '', '', '', '', '', '', 0),
(2923, 'koKR', 'Nadiskrownik Opiłek', 'Nadiskrownik Opiłek bardzo się przejmuje losem swojego mechanicznego dzieła, Techbota. Pamiętam Techbota jako życzliwe i pomocne narzędzie gnomów, ale Opiłek mówi mi, że coś się w nim popsuło.$B$BBardzo smutne. Ale przy odrobinie szczęścia może da się go naprawić!$B$BPorozmawiaj z Nadiskrownikiem Opiłkiem w Majsterkowie w Żelaznej Kuźni. Z radością przyjmie twoją pomoc.', 'Porozmawiaj z Nadiskrownikiem Opiłkiem w Żelaznej Kuźni.', '', '', '', '', '', '', 0),
(2928, 'koKR', 'Żyrowiertłomatyczne wykopywacze', 'To straszne, $N. Nie starczy nam części, żeby dostarczyć naszą flotę żyrowiertłomatycznych wykopywaczy do Dun Morogh.$B$BPotrzebujemy części zamiennych, $N. A gdzie lepiej zdobyć części do naszych maszyn niż w Gnomoregan? Słyszałam, że boty i mechy łażą tam jak bydło po otwartym pastwisku.$B$BChcę, żebyś $gposzedł:poszła; do Gnomoregan i $grozebrał:rozebrała; te roboty na części. Przynieś mi ich robotyczne flaki. Dwa tuziny powinny wystarczyć.$B', 'Przynieś dwadzieścia cztery robomechaniczne flaki Shoni w Wichrogrodzie.', '', 'Wróć do Shoni Szichej w Dzielnicy Krasnoludów w Wichrogrodzie.', '', '', '', '', 0),
(3000, 'koKR', '', 'Witaj, $N. Wiem, że masz pełne ręce roboty, pomagając mieszkańcom Azeroth, ale kiedy znajdziesz czas, wróć do Żelaznej Kuźni i porozmawiaj z jedną z najbardziej szanowanych paladynek twojej ojczyzny: Tizą Bojokuć. To do niej przychodzą młodsi krasnoludzcy paladyni, gdy nadchodzi czas, by dowiedzieć się więcej o Światłości i o tym, czego oczekuje się od nas wszystkich.$B$BZnajdziesz ją na piętrze Sali Tajemnic w Dzielnicy Mistycznej.', 'Porozmawiaj z Tizą Bojokuć w Żelaznej Kuźni.', '', '', '', '', '', '', 0),
(3630, 'koKR', 'Gnomia inżynieria', 'Inżynieria na poziomie eksperckim dzieli się na dwie dyscypliny: gnomią i goblińską. Gnomia inżynieria jest zdecydowanie lepsza z nich dwóch! Chodzi w niej o konstruowanie wspaniałych gadżetów i urządzeń, które ułatwiają życie!$B$B$N, przeczytaj ten podręcznik. Jeśli chcesz dowiedzieć się więcej o gnomiej inżynierii, zanieś go Nadiskrownikowi Opiłkowi w Żelaznej Kuźni. Pamiętaj – przynależność jest dożywotnia i wyklucza wstąpienie do drugiej dyscypliny, więc upewnij się, że naprawdę tego chcesz, zanim wykonasz jego zadanie!', 'Jeśli chcesz dowiedzieć się więcej o gnomiej inżynierii, zanieś podręcznik dyscyplin inżynieryjnych Nadiskrownikowi Opiłkowi w Żelaznej Kuźni.', '', '', '', '', '', '', 0),
(3636, 'koKR', 'Nieś Światłość', 'Plaga to nieustanne zagrożenie dla Przymierza, o czym z pewnością dobrze wiesz. Ostatnio dokonaliśmy bardzo osobliwych odkryć, $N.$B$BNa Pustkowiach leży okropna plątanina ciernistych pnączy zwana Kurhanami Brzytwoskórych. Niegdyś był to dom zwykłych kolcozwierzy, lecz teraz stało się jasne, że zawarto tam pakt z Plagą, z którego zrodziły się istoty o wiele gorsze... Rządzi nimi teraz lisz, Amnennar Zwiastun Chłodu.$B$BStań po stronie Światłości, $N; połóż kres temu złowrogiemu sojuszowi.', 'Arcybiskup Benedykt chce, żebyś $gzabił:zabiła; Amnennara Zwiastuna Chłodu w Kurhanach Brzytwoskórych.', '', 'Wróć do arcybiskupa Benedykta na Placu Katedralnym w Wichrogrodzie.', '', '', '', '', 0),
(3681, 'koKR', '', 'Wybacz, że przerywam ci podróż, $N, ale uznałem, że musisz o tym wiedzieć: niedawno przyszła z Wichrogrodu wiadomość, że paladyni mają się tam stawić na szkolenie.$B$BJeśli się nie mylę, zbliża się dla ciebie szczególna chwila i czas, żebyś $gzaczął:zaczęła; studiować Księgi.$B$BSzukaj Duthoriana Ralla w Wichrogrodzie. Zwykle szkoli paladynów w Katedrze Światła.', 'Porozmawiaj z Duthorianem Rallem w Wichrogrodzie.', '', '', '', '', '', '', 0),
(3765, 'koKR', 'Splugawienie za morzem', 'Wichrogród – cóż za tętniące życiem miejsce.$b$bPrzybyłem z daleka, by szukać pomocy. Często słyszy się, że po ulicach tego miasta przechadzają się dzielni poszukiwacze przygód.$b$bMój brat, Gershala, potrzebuje pomocy na Mrocznym Wybrzeżu. Mieszka w nadmorskim miasteczku Auberdine.$b$bPodróż jest długa i pełna przygód. Dlatego właśnie proszę o pomoc kogoś tak doświadczonego jak ty.', 'Udaj się do Gershali Nocnego Szeptu w Auberdine.', '', '', '', '', '', '', 0),
(3787, 'koKR', 'Prośba Jonespyre\'a', 'Przepraszam, $gprzyjacielu:przyjaciółko;...$B$BMój znajomy chciałby z tobą porozmawiać o badaniach, które prowadzisz wspólnie z Kręgiem Cenariona. To druid o imieniu Quintis Jonespyre, mieszka w Warowni Lunopiórej w Feralas. Chciałby omówić z tobą sprawę jutroziarna... i bardzo mu zależy, żeby nasza rozmowa nie dotarła do uszu arcydruida.$B$BJeśli cię to interesuje, porozmawiaj z nim; bez wątpienia wszystko się wtedy wyjaśni.', 'Porozmawiaj z Quintisem Jonespyre\'em w Warowni Lunopiórej.', '', '', '', '', '', '', 0),
(3789, 'koKR', 'Pomoc arcydruidowi Jeleniorogiemu', 'Przepraszam, $N, ale jeśli to możliwe, chciałabym zająć ci tylko chwilę.$B$BKrąg Cenariona w Darnassus szuka doświadczonych poszukiwaczy przygód, takich jak ty, którzy wsparliby ważny projekt badawczy. Nie znam szczegółów, ale mogę ci powiedzieć, że na czele tych badań stoi nie kto inny jak sam arcydruid Fandral Jeleniorogi.$B$BProszę – jeśli cię to interesuje, porozmawiaj z nim osobiście w Enklawie Cenariona w samym Darnassus.', 'Porozmawiaj z arcydruidem Fandralem Jeleniorogim w Darnassus.', '', '', '', '', '', '', 0),
(4181, 'koKR', 'Goblińska inżynieria', 'Inżynieria na poziomie eksperckim dzieli się na dwie odrębne dyscypliny: gnomią i goblińską. O goblińskiej inżynierii wspominam tylko dlatego, że jestem uczciwym nauczycielem. Gobliny lubią robić rzeczy, które wybuchają, i rzadko przejmują się tym, co stoi na drodze – nawet jeśli to one same.$B$B$N, przeczytaj ten podręcznik. Jeśli chcesz się nauczyć, jak wysadzić się w powietrze, zanieś go Nixxowi Sprężynotrybowi w Gadżetonie. Pamiętaj – przynależność jest dożywotnia i wyklucza wstąpienie do drugiej dyscypliny, więc upewnij się, że właśnie tego chcesz, zanim wykonasz jego zadanie.', 'Jeśli chcesz dowiedzieć się więcej o goblińskiej inżynierii, zanieś podręcznik dyscyplin inżynieryjnych Nixxowi Sprężynotrybowi w Gadżetonie.', '', '', '', '', '', '', 0),
(4485, 'koKR', 'Księga Szlachetności', 'Witaj, $N. Widzę, że twoje oddanie wciąż jest silne, podobnie jak twoja wiara.$B$BMyślę, że nadszedł czas, byś $gporozmawiał:porozmawiała; z Duthorianem Rallem w Wichrogrodzie. Czeka cię jeszcze kilka lekcji, a czuję, że jesteś $ggotów:gotowa;.$B$BOdszukaj go w Katedrze Światła i, $N, traktuj te lekcje poważnie. $GOsiągnąłeś:Osiągnęłaś; swoją pozycję dzięki pokorze i ciężkiej pracy, nie rozczaruj nas, popadając w arogancję.$B$BBywaj.', '', '', '', '', '', '', '', 0),
(4486, 'koKR', 'Księga Szlachetności', 'No proszę, proszę, spójrzcie tylko na $gpotężnego paladyna w całym jego:potężną paladynkę w całym jej; majestacie.$B$BWybacz, $N, nie chciałem cię urazić... Po prostu czasem trochę zazdroszczę, kiedy widzę niektóre z twoich dokonań. Tiza mówi, że to moja słabość, i przysiągłem jej, że będę nad tym pracował. Tylko że czasem jest ciężko, wiesz?$B$BAle chciałem z tobą porozmawiać, bo Duthorian Rall z Wichrogrodu przekazał, żebyś $gspotkał:spotkała; się z nim w Katedrze Światła, kiedy będziesz $ggotów:gotowa;. Brzmiało to poważnie. Wygląda na to, że coś się dzieje.', '', '', '', '', '', '', '', 0),
(4738, 'koKR', 'W poszukiwaniu Menary Rozdzieraczki Pustki', 'Wyjaśnijmy sobie jedno, $N: nie uważam, żebyś $gbył gotów:była gotowa; na takie obowiązki. Nie sądzę, by nowicjusz kiedykolwiek powinien brać udział w tworzeniu przedmiotu mocy, a zwłaszcza ktoś tak niesprawdzony.$B$BAle to nie moja decyzja. Decydują o tym moce wyższe, a przynajmniej te, które pragną obdarzyć cię takimi darami.$B$BJeśli chcesz dowiedzieć się więcej, radzę ci odszukać Menarę Rozdzieraczkę Pustki w Zapadce. Zwykle przebywa w wieży nad portowym miasteczkiem.', 'Porozmawiaj z Menarą Rozdzieraczką Pustki na Pustkowiach.', '', '', '', '', '', '', 0),
(4765, 'koKR', 'Dostawa dla Ridgewella', 'Zapakowałam klamrę Doomriggera do skrzyni, żeby można ją było wysłać do Wichrogrodu. $N, $gbyłeś:byłaś; mi ogromną pomocą – czy mogę cię prosić o ostatnią przysługę?$B$BDostarcz skrzynię hrabiemu Remingtonowi Ridgewellowi. Znajdziesz go w Twierdzy Wichrogród. Jestem pewna, że bardzo się ucieszy, widząc, co dla niego masz.', 'Zanieś skrzynię Ridgewella hrabiemu Remingtonowi Ridgewellowi w Twierdzy Wichrogród w Wichrogrodzie.', '', '', '', '', '', '', 0),
(4766, 'koKR', 'Mayara Jasnoskrzydła', 'Moja agentka, Mayara Jasnoskrzydła, została wysłana na Płonące Stepy, by przeszukać zrujnowane miasto Thaurissan. To zniszczone miasto krasnoludów z Czarnorytych może skrywać przedmioty wielkiej wartości... przedmioty, które świetnie pasowałyby do naszego rodzinnego muzeum.$B$BMayara twierdzi, że coś znalazła i będzie potrzebowała pomocy, by to wydobyć, ale nie w samym Thaurissan. Konieczna będzie za to wyprawa do Iglicy Czarnej Góry.$B$BNie znam szczegółów, ale jeśli cię to interesuje, porozmawiaj z Mayarą na Płonących Stepach.', 'Porozmawiaj z Mayarą Jasnoskrzydłą w Czuwaniu Morgana na Płonących Stepach.', '', '', '', '', '', '', 0),
(4968, 'koKR', 'Wiedza o Kuli Orahila', 'Hmm, $gzaszedłeś:zaszłaś; aż tak daleko... doprawdy zdumiewające. Można by pomyśleć, że skażenie płynące z władania mocą tajemną przesiąkło już do głębi twoją duszę i doprowadziło cię do szaleństwa. Może więc spróbujemy popchnąć cię jeszcze dalej?$B$BJeśli chcesz wystawić swoje umiejętności na próbę, odszukaj Menarę Rozdzieraczkę Pustki w wieży Strahada nad Zapadką. Ona cię poprowadzi.', 'Porozmawiaj z Menarą Rozdzieraczką Pustki na Pustkowiach.', '', '', '', '', '', '', 0),
(5022, 'koKR', 'Lepiej późno niż wcale', 'Podnosisz paczkę i ścierasz z niej cienką warstwę kurzu i brudu. Jest pośpiesznie zaadresowana do niejakiej Emmy Felstone z Wichrogrodu; termin doręczenia minął ponad cztery lata temu.$B$BNie wiadomo, czy Emma Felstone w ogóle żyje, ale powszechnie wiadomo, że Ratusz Wichrogrodu prowadzi ewidencję mieszkańców miasta. Zajmują się tym królewscy faktorzy ze spisu ludności Wichrogrodu.', 'Zasięgnij informacji u królewskich faktorów w Wichrogrodzie, by dowiedzieć się, gdzie przebywa niejaka Emma Felstone. Urzędnika spisu ludności zwykle można zastać w Ratuszu.', '', '', '', '', '', '', 0),
(5048, 'koKR', 'Poczciwa Emma', 'Jest trochę zrzędliwa i całkiem możliwe, że ma nie po kolei w głowie... ale według ewidencji Stara Emma pasuje do tego, kim mogłaby być Emma Felstone.$B$BMoże $gwidziałeś:widziałaś;, jak Stara Emma wałęsa się po mieście – mówi do siebie, najczęściej jakieś bezsensowne trele-morele. Mimo to nikomu i niczemu nie szkodzi, więc ludzie raczej dają jej spokój.$B$BBiorąc wszystko pod uwagę, powiedziałbym, że Stara Emma to w istocie Emma Felstone. Możesz spróbować ją zapytać, czy rzeczywiście nazywa się Felstone.', 'Odszukaj Starą Emmę w Wichrogrodzie i sprawdź, czy to rzeczywiście Emma Felstone. Jeśli tak, może zechce przyjąć paczkę, którą przygotowała dla niej Janice Felstone.', '', '', '', '', '', '', 0),
(5050, 'koKR', 'Amulet szczęścia', 'Najwyraźniej niesłusznie cię oceniono, $N, i za to należą ci się przeprosiny. Moja siostra przysłała mi sporo osobistych rzeczy, w tym – co dość zabawne – akt własności gospodarstwa Felstone\'ów. Chyba na razie nie będę się starać o jego odzyskanie.$B$BJeśli duch mojej siostry pozostaje przywiązany do gospodarstwa i nie może zaznać spokoju, proszę... czy możesz jej to oddać? To połówka amuletu szczęścia, który miała; drugą połówkę miał jej mąż.$B$BMoże świadomość, że te rzeczy są teraz u mnie, pozwoli jej duszy wreszcie spocząć.', 'Oddaj połówkę amuletu szczęścia Janice Felstone na Zachodnich Plagowiskach.', '', '', '', '', '', '', 0),
(5066, 'koKR', 'Do broni: Plagowiska!', 'Słuchajcie, słuchajcie! Niechaj wszyscy bohaterowie wysłuchają tych słów!$B$BKrólestwo Wichrogrodu wzywa do broni! Wszyscy zdolni do walki proszeni są o chwycenie za oręż przeciwko mrocznemu zagrożeniu ze strony Plagi w północnych krainach Wschodnich Królestw! Krążą pogłoski o nowych zagrożeniach powstających z ruin Plagowisk!$B$BBohaterowie królestwa – odszukajcie dowódcę Ashlama Mężnopięść, który założył swoją bazę w Obozie Zimnych Wichrów, na północ od Gór Alterak!', 'Odszukaj dowódcę Ashlama Mężnopięść. Jego baza mieści się w Obozie Zimnych Wichrów, na północ od Gór Alterak.', '', '', '', '', '', '', 0),
(5924, 'koKR', 'Odpowiedź na wezwanie', 'Przepraszam, $gprzyjacielu:przyjaciółko;...$B$BDoszły mnie słuchy, że Mathrengyl Niedźwiedzi Krok rozesłał wieść, iż chce z tobą porozmawiać. Wygląda na to, że twoje druidzkie szkolenie nabierze nowego życia, a on sam będzie cię szkolić. Mathrengyl jest bezpośrednim pomocnikiem samego arcydruida i jednym z najmądrzejszych i najdostojniejszych druidów, jakich spotkasz na Teldrassilu.$B$BZnajdziesz go w Enklawie Cenariona w Darnassus, na piętrze drzewa Fandrala Jeleniorogiego.', 'Porozmawiaj z Mathrengylem Niedźwiedzim Krokiem w Enklawie Cenariona w Darnassus.', '', '', '', '', '', '', 0),
(6073, 'koKR', 'Ścieżka łowcy', 'Witaj, $gmłody łowco:młoda łowczyni;. Wyglądasz mi na kogoś dość wprawnego, by poradzić sobie z bestią i wyszkolić ją na swojego towarzysza.$B$BMusisz odwiedzić Dazalara w Dolanaar. On wskaże ci ścieżkę do zdobycia własnego zwierzęcia.', 'Porozmawiaj z Dazalarem w Dolanaar na Teldrassilu.', '', '', '', '', '', '', 0),
(6076, 'koKR', 'Ścieżka łowcy', 'Witaj, $gmłody łowco:młoda łowczyni;. Wyglądasz mi na kogoś dość wprawnego, by poradzić sobie z bestią i wyszkolić ją na swojego towarzysza.$B$BMusisz odwiedzić Grifa Serce Dziczy w Kharanos. On wskaże ci ścieżkę do zdobycia własnego zwierzęcia.', 'Porozmawiaj z Grifem Serce Dziczy w Kharanos w Dun Morogh.', '', '', '', '', '', '', 0),
(6141, 'koKR', 'Brat Anton', 'Mój towarzysz broni, brat Anton, usłyszał pogłoski o inwazji nieumarłych w dalekim Kalimdorze, w krainie zwanej Mrocznym Pustkowiem. Anton natychmiast wykupił rejs w tamte strony, by odnaleźć i zniszczyć nieumarłe zagrożenie!$B$BSzuka ludzi dość odważnych i zdeterminowanych, by mu pomóc. Jeśli twoje serce jest szczere, porozmawiaj z Antonem. Przebywa w Mrocznym Pustkowiu, w osadzie Przymierza zwanej Punktem Nijela.', 'Porozmawiaj z bratem Antonem w Punkcie Nijela w Mrocznym Pustkowiu.', '', '', '', '', '', '', 0),
(6182, 'koKR', 'Pierwszy i ostatni', 'Nathanos Marris był pierwszym i ostatnim ludzkim lordem tropicieli. Uczeń Sylwany Bieżywiatr, obecnie Królowej Banshee Porzuconych.$B$BSądziliśmy, że Nathanos poległ pięć lat temu w obronie Lordaeronu. Choć jego ciała nigdy nie odnaleziono, zakładano, że nie wydostał się ze Wschodnich Plagowisk.$B$BMathias Shaw bada sprawę jego zniknięcia i może mieć nowe informacje. Natychmiast się u niego zamelduj. Przebywa na Starym Mieście, w koszarach.', 'Porozmawiaj z Mathiasem Shawem na Starym Mieście w Wichrogrodzie. Przebywa w koszarach.', '', '', '', '', '', '', 0),
(6183, 'koKR', 'Uczczenie zmarłych', 'Sprawę Marrisa przydzielono pięciu moim najlepszym agentom terenowym. Wrócił jeden, tylko po to, by trzy dni później umrzeć we śnie.$B$BTo niewiele, co zdołaliśmy z niego wyciągnąć, było bezładnym bełkotem. Rozróżniliśmy dwa słowa: „Nathanos” i „Herold Plagi”.$B$BNie mam wolnych ludzi, by kontynuować to śledztwo, a Krukowisko nam nie pomoże. Musimy dotrzeć do sedna tej sprawy – choćby po to, by rodziny zmarłych mogły zamknąć ten rozdział. Pomożesz?', 'Jeśli chcesz przyjąć jego zadanie, porozmawiaj ponownie z Mathiasem Shawem.', '', '', '', '', '', '', 0),
(6184, 'koKR', 'Flint Shadowmore', 'Jedyne, co zatem na razie wiemy, to że Nathanos Marris mógł zginąć z rąk tego Herolda Plagi. Zakładamy, że Herold Plagi to ten sam potwór, który rozprawił się z moimi agentami.$B$BFlint Shadowmore, inny agent WW:7, stacjonuje w obozie Przymierza w Punkcie Zimnych Wichrów na Zachodnich Plagowiskach. Odszukaj go; zapozna cię z obecną sytuacją na Plagowiskach i przydzieli ci zadanie.$B$BPowodzenia, $N.', 'Udaj się do Obozu Zimnych Wichrów na Zachodnich Plagowiskach i spotkaj się ze swoim łącznikiem, Flintem Shadowmore\'em.$B', '', '', '', '', '', '', 0),
(6186, 'koKR', 'Nadchodzi Herold Plagi', '<Wygląda na to, że z twarzy Flinta odpłynęła cała krew.>$B$BNa... Nathanos to zrobił? Nathanos jest Heroldem Plagi?$B$BDlaczego? On był... był taki szlachetny – lord tropicieli szanowany przez wszystkich. Jedyny człowiek, któremu kiedykolwiek pozwolono szkolić się u wysokich elfów. A teraz bezwzględny agent Porzuconych?$B$BPrzy... przykro mi, że cię o to proszę, $N, ale król Wrynn musi natychmiast dowiedzieć się o tym obrocie spraw. Proszę, wróć do Wichrogrodu i przekaż mu te wieści.', 'Wróć do Wichrogrodu i powiadom króla Variana Wrynna o losie Nathanosa Marrisa.', '', '', '', '', '', '', 0),
(6187, 'koKR', 'Trzeba przywrócić porządek', 'Wiesz, ilu lordów tropicieli jest na tym świecie? Ilu ludzkich lordów tropicieli było kiedykolwiek?$B$BDokonania Nathanosa były bezprecedensowe. Był geniuszem taktyki, któremu Przymierze zawdzięczało zwycięstwa w ciągu dekady walk.$B$BA teraz... czempion Porzuconych.$B$BNie. Tak być nie może. Trzeba przywrócić porządek.$B$BZbierz armię, $N. Wróć ze swoją armią na Plagowiska i zniszcz Herolda Plagi.$B$BŻyczę ci szczęścia, $N. Naprawdę będzie ci potrzebne w tej bitwie.', 'Zbierz armię i wyrusz na Wschodnie Plagowiska. Przypuść zmasowany atak na Nathanosa Herolda Plagi i wszelkie plugastwo Hordy, które spróbuje go chronić.$B$BZachowaj czujność, $N. Horda będzie bronić lorda tropicieli za cenę własnego życia.', '', 'Wróć do króla Variana Wrynna w Kniei Elwynn.', '', '', '', '', 0),
(6261, 'koKR', 'Dungar Długołyk', '$N, zebrałem w tej skrzyni wszystko, o co prosił Lewis. Zaniesiesz mu ją?$B$BJeśli już $grozmawiałeś:rozmawiałaś; z Thorem w Zachodnim Skraju, możesz polecieć do niego gryfem. Dungar Długołyk to nasz mistrz gryfów, tam, w Dzielnicy Handlowej.$B$BPorozmawiaj z Dungarem, a potem jak najszybciej dostarcz tę skrzynię Lewisowi. Nie chcemy, żeby nasi żołnierze i żołnierki w Zachodnim Skraju zostali bez nowego ekwipunku!', 'Zanieś skrzynię Osrica mistrzowi gryfów Dungarowi Długołykowi.', '', '', '', '', '', '', 0),
(6281, 'koKR', 'Dalej do Wichrogrodu', 'Za niewielką opłatą możesz polecieć gryfem do Wichrogrodu i dostarczyć liścik Lewisa Osricowi. Szybciej się tam nie dostaniesz.$B$BJeśli ci to odpowiada, po prostu porozmawiaj ze mną ponownie, gdy będziesz $ggotów:gotowa; do lotu. Wezmę od ciebie trochę grosza, ale uwierz mi, będzie warto!', 'Wykup lot gryfem u mistrza gryfów Thora, a następnie zanieś liścik Lewisa Osricowi Strangowi do sklepu „Ograniczona Odporność” na Starym Mieście w Wichrogrodzie.', '', '', '', '', '', '', 0),
(6285, 'koKR', 'Powrót do Lewisa', 'Mistrzem gryfów w Zachodnim Skraju jest Thor. Jeśli już z nim $grozmawiałeś:rozmawiałaś;, możesz polecieć do niego jednym z moich gryfów.$B$BTo dobra lekcja: gryfy zawsze są wyszkolone, by latać do swojej stolicy, ale do odległego mistrza gryfów zabiorą cię dopiero wtedy, gdy już tam $gbyłeś:byłaś;.$B$BU Thora już $gbyłeś:byłaś;, więc po prostu porozmawiaj ze mną ponownie, gdy będziesz $ggotów:gotowa; polecieć gryfem do Zachodniego Skraju. Na miejscu możesz oddać skrzynię Osrica kwatermistrzowi Lewisowi.', 'Wykup u mistrza gryfów Dungara Długołyka lot gryfem na Wzgórze Strażnicze, a następnie zanieś skrzynię Osrica Lewisowi na Wzgórzu Strażniczym.', '', '', '', '', '', '', 0),
(6402, 'koKR', 'Spotkanie w Wichrogrodzie', 'Masz spotkać się z Windsorem u bram Wichrogrodu.$B$BTo, co Windsor zamierza ujawnić, wstrząśnie samymi fundamentami królestwa!$B$BNie próbuj wyruszać tam w pojedynkę, $N. Musisz zebrać armię! Zgromadź swoich towarzyszy. Do broni!$B$B', 'Udaj się do Wichrogrodu i idź do bram miasta. Porozmawiaj z giermkiem Rowe\'em, by mógł powiadomić marszałka Windsora o twoim przybyciu.', '', '', '', '', '', '', 0),
(6403, 'koKR', 'Wielka maskarada', 'To była nie lada przygoda, $gprzyjacielu:przyjaciółko;. Mam wobec ciebie ogromny dług wdzięczności. Może, kiedy już będzie po wszystkim...$B$BJak zapewne już się $gzorientowałeś:zorientowałaś;, lady Prestor to Onyxia, pomiot Śmiercioskrzydłego, siostra bliźniaczka Nefariana, tyrana Iglicy.$B$BZbyt długo więziła nasze królestwo swoim urzekającym spojrzeniem. Nawet najwyższym lordem steruje za pomocą swoich podstępów – jest jej marionetką. Dziś to wszystko się skończy... Czar zostanie złamany.$B$BNie martw się, bo razem zwyciężymy!$B$BCzy jesteś $ggotów:gotowa;?', 'Podążaj za Reginaldem Windsorem przez Wichrogród. Chroń go przed niebezpieczeństwem!', 'Marsz Reginalda', '', '', '', '', '', 0),
(6501, 'koKR', 'Smocze oko', 'Mogę ci dać jedynie odłamek strzaskanego medalionu.$B$BMusisz odnaleźć kogoś innego ze smoczej krwi, kto zechce pomóc ci wykuć nowy klucz. Gdy zdobędziesz ten klucz, musisz udać się na Żmijowe Trzęsawisko na Pyłowym Bagnisku. To tam znajdziesz jej leże, $N.$B$BGdzie szukać innych stad skłonnych do pomocy? Niestety, nie wiem... Mówi się, że istnieją. Niektórzy mogą nawet pracować i żyć wśród nas, przebrani za przedstawicieli ras humanoidalnych. Życzę ci szczęścia.$B', 'Musisz przemierzyć świat w poszukiwaniu istoty zdolnej przywrócić moc odłamkowi smoczego oka. Jedyne, co wiesz o takiej istocie, to że istnieje.', '', '', '', '', '', '', 0),
(6722, 'koKR', 'Ścieżka łowcy', 'Witaj, $gmłody łowco:młoda łowczyni;. Wyglądasz mi na kogoś dość wprawnego, by poradzić sobie z bestią i wyszkolić ją na swojego towarzysza.$B$BMusisz odwiedzić Dazalara w Dolanaar. On wskaże ci ścieżkę do zdobycia własnego zwierzęcia.', 'Porozmawiaj z Dazalarem w Dolanaar na Teldrassilu.', '', '', '', '', '', '', 0),
(7494, 'koKR', 'Warownia Lunopiórej', '$N! Twoja pomoc jest potrzebna w Feralas!$B$BWyjęta spod prawa magini, Lethtendris, uciekła do starożytnych elfich ruin Eldre\'thalas, zwanych dziś Srogomłotami. Podobno ma przy sobie przedmiot o niebezpiecznej energii magicznej, który trzeba odzyskać.$B$BLatronicus Księżycowa Włócznia szuka śmiałków, którzy wejdą do Srogomłotów i odbiorą ten przedmiot Lethtendris.$B$BSłuż Przymierzu! Odszukaj Latronicusa w Warowni Lunopiórej w Feralas.', 'Porozmawiaj z Latronicusem Księżycową Włócznią w Warowni Lunopiórej w Feralas.', '', '', '', '', '', '', 0),
(7495, 'koKR', 'Zwycięstwo Przymierza', '$GDokonałeś:Dokonałaś; niemożliwego. Matka Czarnego Stada smoków leży martwa u twoich stóp. Weź jej głowę i zanieś ją królowi Varianowi Wrynnowi.', 'Zanieś głowę Onyxii królowi Varianowi Wrynnowi w Wichrogrodzie.', '', '', '', '', '', '', 0),
(7496, 'koKR', 'Czas świętowania', 'Odszukaj majora Mattingly\'ego w Dolinie Bohaterów, $N. Będzie na ciebie czekał...', 'Odszukaj majora Mattingly\'ego w Dolinie Bohaterów.', '', '', '', '', '', '', 0),
(7497, 'koKR', 'Podróż dopiero się zaczęła', '', '', '', '', '', '', '', '', 0),
(7562, 'koKR', 'Mor\'zul Zwiastun Krwi', '$N, głęboko $gzgłębiłeś:zgłębiłaś; mroczne sztuki. Twoja władza nad istotami z innych światów jest już tak silna... że może jesteś $ggotów:gotowa;, by związać ze sobą jednego z osławionych upiornych rumaków.$B$BRytuał przyzwania bestii z jej rodzimego świata wymaga wielkiej mocy i zasobów, ale jeśli pragniesz zapanować nad tym epickim wierzchowcem, porozmawiaj z Mor\'zulem Zwiastunem Krwi. Obozuje w pobliżu Ołtarza Burz na Płonących Stepach.$B$BIdź, $N. To zadanie będzie niebezpieczne, ale $gczarnoksiężnik twojej rangi nie ucieka:czarnoksiężniczka twojej rangi nie ucieka; przed niebezpieczeństwem!', 'Porozmawiaj z Mor\'zulem Zwiastunem Krwi przy Ołtarzu Burz na Płonących Stepach.', '', '', '', '', '', '', 0),
(7637, 'koKR', 'Przede wszystkim poświęcenie', 'Aby przygotować się do tego zadania, musisz najpierw wykazać się należytym poświęceniem i osądem... przede wszystkim poświęceniem.$B$BDo tego zadania musisz zdobyć kadzielnicę egzorcyzmu wielkiego kapłana Rohana. Choć zostanie użyta w dobrej i słusznej sprawie, należy się za nią odpowiednia rekompensata.$B$BUdaj się do Żelaznej Kuźni i porozmawiaj z wielkim kapłanem. Jeśli przyniesiesz dość monet, by wynagrodzić mu utratę kadzielnicy, wykażesz się należytym poświęceniem.$B$BIdź już, $N, czas nagli.', 'Udaj się do Żelaznej Kuźni i zdobądź kadzielnicę egzorcyzmu wielkiego kapłana Rohana. Aby ją otrzymać, musisz przekazać datek w wysokości 150 sztuk złota.', '', '', '', '', '', '', 0),
(7638, 'koKR', 'Lord Grayson Cieniołamacz', 'Nadszedł czas, $N, byś $gdowiedział:dowiedziała; się, czego wymaga zdobycie czegoś, na co bez wątpienia długo $gczekałeś:czekałaś;... twojego szarżownika.$B$BPorozmawiaj z lordem Graysonem Cieniołamaczem tutaj, w Dzielnicy Katedralnej Wichrogrodu. To on wprowadzi cię nie tylko w tajniki najwierniejszego wierzchowca paladyna, ale i w zadania, które czekają cię na drodze do zdobycia własnego.$B$BŻyczę ci powodzenia w tej próbie. Za Światłość, $gszlachetny bracie:szlachetna siostro;!', 'Porozmawiaj z lordem Graysonem Cieniołamaczem w Dzielnicy Katedralnej Wichrogrodu.', '', '', '', '', '', '', 0),
(7639, 'koKR', 'Należyty osąd', 'Weź kadzielnicę z moim błogosławieństwem. Sam używałem jej podczas kilku egzorcyzmów i powinna ci dobrze służyć w trudnych zadaniach, które cię czekają.$B$BWróć teraz do lorda Graysona Cieniołamacza w Wichrogrodzie, $N. To u niego będziesz kontynuować swoją misję.', 'Zanieś kadzielnicę egzorcyzmu lordowi Graysonowi Cieniołamaczowi w Dzielnicy Katedralnej Wichrogrodu.', '', '', '', '', '', '', 0),
(7640, 'koKR', 'Egzorcyzmy w Dolinie Grozy', 'Dodałem do kadzielnicy szczyptę ziemi ze skażonego gruntu Doliny Grozy we Wschodnich Plagowiskach. Użyjesz jej teraz, by odnaleźć tam miejsca, w których widać oznaki duchowego wzburzenia i niepokoju. Szukaj zielonych aur przenikających ziemię tam, gdzie świat materialny ugina się pod udręką królestwa duchów, i użyj kadzielnicy, by wypędzić złe duchy.$B$BGdy wydasz dostateczny osąd na tamtejsze duchy, będziesz $ggotów:gotowa; do dalszej drogi.', 'Użyj kadzielnicy egzorcyzmu, by wypędzić duchy dręczące Dolinę Grozy. Gdy zabijesz 25 duchów z Doliny Grozy, wróć do lorda Graysona Cieniołamacza w Dzielnicy Katedralnej Wichrogrodu.', '', 'Wróć do lorda Graysona Cieniołamacza w Wichrogrodzie.', '', '', '', '', 0),
(7641, 'koKR', 'Dzieło Grimanda Elmore\'a', 'Szarżownik paladyna bez odpowiedniej zbroi końskiej jest niczym więcej niż zwierzęciem jucznym. Zbroja twojego szarżownika musi być nie tylko wykonana z najlepszych możliwych materiałów, ale ze względu na okoliczności musi też być dostatecznie dostrojona do królestwa duchów.$B$BPo kolei, $N – najpierw trzeba wykonać twoją zbroję. W Dzielnicy Krasnoludów w Wichrogrodzie mieszka jeden z najlepszych żyjących rzemieślników, Grimand Elmore. Jego praca nie będzie tania, ale szukamy właśnie takiej jakości. Porozmawiaj z nim.', 'Porozmawiaj z Grimandem Elmore\'em w Dzielnicy Krasnoludów w Wichrogrodzie.', '', '', '', '', '', '', 0),
(7642, 'koKR', 'Zbiórka materiałów', 'Do zbroi potrzebujesz czterech rzeczy – runicznej tkaniny na podszycie, sztabek arkanitu na płyty, Łez Arthasa do dostrojenia duchowego i wody święconej ze Stratholmu do duchowego nasycenia. Właściwie potrzebujesz pięciu rzeczy... złota na moją zapłatę. Obejmuje ona całą robociznę, a także ręcznie robione siodło i strzemiona.$B$BGdy wszystko zdobędziesz, będę w stanie dokończyć twoją zbroję. Do tego czasu, kiedy ty będziesz zbierać materiały, mogę już zacząć nad niektórymi rzeczami pracować.', 'Przynieś 40 sztuk runicznej tkaniny, 6 sztabek arkanitu, 10 Łez Arthasa, 5 fiolek wody święconej ze Stratholmu i 150 sztuk złota Grimandowi Elmore\'owi w Dzielnicy Krasnoludów w Wichrogrodzie.', '', 'Wróć do Grimanda Elmore\'a w Kniei Elwynn.', '', '', '', '', 0),
(7643, 'koKR', 'Pradawny duch konia', 'Twoja zbroja potrzebuje szczególnego błogosławieństwa, udzielonego przez odpowiedniego ducha. W Srogomłotach przebywa taki duch – Pradawny duch konia. Obecnie więzi go zepsuty drzewiec, Tendris Spaczodrzew. Wydaj osąd na tę plugawą bestię, $N.$B$BWiedz jedno: samo uwolnienie nie wystarczy. Zanim otrzymasz błogosławieństwo, musisz ukoić ducha. Do tego potrzebna jest specjalna pasza dla koni. Najpierw udaj się do Południowego Brzegu i porozmawiaj o tym z Merideth Carlson... i przygotuj się na kolejne poświęcenie.', 'Zdobądź specjalną paszę, którą karmi się duchy koni. Podobno można ją dostać u Merideth Carlson w Południowym Brzegu.$B$BUdaj się do lochów Srogomłotów w Feralas i zabij Tendrisa Spaczodrzewa. W ten sposób uwolnisz Pradawnego ducha konia. Nakarm go specjalną paszą, by go ukoić. Na koniec daj mu arkanitową zbroję końską, by ją pobłogosławił.', '', '', '', '', '', '', 0),
(7644, 'koKR', 'Błogosławiona arkanitowa zbroja końska', 'Gdy zbroja spoczywa na grzbiecie Pradawnego ducha konia, zaczyna lekko jaśnieć. Przez krótką chwilę powietrze gęstnieje od mocy, a potem zbroja znika z grzbietu konia i leży już bezpiecznie w twoim plecaku.$B$BWygląda na to, że zbroja została pobłogosławiona. Zgodnie z poleceniem lorda Cieniołamacza $gpowinieneś:powinnaś; teraz wrócić z nią do niego do Wichrogrodu.', 'Zanieś błogosławioną arkanitową zbroję końską lordowi Graysonowi Cieniołamaczowi w Dzielnicy Katedralnej Wichrogrodu.', '', '', '', '', '', '', 0),
(7646, 'koKR', 'Wróżbiarska kula', 'Teraz musimy złożyć wróżbiarską kulę – to od niej rozpocznie się próba, dzięki której odkupisz poległego szarżownika. Właściwie twoja kula jest prawie gotowa. Jej katalizatorem jest kadzielnica egzorcyzmu, której $gużywałeś:używałaś; w Dolinie Grozy, a ja wykonam dla niej odpowiednią oprawę.$B$BOstatnimi potrzebnymi składnikami są jednak dwa diamenty. Muszą być tak przeciwstawne w blasku, jak i w przeznaczeniu – azerothiański i nieskazitelny czarny. Te dwa kamienie będą latarnią, dzięki której kula przebije cienie!', 'Przynieś azerothiański diament i nieskazitelny czarny diament lordowi Graysonowi Cieniołamaczowi w Dzielnicy Katedralnej Wichrogrodu.', '', 'Wróć do lorda Graysona Cieniołamacza w Wichrogrodzie.', '', '', '', '', 0),
(7647, 'koKR', 'Osąd i odkupienie', 'Weź tę sakwę – są w niej przedmioty, których będziesz potrzebować.$B$BUżyj wróżbiarskiej kuli w samym sercu podziemi Wielkiego Ossuarium, by przywołać przeklęte duchy, które trzeba osądzić. Rozważnie korzystaj z osądów podczas tej próby – okażą się potężniejsze, niż myślisz. Po duchach pojawi się rycerz śmierci; pokonaj go i odzyskaj utraconą duszę szarżownika. Dopiero wtedy, $N, będziesz $gmógł:mogła; go odkupić i założyć zbroję na swojego nowego wierzchowca!$B$BPowodzenia!', 'Użyj wróżbiarskiej kuli w samym sercu podziemi Wielkiego Ossuarium w Scholomancjum. Przywoła ona duchy, które musisz osądzić. Pokonanie tych duchów przyzwie rycerza śmierci Mrocznego Łupieżcę. Pokonaj go i odzyskaj utraconą duszę poległego szarżownika.$B$BOddaj odkupioną duszę szarżownika i błogosławioną arkanitową zbroję końską poległemu szarżownikowi Mrocznego Łupieżcy.', '', 'Wróć do poległego szarżownika Mrocznego Łupieżcy.', '', '', '', '', 0),
(7648, 'koKR', 'Najlepsze dzieło Grimanda', '<Grimand ociera pot z czoła, promieniejąc z dumy.>$B$BProszę bardzo, $gprzyjacielu:przyjaciółko;. To jedno z moich najlepszych dzieł – równie dobre jak zbroja, którą osobiście wykonałem dla lorda Cieniołamacza, gdy zdobywał własnego szarżownika. Dziękuję, że $gzaufałeś:zaufałaś; mi, że zapewnię ci to, co najlepsze.$B$BGrayson na pewno też zechce obejrzeć tę robotę. Zanieś mu zbroję i przekaż podziękowania za uczciwe interesy.', 'Zanieś arkanitową zbroję końską do obejrzenia lordowi Graysonowi Cieniołamaczowi w Dzielnicy Katedralnej Wichrogrodu.', '', '', '', '', '', '', 0),
(7666, 'koKR', 'Znów do Wielkiego Ossuarium', '', '', '', '', '', '', '', '', 0),
(7669, 'koKR', 'Znów do Wielkiego Ossuarium', '', '', '', '', '', '', '', '', 0),
(7670, 'koKR', 'Lord Grayson Cieniołamacz', 'Nadszedł czas, $N, byś $gdowiedział:dowiedziała; się, czego wymaga zdobycie czegoś, na co bez wątpienia długo $gczekałeś:czekałaś;... twojego szarżownika.$B$BPorozmawiaj z lordem Graysonem Cieniołamaczem w Dzielnicy Katedralnej Wichrogrodu. To on wprowadzi cię nie tylko w tajniki najwierniejszego wierzchowca paladyna, ale i w zadania, które czekają cię na drodze do zdobycia własnego.$B$BŻyczę ci powodzenia w tej próbie. Za Światłość, $gszlachetny bracie:szlachetna siostro;!', 'Porozmawiaj z lordem Graysonem Cieniołamaczem w Dzielnicy Katedralnej Wichrogrodu.', '', '', '', '', '', '', 0),
(7781, 'koKR', 'Władca Czarnej Góry', 'Powraca dawne uczucie. Rozkoszne ukłucie zwycięstwa rozbrzmiewa w całym twoim jestestwie. Przed tobą leży monumentalna, poznaczona bliznami bitew głowa Nefariana. Zanieś ją królowi Varianowi Wrynnowi, $gczempionie:czempionko;.', 'Zanieś głowę Nefariana królowi Varianowi Wrynnowi w Wichrogrodzie.', '', '', '', '', '', '', 0),
(7782, 'koKR', 'Władca Czarnej Góry', 'Udaj się do Doliny Bohaterów i porozmawiaj z feldmarszałkiem Afrasiabim.', 'Udaj się do Doliny Bohaterów w Wichrogrodzie i porozmawiaj z feldmarszałkiem Afrasiabim.', '', '', '', '', '', '', 0),
(7791, 'koKR', 'Dar wełnianego płótna', '', '', '', 'Wróć do Clavicusa Knavinghama w Kniei Elwynn.', '', '', '', '', 0),
(7793, 'koKR', 'Dar jedwabnego płótna', '', '', '', 'Wróć do Clavicusa Knavinghama w Kniei Elwynn.', '', '', '', '', 0),
(7794, 'koKR', 'Dar tkaniny magów', '', '', '', 'Wróć do Clavicusa Knavinghama w Kniei Elwynn.', '', '', '', '', 0),
(7795, 'koKR', 'Dar runicznej tkaniny', '', '', '', 'Wróć do Clavicusa Knavinghama w Kniei Elwynn.', '', '', '', '', 0),
(7796, 'koKR', 'Więcej runicznej tkaniny', '', '', '', 'Wróć do Clavicusa Knavinghama w Kniei Elwynn.', '', '', '', '', 0),
(8151, 'koKR', 'Urok łowcy', 'Ogtinc z Aszary wzywa doświadczonych łowców takich jak ty. To łowca z rasy furbolgów, który opuścił swoje plemię, by pomagać Kręgowi Cenariona. Jego nauki mają wzbogacić mądrość innych, którzy parają się tym samym fachem, i prowadzić ich ku zachowaniu równowagi. Dobrze zrobisz, jeśli z nim porozmawiasz.$b$bOgtinc mieszka na szczycie klifów Aszary, na północny wschód od Ruin Eldarath.', 'Porozmawiaj z Ogtinkiem w Aszarze.', '', '', '', '', '', '', 0),
(8233, 'koKR', 'Prosta prośba', 'Lord Jorach Ravenholdt prosi cię o przybycie. Sprawa jest tajna i nic więcej nie mogę powiedzieć.$b$bDwór Krukowiska leży w Międzygórzu – szukaj ścieżki w górach na północny zachód od Twierdzy Durnhold.', 'Porozmawiaj z lordem Jorachem Ravenholdtem we Dworze Krukowiska.', '', '', '', '', '', '', 0),
(8250, 'koKR', 'Kunszt maga', 'Arcymag Xylem rozpytywał ostatnio... o kogoś z twoim doświadczeniem.$b$bJeśli chcesz go odszukać, znajdziesz go w Aszarze. Jego wieża stoi wysoko na szczycie klifów, a jedyną drogą na górę jest zaklęcie teleportacji rzucane przez jego aroganckiego sługę, Sanatha Lim-yo.$b$bSanath obozuje u stóp wieży swojego pana. Aby go znaleźć, udaj się tam, gdzie główna droga Aszary rozwidla się u wejścia do Ruin Eldarath. Stamtąd idź prosto na północ, aż dotrzesz do klifów.', 'Odszukaj Sanatha Lim-yo i zdobądź przejście do arcymaga Xylema.', '', '', '', '', '', '', 0),
(8254, 'koKR', 'Pomoc dla Kręgu Cenariona', 'Pomaganie potrzebującym to droga boskości. Sposób nie ma znaczenia – liczy się tylko cel.$b$bKrąg Cenariona jest w potrzebie. Porozmawiaj z Ogtinkiem, by wesprzeć ich w niedoli. Mieszka na szczycie klifów na północny wschód od Ruin Eldarath w Aszarze.', 'Odszukaj Ogtinca w Aszarze.', '', '', '', '', '', '', 0),
(8356, 'koKR', 'Mięśnie za nugat', 'To... ciekawe przebranie. Choć w tym roku jesteś tak $gmiły:miła;, że pomagasz choremu dziecku zbierać słodycze, obawiam się, że muszę cię poprosić o jakąś sztuczkę!$B$BNiech pomyślę... wyglądasz tak silnie i muskularnie w tym... przebraniu... pokaż no mięśnie! Tak, śmiało, napręż się dla mnie, $gsiłaczu:siłaczko;!$B$BDopiero gdy pokażesz mięśnie, dam ci trochę pysznego nugatu z Wichrogrodu. To wspaniały przysmak na Zaduszniki.', 'Użyj emotki /flex przed karczmarką Allison, a w zamian dostaniesz nugat z Wichrogrodu!$B', '', 'Wróć do karczmarki Allison w Wichrogrodzie.', 'Pokaż mięśnie karczmarce Allison', '', '', '', 0),
(8410, 'koKR', 'Mistrzostwo żywiołów', 'Bath\'rah Wiatrowidz wzywa szamana o twojej mądrości. Prosi, byś $gprzyniósł:przyniosła; próbkę każdego z żywiołów na dowód, że jesteś $ggotów:gotowa;.$b$bAby znaleźć Bath\'raha, udaj się nad rzekę na wschód od Smolnego Młyna. Idź w górę rzeki na północ, aż natrafisz na ruiny, w których przebywa Bath\'rah.', 'Zbierz próbkę powietrza, ognia, ziemi i wody dla Bath\'raha Wiatrowidza.', '', 'Wróć do Bath\'raha Wiatrowidza w Punkcie Zimnych Wichrów w Górach Alterak.', '', '', '', '', 0),
(8415, 'koKR', 'Obóz Zimnych Wichrów', 'Dowódca Ashlam Mężnopięść wzywa paladyna o twojej czystości i męstwie, $n. Znajdziesz go w Obozie Zimnych Wichrów w południowej części Zachodnich Plagowisk. Odszukaj go i wesprzyj jego sprawę w imię Światłości!', 'Porozmawiaj z dowódcą Ashlamem Mężnopięścią w Obozie Zimnych Wichrów.', '', '', '', '', '', '', 0),
(8417, 'koKR', 'Niespokojny duch', 'Na Jałowych Ziemiach błąka się niespokojny duch, który niegdyś był wielkim bohaterem Hordy. Honor wojownika nie umiera wraz z ciałem, a rozmowa z nim dobrze ci się przysłuży.', 'Porozmawiaj z Poległym bohaterem Hordy u wejścia na Jałowe Ziemie.', '', '', '', '', '', '', 0),
(8419, 'koKR', 'Prośba chochlika', '$n, chochlik ze Spaczonej Kniei imieniem Chochliś prosi cię o przybycie. To dość dziwne, bo zażyczył sobie, byś na znak dobrej woli $gprzyniósł:przyniosła; kawałek spaczonej tkaniny. Zważywszy na moc, którą już władasz jako czarnoksiężnik, zakładam, że wiesz, iż spaczoną tkaninę noszą przy sobie satyry ze Spaczonej Kniei.$b$bChochlisia znajdziesz tuż na północ od Wodospadów Krwawego Jadu, które podobno o tej porze roku są przeurocze.', 'Przynieś kawałek spaczonej tkaniny Chochlisiowi w Spaczonej Kniei.', '', 'Wróć do Chochlisia w Dolinie Strzaskanej Blizny w Spaczonej Kniei.', '', '', '', '', 0),
(8860, 'koKR', 'Obchody Nowego Roku!', 'Wichrogród świętuje Nowy Rok! Przez cały dzień można tam dostać darmową gorzałę, a w nocy będzie pokaz fajerwerków! Powinno być całkiem fajnie... ale w Łupieżczej Zatoce też jest dziś impreza; założę się, że będzie jeszcze lepsza!$B$BW każdym razie karczmarka Allison z Wichrogrodu potrzebuje zapasów jadła od Wędzonych Pastwisk, żeby wykarmić wszystkich gości. Zrobisz mi przysługę i je dostarczysz?$B$BDzięki, $N! Karczmarka Allison jest w „Złoconej Róży” w Dzielnicy Handlowej Wichrogrodu.', 'Zanieś zapasy od Wędzonych Pastwisk karczmarce Allison w Wichrogrodzie.', '', '', '', '', '', '', 0),
(9026, 'koKR', 'Śladem źródła', 'Musimy znaleźć źródło. Widzę znacznie więcej ludzi niż zwykle – w tym strażników – którzy wchodzą do „Złoconej Róży” i z niej wychodzą. Porozmawiaj z Allison. Jeśli to ona je sprzedaje, powie ci, skąd pochodzą.', 'Porozmawiaj z karczmarką Allison w „Złoconej Róży” w Dzielnicy Handlowej Wichrogrodu.', '', '', '', '', '', '', 0),
(9063, 'koKR', 'Torwa Tropiciel', 'Łowca imieniem Torwa Tropiciel prosi o pomoc druida. Powiedział, że tylko my mamy odpowiednie umiejętności i szacunek dla natury, by mu pomóc.$b$bKrater Un\'Goro i pustynię Tanaris łączy droga. Tam, gdzie wchodzi ona do krateru, znajdziesz w pobliżu Torwę.', 'Porozmawiaj z Torwą Tropicielem w Kraterze Un\'Goro.', '', '', '', '', '', '', 0),
(9429, 'koKR', 'Podróż do Mrocznych Włości', 'Powiedziano mi, że królestwu Wichrogrodu coś uwiera jak cierń w boku. Nazywa się to Knieja Zmierzchu i jest to miejsce pełne zła i plugawego smrodu nieumarłych.$B$BPonieważ staramy się pomagać, jak tylko możemy, chciałbym, żebyś $gudał:udała; się na południowy wschód, do głównej ludzkiej osady w tamtej okolicy, zwanej Mrocznymi Włościami. Anachoreta Delan będzie oczekiwał twojego przybycia.', 'Udaj się do Mrocznych Włości w Kniei Zmierzchu i porozmawiaj z anachoretą Delanem.', '', '', '', '', '', '', 0),
(9757, 'koKR', 'Odszukaj łowczynię Kellę Nocny Łuk', 'Łowczyni Kella Nocny Łuk prosi o przybycie wszystkich łowców, którzy są już na to gotowi. To ona nauczy cię oswajania dzikich zwierząt – a na tym etapie szkolenia to lekcja najważniejsza ze wszystkich.$b$bKellę znajdziesz w pobliżu Nabrzeża Valaara, przystani na zachód od Exodaru.', 'Porozmawiaj z łowczynią Kellą Nocny Łuk w pobliżu Nabrzeża Valaara.', '', '', '', '', '', '', 0),
(10490, 'koKR', 'Zew wody', 'Czuję, że dawno już nie $gprzechodziłeś:przechodziłaś; próby. To dlatego, że wieszcz Nobundo o ciebie pytał.$B$B$GMusiałeś:Musiałaś; bardzo zmądrzeć, skoro zostajesz $gwezwany:wezwana;, by poznać tajemnice żywiołu wody.$B$BUfam, że pamiętasz, jak wrócić statkiem z Auberdine na Mrocznym Wybrzeżu w Kalimdorze do Exodaru? I że pamiętasz, gdzie szukać wieszcza – w Kryształowej Sali w Exodarze, tak?', 'Porozmawiaj z wieszczem Nobundo w Kryształowej Sali w Exodarze na Wyspie Lazurowej Mgły.', '', '', '', '', '', '', 0),
(10491, 'koKR', 'Zew powietrza', '$N, wieszcz Nobundo znów o ciebie pytał. To pewnie czas, byś $gpoznał:poznała; sekrety powietrza, ostatniego z żywiołów!$B$BChcę, żebyś $gwiedział:wiedziała;, że jestem bardzo dumna ze wszystkiego, co do tej pory $gosiągnąłeś:osiągnęłaś;. Wiem, że czekają cię wielkie rzeczy.$B$BWsiądź na statek w Auberdine na Mrocznym Wybrzeżu w Kalimdorze. Przepłyń Spowite Morze i odszukaj wieszcza w Kryształowej Sali Exodaru na Wyspie Lazurowej Mgły.', 'Porozmawiaj z wieszczem Nobundo w Kryształowej Sali w Exodarze na Wyspie Lazurowej Mgły.', '', '', '', '', '', '', 0),
(11451, 'koKR', 'Wiersz Alicii', 'Cześć, napisałam wiersz dla mojej przyjaciółki Caylee. Ona lubi przesiadywać z Aldorami w Shattrath. Wiesz, w Rubieży?$b$bMożesz zanieść jej mój wiersz? Mama mówi, że jestem za mała, żeby jechać do Shattrath!', 'Poproszono cię o dostarczenie wiersza Alicii Caylee Dak w Shattrath w Rubieży.', '', 'Wróć do Caylee Dak w Shattrath.', '', '', '', '', 0),
(12774, 'koKR', 'Wichrogród', 'Nasze modlitwy zostały wysłuchane! Dzięki skupieniu Światłości od naaru z Shattrath i wspólnym błogosławieństwom wiernych stworzyliśmy święte artefakty o niezwykłej mocy. Te artefakty będą naszą bronią przeciw knowaniom Króla Lisza.$B$BWeź to, $n. Strzeż tego pilnie i bezpiecznie dostarcz do Wichrogrodu. Król Wichrogrodu niedawno powrócił; z pewnością przyjmie to narzędzie z radością.', 'Biskup Lazaril chce, żebyś $gzaniósł:zaniosła; artefakt nasycony Światłością królowi Varianowi Wrynnowi w Wichrogrodzie.', '', 'Wróć do króla Variana Wrynna w Kniei Elwynn.', '', '', '', '', 0),
(13188, 'koKR', 'Tam, gdzie kroczą królowie', 'Jesteś teraz i na zawsze $grycerzem:rycerką; Hebanowego Miecza, $N, ale wiedz jedno: niegdyś $gbyłeś bohaterem:byłaś bohaterką; Przymierza.$B$B<Darion wpatruje się w ciebie.>$B$BTen zakon musi zdobyć sojuszników, jeśli ma przetrwać. Musisz reprezentować Rycerzy Hebanowego Miecza przed Przymierzem.$B$BNa platformie na południowy wschód ode mnie znajduje się portal do Wichrogrodu. Weź ten list, który lord Fordring przekazał mi w twoim imieniu, i dostarcz go królowi Varianowi Wrynnowi. Skorzystaj z portalu.', 'Dostarcz list królowi Przymierza Varianowi Wrynnowi w Twierdzy Wichrogród w Wichrogrodzie.', '', 'Wróć do króla Variana Wrynna w Kniei Elwynn.', '', '', '', '', 0),
(13347, 'koKR', 'Odrodzeni z popiołów', 'Nasz los wypisany jest na naszych duszach od narodzin. Upadek Bolvara, choć tragiczny, był nieunikniony.$B$BTeraz możesz jedynie oddać cześć swojemu bohaterowi, $N. Zabierz tarczę Bolvara z pola bitwy i zanieś ją swojemu królowi. Gdy wręczysz ją Varianowi, powiedz mu: „Nie wszystko stracone. Z popiołów poległych powstanie siła, która zjednoczy narody i oczyści ten świat ze zła”.$B$BNie wolno mu tracić wiary. Idź już, $N. Twój lud potrzebuje bohatera. Potrzebuje ciebie.', 'Zabierz tarczę Fordragona z pola bitwy przy Angratharze, Bramie Gniewu, i zanieś ją królowi Varianowi Wrynnowi w Twierdzy Wichrogród w Wichrogrodzie.', '', 'Wróć do króla Variana Wrynna w Twierdzy Wichrogród w Wichrogrodzie.', '', '', '', '', 0),
(13369, 'koKR', 'Los wbrew twej woli', 'Na prośbę lady Proudmoore zgodzę się na misję dyplomatyczną do Orgrimmaru, by przepytać wodza Hordy, Thralla. Będziesz jej towarzyszyć w tej podróży i chronić ją przed niebezpieczeństwem. Wróć do mnie z wieściami z Orgrimmaru.$B$BGdy będziesz $ggotów:gotowa; do drogi, porozmawiaj z Jainą.', 'Wesprzyj lady Jainę Proudmoore w Orgrimmarze. Porozmawiaj z wodzem Hordy, Thrallem, w Orgrimmarze na kontynencie Kalimdor.', '', '', '', '', '', '', 0),
(13370, 'koKR', 'Królewski przewrót', 'Wasz czempion, Bolvar, zginął w obronie naszego świata. Horda opłakuje stratę tak wielkiego bohatera, ale to nie Horda odpowiada za tchórzliwy atak Putressa u Bramy Gniewu. Przez tę zdradę my także straciliśmy potężnych bohaterów.$B$BPowiedz swojemu królowi, że zrobimy wszystko, co w naszej mocy, by postawić sprawców tego tchórzliwego czynu przed sądem. Uczynimy wszystko, by uniknąć konfliktu z Przymierzem, ale sprowokowani nie zawahamy się bronić.', 'Użyj portalu w Fortecy Grommasza, by wrócić do Twierdzy Wichrogród, i przekaż wiadomość Thralla królowi Varianowi Wrynnowi.', '', '', '', '', '', '', 0),
(13371, 'koKR', 'Czas zabijania', 'Zanim $gwyruszyłeś:wyruszyłaś; do Orgrimmaru, wysłałem Brolla i Valeerę pod Podmiasto. Stacjonują teraz przed wejściem do kanałów pod ruinami i czekają na rozkazy.$B$BLady Proudmoore otworzy portal do naszych sił pod Podmiastem. Udaj się tam i zamelduj się u Brolla. Jaina i ja podążymy tuż za tobą.', 'Użyj portalu do Podmiasta w Twierdzy Wichrogród, by teleportować się do Podmiasta. Po dotarciu na miejsce zamelduj się u Brolla Niedźwiedziogrzywego.', '', '', '', '', '', '', 0),
(13377, 'koKR', 'Bitwa o Podmiasto', 'Głęboko w trzewiach Podmiasta ukrywa się zabójca odpowiedzialny za śmierć Bolvara i naszych dzielnych żołnierzy u Bramy Gniewu.$B$BVarian przyprowadził ze sobą całą potęgę Przymierza, by pomogła go pojmać. Dołącz do niego i lady Proudmoore w tej obławie i zasłuż na miejsce wśród największych czempionów Przymierza!$B$BGdy będziesz $ggotów:gotowa;, porozmawiaj z królem Varianem Wrynnem.', 'Pomóż królowi Varianowi Wrynnowi i lady Jainie Proudmoore postawić wielkiego aptekarza Putressa przed sądem! Jeśli ci się uda, zamelduj się u króla Variana Wrynna.', 'Pomóż królowi Varianowi Wrynnowi', 'Wróć do króla Variana Wrynna w Twierdzy Wichrogród w Wichrogrodzie.', '', '', '', '', 0),
(14111, 'koKR', 'Relikwia Kręgu Ziemi', '$GPoczyniłeś:Poczyniłaś; wielkie postępy w szkoleniu, $N. Teraz, gdy $gopanowałeś:opanowałaś; cztery podstawowe żywioły, musisz dbać o równowagę między nimi. Ta dyscyplina ma też praktyczną zaletę – z czasem wystarczy ci jedna relikwia zamiast wszystkich czterech totemów.$B$BPorozmawiaj z wieszczem Eannu przy Wielkiej Kuźni w Żelaznej Kuźni. Pomoże ci doskonalić władzę nad żywiołami.', 'Zanieś swoje cztery totemy wieszczowi Eannu w Żelaznej Kuźni.', '', 'Wróć do wieszcza Eannu w Dun Morogh.', '', '', '', '', 0),
(24427, 'koKR', 'Wezwanie do boju: Dolina Alterak', 'Walka na wielu frontach, $gchłopcze:dziewczyno;, oznacza, że nie możemy zbytnio rozpraszać sił, bo ryzykujemy utratę wszystkiego!$B$BKażdego dnia trzeba kierować wojska tam, gdzie są najbardziej potrzebne. Dziś to bitwa o Dolinę Alterak najbardziej potrzebuje dzielnych wojowników.$B$BIdź, $N, i wesprzyj Ekspedycję Gromdardy. Nie możemy pozwolić, by Klanowi Mroźnego Wilka uszła na sucho przemoc wobec naszych braci!', 'Wygraj bitwę na polu bitwy Dolina Alterak i wróć do generała brygady Przymierza w dowolnej stolicy Przymierza, w Zimościsku, Dalaranie lub Shattrath.$B', 'Zwycięstwo w Dolinie Alterak', 'Wróć do generała brygady Przymierza.', '', '', '', '', 0),
(24428, 'koKR', 'Najbardziej zagadkowe okoliczności', '$GDokonałeś:Dokonałaś; rzeczy prawdziwie niemożliwej. Matka czarnego stada smoków leży martwa u twoich stóp. Weź jej głowę i zanieś ją Zardethowi z Czarnego Szponu.', 'Zanieś głowę Onyxii Zardethowi z Czarnego Szponu w piwnicy tawerny „Zarżnięte Jagnię”.', '', 'Wróć do Zardetha z Czarnego Szponu w Wichrogrodzie.', '', '', '', '', 0),
(24597, 'koKR', 'Prezent dla króla Wichrogrodu', 'Chcesz zrobić uroczą bransoletkę z talizmanami dla króla Wichrogrodu? Na pewno byłby zachwycony.$B$BMasz już zestaw kolekcjonera uroczych talizmanów?', 'Wręcz uroczą bransoletkę z talizmanami królowi Varianowi Wrynnowi w Wichrogrodzie.', '', 'Wróć do króla Variana Wrynna.', '', '', '', '', 0),
(25180, 'koKR', 'Tablice ziemi', 'Jakiś czas temu mój brat Brann przysłał z Ulduaru pilną wiadomość. Napisał, że znalazł starożytną skrytkę tytanów z tajemniczymi i ważnymi reliktami. Król Wrynn wysłał do Północnej Grani jeden ze swoich najszybszych statków, żeby przywiózł kuriera, i statek powinien już był dopłynąć.$B$BMartwię się, $N. Wciąż nie ma żadnych wieści o przybyciu kuriera. Zechcesz udać się do Portu Wichrogrodu i sprawdzić, czy już dotarł?', 'Zanieś tablice ziemi królowi Magniemu Miedziobrodemu w Żelaznej Kuźni.', '', '', '', '', '', '', 0),
(25181, 'koKR', 'Tablice ognia', 'Oczekuję przybycia kuriera z Północnej Grani. Wiezie zbiór starożytnych skarbów tytanów, które, mam nadzieję, rzucą światło na moje niepokojące wizje. Ten szaman powinien był przylecieć jednym z ostatnich sterowców, a ja zaczynam się martwić.$B$BMiał się ze mną spotkać przy wieży sterowców na południowy zachód od bram Orgrimmaru, ale nie chcę przegapić audiencji u wodza. Zechcesz poszukać kuriera i sprawdzić, co go zatrzymało?', 'Zanieś tablice ognia jasnowidzącej Bahurze w Orgrimmarze.', '', '', '', '', '', '', 0),
(25253, 'koKR', 'Proroctwa zagłady', 'Zwiastuni zagłady to nic nowego na ulicach Wichrogrodu, ale ci najnowsi mnie niepokoją. Rozstawili się po całym Starym Mieście i wydają się dobrze zorganizowani.$B$BPrzyszło mi do głowy, żeby ich wyłapać albo w inny sposób przeszkodzić im w działaniu, ale to tylko zepchnie ich do podziemia. Musimy dowiedzieć się o nich jak najwięcej. Pójdziesz na Stare Miasto, posłuchasz, jakie idee szerzą ci prorocy zagłady, i spróbujesz zdobyć któreś z ich ulotek?', 'Wysłuchaj przemowy proroka zagłady na Starym Mieście i zdobądź egzemplarze broszur „Żywiołowy ogień dla duszy”, „Co dla mnie oznacza »koniec wszystkiego«?” oraz „Bezpieczeństwo i otucha w skazanym na zagładę świecie”.', '', 'Wróć do kapitana Antona w Dzielnicy Handlowej Wichrogrodu.', 'Wysłuchaj przemowy proroka zagłady', '', '', '', 0),
(25282, 'koKR', 'Znaki czasu', 'Musimy coś zrobić, żeby osłabić zainteresowanie tym kultem zagłady, ale waham się przed podjęciem poważniejszych kroków, dopóki nie dowiemy się więcej o tym, kto stoi za tą grupą.$B$BMoi ludzie rozmieścili znaczniki w najbardziej uczęszczanych miejscach miasta. Weź te plakaty i rozwieś je tam, gdzie zobaczysz znaczniki. Najbardziej zdeterminowanych poszukiwaczy nie zniechęcą, ale to pierwszy krok do zdemaskowania tego kultu. Król ma już dość wrogów i bez tego, by zwracali się przeciw niemu jego właśni poddani.', 'Rozwieś 5 plakatów ostrzegawczych w Dzielnicy Handlowej, Dzielnicy Magów lub Dzielnicy Katedralnej Wichrogrodu.', '', 'Wróć do kapitana Antona w Dzielnicy Handlowej Wichrogrodu.', 'Rozwieszone plakaty', '', '', '', 0),
(25290, 'koKR', 'Infiltracja kultu', 'Coraz trudniej ukryć kultystów przed oczami ludzi, a po mieście rozchodzą się plotki. Chcę, żebyś $gwstąpił:wstąpiła; do kultu i $gdowiedział:dowiedziała; się jak najwięcej.$B$BPodejdź do któregoś z proroków zagłady na Starym Mieście i powiedz, że chcesz się do nich przyłączyć. Prorok zapewne da ci szaty i polecenie, byś $gspotkał:spotkała; się z innymi kultystami w jednej z kryjówek grupy. Wykonaj te polecenia, $N. To jedyny sposób, by zdobyć ich zaufanie.', 'Porozmawiaj z prorokiem zagłady na Starym Mieście w Wichrogrodzie, by wstąpić do kultu zagłady, a potem załóż otrzymaną szatę rekruta.', '', 'Zamelduj się u nadzorczyni Sylandry w Sadzie nad Lustrzanym Jeziorem w Kniei Elwynn.', 'Wstąp do kultu zagłady', '', '', '', 0),
(25414, 'koKR', 'Zaginieni', 'Kult nie tylko sieje już strach i paranoję. Teraz dostaję zgłoszenia o zaginionych ludziach. Matki, ojcowie, bracia i siostry jakby zapadli się pod ziemię, ale przeczuwam, że można ich znaleźć w którymś z obozów kultu poza miastem. Jeśli podam ci nazwiska kilku zaginionych, spróbujesz ich odnaleźć w obozie kultystów w Sadzie nad Lustrzanym Jeziorem? To na południowy zachód od bram miasta. Żeby wtopić się w tłum, musisz wstąpić do kultu i zdobyć szatę od któregoś z proroków zagłady na Starym Mieście.', 'Mając na sobie szatę rekruta, porozmawiaj z kultystką Lethelyn, kultystką Kaimą, kultystą Wymanem i kultystą Orlunnem w Sadzie nad Lustrzanym Jeziorem w Kniei Elwynn.', '', 'Zamelduj się z powrotem u kapitana Antona w Dzielnicy Handlowej Wichrogrodu.', 'Porozmawiaj z kultystką Lethelyn', 'Porozmawiaj z kultystką Kaimą', 'Porozmawiaj z kultystą Wymanem', 'Porozmawiaj z kultystą Orlunnem', 0),
(25417, 'koKR', 'Plan zagłady', 'Pierwsza partia urządzeń żywiołów jest gotowa. Twoim zadaniem będzie ukrycie ich w zaludnionych częściach Wichrogrodu. W odpowiedniej chwili urządzenia uwolnią swoje żywiołaki. Nie martw się, $N, do tego czasu będziesz już bezpiecznie daleko.$B$BNie rób niczego, co mogłoby zwrócić na ciebie uwagę.$B$B<Nadzorczyni wręcza ci paczkę z kilkoma urządzeniami żywiołów. To właśnie taki dowód, jaki kapitan Anton miał nadzieję, że zdobędziesz. Najlepiej zanieś mu te urządzenia.>', 'Zanieś urządzenia żywiołów kapitanowi Antonowi w Dzielnicy Handlowej Wichrogrodu.', '', 'Zanieś urządzenia żywiołów kapitanowi Antonowi w Dzielnicy Handlowej Wichrogrodu.', '', '', '', '', 0),
(25418, 'koKR', 'Pokrzyżować plany Młota Zmierzchu', 'Nie $gmogłeś:mogłaś; być jedyną osobą wysłaną do Wichrogrodu, by rozmieścić te urządzenia z żywiołakami wiatru. Musimy znaleźć i unieszkodliwić pozostałe urządzenia, zanim uwolnią uwięzione w nich żywiołaki, które rozpętają w mieście burze.$B$BZnasz te urządzenia na tyle, by je zniszczyć? Nasza największa szansa to rozbić je, zanim żywiołaki w środku nabiorą pełni sił. Szukaj urządzeń w Dzielnicy Handlowej, na Placu Katedralnym i w Dzielnicy Magów. Pospiesz się!', 'Zniszcz urządzenia żywiołów, by uwolnić uwięzione w nich żywiołaki. Pokonaj 5 szalejących żywiołaków wiatru.', '', 'Wróć do kapitana Antona w Dzielnicy Handlowej Wichrogrodu.', '', '', '', '', 0),
(25425, 'koKR', 'Ostrzeż króla Wrynna', '$GObroniłeś:Obroniłaś; Wichrogród przed zagrożeniem ze strony kultu Młota Zmierzchu, $N, i to nie krzywdząc naszych własnych obywateli. Nasz wróg nie spocznie na długo. Cho\'gall z pewnością już planuje swój następny ruch.$B$BMusisz powiadomić króla Variana Wrynna. Udaj się prosto do niego, do sali tronowej w Twierdzy Wichrogród. Powiedz królowi, że nasi wrogowie się ujawnili i musimy być gotowi na ich powrót.', 'Porozmawiaj z królem Varianem Wrynnem w Twierdzy Wichrogród.', '', '', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(72, 'koKR', 'Powoli zsuwasz wieko ze skrzyni...', 0),
(120, 'koKR', 'Spocznij, $N.$b$bSędzia Solomon to szlachetny przywódca. Jego słowo wiele dla mnie znaczy. Zasięgnę rady króla i przedstawię mu sytuację. Zapewnij dobrego sędziego, że ma wsparcie Armii Wichrogrodu. Posiłki zostaną wysłane, gdy tylko Jego Królewska Mość wyda rozkaz.', 0),
(121, 'koKR', 'Dziękuję za poświęcony czas, $N. Za twoją służbę dla Jeziernych Włości i Wichrogrodu nagradzam cię tymi monetami.$b$bA teraz wybacz, ale ta korespondencja wydaje mi się dość zagadkowa. W naszym królestwie dzieje się coś niedobrego. Obawiam się, że to początek konfliktu, a nie jego koniec.', 0),
(135, 'koKR', 'Ta sprawa może być bardziej zawiła, niż sądzi Mocnopłaszcz.', 0),
(141, 'koKR', 'Edwin VanCleef... Dobrze znam to nazwisko. Niepokoi mnie myśl, że człowiek tak pracowity i utalentowany mógł stać się takim łajdakiem. Zanim w to uwierzę, potrzebuję więcej dowodów.', 0),
(167, 'koKR', 'Moje podejrzenia się potwierdziły. Mój biedny brat... Cóż, dziękuję, że $gpomogłeś:pomogłaś; wyjaśnić tę zagadkę, nawet jeśli wyjaśnienie okazało się ponure.', 0),
(168, 'koKR', 'Dziękuję, że je $gzebrałeś:zebrałaś;, $N. Dzięki twoim staraniom zmarli zaznają spokoju po tej tragedii. Dopilnuję, żeby rodziny zostały powiadomione.', 0),
(171, 'koKR', 'Niech niebiosa ci błogosławią, $N. $GZrobiłeś:Zrobiłaś; dla Randisa więcej, niż większości ludzi w ogóle przyszłoby do głowy. Dziękuję – jesteś jasną gwiazdą na niebie Przymierza.$b$bProszę, jeśli znajdziesz czas, odwiedź nas jeszcze. Wiem, że Randis by się ucieszył, tak jak i ja.', 0),
(212, 'koKR', 'Ach, to się świetnie nada! Stokrotne dzięki!$b$bA teraz wybacz, muszę posiekać udziec, zamarynować go i przybrać na bankiet.', 0),
(269, 'koKR', '<Po przeczytaniu dziennika i wysłuchaniu twoich zamiarów...>$B$BZłe skażenie zakorzeniło się w i tak już udręczonej Kniei Zmierzchu. Dziękuję Światłości, że mamy $gbohatera:bohaterkę; takiego jak ty, by stawić mu czoła.$B$BAle najpierw musisz przygotować się do nadchodzącej próby... bo nekromanta Morbent Fel jest niezwykle potężny i otoczył się mrocznymi zaklęciami, które chronią go przed fizycznymi atakami. Jeśli masz go pokonać, potrzebujesz broni, przeciwko której te osłony będą bezsilne.', 0),
(270, 'koKR', 'Żelazo z kuźni światła to cenny metal, ale wygląda na to, że twoja misja jest naprawdę poważna. $GPrzebyłeś:Przebyłaś; długą drogę, $gbracie:siostro;. Przy odrobinie szczęścia może znajdziesz to, czego szukasz!$B$BA jeśli zdobędziesz to żelazo, znam kogoś, kto wykuje z niego broń przeciwko temu nekromancie z Kniei Zmierzchu, o którym mówisz.', 0),
(293, 'koKR', 'Oko Paletha. Ale to jedno widziało wiele smutku... musiało być świadkiem straszliwej, straszliwej tragedii.$b$bPozwól mi je oczyścić, bo Oczy stworzono, by jasno świeciły, a ich moc bywa bardzo niebezpieczna, gdy zostaną skażone tak jak to.', 0),
(322, 'koKR', 'Niezwykłą historię mi opowiadasz. I żelazo z kuźni światła! Od lat nie pracowałem z takim metalem. Będzie dla mnie zaszczytem znów z niego kuć. A ty musisz później do mnie wrócić i opowiedzieć o swojej walce z nekromantą.$b$bAle wybiegamy za daleko naprzód. Najpierw twoja broń przeciwko Morbentowi Felowi...', 0),
(325, 'koKR', 'Ach, z tym Morbent Fel nie będzie miał szans! Dobra robota!$b$bJesteś $ggotów:gotowa;. Morbent Fel padnie.', 0),
(332, 'koKR', 'Ach, więc $gwidziałeś:widziałaś; się z Renatem? Proszę bardzo, $gszanowny panie:szanowna pani;. Butelka naszego specjalnego pinot noir. Nie znajdziesz mu równego w całym Azeroth!', 0),
(333, 'koKR', 'Piszą tu, że interes Harlana kwitnie. To dobra wiadomość, ale zastanawiam się, po co ludziom tyle zbroi. Nie słyszałam o żadnej otwartej wojnie... czy szlachta czegoś nam nie mówi?$B$BCóż, dziękuję za dostarczenie zamówienia. Oto twoja zapłata, a ja dopilnuję, żeby Harlan dostał swój towar.', 0),
(334, 'koKR', 'Och, psiakrew! Myślałem, że jak zapomnę przybornika, to wymigam się od roboty. Teraz chyba będę musiał pomagać Larsonom w szyciu...$B$BA, trudno. Na zabawę przyjdzie czas później.', 0),
(335, 'koKR', 'Wyśmienicie! To naprawdę doskonałe okazy!', 0),
(336, 'koKR', 'Ach, dziękuję, że $gprzyniosłeś:przyniosłaś; mi ten wspaniale wyglądający trunek, sługo. Masz tu miedziaka. A teraz zejdź mi z oczu i pozwól mi się delektować!', 0),
(337, 'koKR', 'O rety! Ta księga nie stała na naszych półkach od czasów sprzed odbudowy Wichrogrodu, a to było przed laty. Oczywiście trzeba będzie ją odrestaurować, bo jest w kiepskim stanie, ale umieszczenie jej w naszym zbiorze rzadkich ksiąg będzie dla mnie zaszczytem.$B$BDziękuję, $N. Przyjmij to jako zapłatę za zwrot księgi!', 0),
(343, 'koKR', 'Metalurgia? Ach tak, mamy wiele książek na ten temat i chętnie pomożemy bratu Kristoffowi w przygotowaniu przemowy! A więc... której konkretnie książki potrzebował dobry brat?', 0),
(350, 'koKR', 'Żartujesz? Shaw znowu chce mojej pomocy? Co za tupet...$b$bBractwo Nieskornych, mówisz? Cóż, z pewnością przynosisz cudowne wieści, co? Zaraz mi powiesz, że Śmiercioskrzydły wciąż żyje i atakuje miasto.$b$bNo dobrze, opowiedz mi wszystko od początku. I niczego nie pomijaj, nawet jeśli uważasz, że to nieważne. Muszę wiedzieć wszystko.', 0),
(353, 'koKR', 'Aha! Więc Grimand w końcu skończył mój topór! Nie mogę się doczekać, aż wypróbuję go na troggach i koboldach!$b$bStokrotne dzięki, $N. $GPrzebyłeś:Przebyłaś; długą drogę z tą przesyłką. Oto trochę monet za twój trud.', 0),
(373, 'koKR', 'Edwin VanCleef, mówisz? Prędzej spodziewałbym się listu od mojej nieżyjącej babki... Więc go $gzabiłeś:zabiłaś;? Wybacz, że to mówię, ale jestem nieco zaskoczony. Za młodu był niezrównanym wojownikiem. Zobaczmy, o czym po tylu latach uznał za stosowne do mnie napisać.$b$b<Baros przegląda list.>$b$bEdwinie... Widzę, że lata wcale cię nie zmieniły – wciąż idealista i romantyk. Nie obchodzi go, kogo krzywdzi, $N. Zemsta go pochłonęła. Choć właściwie nie wiem, czy mogę go za to winić.', 0),
(387, 'koKR', 'Dzielnie $gwalczyłeś:walczyłaś; w Kazamatach, $N. Widać, że ten problem nas przerasta. Ale $gspisałeś:spisałaś; się dobrze i jestem ci za to wdzięczny.', 0),
(388, 'koKR', 'Więc to za te chusty – plugawe symbole zepsucia – musiał zginąć mój Mac? Co za strata. Co za tragiczna ofiara.$b$bAle niestety nie cofnę czasu. Wiedz tylko, $N, że swoimi czynami $goddałeś:oddałaś; mojej rodzinie sprawiedliwość.', 0),
(389, 'koKR', 'Na Światłość, czego chcesz? Nie widzisz, że mamy tu kryzys?$b$bBazil Thredd?! A po co ci rozmowa z tym draniem? Skąd mam wiedzieć, że nie należysz do jego kompanów i nie $gprzyszedłeś:przyszłaś; pomóc w tym przeklętym buncie? Gdyby te cholerne cele nie stały otworem, sam bym cię w jednej na jakiś czas zamknął!', 0),
(391, 'koKR', 'Bez Thredda na czele buntowników mam nadzieję, że łatwiej będzie opanować rozruchy. Zobaczymy.$B$BMuszę przyznać, że po pół godzinie nie spodziewałem się już, że wyjdziesz, ale najwyraźniej źle cię oceniłem.$B$BZgaduję więc, że niewiele się od niego $gdowiedziałeś:dowiedziałaś;? Ale ja wiem to i owo o poczynaniach Thredda, co może cię zainteresować.', 0),
(392, 'koKR', 'Hmm. Maelik? Nie, to imię nic mi nie mówi, podobnie jak ten rysopis. Ale to może być ktokolwiek! Dawny kamieniarz, ktoś z Bractwa Nieskornych... Choć jeśli ma tak dobre koneksje, jak sugeruje Thelwater, może ktoś inny go rozpozna. Niech pomyślę.', 0),
(393, 'koKR', 'Co? Co to jest? Tak, chyba wiem, kim jest ten człowiek, ale nie nazywa się Maelik. Zabójcy noszą wiele imion i wiele masek i porzucają je, gdy przestają być użyteczne. Inny znany pseudonim tego człowieka to Marzon, choć i to z pewnością nie jest jego prawdziwe imię.$b$bTak czy inaczej, to zabójca, a ja sporo o nim wiem.$b$bMarzon pracuje obecnie dla lorda Gregora Lescovara, lorda o podejrzanej reputacji, nawet jak na zepsutą szlachtę Wichrogrodu.', 0),
(394, 'koKR', 'A więc nie żyje? Szybko $gwymierzyłeś:wymierzyłaś; sprawiedliwość, $N. Modlę się do Światłości, bym nigdy nie stał się twoją zwierzyną!$b$b<Śmieje się i klepie cię po ramieniu.>$b$bNie chcę cię krytykować, $N. Jakże bym mógł, sam będąc mistrzem wszystkich zabójców? Ale prawdę mówiąc, $goddałeś:oddałaś; mieszkańcom Wichrogrodu wielką przysługę i za to ci dziękuję.', 0),
(395, 'koKR', 'Dobrze cię widzieć, $N. Słyszałem, że niedawno znaleziono martwego lorda Gregora Lescovara.$b$bWygląda na to, że twoja misja się powiodła. Jestem ci wdzięczny, że $guratowałeś:uratowałaś; mnie i wielu innych przed zemstą VanCleefa.', 0),
(396, 'koKR', 'Należy ci się uznanie za przysługę, jaką $goddałeś:oddałaś; Wichrogrodowi, $N. Gdyby machinacje VanCleefa się powiodły, bez wątpienia wyrządziłby królestwu poważne szkody – a tego rzecz jasna musimy unikać.$B$BPrzyjmij to jako wyraz mojego uznania.', 0),
(397, 'koKR', 'Pan każe dać prezent. To dla ciebie, $N. Zggi chce zatrzymać ładny prezent, ale Zggi wie, że nie wolno zdradzać Pana.', 0),
(399, 'koKR', 'Och, dziękuję, $N! W praktyce do niczego mi się nie przyda, ale wartość sentymentalna... Nie muszę chyba mówić, jak bardzo dziękuję, że mi go $gprzyniosłeś:przyniosłaś;... narażając własne zdrowie, nie wspominając o czasie, jaki zajęła ci droga aż do Zachodniego Skraju. Masz moją wdzięczność – przyjmij to jako wyraz podziękowania.', 0),
(434, 'koKR', 'A więc załatwione? Dobrze. Bardzo dziękuję za dyskrecję, $N. Niejeden raz $gdowiodłeś:dowiodłaś; swojej wartości. Będę uważnie śledził ciebie i twoje postępy w Przymierzu.$B$BTylko nie pakuj się w kłopoty.', 0),
(538, 'koKR', 'Ach tak, pamiętam Miltona. Mól książkowy, bez dwóch zdań. Poczciwina.$B$BI ma rację. Ruiny Alterak wciąż kryją zasoby wiedzy, którym grozi przepadnięcie!$B$BW Alterak mieszkają teraz ogry, a one nie przepadają za wyższą nauką.', 0),
(540, 'koKR', 'Och, $gzdobyłeś:zdobyłaś; je! Wspaniale! Muszę natychmiast zacząć studiować „Ramię Gri\'leka”!', 0),
(542, 'koKR', 'O rety, rety! Spójrz tylko na nie! Nie mogę uwierzyć, że przetrwały upadek Alterak. I to jeszcze wśród tych wszystkich ogrów!$B$BDziękuję, $N. Stokrotne dzięki! $GPomogłeś:Pomogłaś; ocalić ludzką wiedzę i przydajesz blasku Bibliotece Królewskiej Wichrogrodu.', 0),
(543, 'koKR', 'Ach, wspaniale. Trzeba ją będzie oczywiście wyczyścić, ale naprawdę $gprzeszedłeś samego siebie:przeszłaś samą siebie;, $N. Każę komuś przygotować tiarę i niezwłocznie umieścić ją w naszej kolekcji.', 0),
(563, 'koKR', 'Co to? Ach... a więc mój pilny uczeń zajął się problemem nag przy Południowym Brzegu. Dziękuję, że mi to $gprzyniosłeś:przyniosłaś;. Z pewnością wezmę to pod uwagę, kiedy w przyszłym miesiącu będę rozpatrywał przydziały żołnierzy.', 0),
(579, 'koKR', 'Czy któryś z tych tytułów cię interesuje, $N?', 0),
(690, 'koKR', 'Malin cię przysłał, co? Nic mnie to nie obchodzi, choćby sam Muradin wstał z martwych i przywiózł cię tu na smoku. Jestem zajęty! Jak czegoś trza, gadaj z Krytenem.', 0),
(697, 'koKR', '<Arcymag Malin otwiera list, a jego oczy robią się okrągłe ze zdumienia.>$B$BNa Światłość, udało ci się. Cudownie. Trelane będzie zachwycony. Jestem pewien, że Kryten i Skuerto cieszą się z powrotu do Wichrogrodu tak samo jak ja.$B$BDziękuję, $N. Proszę, weź to, przyda ci się w podróżach.', 0),
(1015, 'koKR', 'A skąd pomysł, że mam ochotę znosić natręctwo kogoś takiego jak ty, $c? Zaczekaj – porzucę tylko ważne obowiązki, którymi zajmuję się każdego dnia, żeby pomóc ci znaleźć jakiś drobiazg. Ależ oczywiście, dobro Darnassus – ba, całego Teldrassilu – musi ustąpić zdobyciu kolejnej błyskotki do twojej kolekcji.$B$BGłupcy z Gaju Luny marnują mój czas, wołając o pomoc, a teraz jeszcze muszę znosić i to?', 0),
(1075, 'koKR', 'A więc to zaklęcie, którego potrzebujesz... takie, które pozwoli ci zdetonować ładunki z odległości... hmmm.', 0),
(1076, 'koKR', 'Daj mi tylko chwilkę, a twój zwój będzie gotowy.', 0),
(1077, 'koKR', 'Idealnie, $N! Dobra robota.$B$BTo zaklęcie w połączeniu z NG-5 da nam idealny ładunek zdalny.$B$BUrządzimy idealną dywersję, żebyś $gmógł:mogła; się zakraść i wykraść listy i plany inżynieryjne spółki Gitgeszeft.$B$BTo z pewnością spowolni wycinkę lasów, którą prowadzą.', 0),
(1078, 'koKR', 'Idealnie, $N. Serdecznie ci dziękuję.$B$BMoże pewnego dnia będę mógł pomóc tobie, tak jak ty $gpomogłeś:pomogłaś; mnie.', 0),
(1241, 'koKR', 'Hmm... <Jorgen przygląda ci się spod zmrużonych powiek.>$b$bNiech będzie. Pomogę ci, ale nie dlatego, że chcę, tylko dlatego, że muszę.$b$bI wyjaśnijmy sobie jedno: już teraz wiesz o wiele więcej, niż $gpowinieneś:powinnaś;. Niech to zostanie naszą małą tajemnicą i nie paplaj po karczmach o niczym, czego się dowiesz. Zrozumiano?', 0),
(1242, 'koKR', 'Przepraszam, list do mnie? No proszę... Rzadko się zdarza, żeby człowiek, który tylko pracuje, dostał przesyłkę, która nie jest skrzynią ani beczką. Zobaczmy, o co chodzi.$B$B<Elling otwiera list, zerkając na ciebie.>$B$BWyglądasz na trochę $gspiętego:spiętą;. Wszystko w porządku, $N?', 0),
(1243, 'koKR', 'Och, Trias cię przysłał, tak? To co innego.$B$BŚmiało walcz z każdym potworem, który wyskoczy na ciebie z ciemności. Skoro zadajesz się z kimś takim jak on, na pewno łatwo sobie z nimi poradzisz.$B$BTo czego mój przyjaciel ode mnie potrzebuje w taki ponury dzień jak dziś?', 0),
(1244, 'koKR', '$GWróciłeś cały:Wróciłaś cała; i $gzdrowy:zdrowa;. Czego chcieć więcej, prawda?$B$BZobaczmy, co tu mamy. W porównaniu z dokumentami Nieskornych, które widziałem, ten wygląda na całkiem oficjalny. Ale może to być podpucha, która ma zbić cię z tropu, czegokolwiek szukasz.', 0),
(1245, 'koKR', 'Tak... ciekawa lektura. Jorgen i DeLavey mądrze zrobili, że mnie w to wciągnęli.$B$BWygląda na to, że Nieskorni bardzo się starają doprowadzić ten swój plan do końca. Hmm... a co to? Pięść? Znajome przezwisko.', 0),
(1246, 'koKR', 'Co?!$B$BWłazisz mi w zaułek i wypytujesz o moje prywatne interesy? Interesy, które w ogóle cię nie dotyczą.', 0),
(1247, 'koKR', 'Dobrze widzieć, że jeszcze żyjesz, $N. Czyli z Dashelem poszło dobrze, co?$B$BPoczytałem więcej o tym ich planie i choć nie pada tu imię dyplomaty, na którego polowali, jest mowa o planie B, który wprowadzili w życie, kiedy nie udała im się pierwsza próba porwania.$B$BTen Chudy, o którym wspomniał Dashel, nie występuje tu pod żadnym innym imieniem, ale jeśli mówisz, że jest w Przystani Menethilów, to już jakiś początek.', 0),
(1248, 'koKR', 'Witaj, witaj, witaj, $N. Miło, że do nas $gzajrzałeś:zajrzałaś;. Może kufel piwa na dziś? Albo baranina?$B$BMów, czego sobie życzysz, a dopilnuję, żeby niczego ci nie zabrakło. Nazywam się Mikhail i z przyjemnością cię obsłużę.$B$BHmm? Co takiego? Trias? Ciszej, $gprzyjacielu:przyjaciółko;. Nie cała tawerna musi o tym słyszeć.', 0),
(1249, 'koKR', '$GZłapałeś:Złapałaś; go, co? Brawo. Nie spodziewałem się, że to właśnie Chudy.$B$BPowiem szczerze, nigdy nie sądziłem, że zatęsknię za dreszczykiem co bardziej podejrzanych interesów w półświatku. Widać stare nawyki trudno wykorzenić. Tylko nie mów o tym Ellingowi – gdyby usłyszał, że brakuje mi akcji, pewnie próbowałby ściągnąć mnie z powrotem do Wichrogrodu.$B$BCieszę się, że mogłem ci choć trochę pomóc podczas twojego pobytu w Przystani Menethilów. Jeśli będziesz czegoś jeszcze potrzebować, wystarczy poprosić.', 0),
(1250, 'koKR', 'KRÓLA?! To znaczy... króla? Prawdziwego króla? Żartujesz? Nie $gmówiłeś:mówiłaś;, że szukasz porywaczy króla. Nawet nie słyszałem, że zaginął – to by trochę wyjaśniało, czemu koronowano jego syna.$B$BZaraz wyślę wiadomość Ellingowi. Będzie chciał wiedzieć, że jesteś na tropie.$B$BNigdy bym nie pomyślał, że Jahn sprzeda Wichrogród za parę marnych monet. Nawet łotr musi mieć w pewnych sprawach honor.$B$BTeraz najważniejsze to znaleźć tego Hendela. I chyba mogę w tym pomóc.', 0),
(1260, 'koKR', 'Och, wujek cię przysłał, tak?$b$bCóż, zbieram przepisy i mam kilka tropów, ale potrzebuję pomocy.$b$bPomocy kogoś, kto nie boi się zamoczyć nóg.', 0),
(1264, 'koKR', 'Miło mi cię poznać, $N. Jestem dowódca Samaul i dowodzę siłami panny Proudmoore tutaj, w Theramore.$B$BChoć mam mnóstwo zajęć, jeśli masz jakieś pytania, śmiało pytaj. Może będę musiał się streszczać, ale nie ma powodu, żebym był nieuprzejmy, skoro potrzebujesz mojej pomocy.$B$BJeśli zamierzasz wyjść poza miasto, radzę uważać. Oprócz ogrów, orków i murloków w południowej części bagien roi się od czarnych smoków.', 0),
(1265, 'koKR', 'Człowieka, którego szukasz, niejakiego Hendela, tu nie ma. Inne źródła przekazały lady Proudmoore informacje, które – jak sądzę – już znasz. Poprosiła mnie, żebym cię odnalazł i wsparł w twoim przedsięwzięciu. Jeśli pozwolisz, powiem ci, gdzie znajdziesz szeregowego Hendela, abyśmy mogli postawić go przed sądem.', 0),
(1266, 'koKR', 'Witaj, $gobywatelu:obywatelko;. To niebezpieczne miejsce na przechadzki. Nie kręciłbym się tu zbyt długo, jeśli życie ci miłe.$B$BJeśli będziesz się streszczać, zobaczę, czy mogę ci pomóc. Tylko miej oczy otwarte, bo wszędzie tu te plugawe ogry. Podobno gdzieś na bagnach jest baza Hordy. Infiltratorzy robią, co mogą, żeby ją znaleźć, ale idzie to powoli i niewiele udało się osiągnąć.', 0),
(1267, 'koKR', 'Pozwól, że jako pierwsza podziękuję ci za wszystko, co $gzrobiłeś:zrobiłaś;, $N. Twoja pomoc okazała się nieocenionym błogosławieństwem dla mojego ludu i dla mieszkańców Wichrogrodu. Żałuję, że nasza znajomość nie zaczęła się w lepszych okolicznościach.$b$bMusisz też zrozumieć, że nie mogę ci otwarcie podziękować za twoje starania, ale zapewniam cię raz jeszcze, że są docenione.$b$bKiedy w przyszłości odwiedzisz Theramore, odszukaj mnie, a postaram się informować cię o rozwoju sytuacji.$b$bJeszcze raz dziękuję, $N.', 0),
(1271, 'koKR', 'Mój bratanek mówi, że $gpomogłeś:pomogłaś; mu w badaniach na Pyłowym Bagnisku i $gwyciągnąłeś:wyciągnęłaś; jego wspólnika z opałów. Cóż, my, Sternowie, trzymamy się razem i nie zapominamy o przyjaciołach!$B$BWięc umyj ręce, $N, bo zaraz wyprawiamy przyjęcie na twoją cześć!', 0),
(1274, 'koKR', 'Witaj, $N. Jestem biskup DeLavey.$B$BSkoro pytasz o moje sprawy tutaj, w twierdzy, to niewątpliwie młodemu Thomasowi udało się zwerbować cię do pomocy naszemu królestwu. Zawsze sprawnie wypełniał moje prośby.$B$BObawiam się, że nie mam czasu na długie wyjaśnienia, więc pozwól, że powiem wprost... i proszę, postaraj się, żeby nie rozeszło się to po całym mieście.', 0),
(1301, 'koKR', 'James? Och, wyjechał już dość dawno temu.$B$BChyba poczuł nowy przypływ patriotyzmu. Nietrudno zrozumieć dlaczego. Przy całym tym szaleństwie w Lordaeronie wielu ludzi przyłączyło się do Jainy Proudmoore, kiedy wyruszała za morze.', 0),
(1324, 'koKR', 'Zapewniam cię, że wszystkich nas bardzo poruszyły ostatnie wydarzenia, ale pozwól nam zabrać go do Theramore na przesłuchanie, a zobaczymy, co da się zrobić, żeby odnaleźć króla.$B$BJestem pewien, że moja pani, lady Proudmoore, chciałaby ci podziękować za pomoc. Porozmawiaj z nią, gdy znajdziesz chwilę.', 0),
(1338, 'koKR', 'Ach, zamówienie od jednego z Gromdardów. To dumny klan, pełen krasnoludów najlepszego sortu. I do tego bogatych.$B$BDziękuję, $N. Jeszcze dziś zabiorę się do tarczy górskiego strażnika Gromdardy.', 0),
(1363, 'koKR', 'To nie była moja wina. Naprawdę nie.', 0),
(1364, 'koKR', 'Ach, wspaniale!$B$BJuż od jakiegoś czasu obawiałem się, że mistrz Mazen z Akademii Sztuk i Nauk Tajemnych przeoczył moją prośbę o Eseje Khadgara o zbieżności wymiarów.$B$BMusi być zasypany prośbami, zważywszy na wszystkie te dziwne rzeczy, które ostatnio się dzieją.$B$BA teraz wybacz, muszę natychmiast zabrać się do badań. Możliwość poznania wreszcie myśli kogoś tak wielkiego jak Khadgar niezmiernie mnie ekscytuje.', 0),
(1447, 'koKR', 'No dobra, $gprzyszedłeś:przyszłaś; do mnie z jakiegoś powodu. Czego potrzebujesz?', 0),
(1448, 'koKR', 'Świątynia Atal\'Hakkar spoczywa na dnie Sadzawki Łez? I otaczają ją smoki z Zielonego Stada?$B$BNiezwykłe odkrycie! Ale najwyraźniej coś poszło bardzo źle.', 0),
(1449, 'koKR', 'Czego chcesz, $gchłopcze:panienko;? Nie widzisz, że mam tu na głowie ważniejsze sprawy? Kto ma czas stać i mielić ozorem z byle gadułą?$B$BTrolle wyłażą z każdej dziury! Streszczaj się.', 0),
(1469, 'koKR', 'Rhapsody Shindigger! No tak... jak mogłem zapomnieć takie imię?$B$BCzyli przez cały czas wiedział, że świątynia zatonęła? Cóż, to by ci z pewnością oszczędziło trochę bieganiny.$B$BAle ten artefakt Atal\'ai! Ależ to znalezisko!', 0),
(1475, 'koKR', 'Tabliczki Atal\'ai! Dziękuję ci, $N!$B$BGdy tylko dostarczę je Lidze Odkrywców, nasze imiona razem przejdą do historii. $GPomogłeś:Pomogłaś; staremu krasnoludowi wypełnić ostatnie życiowe zobowiązanie. Będę ci za to wdzięczny do końca moich dni.', 0),
(1477, 'koKR', 'Andromath cię przysłał? Bardzo dobrze. Mam dla ciebie ważne zadanie...', 0),
(1639, 'koKR', 'No proszę, $gelegancik:elegantka;! Co takie wymuskane stworzonko jak ty robi w „Świni i Gwizdku”? Uważaj, bo jeszcze złamiesz paznokieć...', 0),
(1640, 'koKR', 'Twardsza z ciebie sztuka, niż na to wyglądasz!', 0),
(1641, 'koKR', 'Tu, w Wichrogrodzie, odpowiadam za prowadzenie paladynów ścieżką wyższej cnoty, gdy poświęcają się Światłości i bronią Azeroth przed Plagą oraz innymi zagrożeniami.$B$BNadszedł czas, byś $guczynił:uczyniła; pierwszy krok ku prawdziwej cnocie. Jeśli się zgodzisz, dam ci Księgę Boskości. Studiując ją, dowiesz się co nieco o Światłości i o tym, czego się od ciebie oczekuje. Jeśli ją zrozumiesz i okażesz się $gzdolny:zdolna;, zdobędziesz większe umiejętności.', 0),
(1642, 'koKR', 'Witaj ponownie, $N. Jak ci idą studia nad Księgą Boskości?$B$BW takim razie jesteś $ggotów:gotowa; na próbę. W mieście i na naszych ziemiach zawsze jest coś do zrobienia: czyny współczucia i zrozumienia, ludzie potrzebujący pomocy, stwory do zgładzenia.$B$BDowodząc, że masz cierpliwość, by pomagać innym, zwłaszcza tym mniej szczęśliwym, udowodnisz, że jesteś sługą Światłości i masz trzeźwy umysł.', 0),
(1643, 'koKR', 'Och, witaj, $gzłociutki:złociutka;. Jak tam twoje przygody? Och, tak się cieszę, że dobrze ci idzie.$B$BJa? Dziękuję, że pytasz – radzę sobie całkiem nieźle, zważywszy na okoliczności.$B$BOd kiedy przybyło rzemieślników, ludzie dużo niechętniej oddają skóry i tkaniny, więc trudniej mi szyć ubrania dla dzieci z sierocińca, ale jakoś damy radę. Mówiąc „my”, mam na myśli siebie i męża. Jest teraz w Żelaznej Kuźni i próbuje prosić o pomoc tamtejszych mieszkańców.', 0),
(1644, 'koKR', 'Dziękuję, $N, bardzo ci dziękuję!$B$BDzieci będą zachwycone, a ty $gzaoszczędziłeś:zaoszczędziłaś; mi mnóstwo czasu. Teraz będę mogła zająć się innymi potrzebami dzieci, a mój John może wróci do domu wcześniej, niż myśleliśmy.$B$BJeszcze raz dziękuję, $N. Wiedziałam, że mogę liczyć na dobroć innych. Niech Światłość będzie z tobą.', 0),
(1649, 'koKR', 'Ach, chcesz mnie prosić o próbę męstwa. Wspaniale.$B$BW mieście i na okolicznych ziemiach czeka wiele trudnych zadań, a przydałby się do nich ktoś z twoimi umiejętnościami.$B$BNie traktuj tej próby lekko, $N. Jak wiele rzeczy na naszej ścieżce, może nas ona kosztować życie. Kościół zawsze pragnie powiększać swoje szeregi, ale rozumie, jakich poświęceń trzeba, by służący mu paladyni byli tego godni.$B$BCzy jesteś $ggotów:gotowa;?', 0),
(1650, 'koKR', 'Witaj, $N. Sądząc po tej całej zbroi i broni, albo $gprzyszedłeś:przyszłaś; odebrać mi ziemię, albo Kościół wreszcie przysłał kogoś, kto mnie ochroni, póki mojego Jordana nie ma.$B$BCóż, pozwól, że się przedstawię: jestem Daphne Stilwell. Miło mi.$B$BNie $gspóźniłeś:spóźniłaś; się... Od wczorajszego świtu zabiłam dopiero pół tuzina tych szumowin. Trochę im schodzi, zanim wyjdą zza tamtego zakrętu, ale pewnie widzieli, jak nadchodzisz, a to znaczy, że lada chwila tu będą.', 0),
(1652, 'koKR', 'A więc znów się spotykamy, $N, i widzę, że dopisuje ci humor.$B$BDom Stilwellów przetrwa kolejny dzień, a z twojej opowieści wnioskuję, że niebezpieczeństw nie brakowało. Dobra robota.$B$BDaphne i Jordan bardzo pomogli Kościołowi, a ochrona ich majątku – i samego ich życia – to najmniej, co mogliśmy dla nich zrobić.$B$BZa twoje męstwo spotka cię nagroda.', 0),
(1653, 'koKR', 'Dzień dobry, $N. Mam nadzieję, że Światłość jest z tobą?$b$bCo takiego? Przysłał cię Duthorian!? Moja żona, co z nią? Wiedziałem, że będą kłopoty, jeśli wyjadę. Proszę, powiedz mi, że ona... och, dzięki niebiosom. Tak się cieszę, że jest bezpieczna. Nieskorni stanowili zagrożenie na długo przed tymi napaściami, ale teraz doradcy króla nie mogą już temu zaprzeczyć.$b$bCo jeszcze mówił Duthorian?$b$bTo ciebie wysłano, żeby chronić moją żonę? W takim razie jeszcze raz ci dziękuję, $N. Nie wyobrażam sobie lepszej próby męstwa.', 0),
(1665, 'koKR', 'Jest! Na pewno nie chciał się z nim rozstać, ale $gokazałeś:okazałaś; się $gprzekonujący:przekonująca;. Dobra robota.$B$BA teraz twoja lekcja...', 0),
(1688, 'koKR', 'Surena miała talent, ale za mały, by samodzielnie opanować magię czarnoksięską. Szkoda patrzeć, jak marnuje się talent, ale czasem jest to konieczne.$B$BMam nadzieję, że inwestycja w ciebie przyniesie inne rezultaty.', 0),
(1689, 'koKR', '$GSpisałeś:Spisałaś; się lepiej, niż się spodziewałem, $N, choć dokładnie tak, jak liczyłem. Teraz możesz nauczyć się rozkazywać ujarzmionemu wędrowcowi Pustki – sojusznikowi, który okaże się cenny w próbach, jakie z pewnością cię czekają.$B$BNa razie nie mam cię już czego uczyć, ale jeszcze z tobą nie skończyłem, $N.', 0),
(1698, 'koKR', 'Ha! A więc $gusłyszałeś:usłyszałaś; o moim wyzwaniu, tak?$B$BNo to siadaj i słuchaj. Napij się i delektuj się tym kuflem... bo może być twoim ostatnim.', 0),
(1700, 'koKR', 'Furen to napisał? Jak on śmie! Przecież to ja nauczyłem go wszystkiego, co umie! Myśl, że mógłby mnie czegoś nauczyć, to skandal! Skandal!$B$BHm... ale jest w tych notatkach coś, czego chciałbym spróbować...', 0),
(1701, 'koKR', 'Masz wszystko? Niesamowite! Bałem się, że te chimery na pewno cię pożrą!$B$BNo to bierzmy się za tę zbroję...', 0),
(1702, 'koKR', 'Ach, Parzący Jęczmienny Browar. Wspaniały trunek! A więc $gbyłeś:byłaś; u Yorusa, co?$B$BZałatwię ci tarczę, a jakże! Lepszej nigdzie nie znajdziesz, i to święta prawda!', 0),
(1703, 'koKR', 'Są interesujące, doprawdy bardzo interesujące. Mój krasnoludzki kolega Furen dokonał wielkiego odkrycia!$B$BDziękuję, $N. Zastosowanie jego nowych technik we własnych wyrobach będzie dla mnie zaszczytem.', 0),
(1704, 'koKR', 'O rety! Te notatki są niesamowite! Co więcej... są niewiarygodne i zdumiewające, aż mi się kolana trzęsą!$B$BFuren dokonał przełomu! Prawdziwego przełomu! Nie mogę się doczekać, aż wypróbuję jego nową technikę!', 0),
(1705, 'koKR', 'Świetna robota! A teraz wybacz, sam mam trochę pracy...', 0),
(1706, 'koKR', 'Nie mogę uwierzyć! Technika Furena zadziałała, a ta zbroja powinna wytrzymać ogromne obciążenia.$b$bProszę, $N. I dziękuję. Nie uwierzyłbym w odkrycie Furena, gdybyś nie $gzdobył:zdobyła; surowców, dzięki którym mogłem je sam sprawdzić.', 0),
(1715, 'koKR', 'Przysłał cię Czarnoklucz, tak? Przeklęci czarnoksiężnicy z Żelaznej Kuźni muszą wreszcie zrobić u siebie porządek. W Wichrogrodzie jest ograniczona liczba miejsc i nauczycieli. Przy takim ruchu prędzej czy później ściągniemy na siebie uwagę.', 0),
(1716, 'koKR', 'Czy przeprawa była trudna, $N? $GPrzebyłeś:Przebyłaś; długą drogę, by ze mną porozmawiać. Ale nie obawiaj się, wiem, po co Gakin cię przysłał, i słusznie zrobił, bo mogę ci pomóc w poszukiwaniach.', 0),
(1718, 'koKR', 'Witaj, $N. Dobrze widzieć, że $gdotarłeś:dotarłaś; na Wyspę Jatki. Mam nadzieję, że przypadnie ci do gustu...', 0),
(1738, 'koKR', 'Tak, widzę, że to się świetnie nada, pozwól, że chwilę nad tym popracuję...$B$BTakar to zaradny jegomość, prawda? Gdybym tylko zdołał go namówić do powrotu do cywilizacji.', 0),
(1739, 'koKR', 'Dobra robota, dobra robota, $N. Widzę, że słusznie postanowiliśmy cię szkolić. Twoje dokonania z pewnością nie rozczarowują.$B$BBez obaw pokażę ci, jak panować nad świeżo spętanym sukkubem. Patrz uważnie.', 0),
(1780, 'koKR', 'Szybko $gwróciłeś:wróciłaś;, $N. I czego $gdokonałeś:dokonałaś; podczas nieobecności w Katedrze?$B$BCzy $gpomogłeś:pomogłaś; w szlachetnej sprawie? Może $gpoznałeś:poznałaś; wartość miłosierdzia albo lepiej $gzrozumiałeś:zrozumiałaś; swoje obowiązki wobec mieszkańców Azeroth. Powiedz mi, komu $gpomogłeś:pomogłaś; i w jaki sposób... No proszę, jestem pod wrażeniem, $N. To z pewnością czyny kogoś, kto podąża za Światłością i stawia innych ponad siebie.$B$BTakie poświęcenie zawsze zostanie w swoim czasie nagrodzone.', 0),
(1781, 'koKR', '*kaszle*$B$BMiło cię poznać. Nie przejmuj się moimi ranami, tym razem dobry kapłan zajmie się starym Gazinem. Nie będę potrzebował mocy Symbolu Życia, który masz przy sobie... przynajmniej jeszcze nie teraz.$B$BA więc Duthorian przysłał cię do mnie, co? Niech będzie. Opowiem ci dokładnie, co spotkało mnie i mojego przyjaciela Henzego. Przy odrobinie szczęścia i twoich umiejętnościach może jeszcze zdołasz nam wszystkim pomóc.', 0),
(1782, 'koKR', 'Oto twoja zbroja, $N. Wytrzyma najsilniejsze ciosy albo nie nazywam się Furen Długobrody!$B$BI muszę ci podziękować. Wiele się nauczyłem, pracując z surowcami,$Bktóre mi $gprzyniosłeś:przyniosłaś;. Myślę, że kiedyś dokonam kolejnego przełomu!$B$BPrześlę to, czego się nauczyłem, innym$Bkowalom Przymierza.$B$BPowiem im, że bardzo mi $gpomogłeś:pomogłaś;, to może zechcą się odwdzięczyć.', 0),
(1788, 'koKR', 'Dobrze się dziś $gspisałeś:spisałaś;, $N. Możesz być $gdumny:dumna; ze swoich dokonań.$B$BA jeszcze bardziej możesz być $gdumny:dumna; ze swoich umiejętności. Nie każdy potrafi posłużyć się mocą Symbolu Życia. Skoro wzywasz Światłość, by przywracać umarłych, jesteś $ggotów:gotowa; na jeden z największych zaszczytów paladyna: moc wskrzeszania.$B$BBędziesz $gmógł:mogła; przywracać do życia poległych towarzyszy, tak jak $gprzywróciłeś:przywróciłaś; Henzego.$B$BTrzymaj się, $N. Światłość cię opromienia, przyjmij ją całym sercem.', 0),
(1790, 'koKR', 'Pospiesz się, $N – jeśli zawiedziesz, może przepaść więcej niż jedno życie.$B$BJeśli z jakiegoś powodu nie zdołasz pomóc Gazinowi i Henzemu, wróć do mnie, a dam ci na drogę kolejny Symbol Życia.$B$BNie bierz jednak mojej pomocy za zwykłą jałmużnę. Musisz dowieść swojej wartości jak każdy inny paladyn, a ciągłe porażki mogą się później na tobie odbić.', 0),
(1793, 'koKR', 'Udowodniono, że Światłość jest z tobą, $N, ale w coraz niebezpieczniejszych czasach trzeba wiedzieć, jaka siła kryje się pod skórą. Gdy demony, smoki czy jakiekolwiek inne zło postawią stopę na twoich ziemiach, twój hart zostanie wystawiony na próbę. Czy będziesz $gdość silny:dość silna;?$B$BMęstwo, bez względu na okoliczności, jest częścią bycia paladynem w tym samym stopniu co Światłość, zbroja i broń. Ochrona słabych i niezachwiana wiara to dwie kolejne lekcje, które musisz opanować podczas nauki w Katedrze Światła.', 0),
(1798, 'koKR', '$N? Ach, oczywiście. Nasze najnowsze cudowne dziecko. Obawiam się, że żywy oryginał nie dorówna legendzie. $B$BMniejsza z tym, $gprzybyłeś:przybyłaś; tu się uczyć, a nie słuchać, jak żartuję sam do siebie.', 0),
(1861, 'koKR', 'Dziękuję, $N. Zbadam tę wodę pod kątem właściwości magicznych. Miejmy nadzieję, że żadnych nie ma, bo inaczej może się okazać, że ci, którzy zbyt długo piją z Lustrzanego Jeziora, odczują szkodliwe skutki.$B$BProszę, $N. Weź tę kulę albo kostur w dowód uznania za twoją służbę. Niech dobrze ci służy.', 0),
(1920, 'koKR', 'Świetna robota! Zbadam te stwory i przy odrobinie pilności i szczęścia ustalę, jak przedostały się do naszego świata.$B$BTwoja wartość dla społeczności magów rośnie, $N.', 0),
(1921, 'koKR', 'Tak, to świetne kawałki lnu. Uszyję z nich piękną szatę. A kiedy wplotę w nią klejnoty szczeliny, będzie to strój godny $gmaga:magini;!', 0),
(1938, 'koKR', 'Obawiałem się, że Morganth ukrył księgę gdzie indziej albo znalazł sposób, by ją otworzyć i przeczytać.$B$BDobrze, że tak się nie stało i że pieczęcie, którymi zabezpieczyliśmy Traktat Ura o magii cienia, wciąż trzymają.', 0),
(1939, 'koKR', 'Witaj, $N. Cieszę się, że cię widzę, i mam nadzieję, że znajdziesz czas, by wysłuchać słów starego człowieka...', 0),
(1940, 'koKR', 'Piękne okazy. Zaraz biorę się do pracy!', 0),
(1941, 'koKR', 'Oto twoja szata. To jedna z najlepszych, jakie dotąd uszyłam! Noś ją z dumą, a kiedy ktoś zapyta... powiedz, że masz ją z „Odzieży Larsona”!', 0),
(1942, 'koKR', 'Twój strój jest gotowy! A ten jedwab, który $gzebrałeś:zebrałaś;, był taki piękny... Nie masz nic przeciwko temu, że uszyłam go trochę za krótko, żeby zostało mi trochę jedwabiu dla siebie, prawda?$B$BTylko żartuję. Będzie na tobie świetnie leżał i nada się zarówno na przygody, jak i na uroczyste kolacje. Noś na zdrowie!', 0),
(1947, 'koKR', 'Cisza! Jestem w delikatnym momencie i nie wolno mi przeszkadzać!$B$BChwileczkę...', 0),
(1953, 'koKR', 'Ach, tak. $GPrzyszedłeś:Przyszłaś; po kulę czy po kostur, $N? Dobrze. Pomogę ci go wykonać.$B$BAle ostrzegam – to niebezpieczny proces, który może oznaczać twoją śmierć.$B$BAlbo moją. Na pewno czyjąś śmierć... $B$BAle miejmy nadzieję, że kogoś innego, co?', 0),
(2040, 'koKR', 'Dobra robota, $N. Dzięki tobie Gnomoregan jest o krok bliżej dnia wyzwolenia!', 0),
(2041, 'koKR', 'Przynosisz wieści z centralnego dowództwa?', 0),
(2206, 'koKR', 'Jestem zdumiony... zdumiony, że Keryn w końcu znalazła rekruta, w którym może tkwić materiał na prawdziwego łotra. Weź to ostrze, $N. Nadejdzie dzień, gdy znów zostaniesz $gwezwany:wezwana; do służby w WW:7. Doskonal swoje umiejętności, miej oczy szeroko otwarte, a to ostrze ostre.$B$BNie zobaczysz, jak nadchodzimy, ale poczujesz, gdy już się zjawimy...', 0),
(2260, 'koKR', '$GOdpowiedziałeś:Odpowiedziałaś; na wezwanie WW:7, $N, i $gprzybyłeś:przybyłaś; z dalekich brzegów, by wstąpić w nasze szeregi. Musisz się jednak jeszcze wiele nauczyć.', 0),
(2281, 'koKR', 'Ach, więc masz trochę za grube palce, co? Nie martw się, $N, z bardziej bezużytecznych złodziejaszków niż ty robiłem wytrawnych łotrów.', 0),
(2298, 'koKR', 'Zawsze dobrze mieć w naszych szeregach jednego z łotrów Hulfdana!', 0),
(2359, 'koKR', 'To by wyjaśniało, skąd te bezwolne sługi Nieskornych, które ty i Kearnen widzieliście przed wieżą, $N. Wyjaśniałoby też udział spółki Gitgeszeft w sprawach Nieskornych i dziwne transporty z Kniei Zmierzchu.$B$BWedług tej księgi trolle Zanzila z Doliny Cierniodławów odkryły sposób wskrzeszania umarłych za pomocą mikstur... a ściślej mówiąc: trucizny.$B$BBez gruntownej znajomości trucizn nie przydasz się WW:7, $N – zwłaszcza teraz, gdy przepis na nieumarłość mamy na wyciągnięcie ręki.', 0),
(2360, 'koKR', 'Mathias w końcu przysłał mi kogoś do pomocy, co? Cóż, mam nadzieję, że jest gotów usłyszeć złe wieści.', 0),
(2745, 'koKR', 'Co do...?! Nie skradaj się tak do mnie! I ścisz głos! Na Cień, czemu się do mnie podkradasz? Nie widzisz, że jestem zajęty, głupku jeden?$b$bJak to, co robię? Czekam, aż otworzy się kolejny Mroczny Portal, a jak myślisz, co robię? Mów, co masz do powiedzenia, i zmykaj... zanim strażnicy zauważą, że chowamy się razem w krzakach. Muszę dbać o reputację.', 0),
(2746, 'koKR', 'Świetnie się nadadzą, $N. Dobra robota.$b$bResztę sprzętu mam w plecaku... dzięki Światłości, że znajomy krawiec właśnie uszył mi jedwabną torbę. Kończyło mi się miejsce na cały ten sprzęt, który ze sobą noszę.$b$bZanim szpiegobot wejdzie do środka, ustalmy szczegóły, żebyś $gwiedział:wiedziała;, co masz robić.', 0),
(2758, 'koKR', 'Bardzo dobrze, $N! Słuchaj i ucz się.$B$BKowalstwo nigdy nie bierze się stąd! <Hank wskazuje na swój młot.>$B$BKowalstwo nigdy nie bierze się stąd! <Hank wskazuje na kowadło.>$B$BKowalstwo bierze się tylko stąd! <Hank wskazuje na swoje serce.>$B$BTeraz już wiesz, skąd bierze się kowalstwo.', 0),
(2759, 'koKR', 'Na kudły z grzbietu Czarnego Kopyta – wreszcie ktoś godny Zakonu Mithrilu!', 0),
(2861, 'koKR', 'Zgadza się. Mam kość niezgody z pewną trollicą. Kilka kości. Wszystkie jej kości!$b$bPomożesz mi?', 0),
(2923, 'koKR', 'Tak, to prawda. Techbot się zbuntował – zupełnie jak jakiś $c! Proszę, pomożesz mi?', 0),
(2928, 'koKR', 'To się świetnie nada, $N. Jeden żyrowiertłomatyczny wykopywacz naprawiony; zostało jeszcze 398.', 0),
(3000, 'koKR', 'Pozdrawiam cię i witam, $N.', 0),
(3630, 'koKR', 'Ach, oto ktoś, kto pragnie zgłębiać jedyną prawdziwą dyscyplinę inżynierii! Wybacz mi ten melodramat, $gprzyjacielu:przyjaciółko;. Choć nasze położenie wciąż jest rozpaczliwe, zawsze miło zobaczyć kolejnego inżyniera, który odpowiada na zew prawdziwej inżynierii!', 0),
(3636, 'koKR', 'Dziękuję ci, $N. Teraz Plaga dwa razy się zastanowi, zanim znów spróbuje zasilić swoje szeregi.$B$BNiech Światłość ci błogosławi.', 0),
(3681, 'koKR', 'Witaj w Katedrze Światła, $N.', 0),
(3765, 'koKR', 'Ach, więc to mój brat, Argos, cię przysłał? Wiem, że musisz być $gzmęczony:zmęczona; podróżą. Ale mamy wiele do omówienia.', 0),
(3787, 'koKR', 'Dziękuję, że $gprzybyłeś, znużony wędrowcze:przybyłaś, znużona wędrowczyni;! Pozwól, że się przedstawię – jestem Quintis Jonespyre, druid i pokorny sługa Malfuriona i Kręgu Cenariona. Moi towarzysze (generał Szandris Lunopióra i Protektorat – może o nas $gsłyszałeś:słyszałaś;) i ja chcieliśmy z tobą porozmawiać o pracy, którą wykonujesz dla Fandrala Jeleniorogiego w Darnassus.$B$BZanim przejdziemy dalej, chciałbym cię prosić, żeby nasza rozmowa została tylko między nami. Jeśli nie masz nic przeciwko, możemy kontynuować.', 0),
(3789, 'koKR', 'No proszę, $N... skoro ci powiedziano, że osobiście prowadzę te badania, z pewnością $gprzybyłeś:przybyłaś; tak szybko, jak tylko $gmogłeś:mogłaś;.$B$BSkoro już tu jesteś, słuchaj uważnie, gdy za pierwszym razem przedstawię ci szczegóły; nie mam ochoty się powtarzać.', 0),
(4181, 'koKR', 'No, $N, mądrze $gzrobiłeś:zrobiłaś;, szukając moich nauk! Byle ciamajda może zostać ekspertem od podstaw inżynierii – gnomy i ich napromieniowany dom, Gnomoregan, są na to dowodem. Ale żeby opanować dyscyplinę goblińskiej inżynierii, trzeba mieć tęgi umysł i pewną rękę (z naciskiem na PEWNĄ).$B$BNadstaw uszu, $N, a może się czegoś nauczysz.', 0),
(4485, 'koKR', 'Ach, $gwróciłeś:wróciłaś; do Katedry, $N. Dobrze. Ostatnio wiele się wydarzyło i jeśli okażesz się $ggodzien:godna;, poproszę cię o pomoc.$B$BWokół czyha wielu zdradzieckich wrogów. Będę potrzebował twojej pomocy, by ich powstrzymać.', 0),
(4486, 'koKR', 'Ach, $gwróciłeś:wróciłaś; do Katedry, $N. Dobrze. Ostatnio wiele się wydarzyło i jeśli okażesz się $ggodzien:godna;, poproszę cię o pomoc.$B$BWokół czyha wielu zdradzieckich wrogów. Będę potrzebował twojej pomocy, by ich powstrzymać.', 0),
(4738, 'koKR', 'Ach, przysłała cię Demisette. Dobrze. A zatem wieść dociera dość daleko, by znaleźć przyszłych uczniów. To mnie cieszy.$B$BTo typowe dla nas, $N, że trzymamy się razem bez względu na rasę. To szczególnie ważne, bo ci, z którymi najczęściej mamy do czynienia, nie przebierają w swojej złośliwości, jeśli nie zdołamy ich udobruchać albo należycie kontrolować.$B$BCzuję, że $gnauczyłeś:nauczyłaś; się już wielu rzeczy, i jeśli zechcesz, pomogę ci stworzyć narzędzia, które dopełnią twoje umiejętności.', 0),
(4765, 'koKR', 'Ach, więc to ty! Masz moją wdzięczność, $N. A... jeśli jeszcze nie wiesz... wdzięczność szlachcica z rodu Ridgewellów jest warta niemal tyle co królewski okup.', 0),
(4766, 'koKR', '$GPrzybyłeś:Przybyłaś; z Wichrogrodu? Wspaniale – wiem o pewnym dziele sztuki, dla którego Remington gotów byłby zabić, byle mieć je w swoim muzeum, ale wydobycie go nie będzie łatwe.$B$BI tu wkraczasz ty.', 0),
(4968, 'koKR', 'Ach, więc szukasz czegoś bardziej... namacalnego. W tym mogę ci pomóc, jeśli naprawdę jesteś $ggotów:gotowa;.$B$BMiło dla odmiany zobaczyć kogoś z nas, kto szuka większej mocy w innej postaci niż sama wiedza.$B$BCzy więc czujesz, że jesteś $ggotów:gotowa;, $N?', 0),
(5022, 'koKR', 'Paczka dla niejakiej Emmy Felstone, mówisz? Ostatni znany adres to Wichrogród, cztery lata temu? No to zobaczmy...$B$BZ tego, co wiemy, jakieś cztery lata temu mieszkała w mieście niejaka Emma Felstone. A raczej powinienem powiedzieć: być może – spis, o którym mówię, pochodzi sprzed pięciu lat i nie mam żadnej informacji, żeby wyprowadziła się z miasta. Nie znaczy to jednak, że wciąż tu jest.$B$BChwileczkę... czy ta paczka nie jest przypadkiem dla Starej Emmy?', 0),
(5048, 'koKR', 'Tak, naprawdę nazywam się Emma Felstone – jesteś pierwszą osobą od lat, która tak mnie nazwała. Kim... kim ty jesteś?$B$BMówisz, że $gznałeś:znałaś;... moją siostrę?! Czy ona jeszcze żyje? Kogo ja oszukuję, oczywiście, że nie. Kiedy w Lordaeronie wybuchła zaraza, spodziewałam się najgorszego. Tylu z mojej rodziny umarło... albo gorzej. A teraz jestem tutaj, zwariowana Stara Emma, zupełnie sama. Kim ty jesteś, jakąś hieną cmentarną czy co? Szukasz kolejnego celu?$B$BCo... masz dla mnie paczkę od mojej siostry?', 0),
(5050, 'koKR', 'Oddajesz połówkę amuletu zjawie. Ta patrzy na nią, a potem wyczekująco na ciebie.$B$B„Kochanie, gdzie podziałeś swoją połówkę amuletu? Nie możemy być razem, jeśli nie mamy obu połówek. Kochanie... widzisz mnie?”', 0),
(5066, 'koKR', 'Witaj na Plagowiskach, $gbohaterze:bohaterko;. To jedna z najniebezpieczniejszych rubieży Azeroth, zwłaszcza że Plaga czyha na północy i północnym wschodzie. Cieszę się, że donośny zew obowiązku i służby wyższemu dobru nie trafił w twoim przypadku w próżnię!$B$BJeśli nie boisz się pobrudzić sobie rąk, tu, na skraju Plagowisk, jest mnóstwo pracy dla chętnych i zdolnych bohaterów.', 0),
(5924, 'koKR', 'Cieszę się, że $gtrafiłeś:trafiłaś; tu dzisiaj, $N. Nadszedł czas, byś $gzrobił:zrobiła; wielki krok w znacznie większy świat.$B$BW każdym z dzieci Cenariusa tkwi powołanie do służby naturze. Zwierzęta i rośliny są naszymi przyjaciółmi, a zarazem podopiecznymi. Postanawiamy poświęcić życie strzeżeniu równowagi – przez wzgląd na nie, ale i na nas samych. Twoim pierwszym krokiem w ten świat będzie poznanie ścieżek niedźwiedzia oraz siły ciała i serca.$B$BPrzygotuj się!', 0),
(6073, 'koKR', 'Tak, nadszedł czas, $N.', 0),
(6076, 'koKR', 'Tak, sądzę, że ty też jesteś $ggotów:gotowa;...', 0),
(6141, 'koKR', 'Dotarła do mnie wieść o pomocy nadciągającej ze wschodu. Czy to ty jesteś źródłem tych pogłosek? $GPrzybyłeś:Przybyłaś; tu, by pomóc Szkarłatnemu Bractwu w jego krucjacie?$B$BJeśli tak, słuchaj uważnie...', 0),
(6182, 'koKR', 'Po doniesieniach o nietypowej aktywności Porzuconych na Wschodnich Plagowiskach wysłano tam agentów WW:7, by zbadali sprawę. Wyniki tego śledztwa są niepokojące.', 0),
(6183, 'koKR', '<Mathias kiwa głową.>$B$BWierzyłem, że Wrynn przyśle mi ludzi honoru – najbardziej oddanych żołnierzy Przymierza.', 0),
(6184, 'koKR', 'Pierwsza misja będzie prosta, $N. Wchodzisz, wychodzisz. Zwiad...', 0),
(6186, 'koKR', 'Nie. To... NIE! Jak? Agent Porzuconych? CZEMPION Królowej Banshee???$B$B<Król Varian Wrynn osuwa się, pokonany.>', 0),
(6187, 'koKR', 'To tragedia. Myślę... wierzę, że nasz ród jest przeklęty, $N. Przeklęty, byśmy tracili naszych największych wojowników, naszych najszlachetniejszych bohaterów, naszych najzdolniejszych uczonych.$B$BJesteśmy twoimi dłużnikami i zapewniam cię, $N, że gdziekolwiek jest teraz Nathanos Marris, uśmiecha się do ciebie z góry.', 0),
(6261, 'koKR', 'Skrzynia do Zachodniego Skraju, co? $GByłeś:Byłaś; już kiedyś w Zachodnim Skraju? Jeśli tak, to żaden problem, $gprzyjacielu:przyjaciółko;. Mam mnóstwo gryfów wyszkolonych do latania na tej trasie!', 0),
(6281, 'koKR', 'Ach, liścik od kwatermistrza Lewisa? Nie dziwi mnie, że potrzebuje więcej sprzętu. Wzgórze Strażnicze jest daleko, w krainie, o której Wichrogród niemal zapomniał.$B$BCóż, dziękuję, $N. Oto trochę pieniędzy na pokrycie kosztów podróży.', 0),
(6285, 'koKR', 'Świetnie, $gprzyniosłeś:przyniosłaś; zbroje! Od razu rozdzielimy je między potrzebujących.$B$BDziękuję, $N. Twoje starania bardzo nam pomogły. A skoro gryfy nie są ci już obce, mam nadzieję, że często będziesz $gprzylatywał:przylatywała; z pomocą na Wzgórze Strażnicze!', 0),
(6402, 'koKR', 'Zanim zaczniemy, proszę, zbierz najpierw armię. W końcu stawimy czoła smokowi!', 0),
(6403, 'koKR', '<Bolvar trzyma strzaskany medalion.>$B$BZawarta w nim magia musi zostać na nowo rozniecona. Smocze oko musi zostać dostrojone.$B$BPoświęcenie Windsora uwolniło nasze królestwo, ale zagrożenie ze strony Onyxii i jej pobratymców wciąż nad nami wisi.$B$BTo ten medalion więził mój umysł i ciało. To on dał mi też dostęp do umysłu samej Onyxii – do jej tajemnic. Choć wizje są teraz mętne, niektóre rzeczy pamiętam.', 0),
(6501, 'koKR', 'No tak – kawałek matki Czarnego Stada, Onyxii. Jakież to odrażające...', 0),
(7494, 'koKR', 'Witaj, $N. Cieszę się, że cię widzę, ale żałuję, że nie spotykamy się w przyjemniejszych okolicznościach.$B$BSłuchaj uważnie, bo mam dla ciebie niezwykle ważne zadanie...', 0),
(7495, 'koKR', 'Przez tyle lat więziło mnie jej urzekające spojrzenie. Wreszcie sprawiedliwości stało się zadość, a honor Wichrogrodu został przywrócony! Dziś świętujemy to chwalebne zwycięstwo!', 0),
(7496, 'koKR', 'Niewielu dostępuje zaszczytu takiej ceremonii, $N. Proszę, wybierz nagrodę, abyśmy mogli rozpocząć świętowanie.', 0),
(7497, 'koKR', '$GPogromca smoków i doświadczony garbarz:Pogromczyni smoków i doświadczona garbarka;? Nie przestajesz zadziwiać, $gbohaterze:bohaterko;. Czuję się zaszczycony.$B$BProszę, przyjmij to, czego zaraz cię nauczę. Ta wiedza okaże się bezcenna, jeśli chcesz zniszczyć to, co zostało z Czarnego Stada smoków.$B$BWykonaj płaszcz z łusek matki stada. Ochroni on ciebie i twoich sojuszników przed ognistym oddechem Władcy Czarnej Góry... Nefariana.', 0),
(7562, 'koKR', 'Witaj, $N, rozgość się. Czy $gprzybyłeś:przybyłaś;, by tak jak ja prowadzić badania przy Ołtarzu Burz, może by wykorzystać jego energię do jakiegoś ukrytego celu...$B$BA może... $gprzybyłeś:przybyłaś; porozmawiać ze mną? Tak, chyba tak.$B$BChcesz zapanować nad upiornym rumakiem? To niełatwe zadanie. Będzie cię to kosztować niemało krwi, potu... i oczywiście złota. Ale upiorny rumak z Xoroth to nagroda warta zachodu, więc jeśli cię to interesuje, słuchaj dalej...', 0),
(7637, 'koKR', 'Błogosławieństwo z tobą, $N! Twój datek znacznie przewyższa to, czego było trzeba. Twoje poświęcenie nie tylko pomoże nam odzyskać to, co straciliśmy, ale też pozwoli nam pomóc najbardziej potrzebującym tu, w Żelaznej Kuźni.$B$BA teraz pozwól, że upewnię się, iż należycie przygotowałem tę kadzielnicę na twoje przyszłe potrzeby...', 0),
(7638, 'koKR', 'Cieszę się, że cię widzę, $N. Wiem, że $gczekałeś:czekałaś; na wieść, jak zdobyć swojego szarżownika, i oto nadeszła ta chwila.$B$BZ pewnością czeka cię wiele różnych prób, ale przede wszystkim sprawdzą one twoją gotowość do pokonywania licznych przeszkód, jakie staną ci na drodze. Nie są to ćwiczenia – twoja pozycja wykracza poza zwykłe sprawdziany. Musisz ocalić swojego przyszłego towarzysza ze szponów zła, z którym $gwalczyłeś:walczyłaś; przez całe życie.$B$BBacz uważnie – twój czas nadszedł!', 0),
(7639, 'koKR', 'Tak, to się nada. Podczas tej drogi nieraz zostaniesz $gwezwany:wezwana; do aktów poświęcenia; cieszę się, że jesteś na nie $ggotów:gotowa;. Poświęcenie jest kluczowym elementem tego, czego wymaga wypełnianie obowiązków paladyna... ale nie muszę ci tego wykładać.$B$BA teraz, $N, musisz wykazać się należytym osądem w swoich czynach. W tym celu ta kadzielnica posłuży ci za naczynie, przez które wymierzysz osąd udręczonym duchom z utraconych przez nas ziem.', 0),
(7640, 'koKR', 'Dobra robota, $N. Wydawanie osądu Światłości na tych, którzy żyją w ciemności, to zadanie, do którego trzeba podchodzić z werwą i żarliwością – i właśnie tak $gpostąpiłeś:postąpiłaś;, składając ofiarę w Żelaznej Kuźni i osądzając duchy w Dolinie Grozy.$B$BTwoje kolejne kroki znów będą wymagały poświęcenia i osądu, bo teraz spróbujesz odzyskać ducha poległego szarżownika, który służy obecnie rycerzowi śmierci zwanemu Mrocznym Łupieżcą.', 0),
(7641, 'koKR', 'Witaj – lord Cieniołamacz uprzedził mnie, że się tu do mnie wybierasz. Chętnie wykonam zbroję, której potrzebujesz, ale nie będzie to ani tanie, ani łatwe; niech to będzie jasne od samego początku.$B$BPowiem tylko tyle, a Grayson to potwierdzi: w całym Azeroth nie znajdziesz lepszej zbroi końskiej niż ta wykonana właśnie tutaj.', 0),
(7642, 'koKR', 'To... cóż, to dokładnie to, czego potrzebowałem. Ale z ciebie $gzaradny:zaradna;, prawda?$B$BNo dobrze, dokończmy tę zbroję!', 0),
(7643, 'koKR', 'Pradawny duch konia przyjmuje ofiarę z paszy dla koni wzbogaconej manną i trąca pyskiem pojemnik, częstując się specjalnym owsem i ziarnem. Gdy już trochę zje, spogląda na zbroję, którą masz przy sobie, i ustawia się tak, jakby chciał, żebyś $gpołożył:położyła; mu ją na grzbiecie...', 0),
(7644, 'koKR', '$GPrzebyłeś:Przebyłaś; długą drogę, $gprzyjacielu:przyjaciółko;. Twoja zbroja jest już odpowiednio przygotowana do ostatniego zadania.$B$BUżyjesz jej, by okiełznać swojego szarżownika, gdy dzieło odkupienia zostanie dokonane. Wcześniej jednak czeka cię ogromna walka. Twój czas się zbliża – hura!$B$BZanim zaczniemy, trzeba wykonać jeszcze jedną rzecz, $N. Mam nadzieję, że zaradność cię nie opuściła, odkąd $gzamówiłeś:zamówiłaś; swoją zbroję...', 0),
(7646, 'koKR', 'To wspaniałe okazy, $N – ostatnie elementy są już na miejscu. Wreszcie nadszedł twój czas!$B$BW głębinach Wielkiego Ossuarium w Scholomancjum spoczywają szczątki wielu istot. Wśród nich jest niegdyś szlachetny szarżownik. Wydrążona dusza tego szarżownika służy teraz za wierzchowca rycerzowi śmierci Mrocznemu Łupieżcy. To z nim się zmierzysz i to na tego wierzchowca wydasz osąd. Tylko ty, $N, możesz odkupić jego duszę i uwolnić go od męki niewoli.', 0),
(7647, 'koKR', 'Gdy oddajesz biednemu zwierzęciu jego osądzoną duszę, w jego oczach błyska iskra życia, której od dawna w nich nie było. Kiedy kładziesz mu zbroję na grzbiet, uznając szarżownika za odkupionego, czujesz, jak otacza cię przypływ świętej mocy. Szarżownik trąca pyskiem twoją dłoń, a brzemię przeszłości spada z jego barków. Czujesz, że w razie potrzeby możesz go przywołać, by służył ci jako wierzchowiec.$B$BZdobywasz swojego epickiego szarżownika, $N! Gratulacje!', 0),
(7648, 'koKR', 'To naprawdę imponująca robota. Wygląda na to, że z wiekiem kunszt Grimanda tylko rośnie. To nie lada wyczyn, skoro już wtedy, gdy przed laty robił moją zbroję, jego prace należały do najlepszych, jakie można było znaleźć.$B$BTa zbroja byłaby wspaniałym nabytkiem dla każdego zwykłego wierzchowca, ale my nie mamy do czynienia z tak pospolitym zwierzęciem. Zbroja musi zostać pobłogosławiona przez odpowiednie źródło, by była godna spocząć na szarżowniku paladyna. Do tego czasu przechowam ją dla ciebie.', 0),
(7666, 'koKR', 'Wybierasz się z powrotem do Scholomancjum, $N? $GZapłaciłeś:Zapłaciłaś; już tak wysoką cenę za użycie wróżbiarskiej kuli – może chcesz zabrać ze sobą kolejną. Dzięki niej znów zmierzysz się z niebezpieczeństwami Wielkiego Ossuarium.$b$bOczywiście, weź ją. Z pewnością na nią $gzasłużyłeś:zasłużyłaś;.', 0),
(7670, 'koKR', 'Cieszę się, że cię widzę, $N. Wiem, że $gczekałeś:czekałaś; na wieść, jak zdobyć swojego szarżownika, i oto nadeszła ta chwila.$B$BZ pewnością czeka cię wiele różnych prób, ale przede wszystkim sprawdzą one twoją gotowość do pokonywania licznych przeszkód, jakie staną ci na drodze. Nie są to ćwiczenia – twoja pozycja wykracza poza zwykłe sprawdziany. Musisz ocalić swojego przyszłego towarzysza ze szponów zła, z którym walczysz przez całe życie.$B$BBacz uważnie, twój czas nadszedł!', 0),
(7781, 'koKR', 'Nie trzeba ci mówić, co znaczy twój czyn, $N. Ten dzień zostanie zapisany w annałach historii. Takiego zwycięstwa Przymierze nie znało od lat – o ile w ogóle!', 0),
(7782, 'koKR', '<Feldmarszałek Afrasiabi kłania się.>$B$BWybierz nagrodę i niech zacznie się świętowanie!', 0),
(7791, 'koKR', 'Wspaniale! Dziękujemy za twój hojny dar, $N!', 0),
(7793, 'koKR', 'Wspaniale! Dziękujemy za twój hojny dar, $N!', 0),
(7794, 'koKR', 'Wspaniale! Dziękujemy za twój hojny dar, $N!', 0),
(7795, 'koKR', 'Fantastycznie – zapewniam cię, że od razu zrobimy z tego użytek. Jeszcze raz dziękuję za pomoc! Bez ciebie z pewnością byśmy sobie nie poradzili.$b$bSkoro tyle już $gofiarowałeś:ofiarowałaś;, chętnie przyjmę każdy kolejny dar runicznej tkaniny, jaki zechcesz przekazać w przyszłości. Wystarczy, że się do mnie zgłosisz, a osobiście dopilnuję, by twoje dobre uczynki nie przeszły bez echa!', 0),
(7796, 'koKR', '$N – bez takich bohaterów jak ty, działających na rzecz plemienia, z pewnością byśmy cierpieli. Dziękuję za twoje nieustające starania!', 0),
(8151, 'koKR', 'Moim przeznaczeniem nie jest już polowanie, lecz nauczanie łowców. Tak zrządził los.$B$BStwórz ze mną urok łowcy – zbiór trofeów z upolowanej zwierzyny, który będzie ci przypominał o dawnych próbach i triumfach. Na koniec zatrzymam urok, ale nagrodzę cię czymś innym.', 0),
(8233, 'koKR', 'Witaj, witaj, witaj! Proszę, $N, usiądź i omów ze mną pewną prostą sprawę.$B$BWidzisz, $N, niedawno straciłem coś, co jest mi drogie, i mówiąc wprost, chcę to odzyskać za wszelką cenę. Ty też coś na tym zyskasz, nie martw się! O tak, coś bardzo miłego.$B$BCo ty na to, $N... masz ochotę na przygodę?', 0),
(8250, 'koKR', '<Sanath szydzi z ciebie.>$B$BArcymag Xylem oczekuje twojego przybycia.', 0),
(8254, 'koKR', 'Twoje przybycie zdjęło mi ciężar z ramion. Mamy wiele do zrobienia.', 0),
(8356, 'koKR', 'Ale z ciebie $gsiłacz:siłaczka;, haha! Brawo i dzięki, że dajesz się wciągnąć w zabawę. Oto twoje cukierki.$B$BWesołych Zaduszników, $N!', 0),
(8410, 'koKR', 'Dobrze jest, dobrze. Teraz to se pogadamy.', 0),
(8415, 'koKR', 'Dobrze, $N! Zobaczmy, na co cię stać.', 0),
(8417, 'koKR', 'A więc $gprzybyłeś:przybyłaś;, by ulżyć mojemu cierpieniu. Wolałbym, żebyś po prostu mnie $gpowalił:powaliła;, ale to nie takie proste...', 0),
(8419, 'koKR', 'Cóż za $gwspaniały:wspaniała; z ciebie czarnoksiężnik!$B$B<Chochliś przykłada spaczoną tkaninę do twarzy.>$B$BOch, jak ja kocham jej dotyk, to, jak pali skórę i wplata w umysł złe myśli...', 0),
(8860, 'koKR', 'Och, moje zapasy od Wędzonych Pastwisk! Wspaniale! Będą mi potrzebne, żeby nakarmić wszystkich ludzi w mieście podczas świętowania!$B$BDziękuję, $N. Przyjmij to jako zapłatę i nie zapomnij wypić i potańczyć z biesiadnikami na zewnątrz!', 0),
(9026, 'koKR', 'O tak, perfumy i wodę kolońską dostałam niedawno. Tak dobrze się sprzedają, że nie wiem, jak długo jeszcze utrzymam je na półkach.$B$BJak dla mnie, to trochę nudne. Wszyscy pachną tak samo? Zapach jest świetny, ale jednak.', 0),
(9063, 'koKR', '$GPrzebyłeś:Przebyłaś; długą drogę, by się ze mną spotkać, $N, i w samą porę.', 0),
(9429, 'koKR', 'Witaj, $N. Mam nadzieję, że podróż minęła ci spokojnie?$B$BTe biedne dusze są osaczone ze wszystkich stron przez stworzenia nocy. Pragniemy, byś w miarę swoich możliwości $gpomógł:pomogła; im odeprzeć ciemność.$B$BPrzejdź się po miasteczku i poznaj jego mieszkańców. Proszę, $N, pomóż im, jak tylko możesz.', 0),
(9757, 'koKR', 'Zacznijmy lekcję od razu!', 0),
(10490, 'koKR', 'Znów się spotykamy. Obserwowałem z daleka twoje postępy, $N, i jestem zadowolony.$B$BNadszedł czas, byś $gwszedł:weszła; w łączność z żywiołem wody, $gpoznał:poznała; jego tajemnice i $goddał:oddała; się wodzie, by w zamian nauczyć się nad nią panować.', 0),
(10491, 'koKR', 'I wreszcie dotarliśmy do ostatniego z czterech wielkich żywiołów: powietrza. Czy uważasz się za dość $gmądrego:mądrą;, by iść dalej, $N?', 0),
(11451, 'koKR', 'Jaki wzruszający wiersz, dziękuję!', 0),
(12774, 'koKR', 'A więc święci ludzie z Shattrath stworzyli to, co obiecali! Z perspektywy czasu wysłanie tam tylu kapłanów i paladynów, zamiast rzucić ich przeciw Pladze, okazało się słusznym posunięciem. Z tą świętą bronią odeprzemy tego przeklętego Króla Lisza i jego sługi!$b$bWyrazy uznania, $glordzie:lady; $N.', 0),
(13188, 'koKR', '<Varian patrzy w dal.>$B$BW rzeczy samej, stary przyjacielu... Krew i honor.$B$B<Varian wbija w ciebie wzrok.>$B$BGdyby nie ten list od Tiriona, $gbyłbyś:byłabyś; już plamą na mojej posadzce. Tylko poręczenie jednego z najwspanialszych paladynów, jacy kiedykolwiek żyli, mogło ocalić ci życie.$B$BMy... będziemy razem walczyć z Plagą. Z Królem Liszem!$B$BCHWAŁA PRZYMIERZU!', 0),
(13347, 'koKR', 'Smocza Królowa ma rację, $N. Nie wszystko stracone. To ja będę siłą, która powstanie z popiołów, i to ja oczyszczę ten świat ze zła Hordy. Nasi bracia i siostry nie zginęli na próżno.', 0),
(13369, 'koKR', 'Horda nie chce wojny. Słuchaj uważnie...', 0),
(13370, 'koKR', 'Stracili Podmiasto? W takim razie pora uderzyć. Sami rozprawimy się z Putressem i odbijemy Ruiny Lordaeronu dla Przymierza!', 0),
(13371, 'koKR', 'A ty to niby kto? Varian mówił, że przyśle bohaterów.', 0),
(13377, 'koKR', 'Zbyt długo pozwalaliśmy Hordzie robić, co chce. Pozwoliliśmy jej ziemiom rozkwitać, a ona w zamian za naszą szczodrość knuła i planowała naszą zgubę.$b$bPokój? Bezużyteczny... Nic nam nie dał. Straciliśmy przez „pokój” kilku naszych największych bohaterów. Zobaczmy, co przyniesie wojna...$b$bWracaj do Północnej Grani, $N. Podbij ją dla swojego króla – ZA PRZYMIERZE!', 0),
(14111, 'koKR', 'Widzę, że $gopanowałeś:opanowałaś; użycie czterech totemów. Jesteś na drodze do zjednoczenia z duchami żywiołów, ale to dopiero początek twojej podróży.$b$bProszę, przyjmij ten dar od Kręgu Ziemi. Noś tę relikwię przy sobie, a moc wszystkich czterech żywiołów będzie na twoje rozkazy.$b$bTwoje szkolenie musi trwać! Czuję, że przed tym światem stoi wiele prób, a jeśli mamy zwyciężyć, będziemy potrzebować wsparcia mocy żywiołów.', 0),
(24427, 'koKR', 'Właśnie to chciałem usłyszeć! Zwycięstwo w Dolinie Alterak – nawet chwilowe – ma kluczowe znaczenie dla całej naszej strategii przeciw Hordzie.', 0),
(24428, 'koKR', 'Co? Skąd to masz? Czy ona nie jest... Mniejsza o szczegóły. Pewnie zechcesz w nagrodę jedno z tych świecidełek.', 0),
(24597, 'koKR', 'Dziękuję za tę uroczą bransoletkę z talizmanami.', 0),
(25180, 'koKR', 'Czemu Młot Zmierzchu interesuje się tymi tablicami? Sam Brann napisał, że ledwie rozumie ich znaczenie, choć wspomniał coś o stawaniu się jednym z ziemią. Muszę naradzić się z uczonymi z Ligi Odkrywców, żeby jak najszybciej je odczytać.$B$BDziękuję, $N. Gdyby nie twoja pomoc, te tablice wpadłyby w ręce wroga.', 0),
(25181, 'koKR', 'Czemu Młot Zmierzchu interesuje się tymi tablicami? Ich treść jest zagadką dla naszych najtęższych uczonych, a odczytanie ich zajmie trochę czasu. Skoro Młot Zmierzchu wie o tych reliktach i ich pragnie, co jeszcze knuje?$B$BMamy wielkie szczęście, że $guchroniłeś:uchroniłaś; je przed wrogiem, $N.', 0),
(25253, 'koKR', '<Anton przegląda zebrane przez ciebie zwoje.>$B$BKtokolwiek przygotował te ulotki, wie, jak przyciągnąć uwagę, a sądząc po tym, co się dzieje na Starym Mieście, zainteresowania nie brakuje. Musimy działać, zanim zdobędą w mieście liczne grono zwolenników. Obawiam się, że wykorzystają swoje wpływy, by siać panikę w całym mieście i nas sparaliżować.$B$BMusimy przeniknąć do tej organizacji i dowiedzieć się jak najwięcej.', 0),
(25282, 'koKR', 'Dobra robota, $N. Teraz musimy się skupić na tym, by dowiedzieć się więcej o tym kulcie i uwolnić ludzi, których podstępem nakłonił do przyłączenia się.', 0),
(25290, 'koKR', 'Witaj, $gprzyjacielu:przyjaciółko;. To dla nas zaszczyt, że $gpostanowiłeś:postanowiłaś; przyjąć prawdę i do nas dołączyć. Chodź, na rozmowy przyjdzie jeszcze czas, a musisz się wiele nauczyć.', 0),
(25414, 'koKR', 'Więc ich $gznalazłeś:znalazłaś;? Dlaczego zaginieni mężczyźni i kobiety nie wrócili z tobą?$B$B<Mówisz kapitanowi, że z różnych powodów byli zdecydowani zostać.>$B$BW takim razie nie możemy zmusić ich do powrotu do domu. Mogę tylko mieć nadzieję, że z czasem kultyści zrozumieją, jaką krzywdę wyrządzają, i postanowią wrócić do normalnego życia.$B$BDziękuję za twoje starania, $N. Powiem rodzinom, czego się $gdowiedziałeś:dowiedziałaś;.', 0),
(25417, 'koKR', '<Wręczasz kapitanowi Antonowi urządzenia, które dała ci nadzorczyni, i wyjaśniasz plany kultu.>$B$BTo Cho\'gall przewodzi kultowi? W takim razie to musi być Młot Zmierzchu! Podejrzewaliśmy, że spróbują uderzyć znowu, ale nikt nie wiedział, jaką formę przybierze atak.$B$BŚwietnie się $gspisałeś:spisałaś;, demaskując ten spisek. Niestety nie tylko ciebie wysłano do miasta, by rozmieścić te urządzenia.', 0),
(25418, 'koKR', 'Doskonała robota, $N. Młot Zmierzchu zastanowi się dwa razy, zanim znów spróbuje obrócić przeciw nam naszych własnych ludzi.$B$BNiepokoi mnie tylko, ilu mieszkańców przyłączyło się do ich ruchu, nie zastanawiając się nad pustymi obietnicami kultu. Czy czasy są aż tak ciężkie, że ludzie porzucają Światłość dla obietnic mocy i nieśmiertelności?', 0),
(25425, 'koKR', '<Na twarzy króla maluje się niepokój, a potem gniew, gdy opisujesz spisek Młota Zmierzchu, który miał zniszczyć Wichrogród.>$B$BJak śmią atakować Wichrogród? Jak śmią podburzać mieszkańców tego miasta przeciw nam i Przymierzu! Gdyby nie twoje męstwo tego dnia, $N, nasze miasto nie odkryłoby tego spisku Młota Zmierzchu. Jesteś $gprawdziwym bohaterem:prawdziwą bohaterką; Wichrogrodu i Przymierza.', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(120, 'koKR', 'Co tam masz?', 0),
(121, 'koKR', 'Czy generał przysłał wieści? Czy posiłki są w drodze?', 0),
(135, 'koKR', 'Jaką masz do mnie sprawę? Jestem bardzo zajętym człowiekiem...', 0),
(141, 'koKR', 'Czy mistrz Shaw rzucił na tę sprawę jakieś światło?', 0),
(167, 'koKR', '$GZnalazłeś:Znalazłaś; jakiś ślad mojego brata? Czy po tak długim czasie jest jeszcze jakaś nadzieja?', 0),
(168, 'koKR', 'Udało ci się odzyskać legitymacje Związku Górników moich dawnych towarzyszy z pracy?', 0),
(171, 'koKR', 'Miło cię znowu widzieć, $N. Czy $gwywiązałeś:wywiązałaś; się z obowiązków, których $gpodjąłeś:podjęłaś; się w Tygodniu Dziecka?', 0),
(212, 'koKR', '$N! Masz ten udziec? Muszę wkrótce zacząć go przyrządzać, bo inaczej bankiet będzie zrujnowany!', 0),
(269, 'koKR', 'Odpocznij, $gbracie:siostro;. Widzę, że $gprzebyłeś:przebyłaś; długą drogę i dźwigasz ciężkie brzemię. Powiesz mi, co rzuca na ciebie ten mroczny cień?', 0),
(293, 'koKR', 'Co to za kula? Wygląda na... splugawioną.', 0),
(322, 'koKR', 'W czym mogę ci służyć swoim rzemiosłem, $N?', 0),
(325, 'koKR', 'Witaj, $N. Nie było cię niedługo, ale widzę w twoich oczach ogień, którego wcześniej nie widziałem.', 0),
(332, 'koKR', 'Witaj, $N, rozgość się. $GPróbowałeś:Próbowałaś; już któregoś z naszych wybornych win?', 0),
(333, 'koKR', 'Masz wieści od pana Bagleya?', 0),
(334, 'koKR', '$GPrzyszedłeś:Przyszłaś; kupić ubrania?', 0),
(335, 'koKR', 'Wishock wkrótce zbierze dość poparcia, by narobić nam mnóstwo kłopotów. Udało ci się już zdobyć Łzę Tilloi albo korzeń piżmaka?', 0),
(336, 'koKR', 'Nie widzisz, że jestem zajęty? Moje słowa muszą zostać wysłuchane! Jestem bardzo ważny dla przyszłości tego królestwa!$B$BO... a co ty tam masz? Ależ to wygląda na orzeźwiający napój...', 0),
(337, 'koKR', 'Ooo! Co to za stara księga? Mogę ją zobaczyć??', 0),
(353, 'koKR', '$GPrzybyłeś:Przybyłaś; aż z Wichrogrodu? Słyszałem, że na ludzkich ziemiach robi się niebezpiecznie – wszędzie grasują rozbójnicy i orkowie. Idealne miejsce, by $c $gmógł:mogła; się wykazać!', 0),
(373, 'koKR', 'Tak? Mogę ci w czymś pomóc?', 0),
(387, 'koKR', 'Kazamaty wciąż są w rękach więźniów! Te szczury z Nieskornych muszą się przekonać, że nie będziemy tolerować ich wybryków. Wracaj tam na dół i pokaż im siłę!', 0),
(388, 'koKR', 'Widzę, że $gwróciłeś:wróciłaś;, $N. $GZebrałeś:Zebrałaś; już 10 czerwonych wełnianych chust od tych szumowin z Nieskornych w Kazamatach?', 0),
(391, 'koKR', 'Albo przyniesiesz mi głowę Thredda, albo ja wezmę twoją, rozumiesz, $N?', 0),
(392, 'koKR', 'Tak, $N? Co $gznalazłeś:znalazłaś;?', 0),
(393, 'koKR', 'Witaj. W czym mogę ci służyć, $N?', 0),
(396, 'koKR', '$N, tak? Baros Alexston zapowiedział mi twoje przybycie. Muszę przyznać, że bardzo mnie ciekawi, co masz do powiedzenia.', 0),
(399, 'koKR', '$N! Udało się?', 0),
(434, 'koKR', 'Tak, $N? Wszystko idzie dobrze z Tyrionem? Wprowadził mnie w sytuację, a ja pomogłem mu podstępem ściągnąć Marzona do zamku.$B$BMarzon był solą w oku wielu ludzi w Wichrogrodzie, a spośród nich wielu to moi bliscy przyjaciele. Nikt nie zadziera z moimi przyjaciółmi... jeśli wie, co jest dla niego zdrowe.$B$BSzkoda tylko, że przy okazji pośrednio wyświadczam przysługę Shawowi i WW:7. Cóż, żaden plan nie jest idealny.', 0),
(540, 'koKR', 'Chciałbym sam przeszukać ruiny, ale obawiam się, że te stare kości nie wytrzymałyby wspinaczki w góry. Jak idą twoje poszukiwania wiedzy, $N?', 0),
(542, 'koKR', '$N, $gwróciłeś:wróciłaś;! Jak ci poszła wyprawa do Alterak? $GPrzyniosłeś:Przyniosłaś; coś ze sobą?', 0),
(543, 'koKR', 'Uszanowanie, $N. Postaraj się nie deptać mi po mankietach spodni. Ten strój jest świeżo uszyty.', 0),
(563, 'koKR', 'Witaj, $gobywatelu:obywatelko;. W czym może ci pomóc straż miejska Wichrogrodu?', 0),
(579, 'koKR', 'Król Varian przywiązuje wielką wagę do nauki, dlatego przeznaczył fundusze na sporządzanie kopii rozmaitych ksiąg i pism, które udostępniamy wszystkim mieszkańcom. To bardzo proste. Przynosisz mi kwit biblioteczny, a ja daję ci kopię jednej z dostępnych książek.', 0),
(697, 'koKR', 'Tak? Wyglądasz jakoś znajomo. Najmocniej przepraszam, ale czy myśmy się już spotkali? Mam tyle zajęć, że wszystko mi się myli.', 0),
(1076, 'koKR', 'Witaj, $N. $GZnalazłeś:Znalazłaś; składnik, którego potrzebuję?', 0),
(1077, 'koKR', 'Haha! Jesteś z powrotem! Masz to? Masz zaklęcie?', 0),
(1078, 'koKR', 'Witaj ponownie, $N.$B$BCzyżbyś już $gwrócił:wróciła; ze Zwęglonej Doliny z tymi łuskami?', 0),
(1241, 'koKR', 'Hmpf, lepiej, żebyś $gmiał:miała; dobry powód, by przeszkadzać człowiekowi w łowieniu ryb. Nie przepadam za domokrążcami, a co dopiero za żebrakami.', 0),
(1242, 'koKR', 'Witaj, $N. Czym mogę służyć? Może skosztujesz naszego specjalnego cheddara od Triasa? Albo kostki darnasyjskiego sera pleśniowego?', 0),
(1243, 'koKR', 'Wędrówki po tych lasach nie są zbyt bezpieczne, $N. Uważaj na siebie, a jeśli zobaczysz coś podejrzanego albo groźnego, natychmiast daj znać wartownikom. Nie próbuj niczym zajmować się na własną rękę. Nie odpowiadamy za nic złego, co może cię spotkać.$B$BAle przecież wiemy, że i tak mnie zignorujesz i będziesz walczyć ze wszystkim, co wylezie z ciemności, prawda? Haha, no tak, wy, poszukiwacze przygód... wszyscy jednacy.', 0),
(1244, 'koKR', 'Uważaj na siebie, $N. Wiem, że to Trias cię tu przysłał, ale to nie znaczy, że w lasach nie czai się nic, co mogłoby ci narobić kłopotów... zwłaszcza że węszysz wokół Nieskornych.', 0),
(1245, 'koKR', 'Widzę, że $gwróciłeś:wróciłaś; w jednym kawałku. Dobrze wiemy, że nie przychodzisz tu po ser, więc darujmy sobie uprzejmości. Czy Backus na coś się przydał, czy może jeszcze nawet nie $gwyruszyłeś:wyruszyłaś; do Kniei Zmierzchu?', 0),
(1249, 'koKR', 'Wymknął ci się? Wyglądał dość podejrzanie, tak się na nas gapiąc.', 0),
(1265, 'koKR', 'Tak, $N?', 0),
(1324, 'koKR', 'Witaj ponownie, $N. Mam nadzieję, że nie masz nam za złe tej pomocy, ale nie mogliśmy pozwolić, żeby Hendel uciekł albo, co gorsza, zginął.', 0),
(1338, 'koKR', 'List z krasnoludzkich ziem? Ciekawe, kto pisze z tak daleka, z północy...$B$BPozwól, że rzucę okiem na to zamówienie.', 0),
(1364, 'koKR', 'Co cię sprowadza do Strażnicy Otchłani?', 0),
(1447, 'koKR', 'Nie chciałem cię urazić tym gadaniem, że $gjesteś tępy:jesteś tępa;. Kumple jesteśmy, nie? Bez urazy?', 0),
(1448, 'koKR', 'Przemierzyłem świat od dżungli Azeroth po ośnieżone szczyty Khaz Modan.$B$BNigdy wcześniej nie prosiłem nikogo o pomoc w moich wyprawach. Ale moje stare kości są już zmęczone.$B$BNic nie dałoby mi większej satysfakcji niż świadomość, że ukończyłem ostatnią wyprawę dla Ligi Odkrywców.$B$BJeśli zechcesz pomóc mi w poszukiwaniach Świątyni Atal\'Hakkar, będę ci niezmiernie wdzięczny.$B$BPrzeczesz Moczary Smutków i wróć z tym, czego się dowiesz!', 0),
(1469, 'koKR', 'Nareszcie $gwróciłeś:wróciłaś;, $N. Sporo czasu minęło od naszej ostatniej rozmowy. Myślałem już, że $gzapomniałeś:zapomniałaś; o mojej wyprawie.$B$BCzy $godnalazłeś:odnalazłaś; tego przebiegłego jeźdźca gryfów? Miał coś do zameldowania?', 0),
(1475, 'koKR', 'Gdy nad moją karierą powoli zapada zmierzch, zwracam się do ciebie, $N, byś $gpomógł:pomogła; mi w ostatniej wyprawie dla Ligi Odkrywców. Gdyby moje stare kości znalazły w sobie dość siły, by stawić czoła Moczarom Smutków i zatopionej świątyni, walczyłbym ramię w ramię z tobą.$B$BDuma nie pozwala mi łatwo prosić cię o pomoc w zbieraniu tabliczek Atal\'ai. Ale starość zmusza mnie do tego.$B$BProszę, pomóż mi, $N. Chcę odejść z Ligi Odkrywców na zasłużony odpoczynek, wykonawszy jej ostatnie zlecenie.', 0),
(1644, 'koKR', 'Mam nadzieję, że mój John ma więcej szczęścia w Żelaznej Kuźni. Tak nie lubi tam jeździć, bo zostawia mnie i dzieci samych, ale wie, że to konieczne. Ma takie dobre serce.$B$BBywały lata lżejsze i cięższe, ale ten jest zdecydowanie najcięższy. Jakby coś w powietrzu zwiastowało wielką zmianę. Ale kto to wie?', 0),
(1665, 'koKR', 'Widziałem twoją walkę z Bartlebym. Nieźle! $GZdobyłeś:Zdobyłaś; jego kufel?', 0),
(1688, 'koKR', 'Nawet starszych i mądrzejszych potrafią pozbawić rozsądku powaby młodości i urody, $N. Tę radę warto pamiętać przez całe życie.', 0),
(1689, 'koKR', 'Nie pokażę ci, jak panować nad wędrowcem Pustki, dopóki żadnego nie ujarzmisz.', 0),
(1700, 'koKR', 'Witaj, dobrze cię widzieć. W czym mogę ci pomóc?', 0),
(1701, 'koKR', 'Jak idą poszukiwania, $N? Masz surowce?', 0),
(1702, 'koKR', 'Witaj! Sucho dziś, nie sądzisz?', 0),
(1703, 'koKR', 'Pozdrawiam cię, $N.', 0),
(1704, 'koKR', 'Dzień dobry, a może dobry wieczór. Stąd, z samego dołu, nie poznam, która pora. Masz do mnie jakiś interes?', 0),
(1705, 'koKR', '$N, masz płonącą krew i skałę? Potrzebuję ich, żeby dokończyć zbroję.', 0),
(1738, 'koKR', 'Twoje poszukiwania zakończyły się sukcesem, $N?', 0),
(1739, 'koKR', 'Czasem się zastanawiam, czy Surena nie była sukkubem w przebraniu, zesłanym, by wypaczyć i omotać mój umysł... Ha! Chyba przypisuję jej za dużo zasług.', 0),
(1861, 'koKR', 'Masz próbkę, $N? Przepływ magii w Wichrogrodzie i Elwynn uległ zmianie, a ja muszę wiedzieć, czy nie przesącza się do wody.', 0),
(1920, 'koKR', '$GSchwytałeś:Schwytałaś; te stwory, $n? Trzeba je zbadać, żeby ustalić, dlaczego się tu pojawiły.', 0),
(1921, 'koKR', 'Witaj, $N. Jennea mówiła, że przyjdziesz. Masz coś dla mnie?', 0),
(1938, 'koKR', 'Masz tę księgę, $N? Jej tajemnice nie są przeznaczone dla niewyszkolonych, a zgłębianie ich może prowadzić do zguby i ruiny.', 0),
(1940, 'koKR', 'Ach, tak. Magowie z sanktuarium czarodziejów mówili, że się do mnie zgłosisz. Masz potrzebny jedwab?', 0),
(2040, 'koKR', '$GZnalazłeś:Znalazłaś; Gnoam Sprecklesprocket, $N?', 0),
(2206, 'koKR', 'Z każdą chwilą, którą marnujesz, obijając się w koszarach, ubywa ci życia, $N.', 0),
(2359, 'koKR', 'Jakieś wieści od agentki Kearnen?', 0),
(2746, 'koKR', 'Od paru tygodni obserwuję Lescovara. Trias nigdy mu nie ufał, ale nie podejrzewaliśmy, że ma cokolwiek wspólnego z Bractwem Nieskornych. Szliśmy tropem, który łączył go z Młotem Zmierzchu. Tak czy inaczej, stał się zbyt groźny, by miasto mogło sobie z nim poradzić, i tu wkraczamy my.$b$bZdobądź mi te rzeczy, a wprowadzimy mój plan w życie.', 0),
(2758, 'koKR', 'Czyżbyś $gmiał zostać kolejnym podopiecznym:miała zostać kolejną podopieczną; Galvana?', 0),
(2759, 'koKR', 'Rzadki z ciebie okaz, kamracie. Pokaż no tę odznakę.', 0),
(2928, 'koKR', 'Gdyby to był wyścig, $gprzegrałbyś:przegrałabyś; już dawno.', 0),
(3630, 'koKR', 'Tak, tak, w czym mogę ci dziś pomóc? Oczywiście mam na to czas, skoro jedyne, co robię, to stoję tutaj, podczas gdy nasze ukochane miasto spowija chmura napromieniowanej śmierci.', 0),
(3636, 'koKR', 'Amnennar musi zostać unicestwiony. Idź, szybko.', 0),
(4181, 'koKR', 'Świeżych rekrutów wyczuwam tak samo jak doskonały proch strzelniczy – z odległości mili. $GPrzyszedłeś:Przyszłaś; zgłębić sztukę wybuchów?', 0),
(4765, 'koKR', 'Powiedziano mi, że przybędzie posłaniec. Z darem z Iglicy Czarnej Góry.$B$BCzy to ty?', 0),
(5022, 'koKR', 'Witaj w biurze spisu ludności Wichrogrodu. Jeśli potrzebujesz informacji o naszych mieszkańcach, mogę ci pomóc.', 0),
(5048, 'koKR', 'Kazałabym ci zejść z mojego trawnika, ale jak widzisz, nie mam trawnika.', 0),
(5050, 'koKR', 'John, skarbie... to ty? Nagle zrobiło mi się tak zimno...', 0),
(6187, 'koKR', '<Król Varian Wrynn jest pogrążony w myślach.>', 0),
(6261, 'koKR', 'Czy to pot na twoim czole, $gchłopcze:dziewczyno;? Za dużo biegasz. Następnym razem leć gryfem!', 0),
(6281, 'koKR', 'Podróżowało się, co? $GByłeś:Byłaś; w jakimś ciekawym miejscu?', 0),
(6285, 'koKR', '$GWróciłeś:Wróciłaś; z Wichrogrodu? Osric przysłał zbroje?', 0),
(6403, 'koKR', 'Ja... ja... byłem bezsilny.', 0),
(6501, 'koKR', 'Wyczuwam złą aurę, która od ciebie bije, $N. Co takiego możesz mieć przy sobie, że emanuje taką aurą?', 0),
(7495, 'koKR', 'Na brodę Uthera!', 0),
(7637, 'koKR', 'Witaj, $gszlachetny:szlachetna; $N! Napełniłem moją zaufaną kadzielnicę najświeższym kadzidłem i trzykrotnie ją pobłogosławiłem, abyś $gmógł:mogła; jej użyć. Twój datek pomoże nam w Żelaznej Kuźni nie tylko sprawić nową kadzielnicę, ale też uzupełnić kurczące się zapasy żywności dla potrzebujących.', 0),
(7639, 'koKR', 'Witaj z powrotem, $N. Czy masz już kadzielnicę egzorcyzmu?', 0),
(7640, 'koKR', 'Dobrze cię znów widzieć, $N. Czy $gskończyłeś:skończyłaś; swoją pracę w Dolinie Grozy?', 0),
(7642, 'koKR', 'Ach, to ty. Nie dokończę twojej zbroi bez rzeczy, o których mówiłem. $GZebrałeś:Zebrałaś; już wszystko?', 0),
(7643, 'koKR', 'Pradawny duch konia patrzy na ciebie wyczekująco, jakby czegoś od ciebie chciał.', 0),
(7644, 'koKR', '$N, $gwróciłeś:wróciłaś;! Czy udało ci się załatwić sprawę z Merideth Carlson i Tendrisem Spaczodrzewem? Szczerze mówiąc, czasem nie jestem pewien, które z nich jest groźniejsze...', 0),
(7646, 'koKR', '$GPrzebyłeś:Przebyłaś; tak długą drogę, $N. Twoja ostatnia ofiara z doczesnych dóbr da początek jednemu z twoich największych osiągnięć. Czuję to każdą cząstką swojej istoty!', 0),
(7647, 'koKR', 'Duch poległego szarżownika spogląda na ciebie żałośnie. Smutne, niemal puste oczy patrzą tak, jakby straciły wszelką nadzieję.', 0),
(7648, 'koKR', 'Dobrze ci idzie, $N. Gdy już będziesz $gmiał:miała; swoją zbroję, będziesz na dobrej drodze do następnego zadania.', 0),
(7781, 'koKR', 'Nie do wiary!', 0),
(7791, 'koKR', 'Jeśli masz przy sobie sześćdziesiąt sztuk wełnianego płótna i chcesz je ofiarować, mogę je teraz od ciebie przyjąć.', 0),
(7793, 'koKR', 'Taki szczodry dar jak jedwab – pozwolę sobie dodać – z pewnością podniesie twoją pozycję w miejscowej społeczności! Jeśli masz przy sobie sześćdziesiąt sztuk jedwabnego płótna i chcesz je ofiarować, mogę je teraz od ciebie przyjąć.', 0),
(7794, 'koKR', 'Jeśli masz przy sobie sześćdziesiąt sztuk tkaniny magów i chcesz je ofiarować, mogę je teraz od ciebie przyjąć.', 0),
(7795, 'koKR', '$n, bardzo $gprzysłużyłeś:przysłużyłaś; się naszej zbiórce tkanin. Choć ciężko pracujemy nad uzupełnieniem zapasów, jednej tkaniny wciąż rozpaczliwie brakuje – runicznej. Bardzo jej potrzebujemy i mamy nadzieję, że pomożesz nam tak jak dotąd!$b$bJeśli zechcesz, przynieś mi tyle runicznej tkaniny, ile możesz oddać. Na początek przyjmiemy jednorazowy dar sześćdziesięciu sztuk, a potem zobaczymy.', 0),
(7796, 'koKR', 'Gdy tylko zechcesz oddać porcję runicznej tkaniny, przyjmę ją.', 0),
(8356, 'koKR', 'Nie ma cukierków, dopóki nie pokażesz mi mięśni, $N...', 0),
(8410, 'koKR', 'Co dla mnie masz?', 0),
(8417, 'koKR', 'Czy Stoley wyskoczył z mojej gorzały?', 0),
(8419, 'koKR', 'Masz moją spaczoną tkaninę?', 0),
(8860, 'koKR', 'Witaj! $GPrzyszedłeś:Przyszłaś; na imprezę? A może po prostu musisz dać odpocząć zmęczonym stopom...', 0),
(11451, 'koKR', 'Och, czy to wiersz?', 0),
(12774, 'koKR', '$n, dobrze cię widzieć. Twoja siła i umiejętności są bezcenne w tych czasach próby.', 0),
(13188, 'koKR', 'Zostały ci ledwie chwile życia.', 0),
(13347, 'koKR', '<Król Wrynn ociera łzę.>$b$b<Król Wrynn kiwa głową.>$b$bTo moja wina.', 0),
(14111, 'koKR', 'Duchy poruszają się w tobie. Co cię sprowadza, że szukasz pomocy Kręgu Ziemi?', 0),
(24428, 'koKR', 'Na zęby Nozdormu!', 0),
(24597, 'koKR', 'Witaj. Masz coś dla mnie?', 0),
(25180, 'koKR', 'Udało ci się spotkać z kurierem?', 0),
(25181, 'koKR', 'Udało ci się spotkać z kurierem?', 0),
(25253, 'koKR', 'Na co $gnatrafiłeś:natrafiłaś; na Starym Mieście?', 0),
(25417, 'koKR', 'Nareszcie $gwróciłeś:wróciłaś;. Zaczynało mi się już wydawać, że na dobre $gprzystałeś:przystałaś; do kultystów.', 0);
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES
(344, 0, 'koKR', 'Kim jest ten $c, który staje przed Sądem Jeziernych Włości w Królestwie Wichrogrodu? Wyłóż, jaką masz sprawę w tym miasteczku. Zagrożenie ze strony orków jest dla królestwa zbyt wielkie, by trwonić czas na próżne pogawędki.', 0),
(656, 0, 'koKR', 'Wszędzie byli złodzieje! $b$bTo było straszne. Jaskinia zawaliła się na nas. Chyba cała ekipa górników nie żyje, łącznie z moim bratem, brygadzistą.', 0),
(1141, 0, 'koKR', 'Jeśli przychodzisz tu dla jedzenia, to witaj! Lepszej kuchni nie znajdziesz w całym Wichrogrodzie... ani w całym Azeroth!$B$BJeśli zaś sprowadzają cię inne sprawy, to proszę, streszczaj się. Mam w przygotowaniu tuzin dań i każdego muszę doglądać.', 0),
(1284, 0, 'koKR', 'Witaj, $n.', 0),
(1343, 0, 'koKR', 'No proszę, $gmłody:młoda;, $gpełen:pełna; zapału $c, bez wątpienia $gprzyciągnięty:przyciągnięta; tu opowieściami o moich wyczynach na polach bitew!$B$BTeraz nie ma czasu na historie, bo czekają wielkie, ważne czyny! Jeśli więc szukasz chwały, to los ci dziś sprzyja...', 0),
(1428, 0, 'koKR', 'Witaj, $n.', 0),
(1646, 0, 'koKR', 'Witaj, jestem Baros Alexston, architekt miejski Wichrogrodu.', 0),
(1719, 0, 'koKR', 'Tutaj, ty nicponiu...! Jeśli chcesz się na coś przydać, słuchaj uważnie!', 0),
(1748, 0, 'koKR', 'Jestem Bolvar Fordragon, najwyższy lord Wichrogrodu.', 0),
(2277, 0, 'koKR', 'Mam mnóstwo pracy. $GPrzyszedłeś:Przyszłaś; pomóc mi w badaniach?', 0),
(2285, 0, 'koKR', 'Moja rodzina szczyci się najwspanialszą kolekcją biżuterii i dzieł sztuki spośród wszystkich szlachciców Wichrogrodu!$B$BI zawsze chętnie ją powiększamy...', 0),
(4077, 0, 'koKR', 'Jeśli zdobędę odpowiednie składniki, zrobimy materiały wybuchowe, które nie tylko pozwolą mi zaszkodzić interesom spółki Gitgeszeft, ale też odwrócą uwagę.$B$BWiem, że robi to na tobie wrażenie, ale będzie jeszcze lepiej... Wkrótce powiem ci więcej.', 0),
(4078, 0, 'koKR', 'Witaj, $gprzyjacielu:przyjaciółko;. Co mogę dla ciebie zrobić?', 0),
(4794, 0, 'koKR', 'Prowadzenie badań w Theramore to ciekawe zajęcie, ale w tym mieście naprawdę trudno o miękkie łóżko!', 0),
(6169, 0, 'koKR', 'Jestem na wyprawie. Na wyprawie! Na wyprawie po nowe stopy i twardsze metale do największego wynalazku wszech czasów!!', 0),
(6179, 0, 'koKR', 'Paladyna Światłości czeka wiele prób, $N. Bądź $gpewien:pewna;, że nasze ścieżki jeszcze nieraz się skrzyżują, jeśli zachowasz żarliwość i wierność cnotom, które wysławiamy.', 0),
(6569, 0, 'koKR', 'Tam, gdzie krążą troggi i trędowate gnomy, stoi nasz dom – Gnomoregan.$B$BNasze rodziny zaginione, domy utracone. Rozproszeni.$B$BOch, jakże tęsknię za dniami beztroskiego życia w Gnomoregan, ale te dni minęły. Musimy stawić opór! Musimy ocalić Gnomoregan!', 0),
(6579, 0, 'koKR', 'Za Gnomoregan!', 0);
