INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(30, 'koKR', 'Mój panie,\n\nNadeszła wojna. Zguba stoi u naszych drzwi.\n\nJako sędzia Jeziernych Włości mam obowiązek zdać raport z niedawnych działań wojennych, do których doszło w najdalej na wschód wysuniętej kolonii Jego Królewskiej Mości.\n\nNa tych stronach znajdziesz, panie, opis położenia Jeziernych Włości, leżących w Górach Rudej Grani.', 0),
(31, 'koKR', 'Utrata Twierdzy Kamiennej Straży była ciężkim ciosem. W poprzednich raportach opisałem ci, panie, sojusz między orkowym klanem Czarnej Skały a czarnoksiężnikiem zwanym Morganth. Orkowie z Czarnej Skały walczyli z przerażającą dzikością, bez wątpienia podsycaną złą magią Morgantha. Wielu najdzielniejszych żołnierzy Jego Królewskiej Mości poległo w obronie Twierdzy, lecz ostatecznie nic nie dało się zrobić. ', 0),
(32, 'koKR', 'O dziwo, wkrótce po swoim nikczemnym zwycięstwie Morganth zwrócił się przeciwko orkowym sprzymierzeńcom. Czarnoksiężnik wzniósł na północnym wschodzie tajemną wieżę i dzięki swym mocom zebrał niewielką armię gnolli z klanu Cienioskórych, które wypełniają jego złowrogie rozkazy. Ofiarami okrutnych bestii służących czarnoksiężnikowi padają zarówno orkowie, jak i ludzie. Co do zdrady, do której doszło między Morganthem a Gath\'Ilzoggiem, wodzem wojennym Czarnej Skały, na razie można jedynie snuć przypuszczenia. ', 0),
(33, 'koKR', 'Na naszą zgubę plugawi orkowie zdają się bardziej dążyć do wytępienia dobrych poddanych Jego Królewskiej Mości. W ciągu ostatnich dwóch tygodni klan Czarnej Skały przypuścił na Jezierne Włości bezlitosną ofensywę. Tego ponurego dnia życie straciło wielu dzielnych mężów. Siły orków nacierały z taką szybkością i furią, że most nad Jeziorem Sennych Włości legł w gruzach. Nasze zapasy wojenne bardzo stopniały. Brakuje nam bandaży, by opatrzyć rannych. ', 0),
(34, 'koKR', 'Proszę więc Jego Królewską Mość o wsparcie dobrych mieszkańców Jeziernych Włości w tej godzinie potrzeby. Potrzebujemy nowych żołnierzy do obrony tych ziem, a także nowego oręża w miejsce tego, który przepadł na polu bitwy. Kończą się również żywność i materiały budowlane. Proszę, mój panie, pomóż nam utrzymać ostatni bastion między człowiekiem a nikczemnym orkiem. Wroga nie wolno wpuścić do Królestwa Wichrogrodu. ', 0),
(35, 'koKR', 'Obawiam się, że w kotle zepsucia, jakim stały się Północne Ziemie, warzy się zło jeszcze większe i mroczniejsze. Królestwo Wichrogrodu musi koniecznie podjąć działania, jeśli nie chcemy stać się blednącym wspomnieniem dla żywych albo niewolnikami Wroga.\n\nPodpisano:\n\nSędzia Solomon\nJezierne Włości\nKrólestwo Wichrogrodu', 0),
(36, 'koKR', 'Czcigodny sędzio Solomonie,\n\nopłakuję poległych wraz z tobą. Osobiście dopilnuję, by król dowiedział się o sytuacji, i mam najszczerszą nadzieję, że zdołam sprowadzić do Jeziernych Włości posiłki. Jego Królewska Mość ostatnio rzadko się pokazuje i zachowuje się dość dziwnie. Mówię ci to w zaufaniu.\n\nDo tego czasu pozostaję\n\nGenerał Marcus Jonathan\nKrólestwo Wichrogrodu', 0),
(38, 'koKR', 'Mocnopłaszczu – niezły tupet, żeby przysyłać zupełnie obcą osobę na rozmowę o bandzie Nieskornych. Kiedyś ocaliłeś mi życie, a teraz wystawiasz je na wielkie niebezpieczeństwo. Ale mam u ciebie dług. Bractwo Nieskornych jest większe, niż myślisz. Każda kopalnia od Zachodniego Skraju po Knieję Elwynn jest pod ich kontrolą. Do brudnej roboty zwerbowali koboldy i gnolle. Gobliny budują dla nich metalowe potwory, które stawiają na polach Zachodniego Skraju, by żerować na przesądach miejscowych. ', 0),
(39, 'koKR', 'Zbudowali rozległą sieć podziemną. Większą, niż sądzisz, Mocnopłaszczu. Od Łupieżczej Zatoki aż po Twierdzę Wichrogród. Może i jesteś dzielnym paladynem, ale jesteś głupcem, jeśli myślisz, że zdołasz ich powstrzymać. Pracują nad bronią masowej zagłady. W końcu jeśli kamieniarze coś potrafią, to budować z rozmachem. Chyba nie myślałeś, że chodzi o farmy dyń i winnice, co? Spłaciłem dług. A teraz zostaw mnie w spokoju!\n\n--W\n', 0),
(41, 'koKR', 'Lordzie Mocnopłaszczu – Gildię Kamieniarzy, na której czele stał Edwin VanCleef, tworzyli najzdolniejsi budowniczowie spośród ludzi. Kamieniarze pomogli odbudować zniszczone miasto Wichrogród, zrównane z ziemią przez orków podczas Pierwszej Wojny. VanCleef i jego rzemieślnicy byli budowniczymi bez równych, a ich pracę i kunszt widać w gmachach Katedry Światła i samej Twierdzy Wichrogród. ', 0),
(42, 'koKR', 'Jednak szlachta Wichrogrodu zaciągnęła ogromny dług, rozszerzając obecność wojskową królestwa na Knieję Elwynn i dalej, aż po Dolinę Cierniodławów. Olbrzymie zadłużenie zrujnowało gospodarkę królestwa i pozbawiło VanCleefa i jego kamieniarzy obiecanej zapłaty. Po latach harówki przy odbudowie wspaniałego miasta kamieniarze zostali bez grosza, zapomniani przez skorumpowanych urzędników miasta. ', 0),
(43, 'koKR', 'Znam Edwina VanCleefa osobiście przez całe życie, więc mogę ci powiedzieć, że zmierzenie się z nim jako z wrogiem to zadanie niełatwe. Widzisz, był moim przyjacielem z dzieciństwa i sam wyszkoliłem go w sztuce działania w cieniu, sądząc, że pewnego dnia zechce pracować u mego boku. Jeśli VanCleef stoi na czele Bractwa Nieskornych, niech Światłość ma w opiece nasze dusze.\n\nMistrz Mathias Shaw\nGildia Skrytobójców Wichrogrodu', 0),
(44, 'koKR', 'Znam Edwina VanCleefa osobiście przez całe życie, więc mogę ci powiedzieć, że zmierzenie się z nim jako z wrogiem to zadanie niełatwe. Widzisz, był moim przyjacielem z dzieciństwa i sam wyszkoliłem go w sztuce działania w cieniu, sądząc, że pewnego dnia zechce pracować u mego boku. Jeśli VanCleef stoi na czele Bractwa Nieskornych, niech Światłość ma w opiece nasze dusze. Mistrz Mathias Shaw Gildia Skrytobójców Wichrogrodu ', 0),
(64, 'koKR', 'Morgan Ladimore był wielkim i szlachetnym rycerzem, który bronił niewinnych, ubogich i cierpiących. Przez wiele lat niestrudzenie działał na odległych rubieżach Azeroth, niosąc ulgę cierpiącym i szybką sprawiedliwość złoczyńcom.$B$BLatem swojego osiemnastego roku życia poślubił młodą dziewczynę imieniem Lys. Bardzo się kochali i z czasem doczekali się trojga dzieci: syna i dwóch córek.$B$BMorgan miał trzydzieści dwa lata, gdy wybuchła wojna w', 0),
(65, 'koKR', 'Lordaeronie. Morgan został wezwany, by u boku legendarnego paladyna Uthera Światłodzierżcy walczyć z orkami i nieumarłymi. Zostawił żonę i dzieci bezpiecznych w domu i wyruszył na wojnę.$B$BMijały lata, wojna się przeciągała, a Morgan był świadkiem wielu okropieństw, w tym rozwiązania zakonu paladynów Srebrnej Dłoni, śmierci Uthera i szerzenia się zarazy. Przed obłędem chroniła go tylko świadomość, że', 0),
(66, 'koKR', 'pewnego dnia znów połączy się z żoną i dziećmi.$B$BMorgan w końcu powrócił w rodzinne strony, lecz zastał je zupełnie inne, niż je zapamiętał. Niegdyś zielony las był skażony i roił się od nieumarłych i innych mrocznych sił. Wszędzie widać było zniszczone domy i farmy, a cmentarz przy Kruczym Wzgórzu zajmował teraz znaczną część okolicy. Wstrząśnięty i oszołomiony Morgan dotarł w końcu do swojego domu, tylko po to, by zastać go w ruinie. Nie wiedząc, co spotkało jego ojczyznę,', 0),
(67, 'koKR', 'udał się do wioski, by znaleźć odpowiedzi i, jak miał nadzieję, żonę i dzieci.$B$BMorgan wypytywał o rodzinę, ale nikt nie potrafił mu nic powiedzieć. Kapłan w Mrocznych Włościach, jak teraz nazywano tę osadę, poradził mu, by poszukał ich nagrobka na cmentarzu na Kruczym Wzgórzu. Morgan nie chciał uwierzyć, że jego rodzina nie żyje, i dalej przeszukiwał każdą farmę i każdy dom w Kniei Zmierzchu, lecz na próżno.$B$BMorgan pojechał z Mrocznych Włości do pobliskich Jeziernych Włości, sądząc, że może jego rodzina uciekła. Po drodze', 0),
(68, 'koKR', 'postanowił, wbrew rozsądkowi, zajrzeć na cmentarz na Kruczym Wzgórzu. Godzinami chodził między nagrobkami. Rozpoznawał wiele nazwisk znanych sobie ludzi i coraz bardziej wpadał w rozpacz. Wtedy je zobaczył: małą, zaniedbaną kwaterę pośród wielu innych, a na niej trzy niewielkie nagrobki. Gdy się zbliżał, ogarnęła go trwoga. Morgan starł kurz z największego nagrobka, by odsłonić wyryte na nim imię. Proste litery wykute w kamieniu układały się w', 0),
(69, 'koKR', 'jego najgorszy lęk:$B$BLys Ladimore$BUkochana żona i matka$B$BNiepokój Morgana zmienił się w przerażenie, a potem w żal, i Morgan padł na kolana, płacząc. Godzinami wpatrywał się w ten jeden grób, błagając zimny kamień o przebaczenie i łkając słowa przeprosin. Potem, po wielu godzinach, coś w nim pękło i wpadł w szał. Dobył miecza z pochwy i zaczął okładać nagrobki ciosami, wrzeszcząc z wściekłości. Zaślepiony furią, siekł na oślep, aż zwrócił na siebie uwagę', 0),
(70, 'koKR', 'trzech cmentarnych dozorców. Gdy próbowali go powstrzymać, skierował gniew przeciwko nim, obrzucając niewinnych dozorców oskarżeniami, a potem zabił ich wszystkich.$B$BPóźniej, gdy wściekłość minęła, do umysłu Morgana zaczęła docierać prawda: zobaczył swój zakrwawiony miecz wbity w pierś jednego z dozorców. Doprowadzony przez własne uczucia na skraj, wyjął nóż zza pasa i wbił go sobie w serce.$B$BCiało Morgana Ladimore\'a i trzy ciała jego ofiar znaleziono', 0),
(71, 'koKR', 'następnego dnia. Pochowano go pośpiesznie, bez ceremonii, w naprędce wykopanym grobie na obrzeżach cmentarza. Ponieważ Morgan zamordował niewinnych, co było całkowicie sprzeczne z jego przekonaniami i naturą, i ponieważ dręczył go żal, że nie zdołał ocalić rodziny, nie mógł zaznać spokojnej śmierci i trwał dalej jako jeden z niespokojnych umarłych.$B$BZaledwie kilka dni później ktoś naruszył jego grób, a ciała nie odnaleziono. Istota, którą był niegdyś Morgan, teraz', 0),
(72, 'koKR', 'przemierza Knieję Zmierzchu, trawiona żalem po utracie żony i dzieci oraz nienawiścią do samej siebie. Mor\'Ladim, jak teraz sam siebie nazywa, krąży po Kniei Zmierzchu, powodowany bezrozumną żądzą zemsty i nienawiścią, i wiadomo, że zabija bez wyboru.', 0),
(85, 'koKR', 'Mój dziennik\n\nGroza ostatnich tygodni jest niemal ponad moje siły. Czemu, kiedy zapisuję słowa w tej księdze, udaje mi się jakoś trzymać obłęd na dystans? Może to tak, jakbym spowiadał się z grzechów milczącemu towarzyszowi albo uwalniał umysł od udręczonych myśli i zamykał je na papierze.\n\nZacząłem już wcześniej inny dziennik, ale został w miejscu, do którego nie mogę wrócić. Zacznę więc od nowa. Tym razem jednak zacznę od prawdziwego początku.', 0),
(186, 'koKR', 'Wszystko zaczęło się od znalezienia tej przeklętej kosy w kopalni, którą nazywają Zgubą Rolanda. Tak, to był początek. Wcześniej Bractwo Nieskornych było zadowolone z naszych postępów w Kniei Zmierzchu. Przed Kosą tutejsze strachy wydawały się równie niegroźne jak Dolina Północnych Włości.\n\nAle odkąd znalazłem trzonek Kosy sterczący ze sterty gruzu w kopalni i – przeklęty niech będę – wyciągnąłem ją, Zguba Rolanda stała się miejscem ohydnej śmierci!', 0),
(187, 'koKR', 'Gdybym wiedział, co się stanie, odrąbałbym sobie rękę, byle nie chwycić tego drewna pokrytego runami. Tyle żalu! Zawsze myślałem, że żal to przywilej starych. Teraz wiem, że to nie starzy, lecz pozbawieni nadziei przywdziewają płaszcz żalu, niezdolni i niechętni, by zrzucić go z ramion zgarbionych od nieszczęścia.\n\nDość jednak tych wynurzeń w stylu poety odurzonego fajką. Muszę kontynuować kronikę...', 0),
(188, 'koKR', 'Gdy Kosa została uwolniona, przez kopalnię przeszła jakaś zmiana. Światło naszych migoczących pochodni wykrzywiało się, a siła naszych głosów zdawała się wymykać spod kontroli. Czasem czyjś szept rozlegał się w tunelach rykiem, aż trzeba było zatykać uszy, a czasem nasze krzyki ledwie niosły się na kilka kroków, po czym gasły jak ledwie wyczuwalny powiew.\n\nNiepokojące, owszem, ale nie mieliśmy wiele czasu, by się nad tym dziwić. To był zaledwie zwiastun tego, co naprawdę wygnało nas z kopalni. Worgeny.', 0),
(189, 'koKR', 'Atakowały nas zewsząd, wypełzając z ukrytych nor pod naszymi stopami i spadając na nas z cichych kryjówek w górze. Połowa naszych ludzi padła w tych pierwszych chwilach paniki. Reszta, w tym ja, próbowała uciec. Biegnąc, widziałem, jak kły i pazury dopadają tylu moich braci, słyszałem tyle krzyków urwanych nagle albo gasnących w bulgotaniu.\n\nNa ile wiem, jestem jedynym człowiekiem, który uciekł z tamtego miejsca.', 0),
(190, 'koKR', 'Mogę tylko zgadywać, dlaczego przeżyłem tamtą noc. Zawsze byłem ostrożny, zawsze szybko uchylałem się przed ciosami i odskakiwałem od pułapek. Stąd zresztą moje przezwisko – Jitters, czyli Nerwus. Może więc ocaliła mnie po prostu ta smykałka do ostrożności...\n\nA może była to Kosa, którą wyciągnąłem z gruzu. Nie mogła to być sama Kosa, bo zgubiłem ją podczas szaleńczej ucieczki. Ale jeśli to ja sprowadziłem worgeny do Kniei Zmierzchu, to może worgeny okazały mi rzadką uprzejmość. Niech je licho.', 0),
(191, 'koKR', 'A może jestem skazany na to, by oglądać zmianę, jaką sprowadziłem na Knieję Zmierzchu. Może takie jest moje przeznaczenie: patrzeć, jak worgeny rozszarpują tę krainę i swoją ohydą plamią ją na coraz mroczniejszy kolor.\n\nJeśli to naprawdę moje przeznaczenie, to jest ono podwójne. Bo worgeny nie są jedyną siłą, która sięga po Knieję Zmierzchu – swoje roszczenia zgłosiły też bestie z Przełęczy Wichrowej Zguby.\n\nTo następny rozdział mojej opowieści i modlę się, by był ostatni...', 0),
(192, 'koKR', 'Gdy przeżyłem ucieczkę ze Zguby Rolanda, ukryłem się w stodole należącej do człowieka imieniem Sven. Spędziłem w niej kilka dni, a groza tak mnie nie opuszczała, że ani razu nie pokazałem się Svenowi ani jego rodzinie. Z tego jednak, co widziałem z kryjówki, wiedziałem, że to bardzo porządni ludzie. Gdybym wyszedł z ukrycia, pewnie by mnie przygarnęli, ale trudno mi komukolwiek zaufać. A jeszcze trudniej po tamtym wstrząsie w kopalni.\n\nZostałem więc w ukryciu. I to ocaliło mi życie.', 0),
(193, 'koKR', 'Kilka dni po tym, jak dotarłem do stodoły, Sven wyruszył z farmy do Mrocznych Włości. Pocałował żonę, uśmiechnął się do dzieci i obiecał, że wkrótce wróci z zabawkami i słodyczami. Biedak. Wtedy po raz ostatni widział swoją rodzinę całą i nieokaleczoną.\n\nPrzynajmniej rozstali się szczęśliwi. I przynajmniej jego żona zginęła pierwsza i nie musiała patrzeć na rzeź swoich dzieci. Ale te drobne łaski nic dla mnie nie znaczą. Widziałem, co się stało, i będzie to nawiedzać moje sny już zawsze.', 0),
(194, 'koKR', 'Ręka mi drży, gdy wspominam szczegóły tamtej nocy, kiedy Svena nie było, a jego rodzina musiała sama stawić czoła Czarnym Jeźdźcom. Znów szarpie mnie żal, bo byłem tam i mogłem wystąpić przeciw tym bestiom z Przełęczy Wichrowej Zguby. Ale to fałszywy żal. Ten sam, który dręczy każdego, kto przeżył tragedię. Wiem, że gdybym opuścił kryjówkę, też bym zginął, a moje ciało zostałoby rozszarpane, jego szczątki zaś rozrzucone tak daleko, że nikt by mnie nie rozpoznał. ', 0),
(195, 'koKR', 'Choć jednak wiem, że nie mogłem nic zrobić, by powstrzymać to ohydne morderstwo, pozostaje jeden prawdziwy żal: to ja sprowadziłem Czarnych Jeźdźców na farmę Svena. Moje odkrycie Kosy nie tylko ściągnęło worgeny do Kniei Zmierzchu – przywiodło też Jeźdźców z Przełęczy Wichrowej Zguby.\n\nWiem to, bo tuż przed rzezią zadali jedno pytanie żonie Svena, gdy tuliła do siebie dzieci, dodając im otuchy, jak tylko mogła, choć była pewna, że śmierć jest blisko.', 0),
(196, 'koKR', '„Kosa Eluny” – zaskrzeczał jeden z Jeźdźców głosem zarazem chrapliwym i piskliwym, jak zgrzyt topora o kamień. A ostatnie słowo – Elune – wycharczał, jakby dławił się tym dźwiękiem.\n\nGdy usłyszałem ten głos, ogarnęła mnie trwoga, zarówno z powodu jego okropnego brzmienia, jak i dlatego, że... wiedziałem, o jakiej Kosie mówi Jeździec. To musiała być ta sama przeklęta rzecz, którą kilka dni wcześniej wyciągnąłem ze skał Zguby Rolanda. Właśnie jej szukali Czarni Jeźdźcy!\n\nI to przez nią miała zginąć rodzina Svena.', 0),
(197, 'koKR', 'Nigdy nie poznałem imienia żony Svena, bo mąż i dzieci nazywali ją tylko „najdroższa”, „kochanie” i „mamusiu”. Ale chciałbym je znać. Tylko ja wśród żywych pamiętam, czego dokonała tamtego dnia, i choć była tylko żoną rolnika, nigdy nie widziałem, by mężczyzna czy kobieta zachowali się tak odważnie.\n\nOczywiście nie wiedziała nic o Kosie, ale gdy usłyszała, że Jeźdźcy jej szukają, w jednej chwili ułożyła w głowie plan.\n\nA był to plan śmiały i sprytny. Gdyby tylko się powiódł.', 0),
(198, 'koKR', '„Kosa?” – powiedziała spokojnym głosem. – „Oczywiście, że wiem. Kto tutaj by nie wiedział?” Patrzyła na Jeźdźców niewzruszonym wzrokiem i przysiągłbym, że mówi prawdę, gdybym nie wiedział, jak jest naprawdę. Nie mogła nic wiedzieć o Kosie.\n\nJej fortel się opłacił. Ten sam Jeździec, który wcześniej zadał pytanie, lekko pochylił ku niej głowę i zaskrzeczał: „Gdzie?”\n\n„Zaprowadzę was. Wszystkich” – odpowiedziała, a ja dostrzegłem w jej oczach nikły błysk nadziei.', 0),
(199, 'koKR', '„Ale droga jest daleka, a dzieci by nas spowalniały. Musimy je zostawić”.\n\nJej podstęp był prosty, ale proste podstępy mają największe szanse powodzenia. Gdyby się udał, odciągnąłby Jeźdźców od farmy. Ona by zginęła, ale jej dzieci byłyby bezpieczne. I udałoby się, gdyby tylko Jeźdźcy uwierzyli w jej szlachetne kłamstwa.\n\nChoć nigdy nie byłem uczniem Światłości, żarliwie modliłem się za żonę Svena, gdy stała naprzeciw tych strasznych Jeźdźców.\n\n„Proszę – modliłem się. – Niech uwierzą”.', 0),
(200, 'koKR', 'Stali jak skamieniali, a ona spokojnie wytrzymywała ich spojrzenia. Wtedy jeden z jeźdźców uniósł głowę, jakby usłyszał odległe wołanie. Wyjął spod szat mały klejnot i zajrzał w jego głąb. Potem wskazał błyskotką żonę Svena. Od Jeźdźca ku kobiecie popełzło światło, przybierając kształt ponurej, białej dłoni. Patrzyła w to światło bez drgnienia, lecz za jej maską pewności siebie widziałem niepewność. Gdy dłoń do niej dotarła, rozpostarła palce nad jej głową.\n\nI zacisnęła się.', 0),
(201, 'koKR', 'Żona Svena zesztywniała jak deska, a jej oczy rozszerzyły się. I choć usta rozchyliły się do krzyku, nie wydobył się z nich żaden dźwięk. Po kilku chwilach tej tortury dłoń ją puściła, a kobieta osunęła się na kolana. Jeździec, który trzymał błyskotkę, wyprostował się w siodle, a z klejnotu buchnął donośny głos.\n\n„Ta kobieta kłamie” – rzekł głosem, który na zawsze naznaczył moje sny. – „Nie widziała Kosy”.', 0),
(202, 'koKR', 'Potem ramiona Jeźdźca lekko opadły, jakby opuścił go jakiś duch. A wtedy dawnym, skrzeczącym głosem, którego używał wcześniej, wypowiedział ostatnie słowa:\n\n„Pan przemówił. Zabić ich”.', 0),
(203, 'koKR', 'Nie potrafię opisać, co stało się potem. Mam to wyraźnie przed oczami, ale nawet moja nędzna dusza nie zdoła przelać na papier tego, co wydarzyło się w tych kilku kolejnych, makabrycznych minutach.\n\nMogę tylko napisać, że rodzina Svena zginęła. A wkrótce potem Sven wrócił do tego ponurego pobojowiska. Tyle było w nim rozpaczy, że bałem się pokazać. I tak bardzo bałem się, że mnie znajdzie, że uciekłem z kryjówki w stodole. Nie wiem, gdzie Sven jest teraz, ale modlę się, by pewnego dnia odnalazł spokój.', 0),
(219, 'koKR', 'Spisane ręką Barosa Alexstona, Urząd Architekta Miejskiego, Wichrogród. Wasza Królewska Mość, istnieje wiele powodów, dla których uznałem, że należy sporządzić i przedłożyć raport o niedawnych poczynaniach „Bractwa Nieskornych” i ich działalności w całym królestwie. Dla szerszego obrazu zacznę od odrobiny historii. Jak Waszej Królewskiej Mości być może wiadomo, moja służba dla miasta Wichrogród rozpoczęła się, gdy byłem członkiem Gildii Kamieniarzy. Po latach pracy ukończyliśmy odbudowę ', 0),
(220, 'koKR', 'Wichrogrodu, lecz wówczas rachunki, opłaty i wynagrodzenia Gildii Kamieniarzy pozostały niezapłacone i przemilczane. Edwin VanCleef był wtedy świeżo wybranym mistrzem Gildii Kamieniarzy i to on zabrał głos, domagając się zadośćuczynienia za naszą pracę. W odpowiedzi Izba Szlachty Wichrogrodu nakazała rozwiązanie Gildii Kamieniarzy, co, rzecz zrozumiała, rozgniewało VanCleefa. Stanąwszy na czele buntu, VanCleef wyprowadził kamieniarzy z miasta. Zanim będę kontynuował, winienem zwrócić uwagę Waszej Królewskiej Mości na kilka innych wydarzeń z ', 0),
(221, 'koKR', 'tamtego okresu. Po pierwsze, właśnie wtedy zaproponowano mi stanowisko architekta miejskiego, jeśli nie przyłączę się do VanCleefa. Z powodu pewnych różnic ideowych postanowiłem zostać w Wichrogrodzie. Podczas zamieszek porucznik VanCleefa i jego najbardziej zaufany pomocnik, Bazil Thredd, został pojmany i osadzony w więzieniu. Czekając na proces i przesłuchanie, Thredd niemal popadł w zapomnienie w Kazamatach. Wracając do VanCleefa: gdy wyprowadził już ', 0),
(222, 'koKR', 'resztki kamieniarzy z Wichrogrodu, wykorzystał to, że Zachodni Skraj był stosunkowo słabo chroniony, i dzięki pokaźnej liczbie ludzi przegnał wielu rolników, po czym przejął garstkę kopalni złota. Korzystając z zasobów, którymi dysponował, VanCleef uknuł plan odwetu na władzach Wichrogrodu. Informacje te wyszły na jaw niedawno dzięki pomocy okaziciela tego dokumentu, którego udział okazał się kluczowy dla ujawnienia tego rozległego spisku. ', 0),
(246, 'koKR', 'Przez następne tygodnie przenosiłem się z miejsca na miejsce, nigdzie nie zostając dłużej ze strachu przed Jeźdźcami. Jestem teraz w opuszczonym miasteczku na Kruczym Wzgórzu i jak zawsze się ukrywam. Nie zdołam stawić czoła mocy, której użyli przeciw żonie Svena, i wiem, że ta moc wciąż przeszukuje Knieję Zmierzchu w poszukiwaniu Kosy. Zgubiłem ją i dziękuję za to Światłości, bo gdybym ją zatrzymał, na pewno by mnie znaleziono. Nawet teraz wiem w głębi serca, że mnie znajdą.\n\nJestem taki zmęczony.', 0),
(286, 'koKR', 'LEGENDY TROLLI, TOM III Kamień Pływów Spisane ręką arcymaga Ansirema Runotkacza, Dalaran WSTĘP Starożytne Imperium Gurubaszów było źródłem wielu fascynujących i intrygujących legend, których korzenie bez wątpienia tkwią w otaczającym ich świecie, jako że badania ich systemów wierzeń i praktyk społecznych wskazują na wielką cześć, jaką darzyli otaczającą ich przyrodę. Choć w poprzednich tomach tego studium zgłębiłem wiele ', 0),
(287, 'koKR', 'Kurdran Dziki Młot$B$BSłynny pogromca smoków. Mistrz gryfów z Orlego Gniazda. Dowódca oddziału jeźdźców gryfów przydzielonego do Ekspedycji Przymierza, która wkroczyła do Draenoru, ojczystego świata orków. Uznany za zmarłego.$B$BBędziemy słyszeć nawoływania Sky\'ree na wietrze. Będziemy słyszeć grzmot twojego młota nad szczytami gór. Leć co sił w zaświaty, bracie. Czekają na ciebie sale naszych przodków.$B$B- Wielki than Falstad Dziki Młot', 0),
(288, 'koKR', 'Kapitan tropicieli Alleria Bieżywiatr$B$BSłynna łowczyni trolli z Quel\'Thalas. Główna zwiadowczyni i agentka wywiadu Ekspedycji Przymierza, która wkroczyła do Draenoru, ojczystego świata orków. Uznana za zmarłą.$B$BTwoje serce leciało prosto jak strzała na wietrze, siostro. Byłaś najjaśniejszą gwiazdą naszego zakonu. Byłaś najukochańszą z naszego rodu.$B$B- Sylwana Bieżywiatr – generał tropicieli Quel\'Thalas', 0),
(289, 'koKR', 'Arcymag Khadgar z Kirin Toru$B$BByły uczeń Medivha. Naczelny dowódca Ekspedycji Przymierza, która wkroczyła do Draenoru, ojczystego świata orków. Uznany za zmarłego.$B$BNikt nigdy tak bezinteresownie nie zagłębił się w mroczne serce magii i wojny. Życzymy ci pomyślności, śmiały wędrowcze. Gdziekolwiek jesteś.$B$B- Antonidas – arcymag Dalaranu', 0),
(290, 'koKR', 'Generał Turalyon$B$BByły zastępca lorda Anduina Lothara. Rycerz Srebrnej Dłoni. Najwyższy generał Ekspedycji Przymierza, która wkroczyła do Draenoru, ojczystego świata orków. Uznany za zmarłego.$B$BEsarus thar no\'Darador – Krwią i honorem służymy.$BByłeś prawą ręką sprawiedliwości i cnoty, stary przyjacielu. Twoje imię zawsze będzie czczone w naszych salach.$B$B- Lord Uther Światłodzierżca – rycerz Srebrnej Dłoni', 0),
(291, 'koKR', 'Danath Trollbane$B$BDowódca milicji Stromgardu. Doradca taktyczny generała Turalyona, dowódca sił Ekspedycji Przymierza, która wkroczyła do Draenoru, ojczystego świata orków. Uznany za zmarłego.$B$BCzcimy twoją pamięć i twoje poświęcenie, bratanku. Od założenia naszego chwalebnego imperium droga męstwa zawsze spływała krwią bohaterów.$B$B- Thoras Trollbane, władca Stromgardu', 0),
(293, 'koKR', 'aspektów ich kultu węży, tutaj przedstawiam analizę interesującej i wyjątkowej więzi trolli z morzem. WIELKIE MORZE Imperium Gurubaszów z trzech stron otaczało morze, nie dziwi więc, że woda zajmowała ważne miejsce w ich społeczeństwie. Choć trolle potrafiły przemierzać i kontrolować rozległe obszary swojego dżunglowego imperium, morze im się wymykało. Było bezkresne i niezmierzone, bez ', 0),
(294, 'koKR', 'wątpienia stanowiło niepokojące sąsiedztwo dla potężnych trolli. Należy tu zaznaczyć, że niedawne odkrycia zdają się sugerować, iż trolle nie przejawiały większego zainteresowania badaniem lądów za Wielkim Morzem. Choć trolle różnych odmian spotykano wzdłuż i wszerz Azeroth, Khaz Modan i Lordaeronu, niewiele śladów ich cywilizacji znaleziono na nowo odkrytych ziemiach Kalimdoru czy na wyspach Południowych Mórz. Czy świadczy to o niechęci ', 0),
(295, 'koKR', 'trolli do oddalania się od swoich lądowych posiadłości, czy o tym, że nie zdołały rozwinąć sztuki potrzebnej do takiej podróży, wymaga dalszych badań i analiz, które wykraczają poza zakres niniejszego pisma. Nie sposób jednak pominąć tak potężnego sąsiedztwa, a nowe znaleziska w rozległych ruinach trolli w Dolinie Cierniodławów ukazują nieznany dotąd i nieopisany aspekt ich więzi z morzem. KAMIEŃ PŁYWÓW Niedawne odkrycia podczas badań ', 0),
(296, 'koKR', 'ruin trolli w Dolinie Cierniodławów ujawniły wzmianki o przedmiocie zwanym „Kamieniem Pływów”. Z rozmaitych fragmentów trollich legend można złożyć dość pełny obraz Kamienia i jego znaczenia dla starożytnego Imperium Gurubaszów. Wygląda na to, że Kamień Pływów pozwalał swemu posiadaczowi panować nad wodą w wielu jej postaciach: rzekami, deszczem i pływami. Na podstawie opowieści o użyciu Kamienia Pływów przypuszczam, że jest on ', 0),
(297, 'koKR', 'w istocie fizycznym przejawem mocy Władcy Wód, potężnego żywiołaka mórz. Jak i dlaczego taki przedmiot miałby wymknąć się spod kontroli Władcy Wód i wpaść w ręce trolli, to kolejne pytanie wykraczające poza zakres mojej wiedzy. NOSICIEL PŁYWÓW Niczym pływy, od których wziął nazwę, Kamień Pływów przychodził do świata trolli i z niego odchodził, nigdy nie pozostając w ich rękach dłużej niż przez jedno pokolenie. ', 0),
(298, 'koKR', 'Legendy trolli mówią, że gdy Kamień Pływów po raz pierwszy trafił do Imperium Gurubaszów, znalazł go wojownik z plemienia trolli wędrujący wzdłuż wybrzeża Cierniodławów. Natknął się na tajemniczy niebieski kamień, w którego wnętrzu unosiły się i płynęły mlecznobiałe smugi. Zaintrygowany kamieniem wojownik zabrał go ze sobą i ruszył w dalszą drogę. Przez kolejne tygodnie i miesiące odkrywał, że kamień dał mu władzę nad wodą. Potrafił przywoływać ', 0),
(299, 'koKR', 'wodne żywiołaki, istoty utworzone w całości z wody – dokonując tego, co potrafią jedynie potężni magowie Kirin Toru. Wojownik udał się do Zul\'Gurub, do serca imperium, by pokazać cesarzowi swoje nowe zdolności. Po pokazie mocy w samym centrum cesarskiej stolicy bez trudu uzyskał posłuchanie na dworze. Jego moce z łatwością zachwyciły cesarza Gurubaszów, który natychmiast dał mu honorowe miejsce na dworze i nadał mu imię „Nosiciel Pływów”, a wojownik porzucił ', 0),
(300, 'koKR', 'swoje dawne imię. Przez lata Nosiciel Pływów służył Imperium Gurubaszów, przyzywając w bitwach podległe mu wodne żywiołaki i kierując biegiem wód w Dolinie Cierniodławów dla dobra imperium. Lecz z biegiem lat Nosiciel Pływów coraz bardziej stronił od ludzi i na długo znikał z dworu. Ukrywał bowiem sekret przed wścibskimi oczami dworzan. Zdolności nadane mu przez Kamień Pływów niosły ze sobą także klątwę. Z każdym ', 0),
(301, 'koKR', 'mijającym rokiem Nosiciel Pływów zanikał. Z każdym przypływem i odpływem stawał się coraz mniej sobą, tracąc cielesną postać – to pojawiając się, to znikając – aż w ostatnich dniach życia udał się na plażę, na której niegdyś znalazł Kamień, i wszedł do morza, by zniknąć po raz ostatni. Pokolenia później morze wyrzuciło Kamień Pływów na brzeg Cierniodławów i wybrano kolejnego Nosiciela Pływów, gdy troll zaniósł Kamień do ', 0),
(302, 'koKR', 'Zul\'Gurub. Tak to trwało przez pokolenia: Kamień pojawiał się z przypływem, a Nosiciel Pływów odchodził z odpływem. Współczesne relacje o Kamieniu Pływów pojawiają się tu i ówdzie, lecz wciąż trzeba się zastanawiać, dlaczego przedmiot o takiej mocy pojawia się z taką regularnością i z czyjego zamysłu. ', 0),
(336, 'koKR', 'Do państwa Schneiderów. Dzień dobry. Ufam, że interesy w Dzielnicy Kanałów idą dobrze. Tu, w Dzielnicy Handlowej, ruch jest ogromny. Potrzebujemy dzianych wyrobów z tkaniny, bo nasze zapasy niemal się wyczerpały. Proszę przysłać standardową dostawę, gdy tylko będzie to możliwe. Powodzenia! Mam nadzieję, że nauka waszego syna Thurmana postępuje, --Harlan Bagley ', 0),
(528, 'koKR', 'Jorgenie,\nmoje obawy się spełniły, a oni posunęli się do czynów, o które nigdy bym ich nie podejrzewał. Nigdy nie sądziłem, że podejdą tak blisko, a jednak to zrobili.\nProszę, pomóż osobie, która przyniesie ten liścik, i wyślij ją do NIEGO. Szczerze mówiąc, sądzę, że on nam pomoże ze względu na powagę sprawy. Gdyby chodziło o jakiekolwiek inne zagrożenie, pewnie dalej ignorowałby nas i problemy naszego pięknego miasta.\nDziękuję ci, stary rybaku. Jak zawsze jestem twoim dłużnikiem.\nTwój przyjaciel\nDeLavey', 0),
(580, 'koKR', 'Nasz pierwszy plan już się nie powiódł! Pięści udało się podmienić grafik straży na zmiany w tunelu tamtego wieczoru, ale przez nieprzewidziane działania kilku mieszkańców Wichrogrodu nasz cel zdołał uciec z miejsca zdarzenia, zanim go pojmaliśmy. Przewidzieliśmy jednak taką ewentualność. Plan 2 wprawiono w ruch i był już w toku, zanim w Wichrogrodzie doszło do naszej zasadzki. ', 0),
(581, 'koKR', 'Plan 2 jest równie prosty, ale będzie wymagał od nas więcej cierpliwości. Nasz człowiek w Przystani Menethilów dostał już zapłatę za swoje starania i spisał się znakomicie. Nie powinniśmy mieć żadnego problemu z dopadnięciem i pojmaniem celu, gdy już wypłyniemy. ', 0),
(582, 'koKR', 'Spodziewajcie się ataku kilka mil przed celem ich podróży. Tam będą czekać w zasadzce nasi??? sojusznicy???. Nie wiem, czemu zmuszono nas do sojuszu z tymi stworzeniami, ale nie mogę pozbyć się wrażenia, że i nas ktoś do tego przymusza. Ostatecznie nie będzie to miało znaczenia. Gdy cel znajdzie się w naszych rękach, będziemy na najlepszej drodze do odebrania Wichrogrodu tym, którzy nam go ukradli!', 0),
(607, 'koKR', 'Mistrzu Długobrody,\n\njak wiesz, my, Gromdardowie, mamy oko do doskonałości, więc jakość twoich tarcz nie jest dla nas tajemnicą.\n\nChętnie zamówię więc u ciebie taką tarczę. Wymagania zamieszczam na następnej stronie:\n\n\n', 0),
(627, 'koKR', 'Niszczycielska Druga Wojna z orkową Hordą pogrążyła Przymierze Lordaeronu w szoku i chaosie. Żądni krwi orkowie, prowadzeni przez potężnego wodza Orgrima Zgładziciela, nie tylko przetoczyli się przez krasnoludzkie ziemie Khaz Modan, ale też zrównali z ziemią wiele centralnych prowincji Lordaeronu. Nieustępliwym orkom udało się nawet spustoszyć odległe$Belfie królestwo Quel\'Thalas, zanim ich niszczycielski pochód wreszcie powstrzymano.', 0),
(628, 'koKR', 'Armie Przymierza pod wodzą sir Anduina Lothara, Uthera Światłodzierżcy i admirała Daelina Proudmoore\'a zepchnęły orków na południe, do zdruzgotanej krainy Azeroth – pierwszego królestwa, które padło pod bezlitosnym naporem orków.$B$BSiłom Przymierza pod wodzą sir Lothara udało się wyprzeć klany Zgładziciela z Lordaeronu z powrotem na kontrolowane przez orków ziemie Azeroth. Wojska Lothara otoczyły wulkaniczną cytadelę orków, Iglicę Czarnej Góry, i obległy jej umocnienia.', 0),
(629, 'koKR', 'W ostatnim desperackim zrywie Zgładziciel i jego zastępcy poprowadzili śmiałą szarżę z Iglicy i starli się z paladynami Lothara w samym sercu Płonących Stepów. Zgładziciel i Lothar stoczyli tytaniczny pojedynek, z którego obaj potężni wojownicy wyszli poturbowani i wyczerpani. Choć Zgładzicielowi ledwie udało się pokonać Lothara, śmierć wielkiego bohatera nie przyniosła skutku, na jaki liczył wódz.', 0),
(630, 'koKR', 'Turalyon, najbardziej zaufany zastępca Lothara, podniósł jego zakrwawioną tarczę i poprowadził pogrążonych w żałobie towarzyszy broni do zaciekłego kontrataku. Pod postrzępionymi sztandarami Lordaeronu i Azeroth wojska Turalyona wybiły większość pozostałych sił Zgładziciela w chwalebnym, lecz straszliwym pogromie.', 0),
(631, 'koKR', 'Obszarpanym, rozproszonym niedobitkom orków nie pozostało nic innego, jak uciec do ostatniego bastionu orkowej potęgi – Mrocznego Portalu.$B$BTuralyon i jego wojownicy ścigali ocalałych orków przez gnijące Moczary Smutków aż na skażone Jałowe Ziemie, gdzie stał Mroczny Portal. Tam, u stóp kolosalnego portalu, rozbita Horda i zaprawione w bojach Przymierze starły się w ostatniej, najkrwawszej bitwie Drugiej Wojny. ', 0),
(632, 'koKR', 'Przewyższeni liczebnie i doprowadzeni do szaleństwa przez klątwę żądzy krwi, orkowie nieuchronnie ulegli gniewowi Przymierza. Zgładziciela wzięto do niewoli i odeskortowano do Lordaeronu, a jego rozbite klany spędzono i przewieziono na północ – do Lordaeronu.', 0),
(633, 'koKR', 'Zaledwie kilka miesięcy po ukończeniu Strażnicy Otchłani energie Mrocznego Portalu skupiły się i otworzyły nowe przejście do Draenoru. Pozostałe klany orków pod wodzą starszego szamana Ner\'zhula ponownie wdarły się do Azeroth. Orkowie zamierzali wykraść szereg magicznych artefaktów, które zwiększyłyby moc Ner\'zhula, i otworzyć w Draenorze nowe portale, dzięki którym na zawsze uciekliby ze swojego skazanego na zagładę czerwonego świata.', 0),
(634, 'koKR', 'Przekonany, że Ner\'zhul planuje nową ofensywę przeciw Przymierzu, król Lordaeronu Terenas wysłał swoje armie do Draenoru, by raz na zawsze położyć kres orkowemu zagrożeniu. Prowadzone przez Khadgara i generała Turalyona siły Przymierza starły się z orkami na płonących pustkowiach. Mimo pomocy elfiej tropicielki Allerii, krasnoluda Kurdrana i doświadczonego żołnierza Danatha Khadgar nie zdołał powstrzymać Ner\'zhula przed otwarciem portali do innych światów.', 0),
(635, 'koKR', 'Potężne burze magiczne wywołane przez zbiegające się energie portali zaczęły rozrywać spustoszony świat. Ner\'zhul, w towarzystwie jedynie najbardziej zaufanych sług, zdołał uciec przez jeden z portali, podczas gdy Khadgar desperacko walczył, by odesłać towarzyszy do Azeroth. Zdając sobie sprawę, że zostaną uwięzieni w umierającym świecie, Khadgar i jego towarzysze bezinteresownie postanowili zniszczyć Mroczny Portal, by gwałtowna zagłada Draenoru nie wyrządziła Azeroth szkody.', 0),
(636, 'koKR', 'Według wszelkich relacji bohaterom udało się zniszczyć portal i ocalić Azeroth – czy jednak zdołali ujść przed agonią Draenoru, dopiero się okaże.', 0),
(637, 'koKR', 'Dziesięć tysięcy lat przed tym, jak orkowie i ludzie starli się w Pierwszej Wojnie, na świecie Azeroth istniał tylko jeden ogromny kontynent, otoczony bezkresnymi, wzburzonymi morzami. Ten ląd, zwany Kalimdorem, zamieszkiwało wiele odmiennych ras i stworzeń, które walczyły o przetrwanie pośród dzikich żywiołów budzącego się świata. W sercu mrocznego kontynentu leżało tajemnicze jezioro jarzących się energii. ', 0),
(638, 'koKR', 'Jezioro, które później nazwano Studnią Wieczności, było prawdziwym sercem magii i naturalnej mocy świata. Czerpiąc energię z nieskończonej Wielkiej Ciemności poza światem, Studnia działała jak mistyczne źródło, rozsyłając swoje potężne energie po całym świecie, by karmiły życie we wszystkich jego cudownych postaciach.$B$BZ czasem prymitywne plemię nocnych humanoidów ostrożnie dotarło na brzegi hipnotyzującego, zaczarowanego jeziora.', 0),
(639, 'koKR', 'Dzikie, koczownicze humanoidy, przyciągnięte przez dziwne energie Studni, zbudowały prymitywne domostwa na jej spokojnych brzegach. Z czasem kosmiczna moc Studni odmieniła to dziwne plemię, czyniąc je silnym, mądrym i praktycznie nieśmiertelnym. Plemię przyjęło nazwę Kaldorei, co w ich ojczystym języku oznaczało „dzieci gwiazd”. Aby uczcić swoje rozkwitające społeczeństwo, wznieśli wokół jeziora wielkie budowle i świątynie. ', 0),
(640, 'koKR', 'Kaldorei, czyli nocne elfy, jak ich później nazwano, czcili boginię księżyca Elunę i wierzyli, że za dnia śpi ona w lśniących głębinach Studni. Pierwsi kapłani i wieszczowie nocnych elfów badali Studnię z nienasyconą ciekawością, pragnąc zgłębić jej niezmierzone tajemnice i moc. W miarę rozwoju swej społeczności nocne elfy przemierzyły$Bcały Kalimdor i napotkały niezliczone zamieszkujące go istoty.', 0),
(641, 'koKR', 'Jedynymi istotami, które budziły w nich respekt, były pradawne i potężne smoki. Choć$Bte wielkie, wężowe bestie zwykle stroniły od innych, wiele robiły, by chronić znane ziemie przed zagrożeniami. Nocne elfy wierzyły, że smoki uważają się za obrońców świata i że najlepiej zostawić je w spokoju razem z ich tajemnicami.', 0),
(642, 'koKR', 'Z czasem ciekawość zawiodła nocne elfy do wielu potężnych istot, z którymi się zaprzyjaźniły, a nie najmniej ważną z nich był Cenarius, potężny półbóg pierwotnych puszcz. Wielkoduszny Cenarius polubił dociekliwe nocne elfy i poświęcał wiele czasu, by uczyć je o świecie natury. Spokojni Kaldorei poczuli głęboką więź z żywymi lasami Kalimdoru i radowali się harmonijną równowagą przyrody.', 0),
(643, 'koKR', 'A jednak w miarę upływu zdawałoby się niekończących się wieków cywilizacja nocnych elfów rozrastała się zarówno terytorialnie, jak i kulturowo. Ich świątynie, drogi i siedziby rozciągały się na całym mrocznym kontynencie. Aszara, piękna i obdarzona wielkimi talentami królowa nocnych elfów, wzniosła na brzegu Studni ogromny, zachwycający pałac, w którego wysadzanych klejnotami salach mieszkali jej ulubieni słudzy.', 0),
(644, 'koKR', 'Jej słudzy, których nazywała Quel\'dorei, czyli „Wysoko Urodzonymi”, spełniali każde jej polecenie i uważali się za lepszych od reszty pobratymców z niższych kast. Choć królowa Aszara była kochana przez cały swój lud, zazdrosne masy potajemnie nienawidziły Wysoko Urodzonych.$B$BPodzielając ciekawość kapłanów wobec Studni Wieczności, Aszara poleciła wykształconym Wysoko Urodzonym zgłębić jej tajemnice i odkryć jej prawdziwe przeznaczenie w świecie.', 0),
(645, 'koKR', 'Wysoko Urodzeni pogrążyli się w pracy i bez wytchnienia badali Studnię. Z czasem nauczyli się kształtować jej kosmiczne energie i nad nimi panować. W miarę postępu lekkomyślnych eksperymentów odkryli, że nowo zdobytej mocy mogą używać do tworzenia lub niszczenia, wedle własnej woli. Nieszczęśni Wysoko Urodzeni natrafili na pierwotną magię i postanowili poświęcić się jej opanowaniu.', 0),
(646, 'koKR', 'Choć zgadzali się, że magia jest z natury niebezpieczna, jeśli obchodzić się z nią nieodpowiedzialnie, Aszara i jej Wysoko Urodzeni zaczęli uprawiać sztukę czarów z lekkomyślną swobodą. Cenarius i wielu mądrych uczonych spośród nocnych elfów ostrzegało, że igranie z tak wyraźnie niestabilną sztuką magii może skończyć się tylko nieszczęściem. Mimo to Aszara i jej zwolennicy uparcie dalej rozwijali swą rosnącą moc.', 0),
(647, 'koKR', 'Wraz ze wzrostem ich mocy Aszara i Wysoko Urodzeni wyraźnie się zmienili. Wyniosła, zdystansowana arystokracja stawała się coraz bardziej bezduszna i okrutna wobec innych nocnych elfów. Mroczny, posępny cień przesłonił niegdyś urzekającą urodę Aszary. Królowa zaczęła odsuwać się od kochających ją poddanych i nie chciała rozmawiać z nikim poza zaufanymi kapłanami spośród Wysoko Urodzonych.', 0),
(648, 'koKR', 'Młody, zuchwały uczony imieniem Furion Burzogniewny, który poświęcił wiele czasu na badanie oddziaływania Studni, zaczął podejrzewać, że jakaś straszliwa moc deprawuje Wysoko Urodzonych i jego ukochaną królową. Choć nie potrafił sobie wyobrazić zła, które miało nadejść, wiedział, że życie nocnych elfów wkrótce odmieni się na zawsze...', 0),
(649, 'koKR', '-Idealnie okrągła, średnicy od pięści do łokcia.\n\n-Ćwieki wzdłuż krawędzi. Srebrne.\n\n-Jeden duży ćwiek pośrodku, szeroki na trzy palce. Srebrny.\n\n-Dębowa, wzmocniona żelazem.\n\n-Moje imię, Gringer Gromdarda, wyryte wzdłuż górnego rantu.\n', 0),
(650, 'koKR', 'Zapłata nastąpi zwykłą drogą. Proszę też wypłacić okazicielowi tego zamówienia standardową opłatę za doręczenie. Można ją doliczyć do ceny tarczy.\n\n\n\nZ wyrazami szacunku i podziękowaniami\n--Gringer Gromdarda', 0),
(831, 'koKR', 'Na kolejnych stronach znajdziesz listę materiałów potrzebnych do wykonania zbroi hartowanej w ogniu. Powodzenia w boju.\n\n\n-Furen Długobrody\n', 0),
(832, 'koKR', 'Osmalone kły pająków:$B$BRuda incendycytu, którą można znaleźć w jaskini w pobliżu Skały Thelgen, osmaliła żyjące tam pająki.$B$BJad w ich kłach wrze i reaguje z samymi kłami, tworząc niezwykle twardą substancję.', 0),
(833, 'koKR', 'Zwęglone rogi:$B$BPodobnie jak osmalone kły pająków, zwęglone rogi chimer zamieszkujących Zwęgloną Dolinę w Górach Szponogłazach w Kalimdorze mają wysoko cenioną właściwość.$B$BRozklepane na płasko i odpowiednio obrobione stają się niezwykle odporne na obciążenia.', 0),
(834, 'koKR', 'Galwanizowany róg:$B$BWytrzymałość rzadkiego galwanizowanego rogu to podstawa całej zbroi, którą wykonam, więc również on musi zostać zdobyty.$B$BMożna go zdobyć od rzadkiej matki chimer ze Zwęglonej Doliny.', 0),
(835, 'koKR', 'Fiolka flogistonu:$B$BOstatni etap wykonania zbroi będzie wymagał niezwykle gorącej kuźni. Aby uzyskać potrzebną temperaturę, muszę mieć fiolkę flogistonu.$B$BJedynym znanym wytwórcą tej substancji jest słynny kolcozwierz Roogug, który nie odda jej bez walki. Roogug mieszka głęboko w Ciernisku Brzytwoskórych, na południu Pustkowi.', 0),
(891, 'koKR', 'Zawiłe symbole i piktogramy wypełniające strony tego podręcznika są tak tajemne, że nie sposób ich pojąć.', 0),
(1031, 'koKR', '<HTML>\n<BODY>\n<BR/>\n<BR/>\n<P>\nPamięci mojego drogiego mentora, Horatia M. Montgomery\'ego, lek. med. Uzdrowiciela, Nauczyciela, Przyjaciela.\n</P>\n<BR/>\n<H1 align="center">\n50 BTFT - 25 ATFT\n</H1>\n<BR/>\n<P>\n„Świat jest pełen chorych i znużonych. Naszym zadaniem jako uzdrowicieli, NIE, jako mężczyzn i kobiet medycyny, jest oczyścić ich WSZYSTKICH z ‚-itisów’”.\n</P>\n<BR/>\n<P>\n- H.M.M., lek. med., dr, dr praw, arcymistrz rolnik, tancerz nad tancerzami, przyjaciel zwierząt\n</P>\n<BR/>\n</BODY>\n</HTML>\n', 0),
(1051, 'koKR', 'Strażnicy tej wieży wydają się wyjątkowo podatni na moje ataki. Kiedy przeczesywałam tyły wieży, zauważyła mnie patrolująca strażniczka i zaatakowała. Bez trudu ją załatwiłam celnym podbiciem oka, a potem ciosem w plecy.\n\nCzekałam w ukryciu, aż jej partner przyjdzie sprawdzić, skąd to zamieszanie. Patrolujący podszedł do krzaków, w które zaciągnęłam ciało, i zaczął przeszukiwać okolicę. Powoli i ostrożnie podkradłam się do niego od tyłu, żeby nie zdradzić zasadzki.', 0),
(1052, 'koKR', 'Gdy nadarzyła się okazja, wbiłam mu sztylet w plecy! Jego płuca szybko ustąpiły pod siłą ciosu, a ciało z głuchym łoskotem runęło na ziemię.\n\nZasadzka była tak szybka i gwałtowna, że biedny głupiec nie zdążył nawet krzyknąć z bólu. Co ciekawe, kiedy wyciągnęłam ostrze z jego pleców, z przedziurawionego strażnika wydobył się paskudny odór.\n\n', 0),
(1053, 'koKR', 'Wygląda na to, że cokolwiek Klaven trzyma zamknięte w skrzyni, szkodzi mieszkańcom wieży. Podejrzewam, że pozostali strażnicy mogą mieć podobne słabości, a być może nawet sam Klaven padł ofiarą tego skażenia.\n\nAgentka Amber Kearnen\nAgentka terenowa WW:7, R8', 0),
(1151, 'koKR', 'Spółka Gitgeszeft <nieczytelny tekst> Wygląda na to, że te głupki omal nie zmiotły całego swojego przedsięwzięcia, próbując ustabilizować mieszankę.\n\n<kilka stron wygląda na wyrwane>\n\n', 0),
(1152, 'koKR', 'Zauważyłem, że skażenie jest niezwykle zabójcze. Wyobraźmy sobie, gdyby <nieczytelny tekst> Hahaha!', 0),
(1153, 'koKR', 'Czy ja wariuję? Dziś odciąłem głowę jednemu z moich najbardziej zaufanych strażników, żeby lepiej przyjrzeć się jego duszy. Kiedy zaglądałem w jego przeciętą tchawicę, dotarło do mnie, że od kilku dni nic nie jadłem!\n', 0),
(1154, 'koKR', 'Mathias Shaw przysłał chłopca na posyłki, żeby mnie zabił. <nieczytelny tekst>\n\nTeraz patroluje na zewnątrz. Bezmyślny, martwy truteń.\n\nHahahah!', 0),
(1155, 'koKR', 'VanCleef...<nieczytelny tekst>\n\nWEZWAŁ mnie?? ZA KOGO ON SIĘ MA?? Jestem Klaven Mortwake! Nie pozwolę, by jakiś insekt mówił mi, co mam robić!\n\n<pozostałych stron w księdze brakuje>', 0),
(1271, 'koKR', 'Dyscypliny inżynierii$B$BMożna się spierać, która rasa pierwsza stworzyła naukę inżynierii w Azeroth, ale nie ma wątpliwości, które rasy są jej głównymi orędownikami w czasach współczesnych: gnomy i gobliny. Ich zbiorowe oddanie inżynierii nie tylko napędzało fantastyczne wynalazki w czymś, co śmiało można nazwać magiczną Erą Wynalazków, ale też podsycało zażartą rywalizację między obiema rasami. Nigdzie nie widać tego wyraźniej niż w ich odmiennych dyscyplinach.', 0),
(1272, 'koKR', 'Gnomia inżynieria$B$BGnomy jako rasa celują w projektowaniu przedmiotów, które mają kształtować otaczający je świat i nad nim panować. Choć mają pobieżne pojęcie o materiałach wybuchowych i broni, gnomia inżynieria skupia się raczej na przedmiotach, które dosłownie próbują ułatwić życie i uczynić świat bardziej przystępnym. To dyscyplina teoretycznych możliwości, które gnomia smykałka zamienia w rzeczywistość. Niektóre możliwości jednak nigdy nie zostają w pełni urzeczywistnione.', 0),
(1273, 'koKR', 'Goblińska inżynieria$B$BJako rasa, która niemal w każdym konflikcie pozostaje neutralna, gobliny dołożyły wszelkich starań, by zamienić naukę w zysk. Stawiają na praktyczne zastosowania inżynierii, czego dowodem są ich radykalne projekty materiałów wybuchowych, broni palnej i maszyn. Goblińska inżynieria interesuje się teorią tylko przelotnie; ich wynalazkom zwykle nie zdarza się nie działać – raczej działają za dobrze. Z pewnością nie jest to nic dla strachliwych.', 0),
(1274, 'koKR', 'Nauka dyscyplin$B$BGnomy i gobliny tak zazdrośnie strzegą swojej wiedzy przed sobą nawzajem, że niemal nie sposób poznać obu dyscyplin jednocześnie. Każda z ras, bez względu na przynależność polityczną, udostępnia wiedzę o swojej dyscyplinie wyłącznie tym, którzy zgodzą się zrezygnować ze zgłębiania dyscypliny drugiej strony. Jeśli na przykład uczeń wybierze gnomią inżynierię, żadna wiedza o inżynierii goblińskiej nigdy nie zostanie mu udostępniona.', 0),
(1275, 'koKR', 'Decyzje nieodwracalne$B$BPoprzedni rozdział zwrócił uwagę na ważną kwestię dotyczącą dwóch dyscyplin inżynierii, którą dla dobra nauki trzeba powtórzyć. Decyzja o wyborze jednej z nich oznacza, że schematy dyscypliny przeciwnej nie będą dostępne do nauki. Choć taka nieodwołalność może onieśmielać inżyniera amatora, doświadczony inżynier rozumie, że gnomy i gobliny strzegą swoich sekretów z całą żarliwością; lepiej mieć choć część wiedzy niż żadnej.', 0),
(1276, 'koKR', 'Cytaty$B$B„Chcesz wiedzieć coś o goblińskiej inżynierii? Zapytaj o nią jednego z ich najzdolniejszych inżynierów – chyba nazywa się »Kikutek Bezpalcy«. Chcesz wiedzieć, skąd to przezwisko? TO WŁAŚNIE jest goblińska inżynieria”.$B-- Ringo Tragediction, gnomi inżynier$B$B„Możecie mówić o nas, goblinach, co chcecie, ale powiem wam jedno: MY MAMY MATERIAŁY WYBUCHOWE!”$B-- Yazz Nitrowidelec, gobliński bombardier', 0),
(1277, 'koKR', 'Więcej cytatów!$B$B„Znasz to uczucie, kiedy kończysz coś budować, włączasz to po raz pierwszy i czujesz moc i radość wynalazczości, gdy twoje urządzenie budzi się do życia? Gnomy go nie znają”.$B-- Nixx Sprężynotryb, mistrz goblińskiej inżynierii z Gadżetonu$B$B„Inżynieria polega na tym, żeby wziąć fantazję i zrobić z niej coś fantastycznego!”$B-- Rovis McCrankenspank, gnomi wynalazca', 0),
(1803, 'koKR', 'Lekkomyślne używanie magii przez Wysoko Urodzonych sprawiło, że fale energii rozchodziły się ze Studni Wieczności w Wielką Ciemność. Te płynące fale energii wyczuły straszliwe, obce umysły. Sargeras – Wielki Wróg wszelkiego życia, Niszczyciel Światów – poczuł potężne fale i zwrócił się ku ich odległemu źródłu.', 0),
(1804, 'koKR', 'Gdy dostrzegł pierwotny świat Azeroth i wyczuł bezgraniczne energie Studni Wieczności, Sargerasa ogarnął nienasycony głód. Wielki mroczny bóg Bezimiennej Pustki postanowił zniszczyć ten młody świat i zagarnąć jego energie dla siebie.', 0),
(1805, 'koKR', 'Sargeras zebrał swój ogromny Płonący Legion i wyruszył ku niczego niepodejrzewającemu światu Azeroth. Legion składał się z miliona wrzeszczących demonów, wyrwanych z najdalszych zakątków wszechświata, a demony te łaknęły podbojów. Porucznicy Sargerasa, Archimond Plugawiciel i Mannoroth Niszczyciel, przygotowali swoje piekielne sługi do ataku.', 0),
(1806, 'koKR', 'Królowa Aszara, przytłoczona straszliwą ekstazą swej magii, uległa nieodpartej potędze Sargerasa i zgodziła się wpuścić go do swojego świata. Nawet jej słudzy z Wysoko Urodzonych poddali się nieuniknionemu spaczeniu magii i zaczęli czcić Sargerasa jako swego boga. Aby okazać wierność Legionowi, Wysoko Urodzeni pomogli królowej otworzyć w głębinach Studni Wieczności ogromny, wirujący portal.', 0),
(1807, 'koKR', 'Gdy wszystkie przygotowania dobiegły końca, Sargeras rozpoczął swą katastrofalną inwazję na Azeroth. Demoniczni wojownicy Płonącego Legionu wdarli się do świata przez Studnię Wieczności i obległy śpiące miasta nocnych elfów. Prowadzony przez Archimonda i Mannorotha Legion zalał ziemie Kalimdoru, pozostawiając za sobą jedynie popiół i żałobę.', 0),
(1808, 'koKR', 'Demoniczni czarnoksiężnicy sprowadzali z nieba ogniste infernale, które niczym piekielne meteory spadały na smukłe iglice świątyń Kalimdoru. Oddział płonących, krwiożerczych zabójców zwanych Strażnikami Zagłady maszerował przez pola Kalimdoru, wyrzynając wszystkich na swojej drodze. Sfory dzikich, demonicznych ogarów spaczenia pustoszyły kraj, nie napotykając oporu. Choć dzielni wojownicy Kaldorei ruszyli bronić swej pradawnej ojczyzny, musieli krok po kroku ustępować przed furią natarcia Legionu.', 0),
(1809, 'koKR', 'Zadanie znalezienia pomocy dla udręczonego ludu spadło na Malfuriona Burzogniewnego. Malfurion, którego własny brat, Illidan, uprawiał magię Wysoko Urodzonych, był oburzony szerzącym się spaczeniem wśród arystokracji. Przekonawszy Illidana, by porzucił swą niebezpieczną obsesję, Malfurion wyruszył na poszukiwanie Cenariusa, by zebrać siły oporu.', 0),
(1810, 'koKR', 'Piękna młoda kapłanka Tyrande zgodziła się towarzyszyć braciom w imię Eluny. Choć zarówno Malfurion, jak i Illidan kochali idealistyczną kapłankę, serce Tyrande należało wyłącznie do Malfuriona. Illidan miał bratu za złe rodzące się uczucie między nim a Tyrande, ale wiedział, że jego zawód miłosny jest niczym w porównaniu z bólem magicznego uzależnienia.', 0),
(1811, 'koKR', 'Illidan, który uzależnił się od wzmacniających energii magii, z trudem panował nad niemal przemożnym głodem, by znów zaczerpnąć z energii Studni. Jednak dzięki cierpliwemu wsparciu Tyrande zdołał się powstrzymać i pomóc bratu odnaleźć stroniącego od innych półboga Cenariusa.', 0),
(1812, 'koKR', 'Cenarius, który mieszkał w świętych Gajach Luny na odległej Górze Hyjal, zgodził się pomóc nocnym elfom, odnajdując pradawne smoki i pozyskując ich wsparcie. Smoki, prowadzone przez wielką czerwoną smoczycę Alexstrazę, zgodziły się wysłać swoje potężne stada do walki z demonami i ich piekielnymi panami.', 0),
(1813, 'koKR', 'Cenarius, przyzywając duchy zaczarowanych lasów, zgromadził armię pradawnych drzewców i poprowadził ją przeciwko Legionowi w śmiałym natarciu lądowym. Gdy sojusznicy nocnych elfów zbiegli się pod świątynią Aszary i Studnią Wieczności, wybuchła wojna na całego. Mimo siły nowych sojuszników Malfurion i jego towarzysze zrozumieli, że samą siłą oręża Legionu nie da się pokonać.', 0),
(1814, 'koKR', 'Podczas gdy wokół stolicy Aszary szalała tytaniczna bitwa, ogarnięta obłędem królowa w napięciu oczekiwała przybycia Sargerasa. Władca Legionu przygotowywał się, by przejść przez Studnię Wieczności i wkroczyć do spustoszonego świata. Gdy jego niewyobrażalnie wielki cień coraz bardziej zbliżał się do powierzchni Studni, Aszara zgromadziła najpotężniejszych spośród swoich Wysoko Urodzonych. Tylko łącząc swą magię w jednym, skupionym zaklęciu, mogli stworzyć wrota dość wielkie, by Sargeras zdołał przez nie przejść.', 0),
(1815, 'koKR', 'Gdy bitwa szalała na płonących polach Kalimdoru, wydarzenia przybrały straszliwy obrót. Szczegóły tych zdarzeń zaginęły w mrokach dziejów, wiadomo jednak, że Neltharion, smoczy Aspekt Ziemi, oszalał podczas kluczowego starcia z Płonącym Legionem. Zaczął rozpadać się na części, a z jego ciemnej skóry buchnęły płomienie i furia. Nazwawszy się Śmiercioskrzydłym, płonący smok zwrócił się przeciwko swoim pobratymcom i przepędził pięć smoczych stad z pola bitwy.', 0),
(1816, 'koKR', 'Nagła zdrada Śmiercioskrzydłego była tak niszczycielska, że pięć smoczych stad już nigdy w pełni się nie podniosło. Ranne i wstrząśnięte, Alexstraza i inne szlachetne smoki musiały porzucić swoich śmiertelnych sojuszników. Malfurion i jego towarzysze, teraz w beznadziejnej mniejszości, ledwie przeżyli nawałnicę, która nastąpiła.', 0),
(1817, 'koKR', 'Malfurion, przekonany, że Studnia Wieczności jest pępowiną łączącą demony ze światem materialnym, nalegał, by ją zniszczyć. Jego towarzysze, wiedząc, że Studnia jest źródłem ich nieśmiertelności i mocy, byli przerażeni tym pochopnym pomysłem. Tyrande jednak dostrzegła mądrość teorii Malfuriona i przekonała Cenariusa oraz ich towarzyszy, by szturmem zdobyli świątynię Aszary i znaleźli sposób, by na zawsze zamknąć Studnię.', 0),
(1828, 'koKR', 'Nieliczne nocne elfy, które przeżyły straszliwą eksplozję, zebrały się na prymitywnie skleconych tratwach i powoli popłynęły ku jedynemu lądowi w zasięgu wzroku. Jakimś cudem, dzięki łasce Eluny, Malfurion, Tyrande i Cenarius przeżyli Wielki Rozłam. Znużeni bohaterowie zgodzili się poprowadzić pozostałych ocalałych i założyć nowy dom dla swojego ludu.', 0),
(1829, 'koKR', 'Podróżując w milczeniu, oglądali szczątki swojego świata i zrozumieli, że to ich własne namiętności sprowadziły zniszczenie, które widzieli wokół. Choć Sargeras i jego Legion zostali wyrwani ze świata przez zagładę Studni, Malfurionowi i jego towarzyszom pozostało rozmyślać nad straszliwą ceną zwycięstwa.', 0),
(1830, 'koKR', 'Wielu Wysoko Urodzonych przeżyło kataklizm bez szwanku. Razem z innymi nocnymi elfami dotarli do brzegów nowego lądu. Choć Malfurion nie ufał pobudkom Wysoko Urodzonych, był przekonany, że bez energii Studni nie zdołają wyrządzić prawdziwych szkód.', 0),
(1831, 'koKR', 'Gdy znużona gromada nocnych elfów wylądowała na brzegach nowego lądu, okazało się, że święta góra Hyjal przetrwała katastrofę. Pragnąc założyć dla siebie nowy dom, Malfurion i nocne elfy wspięli się po zboczach Hyjal i dotarli na jej smagany wiatrem szczyt. Gdy zeszli do zalesionej niecki wtulonej między ogromne wierzchołki góry, znaleźli małe, spokojne jezioro. Ku swemu przerażeniu odkryli, że jego wody zostały skażone magią.', 0),
(1832, 'koKR', 'Illidan, który również przeżył Rozłam, dotarł na szczyt Hyjal na długo przed Malfurionem i nocnymi elfami. W szaleńczej próbie zachowania przepływu magii w świecie Illidan wlał do górskiego jeziora zawartość swoich fiolek, w których przechowywał cenną wodę ze Studni Wieczności.', 0),
(1833, 'koKR', 'Potężne energie Studni szybko rozgorzały i połączyły się w nową Studnię Wieczności. Rozradowany Illidan, przekonany, że nowa Studnia będzie darem dla przyszłych pokoleń, był wstrząśnięty, gdy Malfurion go wytropił. Malfurion wyjaśnił bratu, że magia jest z natury chaotyczna i że jej używanie nieuchronnie doprowadzi do powszechnego zepsucia i niezgody. Mimo to Illidan nie chciał wyrzec się swej magicznej mocy.', 0),
(1834, 'koKR', 'Wiedząc doskonale, dokąd w końcu zaprowadzą bezwzględne knowania Illidana, Malfurion postanowił raz na zawsze rozprawić się ze swym opętanym żądzą władzy bratem. Z pomocą Cenariusa uwięził Illidana w ogromnym podziemnym kurhanie, gdzie ten miał pozostać spętany i bezsilny do końca czasu. Aby zapewnić, że brat nie ucieknie, Malfurion powierzył młodej strażniczce, Maiev Cienistej Pieśni, rolę osobistej strażniczki więziennej Illidana.', 0),
(1835, 'koKR', 'Obawiając się, że zniszczenie nowej Studni mogłoby sprowadzić jeszcze większą katastrofę, nocne elfy postanowiły zostawić ją w spokoju. Malfurion oznajmił jednak, że już nigdy nie będą uprawiać magii. Pod czujnym okiem Cenariusa zaczęły zgłębiać pradawną sztukę druidyzmu, która miała pozwolić im uleczyć zranioną ziemię i odtworzyć ukochane lasy u podnóża Góry Hyjal.', 0),
(1836, 'koKR', 'Przez wiele lat nocne elfy niestrudzenie pracowały, by odbudować to, co zdołały, ze swej pradawnej ojczyzny. Pozostawiwszy zrujnowane świątynie i drogi na pastwę zieleni, wznosiły nowe domy wśród bujnych drzew i ocienionych wzgórz u podnóża Hyjal. Z czasem smoki, które przeżyły Wielki Rozłam, wyszły ze swoich tajemnych siedzib.', 0),
(1837, 'koKR', 'Alexstraza Czerwona, Ysera Zielona i Nozdormu Brązowy zstąpili na spokojne polany druidów i przyjrzeli się owocom pracy nocnych elfów. Malfurion, który stał się arcydruidem o ogromnej mocy, powitał potężne smoki i opowiedział im o powstaniu nowej Studni Wieczności.', 0),
(1838, 'koKR', 'Wielkie smoki zaniepokoiły się tą złą nowiną i uznały, że dopóki Studnia istnieje, Legion może pewnego dnia powrócić i znów zaatakować świat. Malfurion i trzy smoki zawarli pakt, by strzec Studni i dopilnować, że wysłannicy Płonącego Legionu nigdy nie znajdą drogi z powrotem do świata.', 0),
(1839, 'koKR', 'Alexstraza Życiodajna umieściła w samym sercu Studni Wieczności jeden zaczarowany żołądź. Pobudzony przez potężne, magiczne wody żołądź ożył i wyrósł w kolosalne drzewo. Korzenie potężnego drzewa wyrastały z wód Studni, a jego bujna korona zdawała się sięgać sklepienia nieba.', 0),
(1840, 'koKR', 'Ogromne drzewo miało być wiecznym symbolem więzi nocnych elfów z naturą, a jego życiodajne energie z czasem miały rozejść się dalej i uleczyć resztę świata. Nocne elfy nadały swemu Drzewu Świata nowe imię – Nordrassil, co w ich ojczystym języku znaczyło „korona niebios”.', 0),
(1841, 'koKR', 'Nozdormu Wiekuisty rzucił na Drzewo Świata zaklęcie, dzięki któremu, dopóki kolosalne drzewo stało, nocne elfy nigdy nie miały się starzeć ani padać ofiarą chorób i zarazy.', 0),
(1842, 'koKR', 'Ysera Śniąca również rzuciła zaklęcie na Drzewo Świata, łącząc je z własną domeną – eteryczną krainą zwaną Szmaragdowym Snem. Szmaragdowy Sen, rozległy, nieustannie zmieniający się świat duchów, istniał poza granicami świata materialnego. Ze Snu Ysera kierowała przypływami i odpływami natury oraz ewolucyjną drogą samego świata.', 0),
(1843, 'koKR', 'Druidzi nocnych elfów, w tym sam Malfurion, zostali związani ze Snem za pośrednictwem Drzewa Świata. W ramach mistycznego paktu druidzi zgodzili się zapadać w sen na całe stulecia, by ich duchy mogły przemierzać nieskończone Ścieżki Snu Ysery. Choć druidów smuciła myśl o utracie tylu lat życia w uśpieniu, bezinteresownie zgodzili się dotrzymać umowy z Yserą.', 0),
(1876, 'koKR', 'Gdy na północnych ziemiach zabrakło trolli, elfy z Quel\'Thalas skupiły wysiłki na odbudowie swej wspaniałej ojczyzny. Zwycięskie armie Aratoru powróciły do domu, na południowe ziemie Stromu.', 0),
(1877, 'koKR', 'Ludzka społeczność Aratoru rosła i prosperowała, jednak Thoradin, obawiając się, że jego królestwo rozpadnie się, jeśli nadmiernie się rozrośnie, obstawał przy tym, by Strom pozostał ośrodkiem aratorskiego imperium. Po wielu latach pokojowego rozwoju i handlu potężny Thoradin zmarł ze starości, a młodsze pokolenie Aratoru mogło odtąd rozszerzać imperium poza ziemie Stromu.', 0),
(1878, 'koKR', 'Pierwotna setka magów, których elfy nauczyły tajników magii, poszerzyła swą moc i znacznie dokładniej zgłębiła mistyczne dyscypliny tkania zaklęć. Magowie ci, wybrani niegdyś ze względu na silną wolę i szlachetnego ducha, zawsze uprawiali magię ostrożnie i odpowiedzialnie; przekazali jednak swe sekrety i moce nowemu pokoleniu, które nie miało pojęcia o trudach wojny ani o potrzebie powściągliwości.', 0),
(1879, 'koKR', 'Ci młodsi magowie zaczęli uprawiać magię dla własnej korzyści, a nie z poczucia odpowiedzialności wobec bliźnich.', 0),
(1880, 'koKR', 'W miarę jak imperium rosło i rozszerzało się na nowe ziemie, młodzi magowie także rozeszli się po południowych krainach. Władając mistyczną mocą, chronili swych pobratymców przed dzikimi stworzeniami i umożliwiali wznoszenie nowych miast-państw na dziczy. Jednak wraz ze wzrostem swej mocy magowie stawali się coraz bardziej zarozumiali i odizolowani od reszty społeczeństwa.', 0),
(1881, 'koKR', 'Drugie aratorskie miasto-państwo, Dalaran, założono na ziemiach na północ od Stromu. Wielu początkujących czarodziejów porzuciło krępujące ograniczenia Stromu i udało się do Dalaranu, gdzie mieli nadzieję swobodniej korzystać ze swych nowych mocy. Magowie ci wykorzystali swe umiejętności, by wznieść zaczarowane iglice Dalaranu, i oddawali się z upodobaniem swoim studiom.', 0),
(1882, 'koKR', 'Mieszkańcy Dalaranu tolerowali poczynania magów i pod ochroną swych władających magią obrońców rozwinęli kwitnącą gospodarkę. Jednak w miarę jak coraz więcej magów uprawiało swoją sztukę, tkanka rzeczywistości wokół Dalaranu zaczęła słabnąć i się rozdzierać.', 0),
(1883, 'koKR', 'Złowrodzy wysłannicy Płonącego Legionu, wygnani, gdy zapadła się Studnia Wieczności, zostali zwabieni z powrotem do świata przez lekkomyślne czary magów z Dalaranu. Choć te stosunkowo słabe demony nie pojawiły się w wielkiej liczbie, zasiały na ulicach Dalaranu sporo zamętu i chaosu.', 0),
(1884, 'koKR', 'Większość tych spotkań z demonami była odosobnionymi zdarzeniami, a rządzący Magokraci robili, co mogli, by ukryć je przed ludem. Najpotężniejszych magów wysyłano, by schwytali nieuchwytne demony, lecz często okazywało się, że nie mają szans w starciu z samotnymi wysłannikami potężnego Legionu.', 0),
(1885, 'koKR', 'Po kilku miesiącach zabobonni chłopi zaczęli podejrzewać, że władający czarami władcy ukrywają przed nimi coś strasznego. Ulicami Dalaranu zaczęły krążyć plotki o rewolucji, a ogarnięci podejrzliwością mieszkańcy kwestionowali pobudki i praktyki magów, których niegdyś podziwiali. Magokraci, obawiając się buntu chłopów i tego, że Strom podejmie przeciwko nim działania, zwrócili się do jedynych, którzy ich zdaniem mogli zrozumieć ich szczególny problem: do elfów.', 0),
(1886, 'koKR', 'Usłyszawszy od Magokratów o aktywności demonów w Dalaranie, elfy szybko wysłały na ziemie ludzi swoich najpotężniejszych czarodziejów. Elfi czarodzieje zbadali prądy energii w Dalaranie i sporządzili szczegółowe raporty o wszelkiej zaobserwowanej aktywności demonów. Doszli do wniosku, że choć w świecie grasuje zaledwie kilka demonów, sam Legion pozostanie poważnym zagrożeniem, dopóki ludzie będą władać siłami magii.', 0),
(1887, 'koKR', 'Rada Srebrnej Luny, która rządziła elfami z Quel\'Thalas, zawarła tajny pakt z władcami Magokratami z Dalaranu. Elfy opowiedziały Magokratom o dziejach pradawnego Kalimdoru i o Płonącym Legionie – o historii, która wciąż zagrażała światu. Oznajmiły ludziom, że dopóki będą używać magii, będą musieli chronić swoich obywateli przed złowrogimi wysłannikami Legionu.', 0),
(1888, 'koKR', 'Magokraci zaproponowali, by obdarzyć mocą jednego śmiertelnego czempiona, który wykorzystywałby ją, by toczyć niekończącą się, tajną wojnę z Legionem. Podkreślano, że większość ludzkości nigdy nie może się dowiedzieć o Strażnikach ani o zagrożeniu ze strony Legionu, by strach i panika nie wywołały zamieszek. Elfy przystały na tę propozycję i założyły tajne stowarzyszenie, które miało czuwać nad wyborem Strażnika i pomagać powstrzymywać narastanie chaosu w świecie.', 0),
(1889, 'koKR', 'Stowarzyszenie odbywało tajne spotkania w mrocznych Polanach Tirisfal, gdzie wysokie elfy po raz pierwszy osiedliły się w Lordaeronie. Dlatego tajny zakon nazwano Strażnikami Tirisfal. Śmiertelni czempioni wybrani na Strażników otrzymywali niewiarygodną moc zarówno elfiej, jak i ludzkiej magii. Choć naraz miał istnieć tylko jeden Strażnik, posiadał on tak ogromną moc, że w pojedynkę mógł odpierać wysłanników Legionu, gdziekolwiek pojawili się w świecie.', 0),
(1890, 'koKR', 'Moc Strażnika była tak wielka, że tylko Rada Tirisfal mogła wybierać kandydatów na następców tego urzędu. Ilekroć Strażnik się zestarzał albo zmęczył tajną wojną z chaosem, Rada wybierała nowego czempiona i w kontrolowanych warunkach uroczyście przelewała moc Strażnika na nowego wybrańca.', 0),
(1891, 'koKR', 'Mijały pokolenia, a Strażnicy bronili rzesz ludzkości przed niewidzialnym zagrożeniem ze strony Płonącego Legionu na ziemiach Aratoru i Quel\'Thalas. Arator rósł i prosperował, a używanie magii rozprzestrzeniało się po całym imperium. Tymczasem Strażnicy czujnie wypatrywali oznak aktywności demonów.', 0),
(1914, 'koKR', 'Krasnoludy z Góry Żelaznej Kuźni żyły w pokoju przez wiele długich stuleci. Jednak ich społeczność rozrosła się za bardzo jak na granice górskich miast. Choć potężny najwyższy król Modimus Kowadlin rządził wszystkimi krasnoludami sprawiedliwie i mądrze, w krasnoludzkiej społeczności wyrosły trzy potężne stronnictwa.', 0),
(1915, 'koKR', 'Klan Miedziobrodych, którym rządził than Madoran Miedziobrody, był blisko związany z najwyższym królem i tradycyjnie bronił Góry Żelaznej Kuźni. Klan Dzikiego Młota, którym rządził than Khardros Dziki Młot, zamieszkiwał pogórze i urwiska u stóp góry i dążył do zdobycia większych wpływów w mieście.', 0),
(1916, 'koKR', 'Trzecim stronnictwem, klanem Czarnorytych, rządził than-czarnoksiężnik Thaurissan. Czarnoryci kryli się w najgłębszych mrokach pod górą i knuli zarówno przeciw Miedziobrodym, jak i przeciw Dzikim Młotom, swoim krewniakom.', 0),
(1917, 'koKR', 'Przez pewien czas trzy stronnictwa utrzymywały kruchy pokój, lecz napięcia wybuchły, gdy najwyższy król Kowadlin zmarł ze starości. Trzy rządzące klany ruszyły na wojnę o władzę nad samą Żelazną Kuźnią. Wojna domowa krasnoludów szalała pod ziemią przez wiele lat. W końcu Miedziobrodzi, którzy mieli największą stałą armię, wygnali Czarnorytych i Dzikie Młoty spod góry.', 0),
(1918, 'koKR', 'Khardros i jego wojownicy z klanu Dzikiego Młota wyruszyli na północ przez wrota zaporowe Dun Algaz i założyli własne królestwo w odległym szczycie Grim Batol. Tam Dzikie Młoty rozkwitły i odbudowały swoje skarbce. Thaurissanowi i jego Czarnorytym nie wiodło się tak dobrze. Upokorzeni i rozwścieczeni klęską, poprzysięgli zemstę Żelaznej Kuźni. Thaurissan poprowadził swój lud daleko na południe i założył miasto (które nazwał swoim imieniem) w pięknych Górach Rudej Grani.', 0),
(1919, 'koKR', 'Dobrobyt i upływ lat niewiele złagodziły urazę Czarnorytych do ich krewniaków. Thaurissan i jego żona czarodziejka, Modgud, przypuścili dwutorowy atak zarówno na Żelazną Kuźnię, jak i na Grim Batol. Czarnoryci byli zdecydowani zagarnąć całe Khaz Modan dla siebie.', 0),
(1920, 'koKR', 'Armie Czarnorytych uderzyły na twierdze swoich krewniaków i omal nie zdobyły obu królestw. Jednak Madoran Miedziobrody ostatecznie poprowadził swój klan do rozstrzygającego zwycięstwa nad czarnoksięską armią Thaurissana. Thaurissan i jego słudzy uciekli z powrotem w bezpieczne mury swego miasta, nieświadomi wydarzeń w Grim Batol, gdzie armii Modgud nie miało się powieść lepiej w starciu z Khardrosem i jego wojownikami z klanu Dzikiego Młota.', 0),
(1921, 'koKR', 'Stanąwszy naprzeciw wrogich wojowników, Modgud użyła swej mocy, by zasiać strach w ich sercach. Cienie poruszały się na jej rozkaz, a mroczne istoty wypełzały z głębin ziemi, by polować na Dzikie Młoty w ich własnych salach. W końcu Modgud przełamała bramy i obległa samą twierdzę. Dzikie Młoty broniły się rozpaczliwie, a sam Khardros przedarł się przez kłębiące się masy, by zabić królową czarodziejkę.', 0),
(1922, 'koKR', 'Po utracie królowej Czarnoryci rzucili się do ucieczki przed furią Dzikich Młotów. Pognali na południe, ku twierdzy swego króla, tylko po to, by natknąć się na armie Żelaznej Kuźni, które przybyły z odsieczą Grim Batol. Zmiażdżone między dwiema armiami, pozostałe siły Czarnorytych zostały doszczętnie rozbite.', 0),
(1923, 'koKR', 'Połączone armie Żelaznej Kuźni i Grim Batol skierowały się następnie na południe, zdecydowane raz na zawsze zniszczyć Thaurissana i jego Czarnorytych. Nie uszły daleko, gdy furia Thaurissana zaowocowała zaklęciem o kataklizmicznych rozmiarach. Chcąc przyzwać nadprzyrodzonego sługę, który zapewniłby mu zwycięstwo, Thaurissan wezwał pradawne moce śpiące pod powierzchnią świata. Ku jego zaskoczeniu, a ostatecznie i zgubie, istota, która się pojawiła, była straszniejsza niż jakikolwiek koszmar, jaki mógł sobie wyobrazić.', 0),
(1924, 'koKR', 'Ragnaros Władca Ognia, nieśmiertelny pan wszystkich żywiołaków ognia, został wygnany przez tytanów, gdy świat był jeszcze młody. Teraz, uwolniony wezwaniem Thaurissana, Ragnaros znów wybuchł do istnienia. Jego apokaliptyczne odrodzenie w Azeroth zdruzgotało Góry Rudej Grani i utworzyło w samym środku zniszczenia szalejący wulkan.', 0),
(1925, 'koKR', 'Wulkan, zwany Czarną Górą, graniczył od północy z Płonącym Wąwozem, a od południa z Płonącymi Stepami. Choć Thaurissan zginął od sił, które sam uwolnił, jego ocaleni pobratymcy zostali ostatecznie zniewoleni przez Ragnarosa i jego żywiołaki. Do dziś pozostają w głębinach Czarnej Góry.', 0),
(1926, 'koKR', 'Widząc straszliwe zniszczenia i pożary rozprzestrzeniające się po południowych górach, król Madoran i król Khardros zatrzymali swoje armie i pospiesznie zawrócili do swych królestw, nie chcąc stawić czoła przerażającemu gniewowi Ragnarosa.', 0),
(1927, 'koKR', 'Miedziobrodzi wrócili do Żelaznej Kuźni i odbudowali swoje wspaniałe miasto. Dzikie Młoty także wróciły do domu, do Grim Batol. Jednak śmierć Modgud pozostawiła na górskiej twierdzy złowrogie piętno i Dzikie Młoty nie mogły już w niej mieszkać.', 0),
(1928, 'koKR', 'W ich sercach zagościła gorycz po utracie ukochanego domu. Król Miedziobrody zaproponował Dzikim Młotom miejsce do zamieszkania w granicach Żelaznej Kuźni, lecz Dzikie Młoty stanowczo odmówiły. Khardros poprowadził swój lud na północ, ku ziemiom Lordaeronu. Osiadłszy w bujnych lasach Zaziemia, Dzikie Młoty zbudowały miasto Orle Gniazdo, gdzie zbliżyły się do natury, a nawet zawiązały więź z potężnymi gryfami z tamtych stron.', 0),
(1929, 'koKR', 'Chcąc utrzymać stosunki i handel ze swoimi krewniakami, krasnoludy z Żelaznej Kuźni zbudowały dwa ogromne łuki – Most Thandol – by połączyć Khaz Modan z Lordaeronem. Dzięki wzajemnemu handlowi oba królestwa rozkwitły. Po śmierci Madorana i Khardrosa ich synowie wspólnie zamówili dwa wielkie posągi na cześć swoich ojców.', 0),
(1930, 'koKR', 'Dwa posągi miały strzec przełęczy prowadzącej na południowe ziemie, które po palącym przybyciu Ragnarosa stały się krainą wulkanów. Były zarówno ostrzeżeniem dla wszystkich, którzy chcieliby zaatakować krasnoludzkie królestwa, jak i przypomnieniem, jaką cenę zapłacili Czarnoryci za swoje zbrodnie.', 0),
(1931, 'koKR', 'Przez kilka lat oba królestwa utrzymywały bliskie więzi, lecz groza, której Dzikie Młoty doświadczyły w Grim Batol, bardzo je odmieniła. Zamiast wykuwać ogromne królestwo we wnętrzu góry, zamieszkały na powierzchni, na zboczach Orlego Gniazda. Różnice poglądów między dwoma pozostałymi klanami krasnoludów w końcu doprowadziły do tego, że ich drogi się rozeszły.', 0),
(1959, 'koKR', 'Podczas gdy Kil\'jaeden przygotowywał Hordę do inwazji na Azeroth, Medivh wciąż walczył z Sargerasem o swoją duszę. Król Llane, szlachetny władca Wichrogrodu, zaczął z niepokojem spoglądać na mrok, który zdawał się kalać ducha jego dawnego przyjaciela.', 0),
(1960, 'koKR', 'Król Llane podzielił się swoimi obawami z Anduinem Lotharem, ostatnim potomkiem rodu Arathi, którego mianował dowódcą swoich wojsk. Mimo to żaden z nich nie mógł sobie wyobrazić, że powolne popadanie Medivha w szaleństwo sprowadzi okropności, które miały nadejść.', 0),
(1961, 'koKR', 'Jako ostateczną zachętę Sargeras obiecał obdarzyć Gul\'dana wielką mocą, jeśli ten zgodzi się poprowadzić Hordę do Azeroth. Za pośrednictwem Medivha Sargeras oznajmił czarnoksiężnikowi, że może stać się żywym bogiem, jeśli odnajdzie podmorski grobowiec, w którym Strażniczka Egwina prawie tysiąc lat wcześniej złożyła okaleczone ciało Sargerasa.', 0),
(1962, 'koKR', 'Gul\'dan się zgodził i postanowił, że gdy tylko mieszkańcy Azeroth zostaną pokonani, odnajdzie legendarny grobowiec i odbierze swoją nagrodę. Pewny, że Horda posłuży jego celom, Sargeras rozkazał rozpocząć inwazję.', 0),
(1963, 'koKR', 'Wspólnym wysiłkiem Medivh i czarnoksiężnicy z Rady Cieni otworzyli międzywymiarowe wrota zwane Mrocznym Portalem. Portal połączył Azeroth z Draenorem i był na tyle duży, że mogły przez niego przejść całe armie. Gul\'dan wysłał przez portal orczych zwiadowców, by zbadali ziemie, które mieli podbić. Powracający zwiadowcy zapewnili Radę Cieni, że świat Azeroth tylko czeka na zdobycie.', 0),
(1964, 'koKR', 'Wciąż przekonany, że spaczenie Gul\'dana zniszczy jego lud, Durotan raz jeszcze wystąpił przeciwko czarnoksiężnikom. Dzielny wojownik twierdził, że czarnoksiężnicy niszczą czystość orczego ducha i że ta lekkomyślna inwazja będzie ich zgubą. Gul\'dan, który nie mógł zaryzykować zabicia tak popularnego bohatera, musiał wygnać Durotana i jego Klan Mroźnego Wilka w najdalsze zakątki nowego świata.', 0),
(1965, 'koKR', 'Po tym, jak wygnane Mroźne Wilki przeszły przez portal, podążyło za nimi zaledwie kilka orczych klanów. Orkowie ci szybko założyli bazę na Czarnych Mokradłach, mrocznym, bagnistym terenie daleko na wschód od królestwa Wichrogrodu. Gdy zaczęli się rozchodzić i badać nowe ziemie, od razu weszli w konflikt z ludzkimi obrońcami Wichrogrodu. $B', 0),
(1966, 'koKR', 'Choć potyczki te zwykle szybko się kończyły, wiele mówiły o słabościach i mocnych stronach obu rywalizujących ras. Llane i Lothar nigdy nie zdołali zdobyć dokładnych danych o liczebności orków i mogli jedynie zgadywać, jak wielkim siłom przyjdzie im stawić czoła.', 0),
(1967, 'koKR', 'Po kilku latach większość orczej Hordy przeszła do Azeroth, a Gul\'dan uznał, że nadszedł czas głównego uderzenia na ludzkość. Horda rzuciła całą swoją potęgę przeciwko niczego niepodejrzewającemu królestwu Wichrogrodu.', 0),
(1968, 'koKR', 'Gdy siły Azeroth i Hordy ścierały się w całym królestwie, wewnętrzne konflikty zaczęły zbierać żniwo w obu armiach. Król Llane, przekonany, że bestialscy orkowie nie są zdolni podbić Azeroth, z pogardą trwał na swej pozycji w stolicy, Wichrogrodzie. Sir Lothar nabrał jednak przekonania, że walkę należy zanieść wprost do wroga, i musiał wybierać między własnymi przekonaniami a lojalnością wobec króla. ', 0),
(1969, 'koKR', 'Postanowiwszy zaufać instynktowi, Lothar szturmem zdobył wieżę-twierdzę Medivha, Karazhan, z pomocą młodego ucznia czarodzieja, Khadgara. Khadgarowi i Lotharowi udało się pokonać opętanego Strażnika, który – jak się upewnili – był źródłem konfliktu. ', 0),
(1970, 'koKR', 'Zabijając ciało Medivha, Lothar i młody uczeń nieświadomie wygnali ducha Sargerasa w otchłań. Dzięki temu czysty, prawy duch Medivha mógł przetrwać... i przez wiele kolejnych lat błąkać się po sferze astralnej.', 0),
(1971, 'koKR', 'Choć Medivh został pokonany, Horda nadal miażdżyła obrońców Wichrogrodu. Gdy zwycięstwo Hordy było coraz bliżej, Orgrim Zgładziciel, jeden z największych orkowych wodzów, zaczął dostrzegać plugawe zepsucie, które szerzyło się wśród klanów od czasów Draenoru.', 0),
(1972, 'koKR', 'Jego dawny towarzysz, Durotan, powrócił z wygnania i raz jeszcze ostrzegł go przed zdradą Gul\'dana. W szybkim odwecie zabójcy Gul\'dana zamordowali Durotana i jego rodzinę, pozostawiając przy życiu tylko jego maleńkiego syna. Zgładziciel nie wiedział, że niemowlę Durotana znalazł ludzki oficer, Aedelas Blackmoore, i uczynił je niewolnikiem. $B$BTen mały ork miał pewnego dnia wyrosnąć na największego przywódcę, jakiego jego lud kiedykolwiek poznał. ', 0),
(1973, 'koKR', 'Rozwścieczony śmiercią Durotana Orgrim postanowił uwolnić Hordę od demonicznego zepsucia i ostatecznie objął władzę wodza Hordy, zabijając Czarnorękiego, skorumpowaną marionetkę Gul\'dana. Pod jego zdecydowanym przywództwem nieustępliwa Horda wreszcie obległa Twierdzę Wichrogród. ', 0),
(1974, 'koKR', 'Król Llane poważnie nie docenił potęgi Hordy i bezradnie patrzył, jak jego królestwo pada pod naporem zielonoskórych najeźdźców. W końcu króla Llane\'a zamordowała jedna z najlepszych zabójczyń Rady Cieni: półorczyca Garona.', 0),
(1975, 'koKR', 'Lothar i jego wojownicy, wracając do domu z Karazhanu, mieli nadzieję powstrzymać rozlew krwi i ocalić swoją niegdyś wspaniałą ojczyznę. Wrócili jednak za późno i zastali ukochane królestwo w dymiących ruinach. Orkowa Horda nadal pustoszyła okolicę i zagarniała okoliczne ziemie dla siebie. Zmuszeni do ukrycia się Lothar i jego towarzysze złożyli ponurą przysięgę, że odzyskają ojczyznę za wszelką cenę.', 0),
(1976, 'koKR', 'Lord Lothar zebrał resztki armii Azeroth po klęsce pod Twierdzą Wichrogród, a następnie poprowadził wielki exodus przez morze, do północnego królestwa Lordaeronu. Przekonani, że Horda, jeśli nikt jej nie powstrzyma, pokona całą ludzkość, przywódcy siedmiu ludzkich narodów spotkali się i postanowili zjednoczyć w sojuszu, który przeszedł do historii jako Przymierze Lordaeronu. ', 0),
(1977, 'koKR', 'Po raz pierwszy od blisko trzech tysięcy lat rozproszone narody Aratoru znów zjednoczyły się pod wspólnym sztandarem. Mianowany Najwyższym Dowódcą sił Przymierza, lord Lothar przygotował swoje armie na nadejście Hordy.', 0),
(1978, 'koKR', 'Z pomocą swoich zastępców – Uthera Światłodzierżcy, admirała Daelina Proudmoore\'a i Turalyona – Lothar zdołał przekonać o nadciągającym zagrożeniu również pół-ludzkie rasy Lordaeronu. Przymierzu udało się pozyskać wsparcie niewzruszonych krasnoludów z Żelaznej Kuźni oraz niewielkiej liczby wysokich elfów z Quel\'Thalas.', 0),
(1979, 'koKR', 'Elfy, którymi władał wówczas Anasterian Słońcobieżca, w większości nie interesowały się nadciągającym konfliktem. Były jednak zobowiązane pomóc Lotharowi, ponieważ był on ostatnim potomkiem rodu Arathi, który w dawnych wiekach wspierał elfy.', 0),
(1980, 'koKR', 'Horda, dowodzona teraz przez wodza Zgładziciela, sprowadziła ogry ze swojego ojczystego świata, Draenoru, i wcieliła w swoje szeregi wydziedziczone leśne trolle Amani. Wyruszywszy na wielką kampanię, by zalać krasnoludzkie królestwo Khaz Modan i południowe krańce Lordaeronu, Horda bez trudu zdziesiątkowała wszelki opór.', 0),
(1981, 'koKR', 'Epickie bitwy Drugiej Wojny obejmowały zarówno wielkie starcia morskie, jak i ogromne powietrzne pojedynki. Hordzie jakimś sposobem udało się odnaleźć potężny artefakt zwany Duszą Demona, za którego pomocą zniewoliła prastarą Smoczą Królową, Alexstrazę. Grożąc zniszczeniem jej cennych jaj, Horda zmusiła Alexstrazę, by posłała na wojnę swoje dorosłe dzieci. Szlachetne czerwone smoki musiały walczyć dla Hordy – i walczyły.', 0),
(1982, 'koKR', 'Wojna szalała na kontynentach Khaz Modan i Lordaeronu oraz w samym Azeroth. W ramach północnej kampanii Hordzie udało się spalić pogranicze Quel\'Thalas, co ostatecznie przypieczętowało zaangażowanie elfów w sprawę Przymierza. Większe miasta i osady Lordaeronu zostały zrównane z ziemią i spustoszone przez konflikt. Mimo braku posiłków i przytłaczającej przewagi wroga Lothar i jego sojusznicy zdołali utrzymać nieprzyjaciół na dystans.', 0),
(1983, 'koKR', 'Jednak w ostatnich dniach Drugiej Wojny, gdy zwycięstwo Hordy nad Przymierzem wydawało się niemal pewne, między dwoma najpotężniejszymi orkami w Azeroth wybuchł straszliwy spór. Gdy Zgładziciel szykował ostateczny szturm na stolicę Lordaeronu – szturm, który zmiażdżyłby ostatnie resztki Przymierza – Gul\'dan i jego zwolennicy porzucili swoje posterunki i wypłynęli w morze.', 0),
(1984, 'koKR', 'Oszołomiony Zgładziciel, który przez zdradę Gul\'dana stracił niemal połowę swoich sił, musiał się wycofać i zaprzepaścić największą szansę na zwycięstwo nad Przymierzem.', 0),
(1985, 'koKR', 'Żądny władzy Gul\'dan, owładnięty pragnieniem osiągnięcia boskości, wyruszył na desperackie poszukiwania podmorskiego Grobowca Sargerasa, który – jak wierzył – skrywał tajemnice najwyższej potęgi. Skazawszy już wcześniej swoich pobratymców na niewolę u Płonącego Legionu, Gul\'dan w ogóle nie przejmował się rzekomym obowiązkiem wobec Zgładziciela.', 0),
(1986, 'koKR', 'Wspierany przez klany Łupieżców Burzy i Młota Zmierzchu, Gul\'dan zdołał wydźwignąć Grobowiec Sargerasa z dna morza. Kiedy jednak otworzył prastarą, zalaną kryptę, zastał w niej jedynie oszalałe demony.', 0),
(1987, 'koKR', 'Chcąc ukarać krnąbrnych orków za ich kosztowną zdradę, Zgładziciel wysłał swoje siły, by zabiły Gul\'dana i sprowadziły odszczepieńców z powrotem do Hordy. Za swoją lekkomyślność Gul\'dan został rozszarpany przez oszalałe demony, które sam uwolnił. Pozbawione przywódcy klany odszczepieńców szybko padły przed rozwścieczonymi legionami Zgładziciela.', 0),
(1988, 'koKR', 'Choć bunt został stłumiony, Horda nie zdołała odrobić strasznych strat, które poniosła. Zdrada Gul\'dana dała Przymierzu nie tylko nadzieję, lecz także czas, by przegrupować siły i przejść do kontrataku.', 0),
(1989, 'koKR', 'Lord Lothar, widząc, że Horda pęka od środka, zebrał resztki swoich sił i zepchnął Zgładziciela na południe, z powrotem do zrujnowanego serca Wichrogrodu. Tam siły Przymierza osaczyły cofającą się Hordę w wulkanicznej twierdzy Iglicy Czarnej Góry. Choć lord Lothar poległ w bitwie u podnóża Iglicy, jego zastępca Turalyon w ostatniej chwili zebrał siły Przymierza i zepchnął Hordę na ponure Moczary Smutków. ', 0),
(1990, 'koKR', 'Siłom Turalyona udało się zniszczyć Mroczny Portal, mistyczną bramę łączącą orków z ich ojczystym światem, Draenorem. Odcięta od posiłków i rozdarta wewnętrznymi walkami Horda w końcu załamała się i padła przed potęgą Przymierza.', 0),
(1991, 'koKR', 'Rozproszone orkowe klany szybko wyłapano i umieszczono w strzeżonych obozach internowania. Choć wydawało się, że Horda została pokonana na dobre, niektórzy mocno wątpili, by pokój miał przetrwać. Khadgar, teraz arcymag o pewnej renomie, przekonał dowództwo Przymierza, by wzniosło twierdzę Strażnicy Otchłani, która czuwałaby nad ruinami Mrocznego Portalu i dopilnowała, by z Draenoru nie nadeszły już żadne inwazje.', 0),
(2018, 'koKR', 'Tymczasem na zniszczonych wojną ziemiach południa rozproszone resztki Hordy walczyły o przetrwanie. Choć Grom Piekłorycz i jego klan Wojennej Pieśni zdołali uniknąć niewoli, Martwe Oko i jego klan Krwawiącego Oczodołu zostali schwytani i umieszczeni w obozach internowania w Lordaeronie. Mimo tych kosztownych buntów strażnicy obozów szybko przywrócili kontrolę nad swoimi brutalnymi podopiecznymi.', 0),
(2019, 'koKR', 'Przymierze nie wiedziało jednak, że na północnych pustkowiach Khaz Modan nadal swobodnie grasowały duże siły orków. Klan Smoczych Paszcz, prowadzony przez osławionego czarnoksiężnika Nekrosa, wykorzystywał prastary artefakt zwany Duszą Demona, by kontrolować Smoczą Królową Alexstrazę i jej stado. Mając Smoczą Królową jako zakładniczkę, Nekros zbudował tajną armię w opuszczonej – niektórzy twierdzą, że przeklętej – warowni Dzikiego Młota, Grim Batol. ', 0),
(2020, 'koKR', 'Nekros zamierzał rzucić swoje siły i potężne czerwone smoki na Przymierze, mając nadzieję na ponowne zjednoczenie Hordy i kontynuowanie podboju Azeroth. Jego wizja się nie spełniła: niewielka grupa bojowników ruchu oporu pod wodzą ludzkiego maga Rhonina zdołała zniszczyć Duszę Demona i uwolnić Smoczą Królową spod władzy Nekrosa.', 0),
(2021, 'koKR', 'W swej furii smoki Alexstrazy rozniosły Grim Batol i spopieliły większą część klanu Smoczych Paszcz. Wielkie plany zjednoczenia snute przez Nekrosa legły w gruzach, a oddziały Przymierza wyłapały ocalałych orków i wtrąciły ich do czekających obozów internowania. Klęska klanu Smoczych Paszcz oznaczała koniec Hordy i koniec wściekłej żądzy krwi orków. ', 0),
(2030, 'koKR', 'Naczelny strażnik obozów internowania, Aedelas Blackmoore, pilnował pojmanych orków ze swojej twierdzy-więzienia, Durnhold. Jeden ork szczególnie go interesował: osierocone niemowlę, które znalazł blisko osiemnaście lat wcześniej. Blackmoore wychował młodego samca jako swojego ulubionego niewolnika i nazwał go Thrallem. Uczył orka taktyki, filozofii i walki. Thrall został nawet wyszkolony na gladiatora. Przez cały ten czas skorumpowany strażnik usiłował uczynić z orka broń. ', 0),
(2031, 'koKR', 'Mimo surowego wychowania młody Thrall wyrósł na silnego, bystrego orka i w głębi serca wiedział, że życie niewolnika nie jest dla niego. Dorastając, dowiadywał się o swoim ludzie, orkach, których nigdy nie spotkał: po klęsce większość z nich trafiła do obozów internowania. Krążyły pogłoski, że Zgładziciel, przywódca orków, uciekł z Lordaeronu i się ukrył. Tylko jeden zbuntowany klan wciąż działał w ukryciu, starając się umknąć czujnym oczom Przymierza. ', 0),
(2032, 'koKR', 'Zaradny, lecz niedoświadczony Thrall postanowił uciec z twierdzy Blackmoore\'a i wyruszyć na poszukiwanie pobratymców. Podczas wędrówek odwiedzał obozy internowania i odkrył, że jego niegdyś potężna rasa jest dziwnie potulna i ospała. Nie znalazłszy dumnych wojowników, których spodziewał się spotkać, Thrall wyruszył na poszukiwanie ostatniego niepokonanego orkowego wodza, Groma Piekłorycza. ', 0),
(2033, 'koKR', 'Nieustannie ścigany przez ludzi, Piekłorycz wciąż zachowywał niezłomną wolę walki Hordy. Wspierany jedynie przez oddany mu klan Wojennej Pieśni, prowadził podziemną wojnę z uciskiem swojego udręczonego ludu. Niestety, Piekłorycz nigdy nie znalazł sposobu, by wyrwać pojmanych orków z odrętwienia. Podatny na wpływy Thrall, zainspirowany idealizmem Piekłorycza, poczuł silną więź z Hordą i jej wojowniczymi tradycjami. ', 0),
(2034, 'koKR', 'Szukając prawdy o swoim pochodzeniu, Thrall wyruszył na północ, by odnaleźć legendarny klan Mroźnych Wilków. Dowiedział się, że Gul\'dan wygnał Mroźne Wilki we wczesnych dniach Pierwszej Wojny. Odkrył też, że jest synem i dziedzicem orkowego bohatera Durotana, prawowitego wodza Mroźnych Wilków, zamordowanego w dziczy blisko dwadzieścia lat wcześniej. ', 0),
(2035, 'koKR', 'Pod okiem czcigodnego szamana Drek\'Thara Thrall zgłębiał prastarą szamańską kulturę swojego ludu, zapomnianą pod nikczemnymi rządami Gul\'dana. Z czasem Thrall stał się potężnym szamanem i zajął należne mu miejsce wodza wygnanych Mroźnych Wilków. Wzmocniony mocą samych żywiołów i pchany chęcią wypełnienia swojego przeznaczenia, Thrall wyruszył, by uwolnić pojmane klany i uleczyć swoją rasę z demonicznego zepsucia. ', 0),
(2036, 'koKR', 'Podczas swoich podróży Thrall odnalazł sędziwego wodza, Orgrima Zgładziciela, który od wielu lat żył jako pustelnik. Zgładziciel, niegdyś bliski przyjaciel ojca Thralla, postanowił pójść za młodym orkiem wizjonerem i pomóc mu uwolnić pojmane klany. Wspierany przez wielu doświadczonych wodzów, Thrall ostatecznie zdołał tchnąć w Hordę nowe życie i dać swemu ludowi nową duchową tożsamość. ', 0),
(2037, 'koKR', 'Na znak odrodzenia swojego ludu Thrall powrócił do twierdzy Blackmoore\'a, Durnhold, i ostatecznie pokrzyżował plany swojego dawnego pana, oblegając obozy internowania. To zwycięstwo miało swoją cenę: podczas wyzwalania jednego z obozów Zgładziciel poległ w bitwie. ', 0),
(2038, 'koKR', 'Thrall wziął legendarny młot bojowy Zgładziciela i przywdział jego czarną zbroję płytową, stając się nowym wodzem Hordy. W kolejnych miesiącach niewielka, lecz groźna Horda Thralla spustoszyła obozy internowania i udaremniała najlepsze starania Przymierza, by przeciwstawić się jego sprytnym strategiom. Zachęcany przez najlepszego przyjaciela i mentora, Groma Piekłorycza, Thrall dokładał wszelkich starań, by jego lud już nigdy nie stał się niewolnikami. ', 0),
(2039, 'koKR', 'Podczas gdy Thrall wyzwalał swoich braci w Lordaeronie, Ner\'zhul nadal umacniał swoją potęgę w Północnej Grani. Nad Lodowcem Lodowej Korony wzniesiono wielką cytadelę, obsadzoną rosnącymi legionami umarłych. Lecz choć Król Lisz rozciągał swoje wpływy na całą krainę, jedno mroczne imperium sprzeciwiło się jego władzy. ', 0),
(2040, 'koKR', 'Prastare podziemne królestwo Azjol-Nerub, założone przez rasę złowrogich humanoidalnych pająków, wysłało swoją elitarną straż wojowników, by zaatakowała Lodową Koronę i położyła kres szaleńczemu dążeniu Króla Lisza do dominacji. Ku swej frustracji Ner\'zhul odkrył, że źli nerubianie są odporni nie tylko na zarazę, ale i na jego telepatyczną władzę.', 0),
(2041, 'koKR', 'Nerubiańscy pajęczy władcy dowodzili ogromnymi siłami i dysponowali siecią podziemnych tuneli, która sięgała niemal przez połowę Północnej Grani. Ich ataki z zaskoczenia na twierdze Króla Lisza raz po raz udaremniały jego próby wykurzenia ich z kryjówek. Ostatecznie Ner\'zhul wygrał wojnę z nerubianami na wyniszczenie. Z pomocą złowrogich upiornych władców i niezliczonych nieumarłych wojowników Król Lisz najechał Azjol-Nerub i zwalił jego podziemne świątynie na głowy pajęczych władców.', 0),
(2042, 'koKR', 'Choć nerubianie byli odporni na jego zarazę, rosnące moce nekromantyczne pozwoliły Ner\'zhulowi wskrzesić zwłoki pajęczych wojowników i nagiąć je do swojej woli. W hołdzie dla ich nieustępliwości i nieustraszoności Ner\'zhul przejął charakterystyczny styl architektury nerubian dla własnych twierdz i budowli. ', 0),
(2043, 'koKR', 'Mogąc władać swoim królestwem bez przeszkód, Król Lisz zaczął przygotowywać się do swojej prawdziwej misji w świecie. Sięgając swoją ogromną świadomością do ludzkich krain, Król Lisz wzywał każdą mroczną duszę, która zechciałaby go wysłuchać... ', 0),
(2072, 'koKR', 'Gdy Kel\'Thuzad znów był cały, Arthas poprowadził Plagę na południe, do Dalaranu. Tam lisz miał zdobyć potężną księgę zaklęć Medivha i użyć jej, by przywołać Archimonda z powrotem do świata. Od tej chwili sam Archimond miał rozpocząć ostateczną inwazję Legionu. Nawet czarodzieje z Kirin Toru nie zdołali powstrzymać sił Arthasa przed kradzieżą księgi Medivha i wkrótce Kel\'Thuzad miał wszystko, czego potrzebował, by rzucić swoje zaklęcie. ', 0),
(2073, 'koKR', 'Po dziesięciu tysiącach lat potężny demon Archimond i jego zastępy znów pojawili się w świecie Azeroth. Dalaran nie był jednak ich ostatecznym celem. Na rozkaz samego Kil\'jaedena Archimond i jego demony podążyły za nieumarłą Plagą do Kalimdoru, zdecydowane zniszczyć Nordrassil, Drzewo Świata.', 0),
(2074, 'koKR', 'Pośród tego chaosu pojawił się samotny, tajemniczy prorok, by udzielić śmiertelnym rasom wskazówek. Prorokiem tym okazał się nie kto inny jak Medivh, ostatni Strażnik, który w cudowny sposób powrócił z Zaświatów, by odkupić dawne grzechy. Medivh opowiedział Hordzie i Przymierzu o grożących im niebezpieczeństwach i nakłaniał je do połączenia sił. ', 0),
(2075, 'koKR', 'Znużeni pokoleniami nienawiści orkowie i ludzie nie chcieli o tym słyszeć. Medivh musiał zająć się każdą rasą osobno, posługując się proroctwami i podstępem, by poprowadzić je przez morze do legendarnej krainy Kalimdor. Orkowie i ludzie wkrótce natknęli się na długo ukrytą cywilizację kaldorei.', 0),
(2076, 'koKR', 'Orkowie pod wodzą Thralla ponieśli szereg niepowodzeń podczas wędrówki przez Pustkowia Kalimdoru. Choć zaprzyjaźnili się z Kairnem Krwawe Kopyto i jego potężnymi taureńskimi wojownikami, wielu orków zaczęło ulegać demonicznej żądzy krwi, która nękała ich od lat. Największy z zastępców Thralla, Grom Piekłorycz, zdradził nawet Hordę, ulegając swoim niskim instynktom.', 0),
(2077, 'koKR', ' Gdy Piekłorycz i jego wierni wojownicy z Wojennej Pieśni przemierzali lasy Jesionowej Kniei, starli się z prastarymi Strażniczkami nocnych elfów. Pewny, że orkowie powrócili do swoich wojowniczych obyczajów, półbóg Cenarius wystąpił, by przepędzić Piekłorycza i jego orków. Lecz Piekłorycz i jego orkowie, owładnięci nadprzyrodzoną nienawiścią i wściekłością, zdołali zabić Cenariusa i splugawić prastare lasy. ', 0),
(2078, 'koKR', 'Ostatecznie Piekłorycz odzyskał honor, pomagając Thrallowi pokonać Mannorotha, demonicznego władcę, który niegdyś przeklął orków swoją krwią pełną nienawiści i wściekłości. Wraz ze śmiercią Mannorotha klątwa krwi orków wreszcie dobiegła końca. ', 0),
(2079, 'koKR', 'Podczas gdy Medivh starał się przekonać orków i ludzi o potrzebie sojuszu, nocne elfy walczyły z Legionem na swój własny, skryty sposób. Tyrande Szept Wiatru, nieśmiertelna Wielka Kapłanka Strażniczek nocnych elfów, rozpaczliwie broniła lasów Jesionowej Kniei przed zalewem demonów i nieumarłych. Tyrande zrozumiała, że potrzebuje pomocy, i postanowiła przebudzić druidów nocnych elfów z ich tysiącletniego snu. ', 0),
(2080, 'koKR', 'Wezwawszy swoją dawną miłość, Malfuriona Burzogniewnego, Tyrande zdołała wzmocnić obronę i odeprzeć Legion. Z pomocą Malfuriona sama natura powstała, by pokonać Legion i jego sojuszników z Plagi.', 0),
(2081, 'koKR', 'Szukając kolejnych pogrążonych we śnie druidów, Malfurion odnalazł prastare więzienie w kurhanie, w którym niegdyś zakuł swojego brata, Illidana. Przekonana, że Illidan pomoże im w walce z Legionem, Tyrande go uwolniła. Illidan rzeczywiście przez pewien czas im pomagał, lecz w końcu uciekł, by realizować własne cele.', 0),
(2082, 'koKR', 'Nocne elfy zebrały siły i z ponurą determinacją stawiły czoła Płonącemu Legionowi. Legion nigdy nie przestał pożądać Studni Wieczności, od dawna źródła siły Drzewa Świata i zarazem serca królestwa nocnych elfów. Gdyby zaplanowany atak na Drzewo się powiódł, demony dosłownie rozerwałyby świat na strzępy.', 0),
(2291, 'koKR', 'Arcybiskup Alonsus Faol Dobroczynny patron Kościoła Świętej Światłości. Choć swoje dobre dzieło rozpoczął w Stratholmie w Lordaeronie, arcybiskup Faol był wielkim przyjacielem mieszkańców Wichrogrodu. W mrocznych dniach po Drugiej Wojnie pomógł odnowić Bractwo Północnych Włości i zebrał ogromne fundusze na odbudowę samego Wichrogrodu. Ta katedra jest nie tylko bastionem Świętej Światłości, lecz także trwałym świadectwem szlachetnego ducha i hojności jednego człowieka. ', 0),
(2292, 'koKR', 'Król Llane I z rodu Wrynnów Suzeren Wichrogrodu Obrońca Azeroth ', 0),
(2293, 'koKR', 'Dowódca flot Przymierza Przyjaciel Wichrogrodu ', 0),
(2294, 'koKR', 'Lady Mara Fordragon\n\nNajwyższa duchowna Wichrogrodu\n\nPatronka uchodźców, którzy po Pierwszej Wojnie uciekli do Lordaeronu.\n\nByła jasną matką naszej przyszłości. Niech spoczywa w Światłości.\n', 0),
(2512, 'koKR', 'Osricu, poniżej przesyłam listę części zbroi, których potrzebujemy: 10 kolczych koszul, 20 hełmów, 30 łat na zbroje, 15 par kolczych butów. Jak zawsze jesteśmy twoimi dłużnikami. A gdyby Zachodni Skraj uwolnił się kiedyś od złodziei, którzy mu zagrażają, ulżyłoby mojemu sercu, gdybym mógł zaprosić cię do domu mojej rodziny na wyśmienity posiłek z plonów, z których ta ziemia niegdyś tak słynęła. -Kwatermistrz Lewis, Wzgórze Strażnicze ', 0),
(2654, 'koKR', '<HTML>\n<BODY>\n<H1 align="center">TRAKTAT O STOPNIACH WOJSKOWYCH</H1><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRankAlliance" align="left"/><BR/>\n<P align="right">Poniżej przedstawiono</P>\n<P align="right">stopnie wojskowe</P>\n<P align="right">Przymierza,</P>\n<P align="right">a po nich wszystko,</P>\n<P align="right">co wiadomo o stopniach</P>\n<P align="right">ras Hordy. Każda</P>\n<P align="right">z list dzieli się</P>\n<P align="right">na dwie</P>\n<P align="right">części, najpierw oficerowie, potem podoficerowie i szeregowi, a stopnie w każdej z nich podano w kolejności malejącej, od najwyższego do najniższego. Niech żyje Przymierze!</P>\n</BODY>\n</HTML>', 0),
(2655, 'koKR', '<HTML>\n<BODY>\n<H1 align="center">STOPNIE OFICERSKIE PRZYMIERZA</H1><BR/>\n<P align="center">Część 1</P>\n<IMG src="Interface\\PvPRankBadges\\PvPRank14" align="left"/><BR/>\n<P align="right">Wielki marszałek</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank13" align="left"/><BR/>\n<P align="right">Feldmarszałek</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank12" align="left"/><BR/>\n<P align="right">Marszałek</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank11" align="left"/><BR/>\n<P align="right">Komandor</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank10" align="left"/><BR/>\n<P align="right">Komandor porucznik</P><BR/><BR/>\n</BODY>\n</HTML>', 0),
(2656, 'koKR', '<HTML>\n<BODY>\n<H1 align="center">STOPNIE OFICERSKIE PRZYMIERZA</H1><BR/>\n<P align="center">Część 2</P>\n<IMG src="Interface\\PvPRankBadges\\PvPRank09" align="left"/><BR/>\n<P align="right">Rycerz-czempion</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank08" align="left"/><BR/>\n<P align="right">Rycerz-kapitan</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank07" align="left"/><BR/>\n<P align="right">Rycerz-porucznik</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank06" align="left"/><BR/>\n<P align="right">Rycerz</P><BR/><BR/>\n</BODY>\n</HTML>', 0),
(2657, 'koKR', '<HTML>\n<BODY>\n<H1 align="center">PODOFICEROWIE I SZEREGOWI PRZYMIERZA</H1><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank05" align="left"/><BR/>\n<P align="right">Chorąży</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank04" align="left"/><BR/>\n<P align="right">Starszy sierżant</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank03" align="left"/><BR/>\n<P align="right">Sierżant</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank02" align="left"/><BR/>\n<P align="right">Kapral</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank01" align="left"/><BR/>\n<P align="right">Szeregowy</P><BR/><BR/>\n</BODY>\n</HTML>', 0),
(2658, 'koKR', '<HTML>\n<BODY>\n<H1 align="center">STOPNIE OFICERSKIE HORDY</H1><BR/>\n<P align="center">Część 1</P>\n<IMG src="Interface\\PvPRankBadges\\PvPRank14" align="left"/><BR/>\n<P align="right">Najwyższy wódz</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank13" align="left"/><BR/>\n<P align="right">Wódz</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank12" align="left"/><BR/>\n<P align="right">Generał</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank11" align="left"/><BR/>\n<P align="right">Generał porucznik</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank10" align="left"/><BR/>\n<P align="right">Czempion</P><BR/><BR/>\n</BODY>\n</HTML>', 0),
(2676, 'koKR', '<HTML>\n<BODY>\n<H1 align="center">STOPNIE WOJSKOWE PRZYMIERZA</H1><BR/>\n<P align="center">OFICEROWIE</P><BR/>\n<P align="center">Wielki marszałek</P>\n<P align="center">Feldmarszałek</P>\n<P align="center">Marszałek</P>\n<P align="center">Komandor</P>\n<P align="center">Komandor porucznik</P>\n<P align="center">Rycerz-czempion</P>\n<P align="center">Rycerz-kapitan</P>\n<P align="center">Rycerz-porucznik</P>\n<P align="center">Rycerz</P><BR/>\n<P align="center">PODOFICEROWIE I SZEREGOWI</P><BR/>\n<P align="center">Chorąży</P>\n<P align="center">Starszy sierżant</P>\n<P align="center">Sierżant</P>\n<P align="center">Kapral</P>\n<P align="center">Szeregowy</P><BR/>\n</BODY>\n</HTML>', 0),
(2854, 'koKR', '<HTML>\n<BODY>\n<H1 align="center">STOPNIE OFICERSKIE HORDY</H1><BR/>\n<P align="center">Część 2</P>\n<IMG src="Interface\\PvPRankBadges\\PvPRank09" align="left"/><BR/>\n<P align="right">Centurion</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank08" align="left"/><BR/>\n<P align="right">Legionista</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank07" align="left"/><BR/>\n<P align="right">Strażnik krwi</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank06" align="left"/><BR/>\n<P align="right">Kamienny strażnik</P><BR/><BR/>\n</BODY>\n</HTML>', 0),
(2855, 'koKR', '<HTML>\n<BODY>\n<H1 align="center">PODOFICEROWIE I SZEREGOWI HORDY</H1><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank05" align="left"/><BR/>\n<P align="right">Pierwszy sierżant</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank04" align="left"/><BR/>\n<P align="right">Starszy sierżant</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank03" align="left"/><BR/>\n<P align="right">Sierżant</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank02" align="left"/><BR/>\n<P align="right">Siepacz</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank01" align="left"/><BR/>\n<P align="right">Zwiadowca</P><BR/><BR/>\n</BODY>\n</HTML>', 0),
(3039, 'koKR', 'Nie stój nad moim grobem we łzach, nie ma mnie tam, nie śpię w prochach.\nJestem w tysiącu wiatrów, co w dal lecą, nad śniegi Północnej Grani, co jasno świecą.\nJestem łagodnym deszczem nad polami, nad Zachodniego Skraju złotymi łanami.\nJestem w ciszy o świcie, co trwa w Cierniodławach, w zielonej dżungli, w jej bujnych trawach.\nJestem w bębnach, co biją wielko i dumnie, w grzmocie kopyt, co przez Nagrand pędzą tłumnie.\nJestem gwiazdami, co ciepło jaśnieją nad Darnassus, śniącym cicho z nadzieją.\nJestem w ptakach, co śpiewają o świcie, w każdej pięknej rzeczy, co tętni życiem.\nNie stój nad moim grobem, nie płacz przy nim, nie ma mnie tam. Ja nie umieram.', 0),
(3106, 'koKR', '1. Jeśli moc trucizny ci nie odpowiada, podwój składniki albo zmniejsz je o połowę.\n2. Jeśli trucizna nie działa tak, jak chcesz, zawsze mylisz się bardziej, niż ci się wydaje.\n3. Prototypy, prototypy, prototypy (gnomy świetnie nadają się na obiekty doświadczalne).\n4. Po truciznę powinno się łatwo sięgać, a trudno z niej zrezygnować.\n5. Proste składniki współgrają, tworząc ciekawą złożoność.', 0),
(3536, 'koKR', 'Wasza Królewska Mość,$B$Bo miłosierny królu, niech Światłość powstrzyma Twą dłoń i umocni Twe serce. Wstrzymaj swój osąd nad $gtym upadłym czempionem:tą upadłą czempionką; – choćby na chwilę – i wysłuchaj moich słów.$B$B$gOkaziciel:Okazicielka; tego listu to $gdawny bohater:dawna bohaterka; Przymierza. Choć niesie ze sobą odór śmierci i wygląda jak sługa Plagi, ma duszę czempiona. Duszę, która dopiero niedawno połączyła się z ciałem.$B$B', 0),
(3537, 'koKR', '$N reprezentuje nowy, zjednoczony front przeciwko Królowi Liszowi, zwany Rycerzami Hebanowego Miecza. Tak, Wasza Królewska Mość, rycerze śmierci zwrócili się przeciwko swemu dawnemu panu. Przewodzi im syn lorda Alexandrosa Mograine\'a – Spopielacza. Pragną tego, czego i my pragniemy, czego pragniemy wszyscy: końca Plagi.$B$BNie proszę, by $N i Rycerze Hebanowego Miecza zostali przyjęci do Przymierza, a jedynie o to, byś okazał im tolerancję.$B', 0),
(3538, 'koKR', 'Pamiętaj, panie: krwią i honorem wszyscy służymy.$B$BZ wyrazami szacunku$B$BNajwyższy lord Tirion Fordring$B', 0),
(3611, 'koKR', 'Gdzie będziesz, gdy płomienie pochłoną Azeroth?\n\nWiemy, że nikt nie lubi rozmyślać o nadciągającej zagładzie, ale warto się zastanowić, gdzie spędzisz wieczność.\n\nNasi mędrcy przepowiedzieli, że koniec świata jest bliski i że przetrwają tylko przygotowani. Możemy pomóc ci przetrwać szalejące piekło, które oczyści ten świat z niegodziwców. Czy nie czas zaznać spokoju ducha?', 0),
(3612, 'koKR', 'Bez wątpienia $gsłyszałeś:słyszałaś; powiedzenie „wszystko, co dobre, kiedyś się kończy” – i tak też jest z twoim życiem w Azeroth. Już niedługo świat pogrąży się w chaosie, gdy żywioły upomną się o swoje przyrodzone prawa.\n\nAle w tych przerażających czasach nie musisz się bać. Nie musisz umierać. Możemy pomóc ci wznieść się ku nowemu życiu – poza śmiercią, poza strachem i poza bezsilnością śmiertelnego bytu. Dołącz do nas już dziś.', 0),
(3613, 'koKR', 'Żyjemy w burzliwych czasach. Wojna, najazdy i głód przetoczyły się przez świat, lecz prawdziwa próba dopiero nadchodzi: koniec samego Azeroth.\n\nJak zniesiesz utratę i zniszczenie wszystkiego, co ci drogie? Odpowiedź brzmi: nie musisz. Przyprowadź przyjaciół i rodzinę na jedno z naszych spotkań i dowiedz się, jak możecie przetrwać apokalipsę razem – z nami.', 0);
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES
(1244, 'koKR', 'No proszę, kogo my tu mamy! Ktoś młody i pełen zapału, bez wątpienia $gzwabiony:zwabiona; opowieściami o moich wyczynach na polach bitew!$B$BNie czas teraz na historie, bo czekają wielkie i ważne czyny do dokonania! Jeśli więc szukasz chwały, to los ci dziś sprzyja...', 'No proszę, kogo my tu mamy! Ktoś młody i pełen zapału, bez wątpienia $gzwabiony:zwabiona; opowieściami o moich wyczynach na polach bitew!$B$BNie czas teraz na historie, bo czekają wielkie i ważne czyny do dokonania! Jeśli więc szukasz chwały, to los ci dziś sprzyja...', '', '', '', '', '', '', '', '', '', '', '', '', '', ''),
(4782, 'koKR', 'Witaj, $gbracie:siostro;. Jeśli przychodzisz się szkolić, z radością cię wyszkolę.$B$BKrążą plotki o niesnaskach w Kręgu Cenariona, ale nie zwracaj uwagi na takie gadanie. Nasz arcydruid, Fandral Jeleniorogi, prowadzi nas i cały Teldrassil ku chwale!', 'Witaj, $gbracie:siostro;. Jeśli przychodzisz się szkolić, z radością cię wyszkolę.$B$BKrążą plotki o niesnaskach w Kręgu Cenariona, ale nie zwracaj uwagi na takie gadanie. Nasz arcydruid, Fandral Jeleniorogi, prowadzi nas i cały Teldrassil ku chwale!', '', '', '', '', '', '', '', '', '', '', '', '', '', ''),
(50026, 'koKR', 'Jeśli zdobędę odpowiednie składniki, zrobimy materiały wybuchowe, dzięki którym nie tylko zaszkodzę interesom spółki Gitgeszeft, ale też odwrócę uwagę.$B$BWiem, że robi to na tobie wrażenie, ale będzie jeszcze lepiej... Wkrótce powiem ci więcej.', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '');
INSERT INTO `gossip_menu_option_locale` (`MenuID`, `OptionID`, `Locale`, `OptionText`, `BoxText`) VALUES
