INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(179, 'koKR', 'Poratujesz jakim groszem?', '', 0),
(181, 'koKR', 'Datek dla ubogiego?', '', 0),
(182, 'koKR', 'Chętnie oddam ci we wtorek za dzisiejszego hamburgera.', '', 0),
(183, 'koKR', 'Poratujesz biedaka?', '', 0),
(184, 'koKR', 'Grosik dla biednego ślepca? ...Jak to nie jestem ślepy? ...NIE JESTEM ŚLEPY! WIDZĘ!! To cud!', '', 0),
(185, 'koKR', 'Wypucuję ci zbroję za miedziaka.', '', 0),
(186, 'koKR', 'To wszystko ich wina, tej głupiej armii Przymierza. Musieli postawić te swoje wieże akurat za moją farmą.', '', 0),
(187, 'koKR', 'To wszystko ich wina, tych głupich orków. Musieli puścić moją farmę z dymem.', '', 0),
(253, 'koKR', '', 'Corbett, kochanie. Harlan potrzebuje partii dzierganych koszul i spodni, najszybciej jak się da.', 0),
(254, 'koKR', '', 'Corbett, jesteś tam? Harlan potrzebuje kolejnej partii dzianin. Zaniesiesz mu?', 0),
(261, 'koKR', 'Ach, bardzo dziękuję, Corbett. Zaraz powiesimy je na wieszakach.', '', 0),
(262, 'koKR', 'Ach, tak, i dostarczone w samą porę. Jak zawsze, przyjemnie robić z tobą interesy, Corbett.', '', 0),
(286, 'koKR', '', 'Dzień dobry, Corbett. Oto twój ser, świeżo zrobiony dziś rano! A jak tam w twoim sklepie?', 0),
(287, 'koKR', '', 'Cześć, Corbett! Proszę bardzo! Mam nadzieję, że w twoim sklepie z odzieżą interes się kręci...?', 0),
(322, 'koKR', 'Czas na moją medytację, zostaw mnie.', '', 0),
(323, 'koKR', 'Nareszcie jesteś. Jakie wieści z Zachodniego Skraju?', '', 0),
(324, 'koKR', 'VanCleef przesyła wiadomość, że plany są w toku. Ale doszły go plotki, że ktoś tu węszy.', '', 0),
(326, 'koKR', 'Hmm, to może być ten wścibski Shaw. Zobaczę, czego się dowiem. A teraz odejdź. Wkrótce znów się z tobą skontaktuję.', '', 0),
(387, 'koKR', 'Ojej, ten stout z Czarnego Szponu ma niezłego kopa!', '', 0),
(388, 'koKR', 'Coś mi się... kręci w głowie. Ale tu... jest... gorąco...', '', 0),
(1102, 'koKR', 'Ciepły, pożywny chleb!', '', 0),
(1103, 'koKR', 'Bułki, rogale i chleb. Prosto z pieca!', '', 0),
(1104, 'koKR', 'Świeżo upieczony chleb na sprzedaż!', '', 0),
(1105, 'koKR', '', '„Gdzie woda, Emmo?” „Przynieś wodę, Emmo!” Gdyby nie ja, ta banda nie wiedziałaby nawet, jak woda wygląda.', 0),
(1106, 'koKR', '', 'Jakbym na stare lata nie miała nic lepszego do roboty niż noszenie wiader z wodą.', 0),
(1107, 'koKR', '', 'Chyba ze sto razy dziennie łażę aż do studni po wodę. Żadnego szacunku dla starszych, mówię ci.', 0),
(1108, 'koKR', '', 'No pewnie, że gadam do siebie. Tylko tak można w tym mieście porządnie pogadać.', 0),
(1109, 'koKR', '', 'Któregoś dnia utopię go w tej jego niebieskiej szacie. I wszystkie jego miotły też.', 0),
(1110, 'koKR', '', 'Jack i Jill, akurat, a mój pomarszczony zadek! To ja tu dźwigam całą wodę.', 0),
(1111, 'koKR', '', 'Chyba zaczynam wydeptywać koleinę w bruku.', 0),
(1112, 'koKR', '', 'Déjà vu. Przez chwilę myślałam, że znów jestem w domu... sprzed zarazy...', 0),
(1192, 'koKR', 'Zapytaj mnie, jak dostać darmowego drinka w „Błękitnym Samotniku”!', '', 0),
(1193, 'koKR', 'Darmowe drinki w „Błękitnym Samotniku”!', '', 0),
(1194, 'koKR', 'Wpadnij do „Błękitnego Samotnika”. Tam, gdzie wszyscy znają twoje imię!', '', 0),
(1195, 'koKR', 'Najlepsze trunki w Wichrogrodzie!', '', 0),
(1196, 'koKR', 'Przyjdź na piwo, zostań dla atmosfery!', '', 0),
(1197, 'koKR', 'Nauka magii przegrzewa ci mózg? Odpręż się w „Błękitnym Samotniku”!', '', 0),
(1198, 'koKR', 'Jedyne miejsce w Wichrogrodzie, gdzie czary mieszają się z czarkami – przyjdź do „Błękitnego Samotnika”!', '', 0),
(1199, 'koKR', 'Doskwiera ci samotność? Wpadnij do „Błękitnego Samotnika” na dobrą zabawę!', '', 0),
(1200, 'koKR', '', 'Gorąco ci? Schłódź się czymś w „Świni i Gwizdku”!', 0),
(1201, 'koKR', '', 'Bójki co wieczór i świetne trunki! Wszystko to w „Świni i Gwizdku”!', 0),
(1202, 'koKR', '', 'Darmowe piwo w „Świni i Gwizdku”!', 0),
(1203, 'koKR', '', 'Porozmawiaj ze mną, a dostaniesz darmowe piwo w „Świni i Gwizdku”!', 0),
(1205, 'koKR', '', 'Gładsze niż elf, mocniejsze niż ork! W całym Wichrogrodzie nie ma lepszych trunków!', 0),
(1206, 'koKR', '', 'Masz dość tych słabiutkich drineczków dla magików? Spróbuj czegoś mocniejszego w „Świni i Gwizdku”!', 0),
(1207, 'koKR', '', 'Wracasz z długiej podróży? Odpocznij i zrelaksuj się w „Świni i Gwizdku”!', 0),
(1208, 'koKR', '', 'Najlepsze trunki w Wichrogrodzie!', 0),
(1401, 'koKR', '%s nie jest pod wrażeniem.', '%s nie jest pod wrażeniem.', 0),
(1402, 'koKR', 'Przeciągasz strunę, $n.', 'Przeciągasz strunę, $n.', 0),
(1403, 'koKR', 'Nie zmuszaj mnie, żebym się z tobą policzył po średniowiecznemu.', 'Nie zmuszaj mnie, żebym się z tobą policzył po średniowiecznemu.', 0),
(1404, 'koKR', 'Jeszcze raz, $n, a wbiję ci trochę manier do głowy.', 'Jeszcze raz, $n, a wbiję ci trochę manier do głowy.', 0),
(1521, 'koKR', '', '%s odwzajemnia niegrzeczny gest – $n ma za swoje.', 0),
(1529, 'koKR', '', 'Co mogę dla ciebie zrobić?', 0),
(1530, 'koKR', '', 'Na co masz ochotę, $gpanie:panienko;?', 0),
(1531, 'koKR', '', 'No proszę, witaj, $n, co ci dziś podać?', 0),
(1532, 'koKR', '', 'Ciężki dzień? Dobre piwo szybko rozwieje te zmartwienia.', 0),
(1533, 'koKR', '', 'Cześć, co podać?', 0),
(1534, 'koKR', '', 'Dzień dobry. Co podać?', 0),
(1535, 'koKR', '', 'Patrzcie, kogo tu przywiało. Co ci podać, $n?', 0),
(1536, 'koKR', '', 'Myślisz, że powinnam przypiąć sobie więcej przypinek?', 0),
(1657, 'koKR', 'Ach, szeregowy Hendel. Cóż za przyjemność poznać jednego z tych, którzy dla dumy zdradziliby własne królestwo.', '', 0),
(1658, 'koKR', 'Co ja mam zrobić?', '', 0),
(1659, 'koKR', 'Jeśli kapitan się dowie, będzie po mnie.', '', 0),
(1660, 'koKR', 'Jak to się mogło stać?', '', 0),
(1661, 'koKR', 'Nagle byli wszędzie.', '', 0),
(1662, 'koKR', 'Ktoś musiał im pomagać.', '', 0),
(1663, 'koKR', 'Może zajmiemy się tobą od razu, Hendel? Lady Proudmoore porozmawia z tobą w wieży.', '', 0),
(1678, 'koKR', '', 'Widzę, że czujesz się lepiej.', 0),
(1679, 'koKR', '', 'Wypij to, pomoże.', 0),
(1680, 'koKR', '', 'To powinno złagodzić ból.', 0),
(1681, 'koKR', '', 'Trochę tej maści powinno pomóc.', 0),
(1682, 'koKR', '', 'Wszystko będzie dobrze.', 0),
(1683, 'koKR', '', 'Weź to i wypij do dna.', 0),
(1684, 'koKR', '', 'Nie martw się, wszystkie palce u rąk i nóg zostaną na swoim miejscu.', 0),
(1685, 'koKR', '', 'Pozwól, że opatrzę te rany.', 0),
(1712, 'koKR', 'Dobra, dobra! Dość walki. Nikt więcej nie musi oberwać.', '', 0),
(1713, 'koKR', 'W porządku, chłopaki. Odpuśćcie. Wystarczy. Spotkamy się później.', '', 0),
(1718, 'koKR', 'Niech żyje $n, $c wielkiej wartości!', '', 0),
(1719, 'koKR', 'Patrzcie! „Błękitny Samotnik” wydaje ucztę na $gjego:jej; cześć!', '', 0),
(1733, 'koKR', 'Hura, $n!', '', 0),
(1735, 'koKR', 'Brawo, brawo!', '', 0),
(1736, 'koKR', 'Niech żyje $n!', '', 0),
(1743, 'koKR', 'Dobra, dobra! Nie trzeba od razu przemocy. Powiem. Wszystko powiem!', '', 0),
(1744, 'koKR', 'Mam u siebie parę notatek z tamtej roboty. Pójdę po nie, a potem spotkamy się w karczmie.', '', 0),
(1751, 'koKR', 'Idź z gracją i niech chroni cię magia naszej pani.', '', 0),
(1759, 'koKR', 'Proszę... proszę... panno Proudmoore. Ja nie chciałem...', '', 0),
(1761, 'koKR', 'Przepraszam, że zjawiam się tak późno. Chciałem, żeby lady Proudmoore także była obecna.', '', 0),
(1808, 'koKR', 'Możemy zostać tylko chwilę, potem wracamy do wieży. Jeśli zechcesz jeszcze z nami porozmawiać, znajdziesz nas tam.', '', 0),
(1828, 'koKR', 'To nie moja wina, mistrzu Mazenie!', '', 0),
(1829, 'koKR', 'To była zwykła pomyłka. Po prostu źle skręciłem, naprawdę!', '', 0),
(1830, 'koKR', 'Na tych bagnach było okropnie! Byłem taki... taki... przerażony!', '', 0),
(1831, 'koKR', 'Mam szczęście, że żyję!', '', 0),
(1950, 'koKR', 'Czas przyrządzić Kalimdorski Koktajl! Hep!', '', 0),
(1951, 'koKR', 'To powinno wystarczyć! Hep!', '', 0),
(1952, 'koKR', '%s wypija swój trunek duszkiem.', '', 0),
(1953, 'koKR', 'Hep!', '', 0),
(1954, 'koKR', 'Dobra, kto mnie przewrócił? To ty, $n? Niech ktoś zapali z powrotem światło. Hep!', '', 0),
(1955, 'koKR', 'Jeszcze łyczek starej ognistej wody i będę gotów gadać. Hep! Zdrówko!', '', 0),
(1956, 'koKR', 'No więc, $n, jestem gotów opowiedzieć ci, co się stało na Moczarach Smutków. Hep!', '', 0),
(1961, 'koKR', 'Teraz dostaniesz za swoje, $n!', '', 0),
(1986, 'koKR', 'Kto śmie przyzywać moc Pustki?', '', 0),
(1987, 'koKR', 'Za to zaznasz wiecznych mąk, $gżałosny czarnoksiężniku:żałosna czarnoksiężniczko;.', '', 0),
(1991, 'koKR', '', 'Interesujące... To więcej, niż się spodziewałam. Pyszne...', 0),
(2306, 'koKR', '%s zabiera się do pracy...', '', 0),
(2307, 'koKR', 'Gotowe. Mam twoją broń, $n.', '', 0),
(2308, 'koKR', '$n $gprzeszedł:przeszła; ścieżkę zdrowia! Trzykrotne hura na cześć $n!', '', 0),
(2309, 'koKR', 'Hip, hip, hura!', '', 0),
(2310, 'koKR', 'Tysiąc lat temu nieśmiertelne elfy, półbogowie lasu i smoki walczyli z Legionem na zboczach Hyjal.', '', 0),
(2311, 'koKR', 'Anathera i Latherion walczyli plecami do siebie tam, gdzie bitwa wrzała najmocniej. Dwoje kochanków zdecydowanych razem przetrwać wojnę.', '', 0),
(2312, 'koKR', 'Ale nie było im to pisane. Gdy wrogowie napierali, spaczone ostrze demona przebiło zbroję Anathery. W wirze bitwy nic nie mogło jej ocalić.', '', 0),
(2314, 'koKR', 'Nie zważając na szalejącą wokół bitwę, Latherion opuścił gardę, by tulić ukochaną w jej ostatnich chwilach. Lecz demony nie okazały mu litości i szybko go powaliły.', '', 0),
(2317, 'koKR', 'Tam, gdzie padli kochankowie, wyrosło drzewo. Elfy nazywają je sercodrzewem. Z pewnością posłuży twoim celom.', '', 0),
(2342, 'koKR', 'Skończone! A wyniki są zdumiewające. Muszę przekazać je moim wspólnikom: Grimandowi, Mathielowi i Klockmortowi!', '', 0),
(2343, 'koKR', 'Twój pancerz jest gotowy, $n.', '', 0),
(2345, 'koKR', 'Hura, hura! $n! Gotowe!', '', 0),
(2349, 'koKR', 'Gotowe. $n, twój pancerz czeka.', '', 0),
(2358, 'koKR', '', 'Udało się! Wygraliśmy!', 0),
(2360, 'koKR', '', 'Do domu! Trzymaj się blisko mnie, cokolwiek się stanie! Mam tam strzelbę i amunicję!', 0),
(2369, 'koKR', '', 'Kolejny z głowy!', 0),
(2370, 'koKR', 'Mam nadzieję, że jesteś $ggotów:gotowa;, $n. Chodź za mną.', '', 0),
(2374, 'koKR', 'Chodźcie, moi akolici. Weźcie pręty kanalizowania i utwórzcie wielki krąg przyzywania.', '', 0),
(2382, 'koKR', '%s rozpoczyna zaklęcie przyzwania...', '', 0),
(2383, 'koKR', 'Chodź za mną, $n. Wkrótce rozpocznę przyzwanie...', '', 0),
(2501, 'koKR', 'Bierzmy się do roboty, $n!', '', 0),
(2504, 'koKR', 'Proszę bardzo, $n.', '', 0),
(2527, 'koKR', 'Witaj. Jestem nieumarłym nauczycielem magów, a ty jesteś $gmagiem:magini;.', 'Witaj. Jestem nieumarłym nauczycielem magów, a ty jesteś $gmagiem:magini;.', 0),
(2529, 'koKR', 'Witaj. Czyżbyś $gprzybył:przybyła;, by poznać ukryte sztuki?', 'Witaj. Czyżbyś $gprzybył:przybyła;, by poznać ukryte sztuki?', 0),
(2530, 'koKR', 'Witaj, witaj. Żal mi takich jak ty, bo sekrety prawdziwej magii są poza twoim zasięgiem...', 'Witaj, witaj. Żal mi takich jak ty, bo sekrety prawdziwej magii są poza twoim zasięgiem...', 0),
(2546, 'koKR', 'Za przyzwoleniem lady Sylwany szeregi tropicieli śmierci rosną. Więcej ostrzy, które uderzą w naszych wrogów, gdy najmniej się tego spodziewają.', 'Za przyzwoleniem lady Sylwany szeregi tropicieli śmierci rosną. Więcej ostrzy, które uderzą w naszych wrogów, gdy najmniej się tego spodziewają.', 0),
(2553, 'koKR', '%s zostaje wessany do szkatuły!', '', 0),
(2564, 'koKR', '%s ucieka w Pustkę!', '', 0),
(2602, 'koKR', 'Strzaskana Dłoń przywróci Hordzie dawną chwałę.', 'Strzaskana Dłoń przywróci Hordzie dawną chwałę.', 0),
(2603, 'koKR', 'Potrzebuję szkolenia.', 'Potrzebuję szkolenia.', 0),
(2624, 'koKR', '', 'Powodzenia, $n.', 0),
(2629, 'koKR', '', 'Przygotuj się, $n, bo demon zamknięty w tej kuli to plugawa bestia.', 0),
(2647, 'koKR', '', 'To świetne materiały, $n. Zabiorę się do twojej szaty.', 0),
(2648, 'koKR', '', 'Gotowe! Wszystko skończone, $n.', 0),
(2649, 'koKR', '', 'No dobrze, do roboty!', 0),
(2650, 'koKR', '', 'Aha! Tu jest.', 0),
(2651, 'koKR', '', 'Gdzie ja położyłam tę srebrną szpulę...', 0),
(2656, 'koKR', '', 'Muszę jeszcze tylko coś sprawdzić...', 0),
(2657, 'koKR', '', 'Gotowe! Zadziałało!', 0),
(2658, 'koKR', '', 'Dziękuję za cierpliwość, $n.', 0),
(2659, 'koKR', '', 'Przechowam to tutaj, dopóki nie będzie potrzebne...', 0),
(2663, 'koKR', '', 'Dobrze, zróbmy tę kulę...', 0),
(2664, 'koKR', '', 'No dobrze. Gotowe!', 0),
(2682, 'koKR', '', 'Weź skrzynię szkatuł izolujących i inkantację manifestacji, $n. Będą ci potrzebne w twojej misji.', 0),
(2708, 'koKR', '', 'Odsuń się i... wstrzymaj oddech. Dawno tego nie robiłam.', 0),
(2709, 'koKR', '', 'Zadziałało! Niesamowite! Chyba jeszcze nie wyszłam z wprawy...', 0),
(2930, 'koKR', 'Z każdym dniem jest coraz grubszy i bardziej zepsuty. Czuć smród, co od niego bije. Brudny on jest, a nie chodzi mi tylko o to, że przydałoby mu się umyć.$B$BDość już gadania Hulfdana. Skąd przybywasz i jak mogę ci pomóc?', 'Z każdym dniem jest coraz grubszy i bardziej zepsuty. Czuć smród, co od niego bije. Brudny on jest, a nie chodzi mi tylko o to, że przydałoby mu się umyć.$B$BDość już gadania Hulfdana. Skąd przybywasz i jak mogę ci pomóc?', 0),
(2931, 'koKR', 'Dzień dobry, Hulfdanie, szukam szkolenia.', 'Dzień dobry, Hulfdanie, szukam szkolenia.', 0),
(3074, 'koKR', '%s wpada w gniew i atakuje!', '', 0),
(3090, 'koKR', '', 'Spotkajmy się przy sadzie – muszę tylko odłożyć strzelbę.', 0),
(3146, 'koKR', 'Przychodzisz na szkolenie? Czy tylko po to, żeby marnować czas wojownika?', 'Przychodzisz na szkolenie? Czy tylko po to, żeby marnować czas wojownika?', 0),
(3265, 'koKR', 'Więc chcesz zostać $gkowalem:kowalką;, co? Bierz fartuch i młot, $gchłopcze:dziewczyno;, zobaczymy, co potrafisz.', '', 0),
(3276, 'koKR', 'Nie widzisz, że jestem zajęty? Lepiej, żeby to było coś ważnego.', '', 0),
(3277, 'koKR', 'Rozum ci odjęło? To nie broń, to nożyk do masła. Nie szkolę amatorów.', '', 0),
(3336, 'koKR', 'Mam nadzieję, że przerywasz mi w słusznej sprawie, bo właśnie zajmowała mnie ważna praca.', 'Mam nadzieję, że przerywasz mi w słusznej sprawie, bo właśnie zajmowała mnie ważna praca.', 0),
(3337, 'koKR', '$gKolejny zielarz:Kolejna zielarka;, hmm. Wątpię, żeby twoje umiejętności dorównywały moim, więc może nauczę cię kilku porządnych technik.', '$gKolejny zielarz:Kolejna zielarka;, hmm. Wątpię, żeby twoje umiejętności dorównywały moim, więc może nauczę cię kilku porządnych technik.', 0),
(3340, 'koKR', 'Witaj w Wichrogrodzie. Odbudowa trwała długo, ale było warto. Przybywasz w odwiedziny czy w interesach?', 'Witaj w Wichrogrodzie. Odbudowa trwała długo, ale było warto. Przybywasz w odwiedziny czy w interesach?', 0),
(3341, 'koKR', 'Niewielu kucharzy przychodzi tu po naukę, ale chyba mogę cię czegoś nauczyć, jeśli jesteś $ggotów:gotowa;.', 'Niewielu kucharzy przychodzi tu po naukę, ale chyba mogę cię czegoś nauczyć, jeśli jesteś $ggotów:gotowa;.', 0),
(3342, 'koKR', 'Czy wyglądam na kogoś, kto ma czas i siłę niańczyć każdego turystę, który zabłąka się do mojego sklepu? Mów, czego potrzebujesz, i to szybko.', 'Czy wyglądam na kogoś, kto ma czas i siłę niańczyć każdego turystę, który zabłąka się do mojego sklepu? Mów, czego potrzebujesz, i to szybko.', 0),
(3351, 'koKR', 'Wielkie wojny może i się skończyły, przynajmniej na razie, ale wciąż musimy szlifować umiejętności!', 'Wielkie wojny może i się skończyły, przynajmniej na razie, ale wciąż musimy szlifować umiejętności!', 0),
(3353, 'koKR', 'Witaj. Szukasz nauki w sztuce wojennej?', 'Witaj. Czy szukasz nauki w sztuce wojennej?', 0),
(3354, 'koKR', 'Choćby nie wiem ile się nauczyć, zawsze jest coś więcej do poznania.', 'Choćby nie wiem ile się nauczyć, zawsze jest coś więcej do poznania.', 0),
(3355, 'koKR', 'Rolą wojownika jest ochrona. Tak jak w bitwie chronimy naszych towarzyszy, tak samo musimy chronić interesy Porzuconych.', 'Rolą wojownika jest ochrona. Tak jak w bitwie chronimy naszych towarzyszy, tak samo musimy chronić interesy Porzuconych.', 0),
(3356, 'koKR', 'Och, $gkolega lekarz:koleżanka lekarka;. Chętnie nauczę cię wszystkiego, co pomoże ci w podróżach.', 'Och, $gkolega lekarz:koleżanka lekarka;. Chętnie nauczę cię wszystkiego, co pomoże ci w podróżach.', 0),
(3357, 'koKR', 'Tak, $gsynu:córko;? W czym mogę ci pomóc?', 'Tak, $gsynu:córko;? W czym mogę ci pomóc?', 0),
(3362, 'koKR', 'No? Przerywasz mi, więc lepiej miej cholernie dobry powód.', 'No? Przerywasz mi, więc lepiej miej cholernie dobry powód.', 0),
(3368, 'koKR', 'Od upadku Dalaranu i zniszczenia Quel\'Thalas o takie towary jest trudno. Ale Lucan Cordell i paru innych naszych handlarzy świetnie się spisują, zaopatrując nas w porządny towar.', 'Od upadku Dalaranu i zniszczenia Quel\'Thalas o takie towary jest trudno. Ale Lucan Cordell i paru innych naszych handlarzy świetnie się spisują, zaopatrując nas w porządny towar.', 0),
(3369, 'koKR', 'Sprzedaję tylko najlepszy magiczny ekwipunek, wykonany przez rzemieślników i magów tu, w Wichrogrodzie.', 'Sprzedaję tylko najlepszy magiczny ekwipunek, wykonany przez rzemieślników i magów tu, w Wichrogrodzie.', 0),
