(20786, 'koKR', 'Jak dorosnę, będę garbować skóry!', '', 0),
(20969, 'koKR', '$GZgubiłem:Zgubiłam; mój kamień księżycowy nasycony esencją. Możesz mi dać nowy?', '$GZgubiłem:Zgubiłam; mój kamień księżycowy nasycony esencją. Możesz mi dać nowy?', 0),
(22523, 'koKR', 'Miło cię poznać.', '', 0),
(22524, 'koKR', 'Możesz mnie wysłać do Theramore? Mam pilną wiadomość dla lady Jainy od króla Wrynna.', 'Możesz mnie wysłać do Theramore? Mam pilną wiadomość dla lady Jainy od króla Wrynna.', 0),
(23767, 'koKR', '', 'Witaj, niech Światło Eluny będzie z tobą.', 0),
(25755, 'koKR', '', 'Chcesz jak najszybciej dotrzeć do Północnej Grani, co? Parowiec „Kraken” pływa stąd do Twierdzy Walecznych w Boreańskiej Tundrze.', 0),
(27801, 'koKR', 'Szefie, klienci narzekają, że w naszych zabójczych truciznach jest za mało dziewiczej męki.', '', 0),
(27802, 'koKR', 'Szefie, klienci narzekają, że w naszych truciznach znieczulających jest za dużo śmiertelnicy.', '', 0),
(27803, 'koKR', 'Szefie, myślę, że z korzeniem letargu w tym ostatnim przepisie na truciznę byliśmy już blisko.', '', 0),
(27804, 'koKR', 'Wright, skończyłeś już tę nową miksturę, nad którą pracujesz? Mam dość tych zarodników, które zapychają mi sklep!', '', 0),
(27805, 'koKR', 'To następnym razem dodaj dwa razy więcej!', '', 0),
(27806, 'koKR', 'To następnym razem dodaj o połowę mniej.', '', 0),
(27807, 'koKR', 'Zapamiętaj, młody: zawsze mylisz się bardziej, niż ci się wydaje. Podwój to!', '', 0);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(27808, 'koKR', 'Pracuję nad tym, tylko nie chcę jej sprzedawać, dopóki nie będę z niej zadowolony. To już nie potrwa długo.', '', 0),
(27810, 'koKR', 'Zawsze tak mówisz. Czasem myślę, że nigdy tego nie skończysz.', '', 0),
(27816, 'koKR', 'Horda zdobywa Fortecę Zimościsku!', '', 0),
(27817, 'koKR', 'Przymierze zdobywa Fortecę Zimościsku!', '', 0),
(28636, 'koKR', '', 'Z tego doku „Odwaga” kursuje tam i z powrotem między Wichrogrodem a Wioską Rut\'theran.', 0),
(29419, 'koKR', 'Witaj. Ufam, że przynosisz mi dobre wieści w sprawie Worldwide Invitational? Jeśli tak, to na pewno $gdostałeś:dostałaś; tajny kod, który masz mi przekazać. W zamian za kod dam ci podarunek – Rękojeść Tyraela.$B$BWyszeptaj mi go do ucha, gdy będziesz $ggotów:gotowa;.', 'Witaj. Ufam, że przynosisz mi dobre wieści w sprawie Worldwide Invitational? Jeśli tak, to na pewno $gdostałeś:dostałaś; tajny kod, który masz mi przekazać. W zamian za kod dam ci podarunek – Rękojeść Tyraela.$B$BWyszeptaj mi go do ucha, gdy będziesz $ggotów:gotowa;.', 0),
(29420, 'koKR', 'Chcę wyszeptać ci mój tajny kod, by otrzymać Rękojeść Tyraela.', 'Chcę wyszeptać ci mój tajny kod, by otrzymać Rękojeść Tyraela.', 0),
(29488, 'koKR', 'Witaj! Port Wichrogrodu to niezwykły widok, a z powietrza wygląda jeszcze lepiej. Może chcesz obejrzeć port z lotu ptaka?', '', 0),
(29489, 'koKR', 'Chcę polecieć nad Portem Wichrogrodu.', 'Chcę polecieć nad Portem Wichrogrodu.', 0),
(29495, 'koKR', 'Witaj, przyjacielu, w zakładzie fryzjerskim! Przychodzisz się ostrzyc? Ufarbować? A może chodzi o coś innego?$B$BMożemy przystrzyc zarost, zrobić piercing, wytatuować wzory nocnych elfów, a nawet zmienić kształt rogów i macek draenei!$B$BSiadaj, a zaraz weźmiemy się do roboty. Tylko kilka monet dzieli cię od nowej, atrakcyjniejszej wersji siebie...', 'Witaj, przyjacielu, w zakładzie fryzjerskim! Przychodzisz się ostrzyc? Ufarbować? A może chodzi o coś innego?$B$BMożemy przystrzyc zarost, zrobić piercing, wytatuować wzory nocnych elfów, a nawet zmienić kształt rogów i macek draenei!$B$BSiadaj, a zaraz weźmiemy się do roboty. Tylko kilka monet dzieli cię od nowej, atrakcyjniejszej wersji siebie...', 0),
(29498, 'koKR', 'Witaj, przyjacielu, w zakładzie fryzjerskim! Przychodzisz się ostrzyc? Ufarbować? A może chodzi o coś innego?$B$BMożemy przystrzyc zarost, zrobić piercing, zmienić kształt kłów i rogów, a nawet poprawić rysy nieumarłych!$B$BSiadaj, a zaraz weźmiemy się do roboty. Tylko kilka monet dzieli cię od nowej, atrakcyjniejszej wersji siebie...', 'Witaj, przyjacielu, w zakładzie fryzjerskim! Przychodzisz się ostrzyc? Ufarbować? A może chodzi o coś innego?$B$BMożemy przystrzyc zarost, zrobić piercing, zmienić kształt kłów i rogów, a nawet poprawić rysy nieumarłych!$B$BSiadaj, a zaraz weźmiemy się do roboty. Tylko kilka monet dzieli cię od nowej, atrakcyjniejszej wersji siebie...', 0),
(29625, 'koKR', 'Jak mam szkolić mojego zwierzaka?', 'Jak mam szkolić mojego zwierzaka?', 0),
(29626, 'koKR', 'Tak jak łowcy, zwierzaki mogą wybrać specjalizację. Zajadłe zwierzaki, takie jak koty, zadają duże obrażenia, ale same gorzej je znoszą. Nieustępliwe zwierzaki, takie jak żółwie, są bardziej defensywne i potrafią zająć uwagę wroga, gdy ty trzymasz się na dystans. Przebiegłe zwierzaki, takie jak pająki, łączą zdolności ofensywne i defensywne i szczególnie przydają się na polach bitew i arenach.$b$bKażdy zwierzak ma domyślną specjalizację, ale możesz ją zmienić, jeśli chcesz.', 'Tak jak łowcy, zwierzaki mogą wybrać specjalizację. Zajadłe zwierzaki, takie jak koty, zadają duże obrażenia, ale same gorzej je znoszą. Nieustępliwe zwierzaki, takie jak żółwie, są bardziej defensywne i potrafią zająć uwagę wroga, gdy ty trzymasz się na dystans. Przebiegłe zwierzaki, takie jak pająki, łączą zdolności ofensywne i defensywne i szczególnie przydają się na polach bitew i arenach.$b$bKażdy zwierzak ma domyślną specjalizację, ale możesz ją zmienić, jeśli chcesz.', 0),
(29959, 'koKR', 'Pokaż mi, co masz na sprzedaż.', 'Pokaż mi, co masz na sprzedaż.', 0),
(30120, 'koKR', 'Tak jest!', 'Tak jest!', 0),
(30314, 'koKR', 'Hej, jeśli $gzgubiłeś:zgubiłaś; klucz, może zdołam ci pomóc.', 'Hej, jeśli $gzgubiłeś:zgubiłaś; klucz, może zdołam ci pomóc.', 0),
(30315, 'koKR', '$GZgubiłem:Zgubiłam; klucz do Scholomancjum.', '$GZgubiłem:Zgubiłam; klucz do Scholomancjum.', 0),
