(30318, 'koKR', '$GZgubiłem:Zgubiłam; klucz do Płonącego Wąwozu.', '$GZgubiłem:Zgubiłam; klucz do Płonącego Wąwozu.', 0),
(30319, 'koKR', '$GZgubiłem:Zgubiłam; Klucz Cienistej Kuźni.', '$GZgubiłem:Zgubiłam; Klucz Cienistej Kuźni.', 0),
(30320, 'koKR', '$GZgubiłem:Zgubiłam; Oko Haramada.', '$GZgubiłem:Zgubiłam; Oko Haramada.', 0),
(30321, 'koKR', '$GZgubiłem:Zgubiłam; klucz do Karazhanu.', '$GZgubiłem:Zgubiłam; klucz do Karazhanu.', 0),
(30379, 'koKR', 'Zbyt długo mnie nie było, gdy torowałem sobie drogę przez Azeroth, by odkryć na nowo swoją przeszłość i odzyskać tron. Wobec wszystkich prób, na jakie wystawiono Przymierze pod moją nieobecność, serce rośnie mi na widok bohaterów takich jak ty, którzy bronią naszej koalicji.', '', 0),
(30650, 'koKR', 'Osiągasz rangę 1: Kapral', 'Osiągasz rangę 1: Kapral', 0),
(30651, 'koKR', 'Osiągasz rangę 2: Porucznik', 'Osiągasz rangę 2: Porucznik', 0),
(30908, 'koKR', 'Kim jesteś?$B$BIdź sobie... Padam z nóg po harówce przy budowie drogi do portu. Czas napić się krasnoludzkiego piwa, porządnie się wypłakać i uciąć sobie drzemkę.', '', 0),
