(32286, 'koKR', 'Kor\'kron, opuścić broń!', '', 0),
(32287, 'koKR', 'Jaino...', '', 0),
(32289, 'koKR', 'Jaino, to, co wydarzyło się przy Bramie Gniewu... To była zdrada od wewnątrz...', '', 0),
(32292, 'koKR', 'Horda straciła Podmiasto.', '', 0),
